package io.droptracker;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class DropTrackerPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(DropTrackerPlugin.class);
		RuneLite.main(args);
	}
}

package io.droptracker.events;

import org.junit.Test;

import java.util.regex.Matcher;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Tests the pet chat-message patterns exposed via {@code @VisibleForTesting}.
 * PET_REGEX gates local pet detection; CLAN_REGEX pulls the pet name and
 * milestone out of the clan broadcast.
 */
public class PetHandlerParseTest {

    @Test
    public void petRegexMatchesFunnyFeelingVariants() {
        assertTrue(PetHandler.PET_REGEX.matcher("You have a funny feeling like you're being followed.").matches());
        assertTrue(PetHandler.PET_REGEX.matcher("You have a funny feeling like you would have been followed...").matches());
        assertTrue(PetHandler.PET_REGEX.matcher("You feel something weird sneaking into your backpack.").matches());
    }

    @Test
    public void petRegexRejectsUnrelatedMessages() {
        assertFalse(PetHandler.PET_REGEX.matcher("You have completed a Treasure Trail.").matches());
        assertFalse(PetHandler.PET_REGEX.matcher("You feel a funny sensation.").matches());
    }

    @Test
    public void clanRegexExtractsUserPetAndMilestoneForFollow() {
        Matcher m = PetHandler.CLAN_REGEX.matcher(
                "Koeppy has a funny feeling like he would have been followed: Herbi at 500 kills.");
        assertTrue(m.find());
        assertEquals("Koeppy", m.group("user"));
        assertEquals("Herbi", m.group("pet"));
        assertEquals("500 kills.", m.group("milestone"));
    }

    @Test
    public void clanRegexExtractsBackpackVariant() {
        Matcher m = PetHandler.CLAN_REGEX.matcher(
                "Big Man feels something weird sneaking into his backpack: Baby mole at 200 kills.");
        assertTrue(m.find());
        assertEquals("Big Man", m.group("user"));
        assertEquals("Baby mole", m.group("pet"));
        assertEquals("200 kills.", m.group("milestone"));
    }

    // Regression: skilling pets have no boss source and are absent from PET_TO_SOURCE,
    // but must still be recognised via the Pet enum, else their name is dropped.
    @Test
    public void isPetNameRecognisesSkillingPets() {
        for (String skillingPet : new String[]{
                "Beaver", "Heron", "Rock golem", "Rocky", "Giant squirrel",
                "Tangleroot", "Rift guardian", "Baby chinchompa"}) {
            assertTrue(skillingPet + " should be recognised", PetHandler.isPetName(skillingPet));
        }
    }

    @Test
    public void isPetNameRecognisesBossPetsAndRejectsNonPets() {
        // Newer boss pets live only in PET_TO_SOURCE, not the Pet enum.
        assertTrue(PetHandler.isPetName("Yami"));
        assertTrue(PetHandler.isPetName("Dom"));
        assertTrue(PetHandler.isPetName("Baby mole"));
        assertFalse(PetHandler.isPetName("Dragon warhammer"));
    }
}

package io.droptracker.events;

import net.runelite.client.util.Text;
import org.junit.Test;

import java.time.Duration;
import java.util.regex.Matcher;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Tests for the chat-message regex patterns in {@link PbHandler}, exposed via
 * package-private {@code @VisibleForTesting} accessors.
 */
public class PbHandlerParseTest {

    // --- BOSS_COUNT_PATTERN ---

    @Test
    public void bossCountMatchesKillCountMessage() {
        Matcher m = PbHandler.bossCountPattern().matcher("Your Zulrah kill count is: 1,234");
        assertTrue(m.find());
        assertEquals("Zulrah", m.group("key"));
        assertEquals("kill", m.group("type"));
        assertEquals("1,234", m.group("value"));
    }

    @Test
    public void bossCountMatchesMultiWordBossName() {
        Matcher m = PbHandler.bossCountPattern().matcher("Your Grotesque Guardians kill count is: 500");
        assertTrue(m.find());
        assertEquals("Grotesque Guardians", m.group("key"));
        assertEquals("500", m.group("value"));
    }

    @Test
    public void bossCountMatchesChestAndSuccessTypes() {
        Matcher chest = PbHandler.bossCountPattern().matcher("Your Barrows chest count is: 42");
        assertTrue(chest.find());
        assertEquals("Barrows", chest.group("key"));
        assertEquals("chest", chest.group("type"));

        Matcher success = PbHandler.bossCountPattern().matcher("Your Wintertodt success count is: 300");
        assertTrue(success.find());
        assertEquals("Wintertodt", success.group("key"));
        assertEquals("success", success.group("type"));
    }

    @Test
    public void bossCountMatchesNamesWithApostrophesAndColons() {
        Matcher m = PbHandler.bossCountPattern().matcher("Your Vet'ion kill count is: 69");
        assertTrue(m.find());
        assertEquals("Vet'ion", m.group("key"));
    }

    @Test
    public void bossCountDoesNotMatchUnrelatedMessages() {
        assertFalse(PbHandler.bossCountPattern().matcher("You have a funny feeling...").find());
        assertFalse(PbHandler.bossCountPattern().matcher("Your heriblore level is now 78.").find());
    }

    // --- SECONDARY_BOSS_PATTERN ---

    @Test
    public void secondaryPatternMatchesCompletedCountMessage() {
        Matcher m = PbHandler.secondaryBossPattern().matcher("Your completed Theatre of Blood count is: 5");
        assertTrue(m.find());
        assertEquals("completed", m.group("type"));
        assertEquals("Theatre of Blood", m.group("key"));
        assertEquals("5", m.group("value"));
    }

    @Test
    public void secondaryPatternMatchesSubduedCountMessage() {
        Matcher m = PbHandler.secondaryBossPattern().matcher("Your subdued Wintertodt count is: 10");
        assertTrue(m.find());
        assertEquals("subdued", m.group("type"));
        assertEquals("Wintertodt", m.group("key"));
        assertEquals("10", m.group("value"));
    }

    // --- TEAM_SIZE_PATTERN ---

    @Test
    public void teamSizeMatchesSolo() {
        Matcher m = PbHandler.teamSizePattern().matcher("Team size: Solo");
        assertTrue(m.find());
        assertEquals("Solo", m.group("size"));
    }

    @Test
    public void teamSizeMatchesNumericPlayers() {
        Matcher m = PbHandler.teamSizePattern().matcher("Team size: 3 players");
        assertTrue(m.find());
        assertEquals("3", m.group("size"));

        Matcher single = PbHandler.teamSizePattern().matcher("Team size: 1 player");
        assertTrue(single.find());
        assertEquals("1", single.group("size"));
    }

    @Test
    public void teamSizeDoesNotMatchUnrelatedText() {
        assertFalse(PbHandler.teamSizePattern().matcher("Fight duration: 1:23").find());
    }

    /**
     * The game buckets big Chambers teams and puts the bucket label on the
     * line. Matching only the leading digits submitted a 16-23 raid as "16",
     * which is a board the game does not have (suggestion #153).
     */
    @Test
    public void teamSizeKeepsRangeBracketsWhole() {
        Matcher m = PbHandler.teamSizePattern().matcher("Team size: 16-23 players");
        assertTrue(m.find());
        assertEquals("16-23", m.group("size"));

        Matcher low = PbHandler.teamSizePattern().matcher("Team size: 11-15 players");
        assertTrue(low.find());
        assertEquals("11-15", low.group("size"));
    }

    @Test
    public void teamSizeKeepsOpenEndedBracketsWhole() {
        Matcher cox = PbHandler.teamSizePattern().matcher("Team size: 24+ players");
        assertTrue(cox.find());
        assertEquals("24+", cox.group("size"));

        Matcher nightmare = PbHandler.teamSizePattern().matcher("Team size: 6+ players");
        assertTrue(nightmare.find());
        assertEquals("6+", nightmare.group("size"));
    }

    // --- TIME_WITH_PB_PATTERN ---

    @Test
    public void timePatternExtractsDurationAndNewPbIndicator() {
        Matcher m = PbHandler.timeWithPbPattern().matcher("Fight duration: 1:23.40 (new personal best)");
        assertTrue(m.find());
        assertEquals("1:23.40", m.group("duration"));
        assertEquals("(new personal best)", m.group("pbIndicator"));
        assertNull(m.group("pbtime"));
    }

    @Test
    public void timePatternExtractsDurationAndExistingPersonalBest() {
        Matcher m = PbHandler.timeWithPbPattern().matcher("Duration: 45:12 Personal best: 40:00");
        assertTrue(m.find());
        assertEquals("45:12", m.group("duration"));
        assertEquals("40:00", m.group("pbtime"));
        assertNull(m.group("pbIndicator"));
    }

    @Test
    public void timePatternHandlesHourLongDurations() {
        Matcher m = PbHandler.timeWithPbPattern().matcher("Overall time: 1:23:45.60 (new personal best)");
        assertTrue(m.find());
        assertEquals("1:23:45.60", m.group("duration"));
        assertEquals("(new personal best)", m.group("pbIndicator"));
    }

    @Test
    public void timePatternWithoutPbInfoLeavesGroupsNull() {
        Matcher m = PbHandler.timeWithPbPattern().matcher("Fight duration: 2:15.");
        assertTrue(m.find());
        assertEquals("2:15", m.group("duration"));
        assertNull(m.group("pbtime"));
        assertNull(m.group("pbIndicator"));
    }

    // --- selectTimeLine ---
    //
    // Raid messages taken verbatim from RuneLite's ChatCommandsPluginTest,
    // run through the plugin's own sanitising.

    /** Mirrors {@code SubmissionManager.sanitize}. */
    private static String sanitize(String message) {
        return Text.removeTags(message.replace("<br>", "\n")).replace('\u00A0', ' ').trim();
    }

    private static Matcher timeMatcherFor(String message) {
        String line = PbHandler.selectTimeLine(sanitize(message));
        assertNotNull("expected a usable time line in: " + message, line);
        Matcher m = PbHandler.timeWithPbPattern().matcher(line);
        assertTrue(m.find());
        return m;
    }

    private static final String TOB_PB_MESSAGE =
        "Wave 'The Final Challenge' (Normal Mode) complete!<br>" +
            "Duration: <col=ff0000>2:42.0</col><br>" +
            "Theatre of Blood completion time: <col=ff0000>17:00.20</col> (new personal best)";

    private static final String TOB_NO_PB_MESSAGE =
        "Wave 'The Final Challenge' (Normal Mode) complete!<br>" +
            "Duration: <col=ff0000>2:42</col><br>" +
            "Theatre of Blood completion time: <col=ff0000>17:00</col>. Personal best: 13:52.80";

    private static final String TOB_TOTAL_MESSAGE =
        "Theatre of Blood total completion time: <col=ff0000>24:40.20</col>. Personal best: 20:45.00";

    private static final String TOA_PB_MESSAGE =
        "Challenge complete: The Wardens. Duration: <col=ef1020>8:30</col><br>" +
            "Tombs of Amascut challenge completion time: <col=ef1020>8:31</col> (new personal best)";

    private static final String TOA_TOTAL_MESSAGE =
        "Tombs of Amascut total completion time: <col=ef1020>0:01</col> (new personal best)";

    @Test
    public void tobTakesRaidCompletionTimeOverTheFinalWaveDuration() {
        Matcher m = timeMatcherFor(TOB_PB_MESSAGE);
        // Not 2:42.0, the Verzik room duration that shares this message.
        assertEquals("17:00.20", m.group("duration"));
        assertEquals("(new personal best)", m.group("pbIndicator"));
        assertNull(m.group("pbtime"));
    }

    @Test
    public void tobKeepsTheNewPersonalBestSuffixThatSitsLinesAwayFromTheFirstTime() {
        Matcher m = timeMatcherFor(TOB_PB_MESSAGE);
        assertNotNull("a genuine PB must not be reported as a non-PB", m.group("pbIndicator"));
        assertEquals(Duration.ofMinutes(17).plusMillis(200), PbHandler.parseTime(m.group("duration")));
    }

    @Test
    public void tobNonPbKillReportsCompletionTimeAndStandingBest() {
        Matcher m = timeMatcherFor(TOB_NO_PB_MESSAGE);
        assertEquals("17:00", m.group("duration"));
        assertEquals("13:52.80", m.group("pbtime"));
        assertNull(m.group("pbIndicator"));
    }

    @Test
    public void tobWallClockTotalIsNotAKillTimeAtAll() {
        // Null keeps updateKillData from overwriting the raid time.
        assertNull(PbHandler.selectTimeLine(sanitize(TOB_TOTAL_MESSAGE)));
    }

    @Test
    public void toaTakesChallengeCompletionTimeOverTheWardensDuration() {
        Matcher m = timeMatcherFor(TOA_PB_MESSAGE);
        assertEquals("8:31", m.group("duration"));
        assertEquals("(new personal best)", m.group("pbIndicator"));
    }

    @Test
    public void toaWallClockTotalIsNotAKillTimeAtAll() {
        assertNull(PbHandler.selectTimeLine(sanitize(TOA_TOTAL_MESSAGE)));
    }

    @Test
    public void coxRaidCompletionIsUnaffected() {
        Matcher m = timeMatcherFor(
            "<col=ef20ff>Congratulations - your raid is complete!</col><br>" +
                "Team size: <col=ff0000>4 players</col> Duration:</col> <col=ff0000>37:04.20</col> " +
                "Personal best: </col><col=ff0000>32:26.40</col>");
        assertEquals("37:04.20", m.group("duration"));
        assertEquals("32:26.40", m.group("pbtime"));
    }

    @Test
    public void singleLineKillTimesAreUnaffected() {
        Matcher pb = timeMatcherFor("Fight duration: <col=ff0000>1:23.40</col> (new personal best)");
        assertEquals("1:23.40", pb.group("duration"));
        assertEquals("(new personal best)", pb.group("pbIndicator"));

        Matcher standing = timeMatcherFor(
            "Fight duration: <col=ff0000>2:30</col>. Personal best: 2:15.60");
        assertEquals("2:30", standing.group("duration"));
        assertEquals("2:15.60", standing.group("pbtime"));

        Matcher gauntlet = timeMatcherFor(
            "Challenge duration: <col=ff0000>10:30</col>. Personal best: 9:45");
        assertEquals("10:30", gauntlet.group("duration"));
    }

    /**
     * The shape that poisoned ~47 ToB rows between 2026-08-04 and 08-17: a
     * non-PB raid, where the completion line carries no PB marker so nothing
     * returned early and the fallback took Verzik's room split as the raid
     * time. 5:34.20 is not a Theatre of Blood time; it is roughly a third of
     * the world record.
     */
    private static final String TOB_NON_PB_TOTAL_HOLDS_THE_BEST =
        "Wave 'The Final Challenge' (Normal Mode) complete!<br>" +
            "Duration: <col=ff0000>5:34.20</col><br>" +
            "Theatre of Blood completion time: <col=ff0000>18:54.60</col><br>" +
            "Theatre of Blood total completion time: <col=ff0000>21:42.60</col>. Personal best: 20:45.00";

    /** A room that was itself a PB, on a raid that was not. */
    private static final String TOB_ROOM_PB_ONLY =
        "Wave 'The Final Challenge' (Normal Mode) complete!<br>" +
            "Duration: <col=ff0000>4:53.80</col> (new personal best)<br>" +
            "Theatre of Blood completion time: <col=ff0000>19:14.40</col>";

    @Test
    public void tobNonPbRaidTakesTheCompletionTimeNotTheVerzikSplit() {
        Matcher m = timeMatcherFor(TOB_NON_PB_TOTAL_HOLDS_THE_BEST);
        assertEquals("18:54.60", m.group("duration"));
        assertNull("the room split must not be reported as the raid time", m.group("pbIndicator"));
        assertEquals(Duration.ofMinutes(18).plusSeconds(54).plusMillis(600),
            PbHandler.parseTime(m.group("duration")));
    }

    @Test
    public void tobRoomPersonalBestDoesNotHijackTheRaidTime() {
        // The only (new personal best) in this message sits on the room line,
        // so a "prefer the PB-flagged line" rule alone would submit 4:53.80.
        Matcher m = timeMatcherFor(TOB_ROOM_PB_ONLY);
        assertEquals("19:14.40", m.group("duration"));
    }

    @Test
    public void withoutAnyPbInfoTheFirstTimedLineStillWins() {
        // Unchanged fallback: what a single scan of the whole message returned.
        Matcher m = timeMatcherFor("Wave 'The Final Challenge' complete!<br>" +
            "Duration: <col=ff0000>2:42.0</col><br>Something else: <col=ff0000>9:99</col>");
        assertEquals("2:42.0", m.group("duration"));
    }

    @Test
    public void messagesWithNoTimeYieldNothing() {
        assertNull(PbHandler.selectTimeLine("Your completed Theatre of Blood count is: 73."));
        assertNull(PbHandler.selectTimeLine(""));
        assertNull(PbHandler.selectTimeLine(null));
    }

    // === raid team-size bracketing ===

    @Test
    public void rosterSizeBeatsDecayedCompletionVarbits() {
        // Orbs already read "just me" at loot-chest time; the roster still
        // knows the party.
        assertEquals("5", PbHandler.formatRaidTeamSize(5, 1));
    }

    @Test
    public void varbitsRemainTheFallbackWithoutARoster() {
        assertEquals("4", PbHandler.formatRaidTeamSize(0, 4));
        assertEquals("Solo", PbHandler.formatRaidTeamSize(0, 1));
    }

    @Test
    public void agreeingSourcesKeepTheirBracket() {
        assertEquals("Solo", PbHandler.formatRaidTeamSize(1, 1));
        assertEquals("2", PbHandler.formatRaidTeamSize(2, 2));
    }

    @Test
    public void liveVarbitsCanExceedAStaleRoster() {
        // The max wins in both directions.
        assertEquals("5", PbHandler.formatRaidTeamSize(3, 5));
    }

    @Test
    public void noSourcesPreservesTheLegacyZeroBracket() {
        assertEquals("0", PbHandler.formatRaidTeamSize(0, 0));
    }
}

package io.droptracker.events;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

import io.droptracker.DropTrackerConfig;
import io.droptracker.DropTrackerPlugin;
import io.droptracker.testing.RuneLiteStubs;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.DBTableID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Drives {@link SlayerHandler} the way the client does: var updates arrive as
 * events and are read at the end of the frame, chat lines arrive as text, and
 * the handler decides on the tick.
 *
 * <p>The cache rows are real ({@code slayer_task}, {@code slayer_task_sublist}),
 * trimmed to the assignments these tests hand out.
 */
public class SlayerHandlerTest {

    private static final int TURAEL = 1;
    private static final int DURADEL = 5;
    private static final int NIEVE = 6;
    private static final int KRYSTILIA = 7;
    private static final int KONAR = 8;

    private static final int BIRDS = 5;
    private static final int DUST_DEVILS = 49;
    private static final int CAVE_KRAKEN = 92;
    private static final int HYDRAS = 113;
    private static final int BOSS = SlayerHandler.BOSS_TASK_ID;

    private static final int CAVE_KRAKEN_BOSS = 18;
    private static final int CHAOS_ELEMENTAL = 12;

    /* slayer_task: task id -> row, row -> name. */
    private static final Map<Integer, Integer> TASK_ROWS = new HashMap<>();
    private static final Map<Integer, String> TASK_NAMES = new HashMap<>();
    /* slayer_task_sublist: boss id -> row, row -> slayer_task row. */
    private static final Map<Integer, Integer> BOSS_ROWS = new HashMap<>();
    private static final Map<Integer, Integer> BOSS_TASK_ROWS = new HashMap<>();

    static {
        task(BIRDS, 6218, "Birds");
        task(DUST_DEVILS, 6262, "Dust Devils");
        task(CAVE_KRAKEN, 6304, "Cave Kraken");
        task(HYDRAS, 6326, "Hydras");
        task(BOSS, 6311, "Boss");
        TASK_NAMES.put(6187, "The Cave Kraken boss");
        BOSS_ROWS.put(CAVE_KRAKEN_BOSS, 6186);
        BOSS_TASK_ROWS.put(6186, 6187);
        // The Chaos Elemental's rows are left out: a boss the tables don't know.
    }

    private static void task(int id, int row, String name) {
        TASK_ROWS.put(id, row);
        TASK_NAMES.put(row, name);
    }

    private static final String KRAKEN_LINE =
        "You have completed your task! You killed 150 Cave Kraken. You gained 62,475 xp.";
    private static final String POINTS_LINE =
        "You've completed 1,000 tasks and received 1,000 points, giving you a total of 2,584; return to a Slayer master.";

    private final Map<Integer, Integer> varps = new HashMap<>();
    private final Map<Integer, Integer> varbits = new HashMap<>();
    private final List<Runnable> frameReads = new ArrayList<>();
    private final List<SlayerHandler.Completion> submitted = new ArrayList<>();

    private Client client;
    private DropTrackerConfig config;
    private DropTrackerPlugin plugin;
    private SlayerHandler handler;
    private int tick;

    @Before
    public void setUp() {
        client = RuneLiteStubs.client(RuneLiteStubs.player("Local", 126));
        Map<String, Object> state = RuneLiteStubs.state(client);
        state.put("getVarpValue", (RuneLiteStubs.Answer) args -> read(varps, args));
        state.put("getVarbitValue", (RuneLiteStubs.Answer) args -> read(varbits, args));
        state.put("getDBRowsByValue", (RuneLiteStubs.Answer) SlayerHandlerTest::rowsByValue);
        state.put("getDBTableField", (RuneLiteStubs.Answer) SlayerHandlerTest::tableField);
        state.put("getGameState", GameState.LOGGED_IN);

        config = RuneLiteStubs.stub(DropTrackerConfig.class, "config");
        RuneLiteStubs.state(config).put("slayerEmbeds", true);
        plugin = new DropTrackerPlugin();

        handler = new SlayerHandler() {
            @Override
            void afterVarps(Runnable read) {
                frameReads.add(read);
            }

            @Override
            void submit(Completion completion) {
                submitted.add(completion);
            }
        };
        handler.client = client;
        handler.config = config;
        handler.plugin = plugin;
        tickTo(1);
    }

    // --- the fake client ------------------------------------------------

    private static Object read(Map<Integer, Integer> vars, Object[] args) {
        return args.length == 1 ? vars.getOrDefault((Integer) args[0], 0) : 0;
    }

    private static Object rowsByValue(Object[] args) {
        int table = (Integer) args[0];
        int column = (Integer) args[1];
        Object value = args[3];
        Integer row = null;
        if (table == DBTableID.SlayerTask.ID && column == DBTableID.SlayerTask.COL_ID) {
            row = TASK_ROWS.get(value);
        } else if (table == DBTableID.SlayerTaskSublist.ID
            && column == DBTableID.SlayerTaskSublist.COL_TASK_SUBTABLE_ID) {
            row = BOSS_ROWS.get(value);
        }
        return row == null ? Collections.emptyList() : Collections.singletonList(row);
    }

    private static Object tableField(Object[] args) {
        int row = (Integer) args[0];
        int column = (Integer) args[1];
        if (column == DBTableID.SlayerTaskSublist.COL_TASK && BOSS_TASK_ROWS.containsKey(row)) {
            return new Object[] { BOSS_TASK_ROWS.get(row) };
        }
        if (column == DBTableID.SlayerTask.COL_NAME_UPPERCASE && TASK_NAMES.containsKey(row)) {
            return new Object[] { TASK_NAMES.get(row) };
        }
        return new Object[0];
    }

    private void varp(int id, int value) {
        varps.put(id, value);
        VarbitChanged event = new VarbitChanged();
        event.setVarpId(id);
        event.setValue(value);
        handler.onVarbitChanged(event);
    }

    private void varbit(int id, int value) {
        varbits.put(id, value);
        VarbitChanged event = new VarbitChanged();
        event.setVarbitId(id);
        event.setValue(value);
        handler.onVarbitChanged(event);
    }

    /** The client drains its invokeLater queue once the frame's packets are in. */
    private void endFrame() {
        List<Runnable> reads = new ArrayList<>(frameReads);
        frameReads.clear();
        reads.forEach(Runnable::run);
    }

    private void tickTo(int next) {
        tick = next;
        RuneLiteStubs.state(client).put("getTickCount", next);
    }

    /** One game tick: the frame's reads land, then the tick event. */
    private void nextTick() {
        endFrame();
        tickTo(tick + 1);
        handler.onTick();
    }

    private void assign(int master, int taskId, int amount) {
        varbit(VarbitID.SLAYER_MASTER, master);
        varp(VarPlayerID.SLAYER_TARGET, taskId);
        varp(VarPlayerID.SLAYER_COUNT_ORIGINAL, amount);
        varp(VarPlayerID.SLAYER_COUNT, amount);
        nextTick();
    }

    private void killsLeft(int remaining) {
        varp(VarPlayerID.SLAYER_COUNT, remaining);
    }

    private void chat(String... lines) {
        for (String line : lines) {
            handler.onGameMessage(line);
        }
    }

    private void idle(int ticks) {
        for (int i = 0; i < ticks; i++) {
            nextTick();
        }
    }

    private SlayerHandler.Completion onlySubmission() {
        assertEquals("submissions", 1, submitted.size());
        return submitted.get(0);
    }

    // --- completions ----------------------------------------------------

    @Test
    public void aFinishedTaskIsSubmittedAsTheTaskItWas() {
        assign(DURADEL, CAVE_KRAKEN, 150);
        killsLeft(1);
        nextTick();

        chat(KRAKEN_LINE, POINTS_LINE);
        killsLeft(0);
        nextTick();

        SlayerHandler.Completion done = onlySubmission();
        assertEquals("Cave Kraken", done.getTaskName());
        assertEquals(CAVE_KRAKEN, done.getTaskId());
        assertEquals(DURADEL, done.getMasterId());
        assertFalse(done.isBoss());
        assertEquals(150, done.getAmountInitial());
        assertEquals(150, done.getAmountKilled());
        assertEquals(Integer.valueOf(62475), done.getXpGained());
        assertEquals(Integer.valueOf(1000), done.getStreak());
        assertEquals(Integer.valueOf(1000), done.getPointsAwarded());
        assertEquals(Integer.valueOf(2584), done.getPointsTotal());
        assertEquals(KRAKEN_LINE + " " + POINTS_LINE, done.getCompletionMessage());
    }

    @Test
    public void theCountMayDropBeforeTheLine() {
        assign(DURADEL, CAVE_KRAKEN, 150);
        killsLeft(0);
        nextTick();
        assertTrue(submitted.isEmpty());

        chat(KRAKEN_LINE, POINTS_LINE);
        nextTick();

        assertEquals("Cave Kraken", onlySubmission().getTaskName());
    }

    @Test
    public void theCountMayDropAfterTheLine() {
        assign(DURADEL, CAVE_KRAKEN, 150);
        chat(KRAKEN_LINE, POINTS_LINE);
        nextTick();
        assertTrue(submitted.isEmpty());

        killsLeft(0);
        nextTick();

        assertEquals(DURADEL, onlySubmission().getMasterId());
    }

    @Test
    public void aTaskIsSubmittedOnce() {
        assign(DURADEL, CAVE_KRAKEN, 150);
        chat(KRAKEN_LINE, POINTS_LINE);
        killsLeft(0);
        idle(5);

        assertEquals(1, submitted.size());
    }

    // --- things that are not completions --------------------------------

    /** Cancelling with points, or a task replaced: the count drops, no line. */
    @Test
    public void aCountDropWithoutTheLineIsNotACompletion() {
        assign(DURADEL, CAVE_KRAKEN, 150);
        killsLeft(0);
        idle(3);
        // A stray line well after the drop does not revive it.
        chat(KRAKEN_LINE, POINTS_LINE);
        idle(5);

        assertTrue(submitted.isEmpty());
    }

    /** Anything can print a line; only the game can zero the count. */
    @Test
    public void theLineWithoutACountDropIsNotACompletion() {
        assign(DURADEL, CAVE_KRAKEN, 150);
        chat(KRAKEN_LINE, POINTS_LINE);
        idle(5);
        // The count dropping much later is some other event.
        killsLeft(0);
        idle(5);

        assertTrue(submitted.isEmpty());
    }

    @Test
    public void theLineWithNoTaskLiveIsNotACompletion() {
        chat(KRAKEN_LINE, POINTS_LINE);
        killsLeft(0);
        idle(5);

        assertTrue(submitted.isEmpty());
    }

    /** A login or hop re-sends the varps; a count reading zero then ends nothing. */
    @Test
    public void aHopSyncIsNotACompletion() {
        assign(DURADEL, CAVE_KRAKEN, 150);
        handler.onGameStateChanged(GameState.HOPPING);
        killsLeft(0);
        endFrame();
        chat(KRAKEN_LINE, POINTS_LINE);
        idle(5);

        assertTrue(submitted.isEmpty());
    }

    /** A hop that changes nothing sends no var events; the task must survive it. */
    @Test
    public void aTaskFinishedAfterAHopStillCounts() {
        assign(DURADEL, CAVE_KRAKEN, 150);
        handler.onGameStateChanged(GameState.HOPPING);
        handler.onGameStateChanged(GameState.LOGGED_IN);
