    // --- what a completion carries --------------------------------------

    @Test
    public void aBossTaskIsNamedAfterItsBoss() {
        assign(NIEVE, BOSS, 50);
        varbit(VarbitID.SLAYER_TARGET_BOSSID, CAVE_KRAKEN_BOSS);
