        SlayerHandler.Completion done = onlySubmission();
        assertEquals(130, done.getAmountInitial());
        assertEquals(130, done.getAmountKilled());
    }

    /**
     * If the game clears the other task vars in the same batch as the count,
     * reading between updates would report a task with no master and no name.
     * The task is read once the batch is in, so the count drop still finds it.
     */
    @Test
    public void varsClearedAlongsideTheCountDoNotRewriteTheTask() {
        assign(DURADEL, CAVE_KRAKEN, 150);
        chat(KRAKEN_LINE, POINTS_LINE);
        varbit(VarbitID.SLAYER_MASTER, 0);
        varp(VarPlayerID.SLAYER_TARGET, 0);
        killsLeft(0);
        nextTick();

        SlayerHandler.Completion done = onlySubmission();
        assertEquals("Cave Kraken", done.getTaskName());
        assertEquals(CAVE_KRAKEN, done.getTaskId());
        assertEquals(DURADEL, done.getMasterId());
    }

    /** A new task replaces the old one wholesale, master included. */
    @Test
    public void theNextTaskIsReportedWithItsOwnMaster() {
        assign(DURADEL, CAVE_KRAKEN, 150);
        chat(KRAKEN_LINE, POINTS_LINE);
        killsLeft(0);
        nextTick();
        submitted.clear();

        assign(NIEVE, DUST_DEVILS, 100);
        chat("You have completed your task! You killed 100 Dust Devils. You gained 9,000 xp.",
            "You've completed 1,001 tasks and received 12 points, giving you a total of 2,596; return to a Slayer master.");
        killsLeft(0);
        nextTick();

        SlayerHandler.Completion done = onlySubmission();
        assertEquals("Dust Devils", done.getTaskName());
        assertEquals(NIEVE, done.getMasterId());
        assertEquals(100, done.getAmountInitial());
        assertEquals(Integer.valueOf(1001), done.getStreak());
    }

    // --- fields ---------------------------------------------------------

    @Test
    public void fieldsCarryWhatTheServerReads() {
        SlayerHandler.Completion done = new SlayerHandler.Completion(
            "The Cave Kraken boss", BOSS, CAVE_KRAKEN_BOSS, NIEVE, 0, 50, 50,
            14200, 150, 10, 200, "line");

        Map<String, Object> fields = SlayerHandler.fields(done, 1_700_000_000L);

        assertEquals("The Cave Kraken boss", fields.get("task_name"));
        assertEquals(BOSS, fields.get("task_id"));
        assertEquals(true, fields.get("is_boss"));
        assertEquals(CAVE_KRAKEN_BOSS, fields.get("boss_id"));
        assertEquals(NIEVE, fields.get("master_id"));
        assertEquals(50, fields.get("amount_initial"));
        assertEquals(50, fields.get("amount_killed"));
        assertEquals(14200, fields.get("xp_gained"));
        assertEquals(150, fields.get("streak"));
        assertEquals(10, fields.get("points_awarded"));
        assertEquals(200, fields.get("points_total"));
        assertEquals("line", fields.get("completion_message"));
        assertEquals(1_700_000_000L, fields.get("timestamp"));
        assertFalse("no area outside Konar", fields.containsKey("area_id"));
    }

    /**
     * addFields turns null into "N/A", which the server would keep as text: a
     * master called "N/A", a message reading "N/A". Unknowns stay out.
     */
    @Test
    public void unknownsAreLeftOut() {
        SlayerHandler.Completion done = new SlayerHandler.Completion(
            "Birds", BIRDS, 0, TURAEL, 0, 0, 20, null, null, null, null, "line");

        Map<String, Object> fields = SlayerHandler.fields(done, 1L);

        assertFalse(fields.containsValue(null));
        assertFalse(fields.containsKey("boss_id"));
        assertFalse(fields.containsKey("amount_initial"));
        assertFalse(fields.containsKey("xp_gained"));
        assertFalse(fields.containsKey("streak"));
        assertFalse(fields.containsKey("points_awarded"));
        assertFalse(fields.containsKey("points_total"));
        assertFalse(fields.containsKey("master_name"));
        assertEquals(false, fields.get("is_boss"));
    }
}

package io.droptracker.events;

import org.junit.Test;

import java.util.regex.Matcher;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Tests {@link ClogHandler#COLLECTION_LOG_REGEX}, which lifts the item name out
 * of the "New item added to your collection log:" chat message.
 */
public class ClogHandlerRegexTest {

    @Test
    public void capturesItemName() {
        Matcher m = ClogHandler.COLLECTION_LOG_REGEX.matcher(
                "New item added to your collection log: Twisted bow");
        assertTrue(m.find());
        assertEquals("Twisted bow", m.group("itemName"));
    }

    @Test
    public void capturesItemNameWithPunctuation() {
        Matcher m = ClogHandler.COLLECTION_LOG_REGEX.matcher(
                "New item added to your collection log: Vet'ion jr.");
        assertTrue(m.find());
        assertEquals("Vet'ion jr.", m.group("itemName"));
    }

    @Test
    public void doesNotMatchUnrelatedMessage() {
        assertFalse(ClogHandler.COLLECTION_LOG_REGEX.matcher(
                "You have a funny feeling like you're being followed.").find());
    }
}

package io.droptracker.events;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;

/**
 * The three slayer chat lines. The wording is verbatim from game captures
 * (Dink's SlayerNotifierTest), variants included.
 */
public class SlayerHandlerParseTest {

    // --- "You have completed your task!" --------------------------------

    @Test
    public void readsTheTaskLine() {
        SlayerHandler.TaskLine line = SlayerHandler.parseTaskLine(
            "You have completed your task! You killed 245 Cave Kraken. You gained 62,475 xp.").get();
        assertEquals(245, line.getKilled());
        assertEquals("Cave Kraken", line.getName());
        assertEquals(Integer.valueOf(62475), line.getXp());
    }

    @Test
    public void readsASingleKillWithAHyphenatedName() {
        SlayerHandler.TaskLine line = SlayerHandler.parseTaskLine(
            "You have completed your task! You killed 1 TzTok-Jad. You gained 69,420 xp.").get();
        assertEquals(1, line.getKilled());
        assertEquals("TzTok-Jad", line.getName());
    }

    @Test
    public void readsABossTaskLine() {
        SlayerHandler.TaskLine line = SlayerHandler.parseTaskLine(
            "You have completed your task! You killed 50 Bosses. You gained 14,200 xp.").get();
        assertEquals(50, line.getKilled());
        assertEquals("Bosses", line.getName());
    }

    @Test
    public void theXpIsOptional() {
        SlayerHandler.TaskLine line = SlayerHandler.parseTaskLine(
            "You have completed your task! You killed 1,020 Birds.").get();
        assertEquals(1020, line.getKilled());
        assertEquals("Birds", line.getName());
        assertNull(line.getXp());
    }

    @Test
    public void otherLinesAreNotTaskLines() {
        assertFalse(SlayerHandler.parseTaskLine("You're assigned to kill Cave Kraken; only 150 more to go.").isPresent());
        assertFalse(SlayerHandler.parseTaskLine("You have completed your task!").isPresent());
        assertFalse(SlayerHandler.parseTaskLine(
            "Congratulations, you've completed a hard combat task: Kraken Adept (3 points).").isPresent());
    }

    // --- "You've completed N tasks" -------------------------------------

    @Test
    public void readsStreakAndPoints() {
        SlayerHandler.StreakLine line = SlayerHandler.parseStreakLine(
            "You've completed 1,000 tasks and received 1,000 points, giving you a total of 2,584; return to a Slayer master.").get();
        assertEquals(1000, line.getStreak());
        assertEquals(Integer.valueOf(1000), line.getPointsAwarded());
        assertEquals(Integer.valueOf(2584), line.getPointsTotal());
    }

    @Test
    public void readsTheCommaVariant() {
        SlayerHandler.StreakLine line = SlayerHandler.parseStreakLine(
            "You've completed 1,000 tasks and received 1,000 points, giving you a total of 2,584, return to a Slayer master.").get();
        assertEquals(Integer.valueOf(2584), line.getPointsTotal());
    }

    @Test
    public void readsWildernessAndMortimerStreaks() {
        assertEquals(5, SlayerHandler.parseStreakLine(
            "You've completed 5 Wilderness tasks and received 25 points, giving you a total of 1,234; return to a Slayer master.")
            .get().getStreak());
        assertEquals(12, SlayerHandler.parseStreakLine(
            "You've completed 12 Mortimer tasks and received 10 points, giving you a total of 300; return to a Slayer master.")
            .get().getStreak());
    }

    @Test
    public void readsAtLeast() {
        assertEquals(1000, SlayerHandler.parseStreakLine(
            "You've completed at least 1,000 tasks and received 15 points, giving you a total of 3,000; return to a Slayer master.")
            .get().getStreak());
    }

    @Test
    public void aMasterThatAwardsNothingAwardsZero() {
        SlayerHandler.StreakLine line = SlayerHandler.parseStreakLine(
            "You've completed 17 tasks.You'll be eligible to earn reward points if you complete tasks from a more advanced Slayer Master.").get();
        assertEquals(17, line.getStreak());
        assertEquals(Integer.valueOf(0), line.getPointsAwarded());
        assertNull(line.getPointsTotal());
    }

    @Test
    public void atTheCapTheTotalIsKnownButNotTheAward() {
        SlayerHandler.StreakLine line = SlayerHandler.parseStreakLine(
            "You've completed 500 tasks and reached the maximum amount of Slayer points (64,000).").get();
        assertEquals(500, line.getStreak());
        assertNull(line.getPointsAwarded());
        assertEquals(Integer.valueOf(64000), line.getPointsTotal());
    }

    @Test
    public void aCombatTaskIsNotAStreakLine() {
        assertFalse(SlayerHandler.parseStreakLine(
            "Congratulations, you've completed an elite combat task: Nightmare Veteran (4 points).").isPresent());
    }

    // --- the boss reward line -------------------------------------------

    @Test
    public void readsTheBossTheWayTheCacheSpellsIt() {
        assertEquals("The Cave Kraken boss", SlayerHandler.parseBossLine(
            "You are granted an extra reward of 5k Slayer XP for completing your boss task against the Cave Kraken boss.").get());
        assertEquals("Barrows brothers", SlayerHandler.parseBossLine(
            "You are granted an extra reward of 5k Slayer XP for completing your boss task against Barrows brothers.").get());
        assertEquals("The Chaos Elemental", SlayerHandler.parseBossLine(
            "You are granted an extra reward of 5k Slayer XP for completing your boss task against the Chaos Elemental.").get());
    }
}

package io.droptracker.events;

import java.util.Collections;
import java.util.EnumSet;

import io.droptracker.DropTrackerConfig;
import io.droptracker.testing.RuneLiteStubs;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.WorldType;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.InteractingChanged;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Tests {@link DeathHandler#identifyKiller}, which decides what a death
 * submission reports as its source.
 *
 * <p>Attribution has two layers: a live scan for whoever is still targeting the
 * local player, and — when that finds nobody, which in production is most of the
 * time — the engagement history built from {@code InteractingChanged}. Without
 * the second layer the submission goes out with no source and a killer type of
 * "unknown".
 */
public class DeathHandlerKillerAttributionTest {

    private DeathHandler handler;
    private Player localPlayer;
    private Client client;

    @Before
    public void setUp() {
        handler = new DeathHandler();
        localPlayer = RuneLiteStubs.player("Local", 126);
        client = RuneLiteStubs.client(localPlayer);
        handler.client = client;
        handler.config = RuneLiteStubs.stub(DropTrackerConfig.class, "config");
    }

    private void tick(int tick) {
        RuneLiteStubs.state(client).put("getTickCount", tick);
    }

    private void targets(NPC npc, Object target) {
        RuneLiteStubs.state(npc).put("getInteracting", target);
    }

    // --- live scan ------------------------------------------------------

    @Test
    public void npcStillAttackingUsIsAttributed() {
        NPC vorkath = RuneLiteStubs.npc(1, 8061, "Vorkath", 732);
        targets(vorkath, localPlayer);
        RuneLiteStubs.setScene(client, localPlayer, Collections.emptyList(), Collections.singletonList(vorkath));

        DeathHandler.Killer killer = handler.identifyKiller(localPlayer);
        assertNotNull(killer);
        assertEquals("Vorkath", killer.getName());
        assertEquals(Integer.valueOf(8061), killer.getNpcId());
        assertTrue(killer.isNpc());
        assertFalse(killer.isPlayer());
    }

    /**
     * Instanced NPCs sometimes report no name of their own; the composition still
     * has one, and an embed with an NPC id but no source is what a blank killer
     * looks like on the site.
     */
    @Test
    public void npcWithNoNameOfItsOwnFallsBackToItsComposition() {
        NPC boss = RuneLiteStubs.npc(1, 11751, "The Whisperer", 480);
        RuneLiteStubs.state(boss).put("getName", null);
        targets(boss, localPlayer);
        RuneLiteStubs.setScene(client, localPlayer, Collections.emptyList(), Collections.singletonList(boss));

        assertEquals("The Whisperer", handler.identifyKiller(localPlayer).getName());
    }

    // --- the fallback ---------------------------------------------------

    /**
     * The production failure. The boss dropped its target when we died and the
     * instance took it out of the scene, so nothing is left to scan — but the
     * interaction history still knows who we were fighting two ticks ago.
     */
    @Test
    public void deathWithNothingLeftToScanIsAttributedFromRecentCombat() {
        NPC vorkath = RuneLiteStubs.npc(1, 8061, "Vorkath", 732);

        tick(100);
        handler.onInteractingChanged(new InteractingChanged(localPlayer, vorkath));
        handler.onInteractingChanged(new InteractingChanged(vorkath, localPlayer));

        // Death tick: it lets go of us and leaves the scene entirely.
        tick(118);
        handler.onInteractingChanged(new InteractingChanged(vorkath, null));
        RuneLiteStubs.setScene(client, localPlayer, Collections.emptyList(), Collections.emptyList());

        DeathHandler.Killer killer = handler.identifyKiller(localPlayer);
        assertNotNull("a death with no live attacker must still name a killer", killer);
        assertEquals("Vorkath", killer.getName());
        assertEquals(Integer.valueOf(8061), killer.getNpcId());
        assertEquals(732, killer.getCombatLevel());
    }

    /**
     * Regression: only the local player's outbound target used to be recorded,
     * so anything that attacked us without us ever clicking it — the common way
     * to die — left no trace at all.
     */
    @Test
    public void anNpcAttackingUsIsRememberedEvenIfWeNeverAttackedIt() {
        NPC dagannoth = RuneLiteStubs.npc(1, 100, "Dagannoth", 90);

        tick(50);
        handler.onInteractingChanged(new InteractingChanged(dagannoth, localPlayer));
        assertEquals(1, handler.recentCombat.size());

        tick(52);
        assertEquals("Dagannoth", handler.identifyKiller(localPlayer).getName());
    }

    @Test
    public void aDeathNothingExplainsIsStillReportedAsUnattributed() {
        // Poison, falling damage, a wilderness dragonfire wall: nothing ever
        // engaged us, so there is nobody to blame and we say so.
        assertNull(handler.identifyKiller(localPlayer));
    }

    // --- players --------------------------------------------------------

    @Test
    public void aPlayerIsNotBlamedOutsidePvp() {
        Player bystander = RuneLiteStubs.player("Zezima", 126);
        RuneLiteStubs.state(bystander).put("getInteracting", localPlayer);
        RuneLiteStubs.setScene(client, localPlayer, Collections.singletonList(bystander), Collections.emptyList());

        tick(10);
        handler.onInteractingChanged(new InteractingChanged(bystander, localPlayer));

        assertNull(handler.identifyKiller(localPlayer));
    }

    @Test
    public void aPkerInTheWildernessIsAttributed() {
        insideWilderness();
        Player pker = RuneLiteStubs.player("Zezima", 126);
        RuneLiteStubs.state(pker).put("getInteracting", localPlayer);
        RuneLiteStubs.setScene(client, localPlayer, Collections.singletonList(pker), Collections.emptyList());

        DeathHandler.Killer killer = handler.identifyKiller(localPlayer);
        assertNotNull(killer);
        assertEquals("Zezima", killer.getName());
        assertTrue(killer.isPlayer());
        assertNull(killer.getNpcId());
    }

    /**
     * A PvP world's bank is a safe zone: nobody standing there can have killed
     * us, so no bystander should be named.
     */
    @Test
    public void nobodyIsBlamedInsideAPvpSafeZone() {
        RuneLiteStubs.state(client).put("getWorldType", EnumSet.of(WorldType.PVP));
        RuneLiteStubs.state(client).put("getWidget", RuneLiteStubs.visibleWidget());

        Player bystander = RuneLiteStubs.player("Zezima", 126);
        RuneLiteStubs.state(bystander).put("getInteracting", localPlayer);
        RuneLiteStubs.setScene(client, localPlayer, Collections.singletonList(bystander), Collections.emptyList());

        assertNull(handler.identifyKiller(localPlayer));
    }

    /** A dead attacker is a corpse we outlived, not our killer. */
    @Test
    public void anNpcThatDiedFirstIsNotBlamed() {
        NPC dying = RuneLiteStubs.npc(1, 100, "Dagannoth", 90);
        targets(dying, localPlayer);

        tick(20);
        handler.onInteractingChanged(new InteractingChanged(dying, localPlayer));
        RuneLiteStubs.state(dying).put("isDead", true);
        RuneLiteStubs.setScene(client, localPlayer, Collections.emptyList(), Collections.singletonList(dying));

        assertNull(handler.identifyKiller(localPlayer));
    }

    // --- history lifecycle ----------------------------------------------

    @Test
    public void ourOwnDeathWipesTheHistory() {
        NPC vorkath = RuneLiteStubs.npc(1, 8061, "Vorkath", 732);
        tick(100);
        handler.onInteractingChanged(new InteractingChanged(vorkath, localPlayer));
        assertEquals(1, handler.recentCombat.size());

        // deathEmbeds() is false on the stub, so the handler skips the
        // submission — the history must still be reset for the next life.
        handler.onActorDeath(new ActorDeath(localPlayer));
        assertEquals(0, handler.recentCombat.size());
    }

    @Test
    public void killingSomethingRemovesItFromTheHistory() {
        NPC vorkath = RuneLiteStubs.npc(1, 8061, "Vorkath", 732);
        tick(100);
        handler.onInteractingChanged(new InteractingChanged(localPlayer, vorkath));
        assertEquals(1, handler.recentCombat.size());

        handler.onActorDeath(new ActorDeath(vorkath));
        assertEquals(0, handler.recentCombat.size());
    }

    @Test
    public void interactingWithAHarmlessNpcLeavesNoCandidate() {
        NPC banker = RuneLiteStubs.npc(1, 1613, "Banker", 0, false, false);
        tick(100);
        handler.onInteractingChanged(new InteractingChanged(localPlayer, banker));

        assertEquals(0, handler.recentCombat.size());
        assertNull(handler.identifyKiller(localPlayer));
    }

    private void insideWilderness() {
        RuneLiteStubs.state(client).put("getVarbitValue", 1);
    }

    /**
     * Guards the stub itself: if the scene helper handed back an empty set the
     * live-scan tests above would pass for the wrong reason.
     */
    @Test
    public void sceneStubExposesItsNpcsToTheScan() {
        NPC npc = RuneLiteStubs.npc(1, 100, "Goblin", 2);
        RuneLiteStubs.setScene(client, localPlayer, Collections.emptyList(), Collections.singletonList(npc));
        assertEquals(1L, localPlayer.getWorldView().npcs().stream().count());
    }
}

package io.droptracker.events;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

/**
 * Tests the trawling catch-message parser and the trawling-species id map
 * exposed via {@code @VisibleForTesting}. The species map doubles as the
 * allowlist that keeps ordinary fishing "You catch a ..." messages from being
 * submitted as trawling loot.
 */
public class TrawlingHandlerParseTest {

    @Test
    public void parsesSingleCatch() {
        TrawlingHandler.ParsedCatch parsed = TrawlingHandler.parseCatch("You catch a raw halibut!");
        assertNotNull(parsed);
        assertEquals("raw halibut", parsed.getFishName());
        assertEquals(1, parsed.getQuantity());
    }

    @Test
    public void parsesMultiCatchWithCount() {
        TrawlingHandler.ParsedCatch parsed = TrawlingHandler.parseCatch("You catch 2 raw giant krill!");
        assertNotNull(parsed);
        assertEquals("raw giant krill", parsed.getFishName());
        assertEquals(2, parsed.getQuantity());
    }

    @Test
    public void parsesAnArticleAndPeriodEnding() {
        TrawlingHandler.ParsedCatch parsed = TrawlingHandler.parseCatch("You catch an orangefin.");
        assertNotNull(parsed);
        assertEquals("orangefin", parsed.getFishName());
        assertEquals(1, parsed.getQuantity());
    }

    @Test
    public void rejectsCrewmateCatches() {
        assertNull(TrawlingHandler.parseCatch("First mate Dave catches 3 raw haddock!"));
        assertNull(TrawlingHandler.parseCatch("Koeppy catches a raw marlin!"));
    }

    @Test
    public void rejectsTrawlersTrustBonusLines() {
        assertNull(TrawlingHandler.parseCatch("Your Trawler's trust grants you an extra catch: You catch a raw bluefin!"));
    }

    @Test
    public void rejectsNetCollectionMessages() {
        assertNull(TrawlingHandler.parseCatch("You empty the net into your cargo hold."));
        assertNull(TrawlingHandler.parseCatch("You take all of the fish from the net."));
        assertNull(TrawlingHandler.parseCatch("You take some fish from the net"));
    }

    @Test
    public void rejectsZeroQuantity() {
        assertNull(TrawlingHandler.parseCatch("You catch 0 raw haddock!"));
    }

    @Test
    public void resolvesAllTrawlingSpecies() {
        assertEquals(Integer.valueOf(32309), TrawlingHandler.resolveFishId("raw giant krill"));
        assertEquals(Integer.valueOf(32317), TrawlingHandler.resolveFishId("raw haddock"));
        assertEquals(Integer.valueOf(32325), TrawlingHandler.resolveFishId("raw yellowfin"));
        assertEquals(Integer.valueOf(32333), TrawlingHandler.resolveFishId("raw halibut"));
        assertEquals(Integer.valueOf(32341), TrawlingHandler.resolveFishId("raw bluefin"));
        assertEquals(Integer.valueOf(32349), TrawlingHandler.resolveFishId("raw marlin"));
    }

    @Test
    public void resolvesTrophyFish() {
        assertEquals(Integer.valueOf(31408), TrawlingHandler.resolveFishId("giant blue krill"));
        assertEquals(Integer.valueOf(31412), TrawlingHandler.resolveFishId("golden haddock"));
        assertEquals(Integer.valueOf(31416), TrawlingHandler.resolveFishId("orangefin"));
        assertEquals(Integer.valueOf(31420), TrawlingHandler.resolveFishId("huge halibut"));
        assertEquals(Integer.valueOf(31424), TrawlingHandler.resolveFishId("purplefin"));
        assertEquals(Integer.valueOf(31428), TrawlingHandler.resolveFishId("swift marlin"));
    }

    @Test
    public void resolvesPluralizedNames() {
        assertEquals(Integer.valueOf(32317), TrawlingHandler.resolveFishId("raw haddocks"));
        assertEquals(Integer.valueOf(32349), TrawlingHandler.resolveFishId("marlins"));
    }

    @Test
    public void ordinaryFishingSpeciesDoNotResolve() {
        assertNull(TrawlingHandler.resolveFishId("lobster"));
        assertNull(TrawlingHandler.resolveFishId("swordfish"));
        assertNull(TrawlingHandler.resolveFishId("shark"));
        assertNull(TrawlingHandler.resolveFishId("raw anglerfish"));
    }
}

package io.droptracker.events;

import io.droptracker.models.submissions.CombatAchievement;
import org.apache.commons.lang3.tuple.Pair;
import org.junit.Test;

import java.util.Optional;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Tests {@link CaHandler#parseCombatAchievement} (exposed {@code @VisibleForTesting}):
 * it maps the tier word to a {@link CombatAchievement} and strips the trailing
 * "(N points)" suffix from the task name.
 */
public class CaHandlerParseTest {

    @Test
    public void parsesTierAndTaskName() {
        Optional<Pair<CombatAchievement, String>> result = CaHandler.parseCombatAchievement(
                "Congratulations, you've completed an elite combat task: A Slow Death.");
        assertTrue(result.isPresent());
        assertEquals(CombatAchievement.ELITE, result.get().getLeft());
        assertEquals("A Slow Death", result.get().getRight());
    }

    @Test
    public void stripsTrailingPointsSuffixFromTask() {
        Optional<Pair<CombatAchievement, String>> result = CaHandler.parseCombatAchievement(
                "Congratulations, you've completed a hard combat task: Whack-a-Mole (3 points).");
        assertTrue(result.isPresent());
        assertEquals(CombatAchievement.HARD, result.get().getLeft());
        assertEquals("Whack-a-Mole", result.get().getRight());
    }

    @Test
    public void handlesArticleVariationAAndAn() {
        assertEquals(CombatAchievement.MASTER, CaHandler.parseCombatAchievement(
                "Congratulations, you've completed a master combat task: Peach Conjurer.").get().getLeft());
        assertEquals(CombatAchievement.EASY, CaHandler.parseCombatAchievement(
                "Congratulations, you've completed an easy combat task: Off the Chain.").get().getLeft());
    }

    /**
     * Regression, 2026-08-26: Jagex began wrapping the task name in the
     * {@code @ach_comp@} click-through token. The token travelled with the name
     * into the panel and the submission, and because the server keys a
     * completion on its name, every marked-up task read as one nobody had ever
     * done — a duplicate row and a duplicate notification apiece.
     */
    @Test
    public void stripsAchCompChatToken() {
        Optional<Pair<CombatAchievement, String>> result = CaHandler.parseCombatAchievement(
                "Congratulations, you've completed a hard combat task: @ach_comp@Smite Fight.");
        assertTrue(result.isPresent());
        assertEquals(CombatAchievement.HARD, result.get().getLeft());
        assertEquals("Smite Fight", result.get().getRight());
    }

    @Test
    public void stripsChatTokenAlongsidePointsSuffix() {
        assertEquals("Whack-a-Mole", CaHandler.parseCombatAchievement(
                "Congratulations, you've completed a hard combat task: @ach_comp@Whack-a-Mole (3 points).")
                .get().getRight());
    }

    @Test
    public void cleanTaskNameLeavesOrdinaryNamesAlone() {
        assertEquals("Smite Fight", CaHandler.cleanTaskName("Smite Fight"));
        assertEquals("You're a wizard", CaHandler.cleanTaskName("You're a wizard"));
        assertEquals("", CaHandler.cleanTaskName(null));
    }

    @Test
    public void cleanTaskNameHandlesATrailingToken() {
        // The points suffix anchors on end-of-string, so markup is stripped
        // first; this is what that ordering buys.
        assertEquals("Smite Fight", CaHandler.cleanTaskName("Smite Fight (2 points)@ach_comp@"));
    }

    @Test
    public void returnsEmptyWhenTheTaskNameIsNothingButMarkup() {
        assertFalse(CaHandler.parseCombatAchievement(
                "Congratulations, you've completed a hard combat task: @ach_comp@.").isPresent());
    }

    @Test
    public void keepsTheTrailingPeriodOfTasksThatEndInOne() {
        // Four real tasks end in a period or an ellipsis; stripping it would
        // fork each of them off its own history on the server.
        assertEquals("Back in My Day...", CaHandler.parseCombatAchievement(
                "Congratulations, you've completed a master combat task: @ach_comp@Back in My Day....")
                .get().getRight());
    }

    @Test
    public void returnsEmptyForUnknownTierWord() {
        assertFalse(CaHandler.parseCombatAchievement(
                "Congratulations, you've completed a legendary combat task: Nope.").isPresent());
    }

    @Test
    public void returnsEmptyForUnrelatedMessage() {
        assertFalse(CaHandler.parseCombatAchievement("You have completed 100 hard Treasure Trails.").isPresent());
        assertFalse(CaHandler.parseCombatAchievement("").isPresent());
    }
}

