package io.droptracker.models.api;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Wire-format tests for {@code GET /manifest}, pinning the plugin's parsing of
 * the server contract against bodies shaped like the ones production serves.
 *
 * <p>The case that matters most is {@link #survivesASectionChangingShape()}.
 * The server changed {@code combat_achievement_tasks} from an array to an
 * object; parsing the document in one shot meant Gson abandoned it at that
 * field, so clients silently lost the varp list, the quest ids and the sync
 * kill switch as well, and the only trace was a single debug line reading
 * "Expected BEGIN_ARRAY but was BEGIN_OBJECT".
 */
public class ManifestParseTest {

    private final Gson gson = new Gson();

    /** Keys are served sorted, so the sections a client cares about come last. */
    private static final String LIVE_SHAPE =
        "{\"collection_log\":[{\"name\":\"Bosses\",\"pages\":[{\"name\":\"Abyssal Sire\","
            + "\"items\":[13262,13265,13277]}]}],"
            + "\"combat_achievement_tasks\":{\"varps\":[3116,3117],\"tasks\":["
            + "{\"index\":0,\"varp\":3116,\"bit\":0,\"tier\":\"Easy\",\"tier_id\":1,"
            + "\"name\":\"Noxious Foe\",\"description\":\"Kill an Aberrant Spectre.\","
            + "\"type\":\"Kill Count\",\"monster\":\"Aberrant Spectre\"}]},"
            + "\"combat_achievement_varps\":[3116,3117,3387,5673],"
            + "\"quest_ids\":[3,11],"
            + "\"sync\":{\"enabled\":true,\"interval_minutes\":90,\"rapid_seconds\":5},"
            + "\"version\":\"71c8790895b1\"}";

    @Test
    public void survivesASectionChangingShape() {
        Manifest manifest = Manifest.fromJson(gson, LIVE_SHAPE);

        assertNotNull(manifest);
        assertEquals("71c8790895b1", manifest.getVersion());
        // The three things a client actually reads, all of which used to be
        // collateral damage from the unmodelled section sitting before them.
        assertEquals(4, manifest.getCombatAchievementVarps().size());
        assertEquals(Integer.valueOf(5673), manifest.getCombatAchievementVarps().get(3));
        assertEquals(2, manifest.getQuestIds().size());
        assertEquals(90, manifest.getSync().getIntervalMinutes());
        assertEquals(5, manifest.getSync().getRapidSeconds());
        assertTrue(manifest.getSync().isEnabled());
    }

    @Test
    public void anUnreadableSectionCostsOnlyItself() {
        Manifest manifest = Manifest.fromJson(gson,
            "{\"combat_achievement_varps\":[3116],\"quest_ids\":{\"oops\":1},"
                + "\"sync\":{\"enabled\":false}}");

        assertNotNull(manifest);
        assertEquals(1, manifest.getCombatAchievementVarps().size());
        assertTrue(manifest.getQuestIds().isEmpty());
        // The kill switch still reaches us, which is the whole point: it is the
        // only lever that stops a misbehaving client without a Hub release.
        assertTrue(!manifest.getSync().isEnabled());
    }

    @Test
    public void missingSectionsFallBackToDefaults() {
        Manifest manifest = Manifest.fromJson(gson, "{\"version\":\"abc\"}");

        assertNotNull(manifest);
        assertTrue(manifest.getCombatAchievementVarps().isEmpty());
        assertTrue(manifest.getQuestIds().isEmpty());
        assertTrue(manifest.getSync().isEnabled());
        assertEquals(60, manifest.getSync().getIntervalMinutes());
        assertEquals(3, manifest.getSync().getRapidSeconds());
    }

    @Test
    public void readsTheTeamIndicatorKillSwitch() {
        Manifest manifest = Manifest.fromJson(gson,
            "{\"team_indicators\":{\"enabled\":false,\"max_roster_age_minutes\":15}}");

        assertNotNull(manifest);
        assertTrue(!manifest.getTeamIndicators().isEnabled());
        assertEquals(15, manifest.getTeamIndicators().getMaxRosterAgeMinutes());
    }

    @Test
    public void teamIndicatorsDefaultToOnWhenAbsentOrUnreadable() {
        // Same posture as sync's switch: it exists to turn the feature off
        // deliberately, never to fail closed on a manifest we could not read.
        assertTrue(Manifest.fromJson(gson, "{\"version\":\"abc\"}")
            .getTeamIndicators().isEnabled());
        assertTrue(Manifest.fromJson(gson, "{\"team_indicators\":[1,2]}")
            .getTeamIndicators().isEnabled());
        assertEquals(60, Manifest.fromJson(gson, "{\"team_indicators\":{}}")
            .getTeamIndicators().getMaxRosterAgeMinutes());
    }

    @Test
    public void nonsenseSyncValuesFallBackRatherThanDisablingSync() {
        Manifest manifest = Manifest.fromJson(gson,
            "{\"sync\":{\"interval_minutes\":0,\"rapid_seconds\":-1}}");

        assertNotNull(manifest);
        assertEquals(60, manifest.getSync().getIntervalMinutes());
        assertEquals(3, manifest.getSync().getRapidSeconds());
        assertTrue(manifest.getSync().isEnabled());
    }

    /**
     * The premise {@code fromJson} exists for: Gson's reflective adapter
     * abandons the entire document at the first field whose type does not
     * match, rather than skipping that field. If this ever stops being true,
     * the section-by-section loop can go with it.
     */
    @Test(expected = JsonSyntaxException.class)
    public void oneShotParsingAbandonsTheWholeDocument() {
        gson.fromJson("{\"combat_achievement_varps\":[3116],\"quest_ids\":{\"oops\":1}}",
            Manifest.class);
    }

    /**
     * A document that is not an object yields null rather than throwing:
     * callers treat null as "no manifest" and fall back, and an unchecked
     * ClassCastException here would sail past DropTrackerApi's catch.
     */
    @Test
    public void nonObjectDocumentsAreNull() {
        assertNull(Manifest.fromJson(gson, "null"));
        assertNull(Manifest.fromJson(gson, "[]"));
        assertNull(Manifest.fromJson(gson, "\"nope\""));
    }
}

package io.droptracker.ui.components;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.function.Consumer;

import com.google.gson.Gson;
import org.junit.Test;

import io.droptracker.api.DeathMessageApi;
import io.droptracker.models.api.DeathMessages;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The plugin's death message editor, driven headless with a stub API: what it
 * shows, what it refuses, and what it sends.
 */
public class DeathMessageEditorTest {

    private static final Gson GSON = new Gson();

    private static final String LOADED =
        "{\"player_name\":\"Iron Ron\",\"max_messages\":5,\"max_length\":150,"
            + "\"messages\":[\"{player_name} planked\"],"
            + "\"tokens\":[{\"token\":\"{player_name}\",\"help\":\"Your name\",\"sample\":\"Zezima\"},"
            + "{\"token\":\"{killer}\",\"help\":\"What killed you\",\"sample\":\"Vorkath\"}],"
            + "\"groups\":[{\"id\":5,\"name\":\"Clan\",\"allowed\":true,\"blocked\":false}]}";

    /** Answers synchronously, as if the network were instant. */
    private static final class StubApi extends DeathMessageApi {
        int fetches;
        List<String> saved;
        String saveError;

        StubApi() {
            super(null, null, null, null, null);
        }

        @Override
        public void fetch(String playerName, long accountHash, Consumer<Result> callback) {
            fetches++;
            callback.accept(Result.ok(GSON.fromJson(LOADED, DeathMessages.class)));
        }

        @Override
        public void save(String playerName, long accountHash, List<String> messages, Consumer<Result> callback) {
            saved = new ArrayList<>(messages);
            if (saveError != null) {
                callback.accept(Result.failed(saveError));
                return;
            }
            DeathMessages reply = GSON.fromJson(LOADED, DeathMessages.class);
            String json = GSON.toJson(reply).replace("[\"{player_name} planked\"]", GSON.toJson(messages));
            callback.accept(Result.ok(GSON.fromJson(json, DeathMessages.class)));
        }
    }

    private static DeathMessageEditor editor(StubApi api, long hash) {
        DeathMessageEditor editor = new DeathMessageEditor(api, () -> hash, () -> "Iron Ron", () -> { }, () -> { });
        editor.load();
        return editor;
    }

    @Test
    public void loadingFillsTheBoxesAndSaysWhereItPosts() {
        StubApi api = new StubApi();
        DeathMessageEditor editor = editor(api, 42L);
        assertEquals(1, api.fetches);
        assertEquals("{player_name} planked", editor.fields().get(0).getText());
        assertEquals("", editor.fields().get(1).getText());
        assertTrue(editor.fields().get(0).isEditable());
        assertFalse("nothing changed yet", editor.saveButton().isEnabled());
        assertTrue(editor.groupsLabelText(), editor.groupsLabelText().contains("Posted in: "));
        assertTrue(editor.previewText(), editor.previewText().contains("Example: Iron Ron planked"));
    }

    @Test
    public void aRuleBreakIsShownAndCannotBeSaved() {
        DeathMessageEditor editor = editor(new StubApi(), 42L);
        editor.fields().get(1).setText("free gp at www.scam.com");
        assertFalse(editor.saveButton().isEnabled());
        assertTrue(editor.statusText(), editor.statusText().contains("Messages can't contain links."));
    }

    @Test
    public void aValidEditSavesWhatTheServerWillStore() {
        StubApi api = new StubApi();
        DeathMessageEditor editor = editor(api, 42L);
        editor.fields().get(2).setText("  {Killer} got {player_name} again  ");
        assertTrue(editor.saveButton().isEnabled());
        editor.clickSave();
        assertEquals(Arrays.asList("{player_name} planked", "{killer} got {player_name} again"), api.saved);
        assertTrue(editor.statusText(), editor.statusText().contains("Saved."));
        assertFalse("saved, so nothing is unsaved", editor.saveButton().isEnabled());
        assertEquals("{killer} got {player_name} again", editor.fields().get(1).getText());
    }

    @Test
    public void clearingEveryBoxClearsTheMessages() {
        StubApi api = new StubApi();
        DeathMessageEditor editor = editor(api, 42L);
        editor.fields().get(0).setText("");
        editor.clickSave();
        assertEquals(Collections.emptyList(), api.saved);
        assertTrue(editor.statusText(), editor.statusText().contains("Cleared."));
    }

    @Test
    public void aRefusedSaveShowsTheServersWords() {
        StubApi api = new StubApi();
        api.saveError = "You can save at most 5 messages.";
        DeathMessageEditor editor = editor(api, 42L);
        editor.fields().get(1).setText("{player_name} again");
        editor.clickSave();
        assertTrue(editor.statusText(), editor.statusText().contains("You can save at most 5 messages."));
        assertTrue("still editable after a refusal", editor.fields().get(1).isEditable());
    }

    @Test
    public void loggedOutThereIsNothingToEdit() {
        StubApi api = new StubApi();
        DeathMessageEditor editor = editor(api, -1L);
        assertEquals(0, api.fetches);
        assertFalse(editor.fields().get(0).isEditable());
        assertFalse(editor.saveButton().isEnabled());
        assertTrue(editor.statusText(), editor.statusText().contains("Log in first"));
    }

    @Test
    public void aPlaceholderIsAddedWhereTheCursorIs() {
        DeathMessageEditor editor = editor(new StubApi(), 42L);
        editor.fields().get(0).setCaretPosition(editor.fields().get(0).getText().length());
        editor.clickToken("{killer}");
        assertEquals("{player_name} planked {killer}", editor.fields().get(0).getText());
    }

    @Test
    public void namesEachClanWithItsState() {
        String text = DeathMessageEditor.groupsText(Arrays.asList(
            group("{\"id\":1,\"name\":\"Posting Clan\",\"allowed\":true,\"blocked\":false}"),
            group("{\"id\":2,\"name\":\"Quiet Clan\",\"allowed\":false,\"blocked\":false}"),
            group("{\"id\":3,\"name\":\"Strict Clan\",\"allowed\":true,\"blocked\":true}")));
        assertTrue(text, text.contains("Posted in: "));
        assertTrue(text.contains("Posting Clan</font>"));
        assertTrue(text.contains("Quiet Clan (not switched on)"));
        assertTrue(text.contains("Strict Clan (blocked by its leaders)"));
    }

    @Test
    public void noClansSaysSo() {
        assertTrue(DeathMessageEditor.groupsText(Collections.emptyList()).contains("isn't in any clans"));
    }

    @Test
    public void clanNamesCannotInjectMarkup() {
        String text = DeathMessageEditor.groupsText(Collections.singletonList(
            group("{\"id\":1,\"name\":\"<b>Bold</b> & co\",\"allowed\":true,\"blocked\":false}")));
        assertFalse(text, text.contains("<b>"));
        assertTrue(text.contains("&lt;b&gt;Bold&lt;/b&gt; &amp; co"));
    }

    private static DeathMessages.Group group(String json) {
        return GSON.fromJson(json, DeathMessages.Group.class);
    }
}

package io.droptracker.ui;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.stream.Stream;

import org.junit.Test;

import static org.junit.Assert.assertTrue;

/**
 * Fails when panel code renders a character RuneLite's fonts cannot draw.
 * <p>
 * {@code FontManager}'s three fonts map ~247 codepoints and stop at U+2122.
 * They only ever displayed symbols above that by falling back to a system
 * font, and that fallback chain does not cover them on macOS — where the
 * panel showed missing-glyph boxes instead (reported 2026-08). Rather than
 * depend on a per-platform fallback we cannot test from CI, panel text stays
 * inside the fonts' own coverage and shapes are painted (see PanelIcons).
 * <p>
 * If this fails: paint the shape in {@code PanelIcons} instead of typing the
 * character, or pick one of the {@link #IN_FONT_EXTRAS} below.
 */
public class PanelGlyphCoverageTest {

    /**
     * Non-Latin-1 characters verified present in runescape.ttf,
     * runescape_small.ttf and runescape_bold.ttf.
     */
    private static final Set<Character> IN_FONT_EXTRAS = Set.of(
        '…', // …  horizontal ellipsis
        '—', // —  em dash
        '€', // €  euro sign
        '™'  // ™  trade mark
    );

    /** Matches a Java string literal, honouring escapes. */
    private static final Pattern STRING_LITERAL = Pattern.compile("\"((?:[^\"\\\\]|\\\\.)*)\"");
    private static final Pattern BLOCK_COMMENT = Pattern.compile("/\\*.*?\\*/", Pattern.DOTALL);
    private static final Pattern LINE_COMMENT = Pattern.compile("//[^\n]*");

    @Test
    public void panelStringsStayInsideTheBundledFontsCoverage() throws IOException {
        Path uiRoot = Paths.get("src/main/java/io/droptracker/ui");
        assertTrue("expected the UI sources at " + uiRoot.toAbsolutePath()
            + " — run this from the project root", Files.isDirectory(uiRoot));

        List<String> offenders = new ArrayList<>();
        try (Stream<Path> files = Files.walk(uiRoot)) {
            for (Path file : (Iterable<Path>) files.filter(p -> p.toString().endsWith(".java"))::iterator) {
                collectOffenders(file, offenders);
            }
        }

        assertTrue("panel text uses characters RuneLite's fonts cannot render "
            + "(they tofu on macOS) — paint them via PanelIcons instead:\n  "
            + String.join("\n  ", offenders), offenders.isEmpty());
    }

    private static void collectOffenders(Path file, List<String> offenders) throws IOException {
        // Comments are not rendered, so strip them before looking at literals.
        String source = new String(Files.readAllBytes(file), StandardCharsets.UTF_8);
        source = BLOCK_COMMENT.matcher(source).replaceAll("");
        source = LINE_COMMENT.matcher(source).replaceAll("");

        Matcher literal = STRING_LITERAL.matcher(source);
        while (literal.find()) {
            String value = literal.group(1);
            for (int i = 0; i < value.length(); i++) {
                char c = value.charAt(i);
                if (c < 0x100 || IN_FONT_EXTRAS.contains(c)) {
                    continue;
                }
                offenders.add(String.format("%s: U+%04X '%c' in \"%s\"",
                    file.getFileName(), (int) c, c, value));
            }
        }
    }
}

package io.droptracker.service;

import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Tests {@link NearbyPlayerTracker#isSoloRaid}, which decides what an empty
 * authoritative roster means. A solo raid empties the roster exactly the way a
 * broken capture does, and the old code read both as breakage and guessed from
 * proximity + the RuneLite party — so a solo raider's submission was credited
 * to whoever was still in their party from an earlier session.
 *
 * <p>A false positive here drops real participants from a genuine team raid; a
 * false negative re-opens the guessing that credited non-participants.
 */
public class NearbyPlayerTrackerSoloRaidTest {

    /** The regression: solo raid, party size 1 sampled throughout. */
    @Test
    public void soloRaidWithSampledPartySizeIsSolo() {
        assertTrue(NearbyPlayerTracker.isSoloRaid(0, true, 1, true, true));
        // Capture never worked, but the game still said the party was 1.
        assertTrue(NearbyPlayerTracker.isSoloRaid(0, true, 1, false, false));
    }

    @Test
    public void teamSizeSeenDuringTheRaidRulesOutSolo() {
        // Varbits have reset by loot-chest time; only the high-water mark knows.
        assertFalse(NearbyPlayerTracker.isSoloRaid(0, true, 3, false, false));
        assertFalse(NearbyPlayerTracker.isSoloRaid(0, true, 2, true, true));
    }

    @Test
    public void liveTeamSizeRulesOutSolo() {
        assertFalse(NearbyPlayerTracker.isSoloRaid(2, true, 0, true, true));
        assertFalse(NearbyPlayerTracker.isSoloRaid(5, false, 0, false, true));
    }

    /**
     * Team size never sampled (plugin enabled mid-raid): a live source that
     * returned the local player proves the capture works, so an empty roster
     * really is empty.
     */
    @Test
    public void workingCaptureWithNobodyElseIsSolo() {
        assertTrue(NearbyPlayerTracker.isSoloRaid(0, true, 0, true, false));
        assertTrue(NearbyPlayerTracker.isSoloRaid(0, true, 0, false, true));
        assertTrue(NearbyPlayerTracker.isSoloRaid(0, false, 0, false, true));
    }

    /** No evidence either way: keep guessing rather than drop real teammates. */
    @Test
    public void noEvidenceIsNotSolo() {
        assertFalse(NearbyPlayerTracker.isSoloRaid(0, true, 0, false, false));
        assertFalse(NearbyPlayerTracker.isSoloRaid(0, false, 0, false, false));
    }

    /** Retained state from a *different* raid must not settle this one. */
    @Test
    public void staleRosterFromAnotherRaidIsIgnored() {
        // teamSizeMax=1 and captureWorked belong to the previous raid.
        assertFalse(NearbyPlayerTracker.isSoloRaid(0, false, 1, true, false));
    }
}

package io.droptracker.service;

