import static org.junit.Assert.assertTrue;

/**
 * Clan-chat team badges (suggestion #150): the wire format of GET
 * /event_roster, the name matching, the badge sprites, and the chat builder
 * callback that puts a badge on a line as it is drawn.
 *
 * The callback tests drive {@code chatMessageBuilding} against a stubbed
 * client. They pin the two rules whose absence broke private messages: only
 * clan, friends-chat and opted-in public lines are badged, and the
 * {@link MessageNode} itself is never renamed.
 */
public class EventTeamIndicatorTest {

    private final Gson gson = new Gson();

    // ── wire format ──────────────────────────────────────────────────────────

    @Test
    public void parsesRosterResponse() {
        String json = "{\"events\":[{"
            + "\"event_id\":46,\"roster_version\":\"3f1c9a0b12345678\","
            + "\"teams\":[{\"id\":101,\"name\":\"Red Rockets\",\"short_tag\":\"RR\","
            + "\"color\":\"#cc3333\",\"orb\":\"🔴\",\"orb_color\":\"#dd2e44\","
            + "\"icon_item_id\":11802,\"icon_path\":null},"
            + "{\"id\":102,\"name\":\"Blue Blazers\",\"short_tag\":\"BB\","
            + "\"color\":\"#3355cc\",\"orb\":\"🔵\",\"orb_color\":\"#55acee\","
            + "\"icon_item_id\":null,\"icon_path\":null}],"
            + "\"members\":{\"101\":[\"beast owned\",\"zezima\"],\"102\":[\"woox\"]},"
            + "\"members_total\":3,\"truncated\":false}]}";

        EventRoster roster = gson.fromJson(json, EventRoster.class);
        assertNotNull(roster.getEvents());
        assertEquals(1, roster.getEvents().size());

        EventRoster.Entry entry = roster.getEvents().get(0);
        assertEquals(46, entry.getEventId());
        assertEquals("3f1c9a0b12345678", entry.getRosterVersion());
        assertEquals(3, entry.getMembersTotal());
        assertEquals(false, entry.isTruncated());

        EventRoster.Team red = entry.getTeams().get(0);
        assertEquals(101, red.getId());
        assertEquals("RR", red.getShortTag());
        assertEquals("#dd2e44", red.getOrbColor());
        assertEquals(Integer.valueOf(11802), red.getIconItemId());

        List<String> redMembers = entry.getMembers().get("101");
        assertEquals(2, redMembers.size());
        assertTrue(redMembers.contains("beast owned"));
    }

    @Test
    public void toleratesAnEmptyRoster() {
        EventRoster roster = gson.fromJson("{\"events\":[]}", EventRoster.class);
        assertNotNull(roster.getEvents());
        assertTrue(roster.getEvents().isEmpty());
    }

    @Test
    public void rosterVersionIsOptionalOnEventState() {
        // Older servers do not send the stamp; the client must parse the rest
        // of the entry rather than lose the HUD over a missing field.
        String json = "{\"events\":[{\"event\":{\"id\":46,\"name\":\"Bingo\",\"kind\":\"bingo\"},"
            + "\"team\":{\"id\":101,\"name\":\"Red Rockets\",\"score\":5,\"team_count\":2}}]}";
        EventState state = gson.fromJson(json, EventState.class);
        assertNull(state.getEvents().get(0).getRosterVersion());
    }

    @Test
    public void readsRosterVersionWhenPresent() {
        String json = "{\"events\":[{\"event\":{\"id\":46,\"name\":\"Bingo\",\"kind\":\"bingo\"},"
            + "\"team\":{\"id\":101,\"name\":\"Red Rockets\",\"score\":5,\"team_count\":2},"
            + "\"roster_version\":\"abc123\"}]}";
        EventState state = gson.fromJson(json, EventState.class);
        assertEquals("abc123", state.getEvents().get(0).getRosterVersion());
    }

    // ── name matching ────────────────────────────────────────────────────────

    @Test
    public void nameKeyFoldsEverySpellingOfTheSameRsn() {
        // The plugin submits "Beast_Owned", the database stores "Beast Owned",
        // and the game renders the space as U+00A0. All three are one player.
        String expected = "beast owned";
        assertEquals(expected, EventTeamIndicatorService.normalize("Beast Owned"));
        assertEquals(expected, EventTeamIndicatorService.normalize("Beast_Owned"));
        assertEquals(expected, EventTeamIndicatorService.normalize("Beast-Owned"));
        assertEquals(expected, EventTeamIndicatorService.normalize("Beast Owned"));
        assertEquals(expected, EventTeamIndicatorService.normalize("BEAST OWNED"));
    }

    @Test
    public void nameKeyIgnoresIconsAndColoursOnTheName() {
        // Icons and colours another plugin put on a name are not part of it.
        assertEquals("zezima", EventTeamIndicatorService.normalize("<img=25>Zezima"));
        assertEquals("zezima",
            EventTeamIndicatorService.normalize("<img=42><col=cc3333>Zezima</col>"));
    }

    @Test
    public void nameKeyCollapsesWhitespaceLikeTheServerDoes() {
        // normalize_player_display_equivalence collapses runs; two normalizers
        // that disagree by one space badge nobody and look right on both sides.
        assertEquals("beast owned", EventTeamIndicatorService.normalize("Beast__Owned"));
        assertEquals("beast owned", EventTeamIndicatorService.normalize("Beast -_ Owned"));
    }

    @Test
    public void nameKeyHandlesNullAndBlank() {
        assertEquals("", EventTeamIndicatorService.normalize(null));
        assertEquals("", EventTeamIndicatorService.normalize("   "));
    }

    // ── colors ───────────────────────────────────────────────────────────────

    @Test
    public void parsesHexColors() {
        assertEquals(new Color(0xdd2e44), EventTeamIndicatorService.colorOf("#dd2e44"));
        assertEquals(new Color(0xdd2e44), EventTeamIndicatorService.colorOf("DD2E44"));
    }

    @Test
    public void unusableColorsAreNull() {
        assertNull(EventTeamIndicatorService.colorOf(null));
        assertNull(EventTeamIndicatorService.colorOf(""));
        assertNull(EventTeamIndicatorService.colorOf("#fff"));
        assertNull(EventTeamIndicatorService.colorOf("rebeccapurple"));
    }

    // ── rendering the name ───────────────────────────────────────────────────

    private static final int SLOT = 42;

    private EventTeamIndicatorService.TeamBadge badge() {
        return new EventTeamIndicatorService.TeamBadge(
            101, "RR", new Color(0xdd2e44), new Color(0xcc3333));
    }

    @Test
    public void aSlotPrefixesTheName() {
        assertEquals("<img=42>Zezima", badge().render("Zezima", SLOT, false));
    }

    @Test
    public void colorsTheNameWhenAsked() {
        assertEquals("<img=42><col=cc3333>Zezima</col>", badge().render("Zezima", SLOT, true));
    }

    @Test
    public void theGameCanAlwaysStripTheBadgeBackOff() {
        // The chat scripts removetags() the drawn name to find the clan rank
        // icon and to target Report, Kick, Ban, Add friend and Message. The
        // tag used to be typed in as "[RR]", which survives that, so every one
        // of those looked up a player called "[RR]Zezima".
        for (int slot : new int[] {SLOT, -1}) {
            for (boolean colorName : new boolean[] {true, false}) {
                String drawn = badge().render("Zezima", slot, colorName);
                if (drawn != null) {
                    assertEquals("Zezima", Text.removeTags(drawn));
                }
            }
        }
    }

    @Test
    public void withoutASlotTheNameIsStillColoured() {
        assertEquals("<col=cc3333>Zezima</col>", badge().render("Zezima", -1, true));
    }

    @Test
    public void withoutASlotOrAColourTheNameIsLeftAlone() {
        assertNull(badge().render("Zezima", -1, false));
    }

    @Test
    public void anIconAlreadyOnTheNameSurvives() {
        // e.g. RuneLite's friends-chat rank icon, added by a subscriber that
        // ran before this one.
        assertEquals("<img=42><img=25>Zezima", badge().render("<img=25>Zezima", SLOT, false));
    }

    @Test
    public void aModeratorCrownStaysFirst() {
        // The chat builder offers "Crown Info" only when the name starts with
        // <img=0> or <img=1> (script 2759), so the badge goes after a crown.
        assertEquals("<img=0><img=42><col=cc3333>Zezima</col>",
            badge().render("<img=0>Zezima", SLOT, true));
        assertEquals("<img=1><img=42>Zezima", badge().render("<img=1>Zezima", SLOT, false));
        assertEquals("<img=0><col=cc3333>Zezima</col>", badge().render("<img=0>Zezima", -1, true));
        // Any other icon is not a crown, and the badge leads as usual.
        assertEquals("<img=42><img=10>Zezima", badge().render("<img=10>Zezima", SLOT, false));
    }

    @Test
    public void theTeamColourReplacesOneAlreadyOnTheName() {
        // RuneLite's chat colour config may have wrapped the name first. A
        // nested span would leave its colour showing instead of the team's.
        assertEquals("<img=42><col=cc3333>Zezima</col>",
            badge().render("<col=ff9040>Zezima</col>", SLOT, true));
    }

    @Test
    public void fallsBackToTheOrbColorWhenNoAccentIsSet() {
        EventTeamIndicatorService.TeamBadge noAccent =
            new EventTeamIndicatorService.TeamBadge(101, "RR", new Color(0x55acee), null);
        assertEquals("<img=42><col=55acee>Zezima</col>", noAccent.render("Zezima", SLOT, true));
    }

    // ── sprites ──────────────────────────────────────────────────────────────

    /** The chat font as RuneLite ships it, loaded without FontManager's side effects. */
    private static Font chatFont() throws Exception {
        try (InputStream in = EventTeamIndicatorService.class.getClassLoader()
            .getResourceAsStream("net/runelite/client/ui/runescape.ttf")) {
            assertNotNull("runescape.ttf missing from the client jar", in);
            return Font.createFont(Font.TRUETYPE_FONT, in).deriveFont(Font.PLAIN, 16f);
        }
    }

    private static int rgb(BufferedImage image, int x, int y) {
        return image.getRGB(x, y) & 0xFFFFFF;
    }

    private static boolean inked(BufferedImage image, int x, int y) {
        return (image.getRGB(x, y) >>> 24) != 0;
    }

    private static boolean rowInked(BufferedImage image, int y) {
        for (int x = 0; x < image.getWidth(); x++) {
            if (inked(image, x, y)) {
                return true;
            }
        }
        return false;
    }

    @Test
    public void orbStyleDrawsTheOrbAlone() throws Exception {
        EventTeamIndicatorService.BadgeArt art =
            EventTeamIndicatorService.drawBadge(badge(), TeamIndicatorStyle.ORB, chatFont());
        assertNotNull(art);
        assertEquals(12, art.image.getWidth());
        assertEquals(12, art.image.getHeight());
        assertEquals("the whole icon sits above the baseline", 12, art.ascent);
        assertEquals(0xdd2e44, rgb(art.image, 6, 6));
        assertTrue(!inked(art.image, 0, 0));
    }

    @Test
    public void theTagIsDrawnInTheTeamColour() throws Exception {
        EventTeamIndicatorService.BadgeArt art =
            EventTeamIndicatorService.drawBadge(badge(), TeamIndicatorStyle.TAG, chatFont());
        assertNotNull(art);
        boolean anyInk = false;
        for (int y = 0; y < art.image.getHeight(); y++) {
            for (int x = 0; x < art.image.getWidth(); x++) {
                if (inked(art.image, x, y)) {
                    anyInk = true;
                    assertEquals("sprites hold one flat colour, no antialiasing",
                        0xcc3333, rgb(art.image, x, y));
                }
            }
        }
        assertTrue(anyInk);
        assertTrue("cropped to the ink", rowInked(art.image, 0));
        assertTrue(rowInked(art.image, art.image.getHeight() - 1));
    }

    @Test
    public void theTagStandsOnTheTextBaseline() throws Exception {
        Font font = chatFont();
        // A capital sits exactly on the baseline, so its drawing has nothing
        // hanging below it...
        EventTeamIndicatorService.BadgeArt capital =
            EventTeamIndicatorService.drawText("RR", new Color(0xcc3333), font);
        assertNotNull(capital);
        assertEquals(capital.image.getHeight(), capital.ascent);
        // ...while a bracket's tail hangs below the baseline, the way the game
        // draws it beside the name, instead of lifting the whole tag. In this
        // font a bracket starts at cap height, so the tag stands exactly where
        // a bare capital does, plus the one row of tail.
        EventTeamIndicatorService.BadgeArt tag =
            EventTeamIndicatorService.drawText("[RR]", new Color(0xcc3333), font);
        assertNotNull(tag);
        assertEquals("brackets and capitals share a baseline", capital.ascent, tag.ascent);
        assertEquals("only the bracket tails hang below it", tag.ascent + 1, tag.image.getHeight());
    }

    @Test
    public void orbAndTagShareOneBaseline() throws Exception {
        Font font = chatFont();
        EventTeamIndicatorService.BadgeArt orb =
            EventTeamIndicatorService.drawBadge(badge(), TeamIndicatorStyle.ORB, font);
        EventTeamIndicatorService.BadgeArt tag =
            EventTeamIndicatorService.drawBadge(badge(), TeamIndicatorStyle.TAG, font);
        EventTeamIndicatorService.BadgeArt both =
            EventTeamIndicatorService.drawBadge(badge(), TeamIndicatorStyle.ORB_AND_TAG, font);
        assertNotNull(orb);
        assertNotNull(tag);
        assertNotNull(both);
        assertEquals(orb.image.getWidth() + 2 + tag.image.getWidth(), both.image.getWidth());
        assertEquals(Math.max(orb.ascent, tag.ascent), both.ascent);
        // The orb sits exactly where it does on its own...
        for (int y = 0; y < orb.image.getHeight(); y++) {
            for (int x = 0; x < orb.image.getWidth(); x++) {
                int shift = both.ascent - orb.ascent;
                assertEquals(orb.image.getRGB(x, y), both.image.getRGB(x, y + shift));
            }
        }
        // ...and the tag's baseline row lands on the orb's bottom row.
        int tagLeft = orb.image.getWidth() + 2;
        int tagTop = both.ascent - tag.ascent;
        for (int y = 0; y < tag.image.getHeight(); y++) {
            for (int x = 0; x < tag.image.getWidth(); x++) {
                assertEquals(tag.image.getRGB(x, y), both.image.getRGB(tagLeft + x, tagTop + y));
            }
        }
    }

    @Test
    public void orbDegradesToTheTagWithoutAnOrbColour() throws Exception {
        Font font = chatFont();
        EventTeamIndicatorService.TeamBadge noOrb =
            new EventTeamIndicatorService.TeamBadge(101, "RR", null, new Color(0xcc3333));
        EventTeamIndicatorService.BadgeArt art =
            EventTeamIndicatorService.drawBadge(noOrb, TeamIndicatorStyle.ORB, font);
        EventTeamIndicatorService.BadgeArt tag =
            EventTeamIndicatorService.drawBadge(noOrb, TeamIndicatorStyle.TAG, font);
        assertNotNull(art);
        assertNotNull(tag);
        assertEquals(tag.image.getWidth(), art.image.getWidth());
        assertEquals(tag.ascent, art.ascent);
    }

    @Test
    public void withoutAFontTheTagIsLeftOut() {
        EventTeamIndicatorService.BadgeArt art =
            EventTeamIndicatorService.drawBadge(badge(), TeamIndicatorStyle.ORB_AND_TAG, null);
        assertNotNull(art);
        assertEquals(12, art.image.getWidth());
    }

    @Test
    public void aTeamWithNothingToDrawGetsNoSprite() throws Exception {
        EventTeamIndicatorService.TeamBadge bare =
            new EventTeamIndicatorService.TeamBadge(101, null, null, null);
        assertNull(EventTeamIndicatorService.drawBadge(bare, TeamIndicatorStyle.ORB_AND_TAG, chatFont()));
    }

    @Test
    public void offDrawsNothing() throws Exception {
        assertNull(EventTeamIndicatorService.drawBadge(badge(), TeamIndicatorStyle.OFF, chatFont()));
    }

    @Test
    public void blackIsNeverTheTransparentIndex() {
        // ImageUtil.getImageIndexedSprite reads rgb 0 as its transparent
        // index, so a black team would come out invisible.
        assertEquals(0x010101, EventTeamIndicatorService.spriteSafe(Color.BLACK).getRGB() & 0xFFFFFF);
        EventTeamIndicatorService.TeamBadge black =
            new EventTeamIndicatorService.TeamBadge(101, "BK", Color.BLACK, null);
        EventTeamIndicatorService.BadgeArt art =
            EventTeamIndicatorService.drawBadge(black, TeamIndicatorStyle.ORB, null);
        assertNotNull(art);
        assertEquals(0x010101, rgb(art.image, 6, 6));
    }

    // ── the chat builder callback ────────────────────────────────────────────

    private final Map<Long, MessageNode> nodes = new HashMap<>();
    private final List<String> renamed = new ArrayList<>();
    private Client client;
    private DropTrackerConfig config;
    private EventTeamIndicatorService service;

    @Before
    @SuppressWarnings("unchecked")
    public void setUpChat() {
        client = RuneLiteStubs.stub(Client.class, "client");
        IterableHashTable<MessageNode> messages = RuneLiteStubs.stub(IterableHashTable.class, "messages");
        state(messages).put("get", (RuneLiteStubs.Answer) args -> nodes.get((Long) args[0]));
        state(client).put("getMessages", messages);

        config = RuneLiteStubs.stub(DropTrackerConfig.class, "config");
        state(config).put("eventTeamIndicators", TeamIndicatorStyle.ORB);
        state(config).put("eventTeamIndicatorColorNames", true);
        state(config).put("eventTeamIndicatorsPublicChat", false);

        service = new EventTeamIndicatorService(client, null, null, config, null, null, null, null);
        Map<String, EventTeamIndicatorService.TeamBadge> badges = new HashMap<>();
        badges.put("zezima", badge());
        badges.put("beast owned", badge());
        service.useBadges(badges, Collections.singletonMap(101, SLOT));
    }

    /**
     * Run the chatMessageBuilding callback for one line, with the stacks laid
     * out the way ChatBuilder pushes them, and return the name it would draw.
     */
    private String draw(ChatMessageType type, String sender, String shown, boolean splitPmPane) {
        long uid = nodes.size() + 1;
        MessageNode node = RuneLiteStubs.stub(MessageNode.class, "node:" + sender);
        state(node).put("getType", type);
        state(node).put("getName", sender);
        state(node).put("setName", (RuneLiteStubs.Answer) args -> {
            renamed.add((String) args[0]);
            return null;
        });
        nodes.put(uid, node);

        int[] ints = {7, splitPmPane ? 1 : 0, (int) uid};
        Object[] objects = {"below", "Clan", shown, "hello", ""};
        state(client).put("getIntStack", ints);
        state(client).put("getIntStackSize", ints.length);
        state(client).put("getObjectStack", objects);
        state(client).put("getObjectStackSize", objects.length);

        ScriptCallbackEvent event = new ScriptCallbackEvent();
        event.setEventName("chatMessageBuilding");
        service.onScriptCallbackEvent(event);

        assertEquals("the rest of the line is untouched", "Clan", objects[1]);
        assertEquals("hello", objects[3]);
        return (String) objects[2];
    }

    private String draw(ChatMessageType type, String sender) {
        return draw(type, sender, sender, false);
    }

    @Test
    public void aTeammatesClanLineIsBadgedAsItIsDrawn() {
        String drawn = draw(ChatMessageType.CLAN_CHAT, "Zezima");
        assertEquals("<img=42><col=cc3333>Zezima</col>", drawn);
        assertEquals("Zezima", Text.removeTags(drawn));
    }

    @Test
    public void everyClanStyleChannelIsBadged() {
        for (ChatMessageType type : new ChatMessageType[] {
            ChatMessageType.CLAN_CHAT, ChatMessageType.CLAN_GUEST_CHAT,
            ChatMessageType.CLAN_GIM_CHAT, ChatMessageType.FRIENDSCHAT}) {
            assertEquals(type.name(), "<img=42><col=cc3333>Zezima</col>", draw(type, "Zezima"));
        }
    }

    @Test
    public void privateMessagesAreNeverTouched() {
        // The reported bug: a teammate's PMs recoloured, and hidden outright
        // for anyone with Private set to Friends.
        for (ChatMessageType type : new ChatMessageType[] {
            ChatMessageType.PRIVATECHAT, ChatMessageType.PRIVATECHATOUT,
            ChatMessageType.MODPRIVATECHAT}) {
            assertEquals(type.name(), "Zezima", draw(type, "Zezima"));
        }
    }

    @Test
    public void nothingOutsideTheBadgedChannelsIsTouched() {
        for (ChatMessageType type : ChatMessageType.values()) {
            switch (type) {
                case CLAN_CHAT:
                case CLAN_GUEST_CHAT:
                case CLAN_GIM_CHAT:
                case FRIENDSCHAT:
                case PUBLICCHAT:
                    continue;
                default:
                    assertEquals(type.name(), "Zezima", draw(type, "Zezima"));
            }
        }
    }

    @Test
    public void theSplitPrivateChatPaneIsNeverTouched() {
        // It only ever holds DMs; the flag is checked before the type.
        assertEquals("Zezima", draw(ChatMessageType.CLAN_CHAT, "Zezima", "Zezima", true));
    }

    @Test
    public void theMessageNodeIsNeverRenamed() {
        // MessageNode.setName rebuilds the sender identity the game's friend
        // and ignore checks read. Renaming a node is what made DMs vanish.
        for (ChatMessageType type : ChatMessageType.values()) {
            draw(type, "Zezima");
        }
        assertTrue("renamed: " + renamed, renamed.isEmpty());
    }

    @Test
    public void publicChatOnlyWhenOptedIn() {
        assertEquals("Zezima", draw(ChatMessageType.PUBLICCHAT, "Zezima"));
        state(config).put("eventTeamIndicatorsPublicChat", true);
        assertEquals("<img=42><col=cc3333>Zezima</col>", draw(ChatMessageType.PUBLICCHAT, "Zezima"));
    }

    @Test
    public void playersOffTheRosterAreLeftAlone() {
        assertEquals("Woox", draw(ChatMessageType.CLAN_CHAT, "Woox"));
    }

    @Test
    public void discordBridgeLinesAreNotBadged() {
        String sender = "Zezima " + ChatMessageUtil.DISCORD_SENDER_MARKER;
        assertEquals(sender, draw(ChatMessageType.CLAN_CHAT, sender));
    }

    @Test
    public void offBadgesNothing() {
        state(config).put("eventTeamIndicators", TeamIndicatorStyle.OFF);
        assertEquals("Zezima", draw(ChatMessageType.CLAN_CHAT, "Zezima"));
    }

    @Test
    public void theSenderIsMatchedByTheNodeNotTheDrawnName() {
        // Another plugin may have decorated the drawn name already; the node
        // still carries the name the server sent, U+00A0 and all.
        assertEquals("<img=42><col=cc3333><img=5>Beast Owned</col>",
            draw(ChatMessageType.CLAN_CHAT, "Beast\u00A0Owned", "<img=5>Beast Owned", false));
    }

    @Test
    public void otherCallbacksAreIgnored() {
        // No stacks are stubbed at all; touching them would throw.
        ScriptCallbackEvent event = new ScriptCallbackEvent();
        event.setEventName("privChatUsername");
        service.onScriptCallbackEvent(event);
    }

    // ── style semantics ──────────────────────────────────────────────────────

    @Test
    public void styleFlagsMatchTheirNames() {
        assertTrue(TeamIndicatorStyle.TAG.showsTag());
        assertTrue(!TeamIndicatorStyle.TAG.showsOrb());
        assertTrue(TeamIndicatorStyle.ORB.showsOrb());
        assertTrue(!TeamIndicatorStyle.ORB.showsTag());
        assertTrue(TeamIndicatorStyle.ORB_AND_TAG.showsOrb());
        assertTrue(TeamIndicatorStyle.ORB_AND_TAG.showsTag());
        assertTrue(!TeamIndicatorStyle.OFF.showsOrb());
        assertTrue(!TeamIndicatorStyle.OFF.showsTag());
    }
}

package io.droptracker.service;

import io.droptracker.models.CustomWebhookBody;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The chokepoint every submission passes through. Handlers already skip events
 * they cannot name; this is what stops a future path from quietly reintroducing
 * an unattributable submission.
 */
public class SubmissionIdentityGuardTest {

    private static CustomWebhookBody webhookWithName(String... playerNames) {
        CustomWebhookBody webhook = new CustomWebhookBody();
        for (String playerName : playerNames) {
            CustomWebhookBody.Embed embed = new CustomWebhookBody.Embed();
            embed.addField("type", "drop", true);
            embed.addField("player_name", playerName, true);
            embed.addField("acc_hash", "1234567890123456", true);
            webhook.getEmbeds().add(embed);
        }
        return webhook;
    }

    @Test
    public void passesAnIdentifiedSubmission() {
        assertFalse(SubmissionManager.hasUnidentifiedEmbed(webhookWithName("Wimi")));
    }

    @Test
    public void rejectsABlankName() {
        assertTrue(SubmissionManager.hasUnidentifiedEmbed(webhookWithName("")));
        assertTrue(SubmissionManager.hasUnidentifiedEmbed(webhookWithName("   ")));
        assertTrue(SubmissionManager.hasUnidentifiedEmbed(webhookWithName((String) null)));
    }

    // A drop is one embed per item: one nameless embed condemns the payload,
    // since they all describe the same event.
    @Test
    public void rejectsAPayloadWhereOnlyOneEmbedIsNameless() {
        assertTrue(SubmissionManager.hasUnidentifiedEmbed(webhookWithName("Wimi", "", "Wimi")));
    }

    // The adventure log names its identity field "player", not "player_name" —
    // it must not be caught by a guard aimed at a field it does not carry.
    @Test
    public void ignoresEmbedsWithoutAPlayerNameField() {
        CustomWebhookBody webhook = new CustomWebhookBody();
        CustomWebhookBody.Embed embed = new CustomWebhookBody.Embed();
        embed.addField("type", "adventure_log", true);
        embed.addField("player", "Wimi", true);
        webhook.getEmbeds().add(embed);
        assertFalse(SubmissionManager.hasUnidentifiedEmbed(webhook));
    }

    @Test
    public void toleratesEmptyAndNullPayloads() {
        assertFalse(SubmissionManager.hasUnidentifiedEmbed(null));
        assertFalse(SubmissionManager.hasUnidentifiedEmbed(new CustomWebhookBody()));
    }
}

package io.droptracker.service;

import java.util.Optional;

import io.droptracker.service.RecentCombatTracker.Engagement;
import io.droptracker.testing.RuneLiteStubs;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Tests {@link RecentCombatTracker}, the memory that lets a death be attributed
 * after every live candidate has vanished.
 *
 * <p>The production failure this exists for: on the tick the local player dies,
 * the killer has usually already dropped its target (the game clears an NPC's
 * interaction when that target dies), so a scan of "who is attacking me right
 * now" finds nobody and the death is submitted with a blank source and a killer
 * type of "unknown".
 */
public class RecentCombatTrackerTest {

    private final RecentCombatTracker tracker = new RecentCombatTracker();

    /** The incident shape: the boss let go of us at the very tick we died. */
    @Test
    public void attackerIsStillBlamedAfterItDropsItsTargetOnTheDeathTick() {
        NPC vorkath = RuneLiteStubs.npc(1, 8061, "Vorkath", 732);

        tracker.recordAttackedBy(vorkath, 100);
        tracker.recordAttacking(vorkath, 100);
        // Death tick: the client tells us it stopped interacting with us, then
        // fires ActorDeath for the local player.
        tracker.endAttackedBy(vorkath, 118);

        Engagement killer = require(tracker.mostLikelyKiller(118, false));
        assertEquals("Vorkath", killer.getName());
        assertEquals(Integer.valueOf(8061), killer.getNpcId());
        assertEquals(732, killer.getCombatLevel());
        assertFalse(killer.isPlayer());
        assertTrue(killer.isNpc());
    }

    @Test
    public void engagementThatEndedLongAgoIsNotBlamed() {
        NPC goblin = RuneLiteStubs.npc(1, 100, "Goblin", 2);
        tracker.recordAttackedBy(goblin, 100);
        tracker.endAttackedBy(goblin, 100);

        assertTrue(tracker.mostLikelyKiller(100 + RecentCombatTracker.RECENT_WINDOW_TICKS, false).isPresent());
        assertFalse(tracker.mostLikelyKiller(100 + RecentCombatTracker.RECENT_WINDOW_TICKS + 1, false).isPresent());
    }

    /**
     * A boss that despawns with its instance never reports that it disengaged,
     * so the engagement stays open. It is still the right answer for a while —
     * but only a while, or a Gauntlet leftover gets blamed for a bank-stand
     * death minutes later.
     */
    @Test
    public void openEngagementIsTrustedLongerThanAFinishedOneButNotForever() {
        NPC hunllef = RuneLiteStubs.npc(1, 9035, "Crystalline Hunllef", 890);
        tracker.recordAttackedBy(hunllef, 100);

        int longAfterRecent = 100 + RecentCombatTracker.RECENT_WINDOW_TICKS + 5;
        assertTrue(tracker.mostLikelyKiller(longAfterRecent, false).isPresent());
        assertTrue(tracker.mostLikelyKiller(100 + RecentCombatTracker.OPEN_WINDOW_TICKS, false).isPresent());
        assertFalse(tracker.mostLikelyKiller(100 + RecentCombatTracker.OPEN_WINDOW_TICKS + 1, false).isPresent());
    }

    /**
     * The thing we were trading blows with is the answer people expect, even
     * when something bigger wandered in and aggroed us on the way down. The
     * distractor is deliberately the higher-level NPC so that only the
     * direction of the engagement can decide this.
     */
    @Test
    public void mutualCombatOutranksAHigherLevelBystanderThatMerelyAggroed() {
        NPC weFought = RuneLiteStubs.npc(1, 100, "Green dragon", 79);
        NPC aggroed = RuneLiteStubs.npc(2, 101, "Chaos Elemental", 305);

        tracker.recordAttacking(weFought, 100);
        tracker.recordAttackedBy(weFought, 100);
        tracker.recordAttackedBy(aggroed, 104);

        assertEquals("Green dragon", require(tracker.mostLikelyKiller(105, false)).getName());
    }

    /**
     * Something that attacked us beats something we merely clicked on and that
     * never fought back — again with the levels inverted so only the direction
     * can be doing the work.
     */
    @Test
    public void inboundAttackerOutranksAHigherLevelOutboundTarget() {
        NPC weClicked = RuneLiteStubs.npc(1, 8061, "Vorkath", 732);
        NPC itAttackedUs = RuneLiteStubs.npc(2, 101, "Skeletal Wyvern", 140);

        tracker.recordAttacking(weClicked, 100);
        tracker.recordAttackedBy(itAttackedUs, 100);

        assertEquals("Skeletal Wyvern", require(tracker.mostLikelyKiller(101, false)).getName());
    }

    /**
     * Something the client told us disengaged three ticks ago was still on us at
     * the death; something that walked off twenty seconds ago was not, and must
     * not outrank it just for being a bigger monster.
     */
    @Test
    public void anEngagementLiveAtTheDeathBeatsAStalerBiggerOne() {
        NPC oldBoss = RuneLiteStubs.npc(1, 8061, "Vorkath", 732);
        NPC current = RuneLiteStubs.npc(2, 100, "Green dragon", 79);

        tracker.recordAttackedBy(oldBoss, 100);
        tracker.endAttackedBy(oldBoss, 101);
        tracker.recordAttackedBy(current, 108);
        tracker.endAttackedBy(current, 110);

        assertEquals("Green dragon", require(tracker.mostLikelyKiller(111, false)).getName());
    }

    /** Pets follow us around all day; they are not killers. */
    @Test
    public void followersAreNotTracked() {
        NPC pet = RuneLiteStubs.npc(1, 13178, "Vorki", 0, false, true);
        tracker.recordAttackedBy(pet, 100);
        assertEquals(0, tracker.size());
        assertFalse(tracker.mostLikelyKiller(100, false).isPresent());
    }

    /** Talking to a banker is an interaction, not a fight. */
    @Test
    public void harmlessNpcsAreNotTracked() {
        NPC banker = RuneLiteStubs.npc(1, 1613, "Banker", 0, false, false);
        tracker.recordAttacking(banker, 100);
        assertEquals(0, tracker.size());
    }

    /**
     * Regression: the old handler only remembered targets with a combat level
     * above zero, which silently excluded every boss the game gives no level to.
     */
    @Test
    public void attackableNpcWithNoCombatLevelIsStillTracked() {
        NPC zalcano = RuneLiteStubs.npc(1, 9049, "Zalcano", 0, true, false);
        tracker.recordAttackedBy(zalcano, 100);
        assertEquals("Zalcano", require(tracker.mostLikelyKiller(101, false)).getName());
    }

    @Test
    public void playersAreOnlyBlamedWhereTheyCouldHaveKilledUs() {
        Player pker = RuneLiteStubs.player("Zezima", 126);
        tracker.recordAttackedBy(pker, 100);

        assertFalse(tracker.mostLikelyKiller(101, false).isPresent());

        Engagement killer = require(tracker.mostLikelyKiller(101, true));
        assertEquals("Zezima", killer.getName());
        assertTrue(killer.isPlayer());
        assertNull(killer.getNpcId());
    }

    /** Trading a clanmate in the wilderness must not make them the killer. */
    @Test
    public void friendsAreNeverBlamed() {
        Player friend = RuneLiteStubs.friendlyPlayer("Buddy", 126);
        tracker.recordAttacking(friend, 100);
        assertFalse(tracker.mostLikelyKiller(101, true).isPresent());
    }

    @Test
    public void anActorThatDiedFirstIsNotBlamed() {
        NPC dagannoth = RuneLiteStubs.npc(1, 100, "Dagannoth Rex", 303);
        tracker.recordAttacking(dagannoth, 100);
        tracker.recordAttackedBy(dagannoth, 100);

        RuneLiteStubs.state(dagannoth).put("isDead", true);
        assertFalse(tracker.mostLikelyKiller(101, false).isPresent());
    }

    @Test
    public void forgetDropsAnActorAndClearWipesEverything() {
        NPC first = RuneLiteStubs.npc(1, 100, "Goblin", 2);
        NPC second = RuneLiteStubs.npc(2, 101, "Imp", 2);
        tracker.recordAttackedBy(first, 100);
        tracker.recordAttackedBy(second, 100);

        tracker.forget(first);
        assertEquals(1, tracker.size());

        tracker.clear();
        assertEquals(0, tracker.size());
    }

    /**
     * The whole point of snapshotting: the attribution has to survive the actor
     * leaving the scene, so it cannot read anything off the actor at death time.
     */
    @Test
    public void attributionSurvivesTheActorLosingItsIdentity() {
        NPC boss = RuneLiteStubs.npc(1, 11751, "The Whisperer", 480);
        tracker.recordAttackedBy(boss, 100);

        // The instance is torn down: the NPC still exists as an object but no
        // longer reports a name or a composition.
        RuneLiteStubs.state(boss).put("getName", null);
        RuneLiteStubs.state(boss).put("getTransformedComposition", null);
        RuneLiteStubs.state(boss).put("getComposition", null);

        Engagement killer = require(tracker.mostLikelyKiller(101, false));
        assertEquals("The Whisperer", killer.getName());
        assertEquals(Integer.valueOf(11751), killer.getNpcId());
    }

    /** A relog or hop resets the tick counter; the old history means nothing. */
    @Test
    public void historyFromBeforeATickCounterResetIsDiscarded() {
        NPC goblin = RuneLiteStubs.npc(1, 100, "Goblin", 2);
        tracker.recordAttackedBy(goblin, 5_000);
        assertFalse(tracker.mostLikelyKiller(12, false).isPresent());
    }

    @Test
    public void switchingTargetClosesThePreviousOutboundEngagement() {
        NPC first = RuneLiteStubs.npc(1, 100, "Goblin", 2);
        NPC second = RuneLiteStubs.npc(2, 101, "Imp", 2);

        tracker.recordAttacking(first, 100);
        tracker.recordAttacking(second, 102);

        // The first is now a finished engagement and ages out on the short
        // window; the second is still open and does not.
        int afterRecentWindow = 102 + RecentCombatTracker.RECENT_WINDOW_TICKS + 1;
        assertEquals("Imp", require(tracker.mostLikelyKiller(afterRecentWindow, false)).getName());
    }

    @Test
    public void nameIsStrippedOfMarkupAndNonBreakingSpaces() {
        assertEquals("Dark wizard", RecentCombatTracker.cleanName("<col=ff0000>Dark wizard</col>"));
        assertEquals("Elite Black Knight", RecentCombatTracker.cleanName("Elite Black Knight"));
        assertNull(RecentCombatTracker.cleanName("<col=ff0000></col>"));
        assertNull(RecentCombatTracker.cleanName("   "));
        assertNull(RecentCombatTracker.cleanName(null));
    }

    /** A player with no readable name cannot be named as a killer. */
    @Test
    public void namelessPlayersAreNotTracked() {
        Player nameless = RuneLiteStubs.player(null, 100);
        tracker.recordAttackedBy(nameless, 100);
        assertEquals(0, tracker.size());
    }

    private static Engagement require(Optional<Engagement> engagement) {
        assertTrue("expected a killer to be attributed", engagement.isPresent());
        return engagement.get();
    }
}

package io.droptracker.service;

import org.junit.Test;

import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.Set;

import static org.junit.Assert.assertEquals;

/**
 * Tests {@link NearbyPlayerTracker#boundedRoster}, which keeps an accumulated
 * raid roster inside the party the raid can actually hold.
 *
 * <p>Plugin 6.0 started bracketing raid PBs by this roster, and the roster
 * accumulates across whatever the clear-on-entry lifecycle misses — ToB's state
 * varbit covers spectating as well as raiding — so Theatre of Blood times were
 * submitted as 6-, 7-, 8- and 9-player raids and the Hall of Fame grew boards
 * for team sizes the game cannot produce (suggestion #140). The same roster
 * decides who gets split credit, so the names matter as much as the count.
 */
public class NearbyPlayerTrackerRosterBoundTest {

    private static Set<String> setOf(String... names) {
        return new LinkedHashSet<>(Arrays.asList(names));
    }

    @Test
    public void capacityMatchesTheGamesOwnSlotCounts() {
        assertEquals(5, NearbyPlayerTracker.rosterCapacity(NearbyPlayerTracker.RAID_TOB));
        assertEquals(8, NearbyPlayerTracker.rosterCapacity(NearbyPlayerTracker.RAID_TOA));
        // Chambers of Xeric has no small ceiling — mass raids are legal.
        assertEquals(0, NearbyPlayerTracker.rosterCapacity(NearbyPlayerTracker.RAID_COX));
        assertEquals(0, NearbyPlayerTracker.rosterCapacity(null));
    }

    /** The regression: two runs' worth of names can no longer stack up. */
    @Test
    public void staleNamesNeverPushAToBRosterPastFive() {
        Set<String> thisRaid = setOf("Alpha", "Bravo", "Charlie");
        Set<String> lastRaid = setOf("Delta", "Echo", "Foxtrot", "Golf", "Hotel", "India");

        Set<String> bounded = NearbyPlayerTracker.boundedRoster(thisRaid, lastRaid, 5);

        assertEquals(5, bounded.size());
        assertEquals(setOf("Alpha", "Bravo", "Charlie", "Delta", "Echo"), bounded);
    }

    @Test
    public void liveReadWinsOverHistory() {
        // Every name the game is publishing right now survives; history only
        // fills what is left, so a contaminated roster self-heals as soon as
        // the next raid's party appears.
        Set<String> live = setOf("Alpha", "Bravo", "Charlie", "Delta", "Echo");
        Set<String> history = setOf("Stale1", "Stale2", "Stale3");

        assertEquals(live, NearbyPlayerTracker.boundedRoster(live, history, 5));
    }

    /**
     * Why history is kept at all (issue #43): the authoritative sources go
     * quiet before the loot chest opens, so a chest-time read is empty.
     */
    @Test
    public void historyStillCarriesTheRosterWhenTheLiveReadIsEmpty() {
        Set<String> history = setOf("Alpha", "Bravo", "Charlie", "Delta");

        Set<String> bounded = NearbyPlayerTracker.boundedRoster(
            Collections.<String>emptySet(), history, 5);

        assertEquals(history, bounded);
    }

    @Test
    public void toaKeepsItsEightSlots() {
        Set<String> live = setOf("A", "B", "C", "D", "E", "F", "G", "H");
        Set<String> history = setOf("Stale");

        Set<String> bounded = NearbyPlayerTracker.boundedRoster(live, history, 8);

        assertEquals(8, bounded.size());
        assertEquals(live, bounded);
    }

    @Test
    public void unboundedRaidsAreLeftAlone() {
        Set<String> live = setOf("A", "B", "C");
        Set<String> history = setOf("D", "E", "F", "G", "H", "I", "J", "K", "L");

        Set<String> bounded = NearbyPlayerTracker.boundedRoster(live, history, 0);

        assertEquals(12, bounded.size());
    }

    @Test
    public void duplicateNamesAcrossSourcesCountOnce() {
        Set<String> live = setOf("Alpha", "Bravo");
        Set<String> history = setOf("Bravo", "Charlie");

        assertEquals(setOf("Alpha", "Bravo", "Charlie"),
            NearbyPlayerTracker.boundedRoster(live, history, 5));
    }

    @Test
    public void emptySourcesGiveAnEmptyRoster() {
        assertEquals(Collections.<String>emptySet(),
            NearbyPlayerTracker.boundedRoster(
                Collections.<String>emptySet(), Collections.<String>emptySet(), 5));
    }
}

package io.droptracker.service;

import io.droptracker.api.DropTrackerUrls;
import okhttp3.HttpUrl;
import com.google.gson.Gson;
import io.droptracker.api.DropTrackerApi;
import io.droptracker.models.api.EventNotification;
import io.droptracker.models.api.EventState;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Wire-format tests: the JSON bodies here mirror what the production API
 * actually returns (captured from live /notifications and /event_state
 * responses), pinning the plugin's parsing of the server contract.
 */
public class EventNotificationParseTest {

    private final Gson gson = new Gson();

    @Test
    public void parsesNotificationsResponse() {
        String json = "{\"notifications\":[{"
            + "\"id\":\"1752770000-abc12345\",\"type\":\"event_completion\",\"ts\":1752770000,"
            + "\"event\":{\"id\":19,\"name\":\"Bingo Extravaganza\"},"
            + "\"data\":{\"task_label\":\"Obtain 3 Bandos hilts\",\"team_id\":38,"
            + "\"team_name\":\"Team Alpha\",\"player_name\":\"Koeppy\",\"points\":5,"
            + "\"icon_item_id\":11804,\"progress\":3,\"target\":3}}],"
            + "\"active_event\":true}";
        DropTrackerApi.NotificationsResponse response =
            gson.fromJson(json, DropTrackerApi.NotificationsResponse.class);
        assertNotNull(response.notifications);
        assertEquals(1, response.notifications.size());
        assertEquals(Boolean.TRUE, response.activeEvent);

        EventNotification n = response.notifications.get(0);
        assertEquals("event_completion", n.getType());
        assertEquals(Integer.valueOf(19), n.getEvent().getId());
        assertEquals("Team Alpha", n.getData().getTeamName());
        assertEquals(Integer.valueOf(11804), n.getData().getIconItemId());
        assertEquals(Long.valueOf(3L), n.getData().getProgress());
    }

    @Test
    public void parsesReceivedItemDetail() {
        // Completion detail fields (received_item/received_qty/points_based)
        // drive the "received X, completing Y" phrasing; points_based must
        // suppress quantity rendering (credits, not item counts).
        EventNotification n = gson.fromJson(
            "{\"id\":\"x\",\"type\":\"event_completion\",\"ts\":1,"
                + "\"data\":{\"received_item\":\"Dragon bones\",\"received_qty\":3,"
                + "\"points_based\":true}}",
            EventNotification.class);
        assertEquals("Dragon bones", n.getData().getReceivedItem());
        assertEquals(Integer.valueOf(3), n.getData().getReceivedQty());
        assertEquals(Boolean.TRUE, n.getData().getPointsBased());
    }

    @Test
    public void catchUpGateNeedsBothSizeAndStaleness() {
        long now = System.currentTimeMillis() / 1000L;
        // Big AND stale -> digest.
        assertTrue(EventNotificationService.isCatchUpBatch(batchWithTs(
            now - 7200, now - 7200, now - 3600, now - 60)));
        // Big but all fresh (live burst, e.g. a teammate spamming tasks) -> normal render.
        assertFalse(EventNotificationService.isCatchUpBatch(batchWithTs(
            now - 5, now - 5, now - 5, now - 5)));
        // Stale but tiny -> normal render (three old lines don't need a digest).
        assertFalse(EventNotificationService.isCatchUpBatch(batchWithTs(
            now - 7200, now - 7200, now - 7200)));
        // Missing ts (0) never counts as stale.
        assertFalse(EventNotificationService.isCatchUpBatch(batchWithTs(0, 0, 0, 0)));
    }

    private java.util.List<EventNotification> batchWithTs(long... timestamps) {
        java.util.List<EventNotification> batch = new java.util.ArrayList<>();
        for (long ts : timestamps) {
            batch.add(gson.fromJson(
                "{\"id\":\"x" + ts + "\",\"type\":\"event_completion\",\"ts\":" + ts + "}",
                EventNotification.class));
        }
        return batch;
    }

    @Test
    public void parsesLongPollMarker() {
        // Long-poll servers stamp long_poll=true on wait-requests; legacy
        // servers omit it entirely, which must parse as null (not false).
        DropTrackerApi.NotificationsResponse held = gson.fromJson(
            "{\"notifications\":[],\"active_event\":true,\"long_poll\":true}",
            DropTrackerApi.NotificationsResponse.class);
        assertEquals(Boolean.TRUE, held.longPoll);

        DropTrackerApi.NotificationsResponse legacy = gson.fromJson(
            "{\"notifications\":[],\"active_event\":true}",
            DropTrackerApi.NotificationsResponse.class);
        assertNull(legacy.longPoll);
    }

    @Test
    public void unknownFieldsAndTypesParseWithoutError() {
        // Forward compatibility: a future type with unknown fields must still
        // deserialize (the service then drops it by type).
        String json = "{\"notifications\":[{"
            + "\"id\":\"x\",\"type\":\"event_meteor_strike\",\"ts\":1,"
            + "\"data\":{\"brand_new_field\":{\"nested\":true}}}],\"active_event\":false}";
        DropTrackerApi.NotificationsResponse response =
            gson.fromJson(json, DropTrackerApi.NotificationsResponse.class);
        assertEquals("event_meteor_strike", response.notifications.get(0).getType());
        assertNull(response.notifications.get(0).getEvent());
    }

