package io.droptracker.service;

import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/**
 * Tests the rule that decides which item id a collection log unlock is recorded
 * under. The cache walk itself needs a running client; the judgement does not,
 * and it is the judgement that has been getting this wrong.
 *
 * <p>An unlock arrives as a chat message carrying only the item's *name*, which
 * {@link io.droptracker.util.ItemIDSearch} resolves to the earliest item sharing
 * it. For a duplicated name that is the wrong item — the collection log's Coal
 * bag is 25627, the item cache answers 764 — and nothing errors: the slot simply
 * stays empty on the player's profile while a non-slot id sits in their item
 * map.
 */
public class CollectionLogSlotsTest {

    /** Coal bag, Pet snakeling, and both Graceful hoods. */
    private static final Set<Integer> SLOTS = new HashSet<>();
    private static final Map<String, Integer> BY_NAME = new HashMap<>();

    static {
        SLOTS.add(25627);
        SLOTS.add(12921);
        SLOTS.add(11850);
        SLOTS.add(21061);
        BY_NAME.put("coal bag", 25627);
        BY_NAME.put("pet snakeling", 12921);
        // Two slots, one name: unanswerable from a name alone.
        BY_NAME.put("graceful hood", null);
    }

    private static Integer resolve(Integer candidate, String name) {
        return CollectionLogSlots.resolve(candidate, name, SLOTS, BY_NAME);
    }

    @Test
    public void anIdThatIsAlreadyASlotIsKept() {
        assertEquals(Integer.valueOf(12921), resolve(12921, "Pet snakeling"));
    }

    @Test
    public void aSameNamedImpostorIsCorrectedToTheSlot() {
        // The whole point: 764 is a Coal bag, but not the log's Coal bag.
        assertEquals(Integer.valueOf(25627), resolve(764, "Coal bag"));
    }

    @Test
    public void anAmbiguousNameIsRefused() {
        // Rooftop Agility and the Hallowed Sepulchre both have a Graceful hood
        // slot, and the chat message does not say which was unlocked. Recording
        // either would be a coin flip; the next full read knows the answer.
        assertNull(resolve(30045, "Graceful hood"));
    }

    @Test
    public void anUnknownNameIsRefused() {
        // A game update adds slots before the cache read knows them. Better a
        // slot that fills on the next full read than a wrong id recorded now.
        assertNull(resolve(30805, "Dossier"));
    }

    @Test
    public void aNullCandidateStillResolvesByName() {
        // ItemIDSearch has not finished loading, or has no row for the name.
        assertEquals(Integer.valueOf(25627), resolve(null, "Coal bag"));
    }

    @Test
    public void nameMatchingIgnoresCaseAndPadding() {
        assertEquals(Integer.valueOf(25627), resolve(764, "  coal BAG "));
    }

    @Test
    public void anEmptyNameWithAnUnknownIdIsRefused() {
        assertNull(resolve(764, ""));
        assertNull(resolve(764, null));
    }

    @Test
    public void duplicateNamesArePoisonedRatherThanOverwritten() {
        Map<Integer, String> names = new HashMap<>();
        names.put(11850, "Graceful hood");
        names.put(21061, "Graceful hood");
        names.put(30045, "Graceful hood");
        names.put(25627, "Coal bag");

        Map<String, Integer> index = CollectionLogSlots.indexByName(names);
        assertEquals(Integer.valueOf(25627), index.get("coal bag"));
        // Present, but deliberately unanswerable — and a third sighting must
        // not resurrect it.
        assertEquals(true, index.containsKey("graceful hood"));
        assertNull(index.get("graceful hood"));
    }

    @Test
    public void unnamedSlotsAreSkipped() {
        // A cache miss names an item "null"; indexing that would let any unlock
        // the client could not name resolve to a random slot.
        Map<Integer, String> names = new HashMap<>();
        names.put(1, null);
        names.put(2, "");
        names.put(3, "null");
        assertEquals(0, CollectionLogSlots.indexByName(names).size());
    }
}

package io.droptracker.service;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

import java.awt.Image;
import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.Map;
import java.util.function.Consumer;

import io.droptracker.models.PrivacyMode;
import io.droptracker.service.ScreenshotPrivacyService.CapturePlan;
import io.droptracker.testing.RuneLiteStubs;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.ui.DrawManager;
import org.junit.Before;
import org.junit.Test;

/**
 * Covers the capture coordination that keeps a player's privacy mode honest.
 *
 * <p>The bug these exist for: a Broken dragon hook is both a screenshot-worthy
 * drop and a collection log unlock, so two submissions asked for proof of the
 * same kill. Each hid the private chat, captured, then unhid it — and the first
 * one's unhide landed while the second was still waiting for its frame, so the
 * second screenshot went out with the DMs in it.
 */
public class ScreenshotPrivacyServiceTest {

    /** Split private chat on: the PM overlay interface is loaded. */
    private static final boolean SPLIT_CHAT_ON = true;

    private Client client;
    private CountingDrawManager drawManager;
    private ScreenshotPrivacyService service;

    private final Map<Integer, Widget> widgets = new HashMap<>();
    private int tick;

    /** What the chat looked like in the frame the client last handed over. */
    private boolean pmChatHiddenInFrame;
    private boolean transcriptHiddenInFrame;

    @Before
    public void setUp() {
        widgets.clear();
        tick = 0;

        client = RuneLiteStubs.stub(Client.class, "client");
        Map<String, Object> state = RuneLiteStubs.state(client);
        state.put("isResized", true);
        state.put("getGameState", GameState.LOGGED_IN);
        state.put("getTickCount", (RuneLiteStubs.Answer) args -> tick);
        state.put("getWidget", (RuneLiteStubs.Answer) args -> args.length == 1
            ? widgets.get((Integer) args[0])
            : null);

        drawManager = new CountingDrawManager();
        service = new ScreenshotPrivacyService(client, new InlineClientThread(), drawManager, null);
    }

    // --- the reported leak -------------------------------------------------

    @Test
    public void twoSubmissionsFromOneKillShareOneCapture() {
        givenChat(SPLIT_CHAT_ON);

        Capture drop = capture(PrivacyMode.HIDE_DMS);
        Capture clog = capture(PrivacyMode.HIDE_DMS);

        service.onBeforeRender();
        BufferedImage frame = renderFrame();

        assertEquals("one capture request for both submissions", 1, drawManager.requests);
        assertSame(frame, drop.image);
        assertSame(frame, clog.image);
        assertTrue("private chat was hidden in the captured frame", pmChatHiddenInFrame);
    }

    @Test
    public void aSubmissionArrivingJustAfterACaptureReusesIt() {
        givenChat(SPLIT_CHAT_ON);

        Capture drop = capture(PrivacyMode.HIDE_DMS);
        service.onBeforeRender();
        BufferedImage frame = renderFrame();

        Capture clog = capture(PrivacyMode.HIDE_DMS);

        assertEquals("no second capture requested", 1, drawManager.requests);
        assertSame(frame, drop.image);
        assertSame("collection log rode the drop's frame", frame, clog.image);
    }

    @Test
    public void theWholeCycleLeavesTheChatAsItFoundIt() {
        givenChat(SPLIT_CHAT_ON);
        Widget pmChat = widgets.get(InterfaceID.PmChat.CONTAINER);

        capture(PrivacyMode.HIDE_DMS);
        service.onBeforeRender();
        renderFrame();

        assertFalse("private chat put back after the capture", pmChat.isSelfHidden());
    }

    @Test
    public void aWidgetTheGameHadHiddenIsNotRevealed() {
        givenChat(SPLIT_CHAT_ON);
        Widget transcript = widgets.get(InterfaceID.Chatbox.CHATDISPLAY);
        transcript.setHidden(true);

        capture(PrivacyMode.HIDE_MESSAGES_AND_DMS);
        service.onBeforeRender();
        renderFrame();

        assertTrue("a transcript the game hid stays hidden", transcript.isSelfHidden());
    }

    // --- privacy correctness -----------------------------------------------

    @Test
    public void withSplitChatOffHidingDmsHidesTheTranscriptTheyLiveIn() {
        givenChat(!SPLIT_CHAT_ON);
        Widget transcript = widgets.get(InterfaceID.Chatbox.CHATDISPLAY);

        Capture shot = capture(PrivacyMode.HIDE_DMS);
        service.onBeforeRender();
        renderFrame();

        assertTrue("DMs are transcript lines with split chat off", transcriptHiddenInFrame);
        assertFalse("and the transcript comes back", transcript.isSelfHidden());
    }

    @Test
    public void aStricterRequestDoesNotRideALooserFrame() {
        givenChat(SPLIT_CHAT_ON);

        Capture openShot = capture(PrivacyMode.NONE);
        Capture privateShot = capture(PrivacyMode.HIDE_DMS);

        service.onBeforeRender();
        BufferedImage first = renderFrame();

        assertFalse("nothing hidden for the None-mode shot", pmChatHiddenInFrame);
        assertSame(first, openShot.image);
        assertNull("the DM-hiding request did not take the unhidden frame", privateShot.image);

        service.onBeforeRender();
        BufferedImage second = renderFrame();

        assertEquals(2, drawManager.requests);
        assertSame(second, privateShot.image);
        assertTrue("its own frame hid the private chat", pmChatHiddenInFrame);
    }

    @Test
    public void hidingTheWholeChatboxInResizableModeIsAPlainHide() {
        givenChat(SPLIT_CHAT_ON);
        Widget universe = widgets.get(InterfaceID.Chatbox.UNIVERSE);

        capture(PrivacyMode.HIDE_CHATBOX);
        service.onBeforeRender();

        assertTrue("chatbox hidden for the shot", universe.isSelfHidden());

        renderFrame();

        assertFalse("and restored afterwards", universe.isSelfHidden());
    }

    // --- never leave a submission hanging ----------------------------------

    @Test
    public void aCaptureThatNeverRendersGivesUpRatherThanBlockingForever() {
        givenChat(SPLIT_CHAT_ON);
        Widget pmChat = widgets.get(InterfaceID.PmChat.CONTAINER);

        Capture shot = capture(PrivacyMode.HIDE_DMS);
        service.onBeforeRender();

        // Frames stop arriving (minimised client, GPU stall); ticks keep coming.
        // One retry, then the submission is answered with no image at all.
        tick += 50;
        service.onGameTick();
        assertNull(shot.image);

        tick += 50;
        service.onGameTick();

        assertTrue("consumer was called", shot.delivered);
        assertNull("with no image rather than an unhidden one", shot.image);
        assertFalse("and the chat was put back", pmChat.isSelfHidden());
    }

    // --- plan coverage ------------------------------------------------------

    @Test
    public void aPlanCoversAnythingItHidesAtLeastAsMuchOf() {
        CapturePlan dmsOnly = new CapturePlan(true, false, false, false);
        CapturePlan dmsAndTranscript = new CapturePlan(true, true, false, false);
        CapturePlan wholeChatbox = new CapturePlan(true, false, true, false);

        assertTrue(dmsOnly.covers(CapturePlan.NOTHING));
        assertTrue(dmsAndTranscript.covers(dmsOnly));
        assertFalse(dmsOnly.covers(dmsAndTranscript));

        assertTrue("hiding the chatbox hides the transcript in it", wholeChatbox.transcript);
        assertTrue(wholeChatbox.covers(dmsAndTranscript));
        assertFalse(dmsAndTranscript.covers(wholeChatbox));
    }

    // --- harness ------------------------------------------------------------

    /**
     * @param splitChat whether the split private chat overlay exists; with the
     *                  option off the client never loads that interface
     */
    private void givenChat(boolean splitChat) {
        if (splitChat) {
            widgets.put(InterfaceID.PmChat.CONTAINER, widget());
        }
        widgets.put(InterfaceID.Chatbox.CHATDISPLAY, widget());
        widgets.put(InterfaceID.Chatbox.UNIVERSE, widget());
    }

    private Capture capture(PrivacyMode mode) {
        Capture capture = new Capture();
        service.capture(mode, capture);
        return capture;
    }

    /**
     * Draws a frame and hands it to whoever asked for one, as the client does.
     * The chat's state is read as the frame is produced, since that is what the
     * pixels would show - the service unhides again as soon as it has the image.
     */
    private BufferedImage renderFrame() {
        BufferedImage frame = new BufferedImage(4, 4, BufferedImage.TYPE_INT_ARGB);
        drawManager.processDrawComplete(() -> {
            pmChatHiddenInFrame = isHidden(InterfaceID.PmChat.CONTAINER);
            transcriptHiddenInFrame = isHidden(InterfaceID.Chatbox.CHATDISPLAY);
            return frame;
        });
        return frame;
    }

    private boolean isHidden(int componentId) {
        Widget widget = widgets.get(componentId);
        return widget != null && widget.isSelfHidden();
    }

    /** A widget stub whose hidden flag actually changes when it is set. */
    private static Widget widget() {
        Widget widget = RuneLiteStubs.stub(Widget.class, "widget");
        Map<String, Object> state = RuneLiteStubs.state(widget);
        state.put("isSelfHidden", false);
        state.put("isHidden", false);
        state.put("setHidden", (RuneLiteStubs.Answer) args -> {
            state.put("isSelfHidden", args[0]);
            state.put("isHidden", args[0]);
            return null;
        });
        return widget;
    }

    /** Records what the consumer was given. */
    private static final class Capture implements Consumer<BufferedImage> {

        private BufferedImage image;
        private boolean delivered;

        @Override
        public void accept(BufferedImage image) {
            this.image = image;
            this.delivered = true;
        }
    }

    /** The real queue-and-drain behaviour, plus a count of how often it was asked. */
    private static final class CountingDrawManager extends DrawManager {

        private int requests;

        @Override
        public void requestNextFrameListener(Consumer<Image> consumer) {
            requests++;
            super.requestNextFrameListener(consumer);
        }
    }

    /** Runs client-thread work inline, as it would when already on that thread. */
    private static final class InlineClientThread extends ClientThread {

        @Override
        public void invoke(Runnable runnable) {
            runnable.run();
        }

        @Override
        public void invokeLater(Runnable runnable) {
            runnable.run();
        }
    }
}

package io.droptracker.service;

import org.junit.Test;

import static org.junit.Assert.assertEquals;

/**
 * Tests {@link NearbyPlayerTracker#computeRaidPartySize}, the party size a
 * raid submission reports as evidence alongside its participant list. The
 * server splits credit against this number and treats 1 as proof of a solo
 * raid, so under-reporting drops real teammates' shares and over-reporting
 * dilutes everyone's cut.
 */
public class NearbyPlayerTrackerPartySizeTest {

    /** The incident shape: solo raid, no evidence of company anywhere. */
    @Test
    public void soloRaidReportsOne() {
        assertEquals(1, NearbyPlayerTracker.computeRaidPartySize(0, 0, 0));
        assertEquals(1, NearbyPlayerTracker.computeRaidPartySize(1, 1, 0));
    }

    /**
     * The live varbits reset at raid completion, so by loot-chest time only
     * the max accumulated during the raid still knows the team size.
     */
    @Test
    public void accumulatedMaxSurvivesTheVarbitReset() {
        assertEquals(3, NearbyPlayerTracker.computeRaidPartySize(0, 3, 2));
        assertEquals(5, NearbyPlayerTracker.computeRaidPartySize(0, 5, 4));
    }

    @Test
    public void liveReadWorksWhenAccumulationNeverRan() {
        // Plugin enabled mid-raid: nothing accumulated, varbits still live.
        assertEquals(4, NearbyPlayerTracker.computeRaidPartySize(4, 0, 3));
    }

    /**
     * A payload naming k others asserts a party of at least k+1; the reported
     * size can never contradict the roster it travels with. This mirrors the
     * server's split_size consistency rule.
     */
    @Test
    public void participantCountFloorsThePartySize() {
        assertEquals(3, NearbyPlayerTracker.computeRaidPartySize(0, 0, 2));
        // Roster accumulated a leaver the live count no longer shows.
        assertEquals(4, NearbyPlayerTracker.computeRaidPartySize(2, 3, 3));
    }

    @Test
    public void disagreeingSignalsTakeTheMax() {
        assertEquals(5, NearbyPlayerTracker.computeRaidPartySize(5, 3, 1));
        assertEquals(5, NearbyPlayerTracker.computeRaidPartySize(3, 5, 1));
        assertEquals(5, NearbyPlayerTracker.computeRaidPartySize(3, 1, 4));
    }
}

package io.droptracker.service;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/**
 * Tests {@link NearbyPlayerTracker#raidTypeForSource}, which decides whether a
 * submission gets the authoritative raid roster attached or a plain proximity
 * scan. A false positive attaches a raid roster to unrelated content; a false
 * negative silently downgrades a raid submission to proximity guessing.
 */
public class NearbyPlayerTrackerRaidTypeTest {

    @Test
    public void tobVariantsMapToTob() {
        assertEquals("tob", NearbyPlayerTracker.raidTypeForSource("Theatre of Blood"));
        assertEquals("tob", NearbyPlayerTracker.raidTypeForSource("Theatre of Blood: Entry Mode"));
        assertEquals("tob", NearbyPlayerTracker.raidTypeForSource("Theatre of Blood: Hard Mode"));
    }

    @Test
    public void toaVariantsMapToToa() {
        assertEquals("toa", NearbyPlayerTracker.raidTypeForSource("Tombs of Amascut"));
        assertEquals("toa", NearbyPlayerTracker.raidTypeForSource("Tombs of Amascut: Entry Mode"));
        assertEquals("toa", NearbyPlayerTracker.raidTypeForSource("Tombs of Amascut: Expert Mode"));
    }

    @Test
    public void coxVariantsMapToCox() {
        assertEquals("cox", NearbyPlayerTracker.raidTypeForSource("Chambers of Xeric"));
        assertEquals("cox", NearbyPlayerTracker.raidTypeForSource("Chambers of Xeric Challenge Mode"));
        assertEquals("cox", NearbyPlayerTracker.raidTypeForSource("Chambers of Xeric: Challenge Mode"));
    }

    @Test
    public void matchingIsCaseInsensitive() {
        assertEquals("tob", NearbyPlayerTracker.raidTypeForSource("THEATRE OF BLOOD"));
        assertEquals("cox", NearbyPlayerTracker.raidTypeForSource("chambers of xeric"));
    }

    @Test
    public void nonRaidSourcesMapToNull() {
        assertNull(NearbyPlayerTracker.raidTypeForSource(null));
        assertNull(NearbyPlayerTracker.raidTypeForSource(""));
        assertNull(NearbyPlayerTracker.raidTypeForSource("Vorkath"));
        assertNull(NearbyPlayerTracker.raidTypeForSource("Zulrah"));
        assertNull(NearbyPlayerTracker.raidTypeForSource("Barrows Chests"));
        // Raid bosses reported as NPCs are not chest/completion submissions
        assertNull(NearbyPlayerTracker.raidTypeForSource("Verzik Vitur"));
        assertNull(NearbyPlayerTracker.raidTypeForSource("Great Olm"));
    }
}

package io.droptracker.testing;

import java.lang.reflect.InvocationHandler;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;

import net.runelite.api.Client;
import net.runelite.api.IndexedObjectSet;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.Player;
import net.runelite.api.WorldType;
import net.runelite.api.WorldView;
import net.runelite.api.widgets.Widget;

/**
 * JDK dynamic-proxy stand-ins for the RuneLite API interfaces.
 *
 * <p>The plugin has no mocking framework on the test classpath (JUnit 4 only),
 * so handler tests build their client, actors and world view out of proxies that
 * return type-appropriate defaults, with per-method overrides supplied through a
 * mutable map. Mutability matters here: killer attribution turns on an actor's
 * interaction changing between one tick and the next, which is exactly what a
 * fixed stub cannot express.
 */
public final class RuneLiteStubs {

    private RuneLiteStubs() {
    }

    /**
     * An override whose result depends on the call's arguments: a varp read
     * keyed by id, a cache table lookup keyed by row. Put one in a stub's
     * {@link #state} map under the method name.
     */
    @FunctionalInterface
    public interface Answer {
        Object answer(Object[] args);
    }

    /**
     * @return the mutable override map backing a stub, keyed by method name
     */
    public static Map<String, Object> state(Object stub) {
        return ((Handler) Proxy.getInvocationHandler(stub)).values;
    }

    public static <T> T stub(Class<T> type, String label) {
        Object proxy = Proxy.newProxyInstance(
                RuneLiteStubs.class.getClassLoader(), new Class<?>[] { type }, new Handler(label));
        return type.cast(proxy);
    }

    // --- actors ---------------------------------------------------------

    public static NPCComposition composition(int id, String name, int combatLevel, boolean attackable,
            boolean follower) {
        NPCComposition composition = stub(NPCComposition.class, "composition:" + name);
        Map<String, Object> state = state(composition);
        state.put("getId", id);
        state.put("getName", name);
        state.put("getCombatLevel", combatLevel);
        state.put("getActions", attackable ? new String[] { "Attack" } : new String[] { "Talk-to" });
        state.put("isFollower", follower);
        state.put("isInteractible", true);
        state.put("isMinimapVisible", true);
        state.put("getSize", 1);
        return composition;
    }

    /** An attackable NPC of the given combat level. */
    public static NPC npc(int index, int id, String name, int combatLevel) {
        return npc(index, id, name, combatLevel, true, false);
    }

    public static NPC npc(int index, int id, String name, int combatLevel, boolean attackable, boolean follower) {
        NPC npc = stub(NPC.class, "npc:" + name);
        Map<String, Object> state = state(npc);
        state.put("getIndex", index);
        state.put("getId", id);
        state.put("getName", name);
        state.put("getCombatLevel", combatLevel);
        NPCComposition composition = composition(id, name, combatLevel, attackable, follower);
        state.put("getComposition", composition);
        state.put("getTransformedComposition", composition);
        return npc;
    }

    public static Player player(String name, int combatLevel) {
        Player player = stub(Player.class, "player:" + name);
        Map<String, Object> state = state(player);
        state.put("getName", name);
        state.put("getCombatLevel", combatLevel);
        return player;
    }

    /** A player the local account is friends with (a bystander, not a killer). */
    public static Player friendlyPlayer(String name, int combatLevel) {
        Player player = player(name, combatLevel);
        state(player).put("isFriend", true);
        return player;
    }

    // --- world ----------------------------------------------------------

    public static WorldView worldView(List<? extends Player> players, List<? extends NPC> npcs) {
        WorldView worldView = stub(WorldView.class, "worldView");
        Map<String, Object> state = state(worldView);
        state.put("players", objectSet(players));
        state.put("npcs", objectSet(npcs));
        state.put("isInstance", false);
        return worldView;
    }

    public static <T> IndexedObjectSet<T> objectSet(List<T> items) {
        List<T> copy = new ArrayList<>(items);
        return new IndexedObjectSet<T>() {
            @Override
            public T byIndex(int index) {
                return copy.get(index);
            }

            @Override
            public Iterator<T> iterator() {
                return copy.iterator();
            }
        };
    }

    /** A widget that is present and visible — e.g. the PvP safe-zone indicator. */
    public static Widget visibleWidget() {
        Widget widget = stub(Widget.class, "widget");
        state(widget).put("isHidden", false);
        return widget;
    }

    /**
     * A client whose non-primitive returns are safe to call: an empty world type
     * set and an empty world view, both overridable per test.
     */
    public static Client client(Player localPlayer) {
        Client client = stub(Client.class, "client");
        Map<String, Object> state = state(client);
        state.put("getLocalPlayer", localPlayer);
        state.put("getWorldType", EnumSet.noneOf(WorldType.class));
        state.put("getTickCount", 0);
        WorldView worldView = worldView(new ArrayList<>(), new ArrayList<>());
        state.put("getTopLevelWorldView", worldView);
        if (localPlayer != null) {
            state(localPlayer).put("getWorldView", worldView);
        }
        return client;
    }

    /** Replaces the world view seen by both the client and the local player. */
    public static void setScene(Client client, Player localPlayer, List<? extends Player> players,
            List<? extends NPC> npcs) {
        WorldView worldView = worldView(players, npcs);
        state(client).put("getTopLevelWorldView", worldView);
        if (localPlayer != null) {
            state(localPlayer).put("getWorldView", worldView);
        }
    }

    private static final class Handler implements InvocationHandler {

        private final Map<String, Object> values = new HashMap<>();
        private final String label;

        private Handler(String label) {
            this.label = label;
        }

        @Override
        public Object invoke(Object proxy, Method method, Object[] args) {
            String name = method.getName();
            switch (name) {
                case "equals":
                    return proxy == args[0];
                case "hashCode":
                    return System.identityHashCode(proxy);
                case "toString":
                    return label;
                default:
                    break;
            }
            if (values.containsKey(name)) {
                Object value = values.get(name);
                if (value instanceof Answer) {
                    return ((Answer) value).answer(args == null ? new Object[0] : args);
                }
                return value;
            }
            return defaultValue(method.getReturnType());
        }

        private static Object defaultValue(Class<?> type) {
            if (!type.isPrimitive() || type == void.class) {
                return null;
            }
            if (type == boolean.class) {
                return Boolean.FALSE;
            }
            if (type == long.class) {
                return 0L;
            }
            if (type == double.class) {
                return 0d;
            }
            if (type == float.class) {
                return 0f;
            }
            if (type == char.class) {
                return (char) 0;
            }
            if (type == byte.class) {
                return (byte) 0;
            }
            if (type == short.class) {
                return (short) 0;
            }
            return 0;
        }
    }
}

package io.droptracker;

import java.lang.reflect.Method;
import java.util.Set;
import java.util.TreeSet;

import net.runelite.client.config.ConfigItem;

import org.junit.Test;

import static org.junit.Assert.assertEquals;

/**
 * Pins every config keyName.
 * <p>
 * A player's saved setting is looked up by keyName, so renaming one silently
 * resets that option for everyone who had configured it — there is no
 * migration and no warning, the old value simply stops being found. Section,
 * position, display name and description are all safe to change and are
 * deliberately not asserted here.
 * <p>
 * If this fails you either renamed a key (don't — keep the old keyName and
 * change the display name instead) or added/removed one, in which case update
 * the list below and make sure it's a deliberate choice.
 */
public class DropTrackerConfigKeyNamesTest {

    /** Every keyName the plugin is allowed to read or write. */
    private static final Set<String> EXPECTED = new TreeSet<>(Set.of(
        // Tracking
        "lootEmbeds", "pbEmbeds", "clogEmbeds", "caEmbeds", "petEmbeds",
        "levelEmbed", "xpMilestoneEmbeds", "questsEmbed", "deathEmbeds",
        "diaryEmbeds", "slayerEmbeds", "trackActivities",
        // Screenshots
        "screenshots", "screenshotValue", "screenshotUntradeables",
        "minLevelToScreenshot", "privacyMode", "compressImages",
        "imageCompressionThresholdKb",
        // Events
        "eventNotifications", "eventDisplayMode", "eventTaskProgressNotifications",
        "eventHudDetail", "eventTeamIndicators", "eventTeamIndicatorColorNames",
        "eventTeamIndicatorsPublicChat",
        // Clan Chat
        "relayClanBroadcasts", "relayClanChat", "receiveDiscordChat",
        // Advanced
        "useApi", "receiveInGameMessages", "dropConfirmations", "syncAccountState",
        "uploadCharacterModel", "showSidePanel", "debugLogging",
        // Retired from the UI, kept so existing values still apply
        "trackExperience", "trackTrawling", "hideWhispers",
        "sendLoadoutWithPbs", "eventImportantPopupsOnly", "pollUpdates",
        // Internal state
        "pinnedEventId", "lastVersionNotified", "lastAccountName",
        "customApiEndpoint", "lastAccountHash"
    ));

    @Test
    public void configKeyNamesAreUnchanged() {
        Set<String> actual = new TreeSet<>();
        for (Method m : DropTrackerConfig.class.getMethods()) {
            ConfigItem item = m.getAnnotation(ConfigItem.class);
            if (item != null) {
                actual.add(item.keyName());
            }
        }
        assertEquals("config keyNames changed — a rename resets that setting for "
            + "every player who had configured it", EXPECTED, actual);
    }

    @Test
    public void everySettingHasAHomeOrIsDeliberatelyHidden() {
        // A visible item with no section renders loose at the top of the panel,
        // which is how options quietly escape the four-section layout.
        for (Method m : DropTrackerConfig.class.getMethods()) {
            ConfigItem item = m.getAnnotation(ConfigItem.class);
            if (item == null || item.hidden()) {
                continue;
            }
            assertEquals(item.keyName() + " is visible but has no section",
                false, item.section().isEmpty());
        }
    }
}

package io.droptracker.api;

import org.junit.Test;

import io.droptracker.api.UrlManager.WebhookEndpoint;
import okhttp3.HttpUrl;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

/**
 * The published webhook list is fetched at runtime, so its contents are outside
 * our control at review time. {@link UrlManager#parseEndpoint} is what makes that
 * acceptable: it reads two credentials out of an entry and throws the rest away,
 * so the host is always ours. These tests pin that behaviour.
 */
public class UrlManagerEndpointTest {

    private static final String ID = "123456789012345678";
    private static final String TOKEN = "abcdefghijklmnopqrstuvwxyz012345";

    @Test
    public void parsesBareCredentialPair() {
        // The format the backend publishes going forward.
        WebhookEndpoint endpoint = UrlManager.parseEndpoint(ID + "/" + TOKEN);
        assertNotNull(endpoint);
        assertEquals(HttpUrl.get("https://discord.com/api/webhooks/" + ID + "/" + TOKEN), endpoint.url());
    }

    @Test
    public void parsesLegacyFullUrlEntries() {
        // Lists published before the switch carry whole URLs; they must still work.
        assertEquals(HttpUrl.get("https://discord.com/api/webhooks/" + ID + "/" + TOKEN),
            UrlManager.parseEndpoint("https://discord.com/api/webhooks/" + ID + "/" + TOKEN).url());
        assertEquals(HttpUrl.get("https://discord.com/api/webhooks/" + ID + "/" + TOKEN),
            UrlManager.parseEndpoint("https://discordapp.com/api/webhooks/" + ID + "/" + TOKEN).url());
        assertEquals(HttpUrl.get("https://discord.com/api/webhooks/" + ID + "/" + TOKEN),
            UrlManager.parseEndpoint("/api/webhooks/" + ID + "/" + TOKEN).url());
    }

    @Test
    public void discardsWhateverHostTheEntryClaims() {
        // The property the whole design rests on: a compromised or malicious list
        // entry can change which webhook we post to, never which host.
        WebhookEndpoint endpoint =
            UrlManager.parseEndpoint("https://evil.example/api/webhooks/" + ID + "/" + TOKEN);
        assertNotNull(endpoint);
        assertEquals("discord.com", endpoint.url().host());
    }

    @Test
    public void stripsQueryAndFragment() {
        assertEquals(HttpUrl.get("https://discord.com/api/webhooks/" + ID + "/" + TOKEN),
            UrlManager.parseEndpoint(ID + "/" + TOKEN + "?wait=true").url());
        assertEquals(HttpUrl.get("https://discord.com/api/webhooks/" + ID + "/" + TOKEN),
            UrlManager.parseEndpoint(ID + "/" + TOKEN + "#x").url());
    }

    @Test
    public void rejectsAnythingThatIsNotACredentialPair() {
        assertNull(UrlManager.parseEndpoint(null));
        assertNull(UrlManager.parseEndpoint(""));
        assertNull(UrlManager.parseEndpoint("https://evil.example/"));
        assertNull(UrlManager.parseEndpoint(ID));
        assertNull(UrlManager.parseEndpoint(ID + "/" + TOKEN + "/extra"));
        assertNull(UrlManager.parseEndpoint("notanid/" + TOKEN));
        assertNull(UrlManager.parseEndpoint(ID + "/short"));
        assertNull(UrlManager.parseEndpoint(ID + "/tok en" + TOKEN));
    }

    @Test
    public void toleratesLeadingControlCharacters() {
        // Decryption occasionally leaves these on the front of the plaintext.
        assertEquals(HttpUrl.get("https://discord.com/api/webhooks/" + ID + "/" + TOKEN),
            UrlManager.parseEndpoint("  " + ID + "/" + TOKEN + "  ").url());
    }
}

package io.droptracker.api;

import com.google.gson.Gson;
import org.junit.Test;

import io.droptracker.models.api.DeathMessages;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * How {@code /player/death_messages} answers become what the editor shows,
 * against bodies shaped like the ones the server sends.
 */
public class DeathMessageApiInterpretTest {

    private final Gson gson = new Gson();

    private static final String LIVE_SHAPE =
        "{\"groups\":[{\"allowed\":false,\"blocked\":false,\"id\":2,\"name\":\"DropTracker.io\"},"
            + "{\"allowed\":true,\"blocked\":true,\"id\":270,\"name\":\"Evangelist\"}],"
            + "\"max_length\":150,\"max_messages\":5,"
            + "\"messages\":[\"{player_name} forgot to pray against {killer}\"],"
            + "\"player_name\":\"Iron Ron\","
            + "\"tokens\":[{\"help\":\"Your name\",\"sample\":\"Zezima\",\"token\":\"{player_name}\"},"
            + "{\"help\":\"What killed you\",\"sample\":\"Vorkath\",\"token\":\"{killer}\"}]}";

    @Test
    public void aSuccessfulAnswerCarriesEverythingTheEditorNeeds() {
        DeathMessageApi.Result result = DeathMessageApi.interpret(gson, 200, LIVE_SHAPE);
        assertNull(result.error);
        DeathMessages messages = result.messages;
        assertNotNull(messages);
        assertEquals("Iron Ron", messages.getPlayerName());
        assertEquals(5, messages.getMaxMessages());
        assertEquals(1, messages.getMessages().size());
        assertEquals("{killer}", messages.getTokens().get(1).getToken());
        assertEquals("Vorkath", messages.getTokens().get(1).getSample());
        assertFalse(messages.getGroups().get(0).isAllowed());
        assertTrue(messages.getGroups().get(1).isBlocked());
    }

    @Test
    public void anOlderServerLeavingFieldsOutKeepsTheDefaults() {
        DeathMessageApi.Result result = DeathMessageApi.interpret(gson, 200, "{\"messages\":[]}");
        assertNotNull(result.messages);
        assertEquals(5, result.messages.getMaxMessages());
        assertEquals(150, result.messages.getMaxLength());
        assertTrue(result.messages.getGroups().isEmpty());
        assertTrue(result.messages.getTokens().isEmpty());
    }

    @Test
    public void aRefusalIsShownInTheServersOwnWords() {
        DeathMessageApi.Result result = DeathMessageApi.interpret(gson, 422,
            "{\"error\":\"Messages can't contain links.\"}");
        assertNull(result.messages);
        assertEquals("Messages can't contain links.", result.error);
    }

    @Test
    public void anUnknownAccountSaysSo() {
        assertEquals(DeathMessageApi.NOT_REGISTERED,
            DeathMessageApi.interpret(gson, 404, "{\"error\":\"Player not found\"}").error);
    }

    @Test
    public void rateLimitedSaysToWait() {
        assertEquals(DeathMessageApi.TOO_MANY, DeathMessageApi.interpret(gson, 429, "").error);
    }

    @Test
    public void anythingElseIsTheGenericMessage() {
        assertEquals(DeathMessageApi.UNREACHABLE, DeathMessageApi.interpret(gson, 500, "<html>oops</html>").error);
        assertEquals(DeathMessageApi.UNREACHABLE, DeathMessageApi.interpret(gson, 200, "<html>proxy page</html>").error);
        assertEquals(DeathMessageApi.UNREACHABLE, DeathMessageApi.interpret(gson, 422, "not json").error);
        assertEquals(DeathMessageApi.UNREACHABLE, DeathMessageApi.interpret(gson, 200, "").error);
    }
}

package io.droptracker.api;

import org.junit.Test;

import okhttp3.HttpUrl;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/**
 * The Plugin Hub requires that every host the plugin contacts is hardcoded. That
 * guarantee rests entirely on {@link DropTrackerUrls#underBase} refusing to let a
 * server-supplied path escape its base, so these cases are the contract: if any
 * "rejected" assertion here starts returning a URL, the plugin can be pointed at
 * a host we never reviewed.
 */
public class DropTrackerUrlsTest {

    @Test
    public void anchorsPlainRelativePaths() {
        assertEquals(HttpUrl.get("https://www.droptracker.io/img/itemdb/4151.png"),
            DropTrackerUrls.image("itemdb/4151.png"));
        assertEquals(HttpUrl.get("https://www.droptracker.io/img/clans/2/lb/lootboard.png"),
            DropTrackerUrls.image("clans/2/lb/lootboard.png"));
        assertEquals(HttpUrl.get("https://droptracker-io.github.io/content/valued_items.txt"),
            DropTrackerUrls.content("valued_items.txt"));
        assertEquals(HttpUrl.get("https://static.runelite.net/cache/item/names.json"),
            DropTrackerUrls.itemCache("names.json"));
    }

    @Test
    public void rejectsAbsoluteUrls() {
        // The whole point: an API that starts returning URLs instead of paths gets ignored.
        assertNull(DropTrackerUrls.image("https://evil.example/x.png"));
        assertNull(DropTrackerUrls.image("http://evil.example/x.png"));
        assertNull(DropTrackerUrls.image("//evil.example/x.png"));
        assertNull(DropTrackerUrls.image("https://www.droptracker.io/img/itemdb/4151.png"));
    }

    @Test
    public void rejectsPathEscapes() {
        assertNull(DropTrackerUrls.image("../../etc/passwd"));
        assertNull(DropTrackerUrls.image("itemdb/../../../x.png"));
        assertNull(DropTrackerUrls.image("./x.png"));
        assertNull(DropTrackerUrls.image("/img/x.png"));
        assertNull(DropTrackerUrls.image("itemdb//x.png"));
        assertNull(DropTrackerUrls.image("itemdb\\x.png"));
    }

    @Test
    public void rejectsQueryFragmentAndEncodedCharacters() {
        assertNull(DropTrackerUrls.image("x.png?redirect=https://evil.example"));
        assertNull(DropTrackerUrls.image("x.png#frag"));
        assertNull(DropTrackerUrls.image("%2e%2e/x.png"));
        assertNull(DropTrackerUrls.image("evil.example:8080/x.png"));
        assertNull(DropTrackerUrls.image("x�.png"));
    }

    @Test
    public void encodesRatherThanRejectsRealScreenshotPaths() {
        // Screenshot directories are named after the NPC, so apostrophes, parens
        // and spaces reach us routinely — they must render, not silently vanish.
        assertEquals(HttpUrl.get("https://www.droptracker.io/img/user-upload/1/pb/Kree'arra/a.jpg"),
            DropTrackerUrls.image("user-upload/1/pb/Kree'arra/a.jpg"));
        assertEquals(HttpUrl.get("https://www.droptracker.io/img/user-upload/1/drop/Dagannoth_Rex_(hard)/a.jpg"),
            DropTrackerUrls.image("user-upload/1/drop/Dagannoth_Rex_(hard)/a.jpg"));
    }

    @Test
    public void webSegmentsAreEncodedNotInterpreted() {
        // RSNs contain spaces, and a free-form segment must never add path depth.
        assertEquals("https://www.droptracker.io/players/Big%20Boy/view",
            DropTrackerUrls.web("players", "Big Boy", "view").toString());
        assertEquals("https://www.droptracker.io/players/a%2F..%2Fb/view",
            DropTrackerUrls.web("players", "a/../b", "view").toString());
    }

    @Test
    public void rejectsEmptyAndOversizedInput() {
        assertNull(DropTrackerUrls.image(null));
        assertNull(DropTrackerUrls.image(""));
        assertNull(DropTrackerUrls.image("   "));
        StringBuilder tooLongSegment = new StringBuilder();
        for (int i = 0; i < 129; i++) {
            tooLongSegment.append('a');
        }
        assertNull(DropTrackerUrls.image(tooLongSegment.toString()));
        StringBuilder tooLongPath = new StringBuilder();
        for (int i = 0; i < 60; i++) {
            tooLongPath.append("abcdefgh/");
        }
        assertNull(DropTrackerUrls.image(tooLongPath + "x.png"));
    }

    @Test
    public void buildsDiscordWebhookFromCredentials() {
        assertEquals(
            HttpUrl.get("https://discord.com/api/webhooks/123456789012345678/abcdefghijklmnopqrstuvwxyz-_1234"),
            DropTrackerUrls.discordWebhook("123456789012345678", "abcdefghijklmnopqrstuvwxyz-_1234"));
    }

    @Test
    public void rejectsMalformedWebhookCredentials() {
        // A credential that tries to smuggle in a host or extra path depth.
        assertNull(DropTrackerUrls.discordWebhook("123/../..", "abcdefghijklmnopqrstuvwxyz"));
        assertNull(DropTrackerUrls.discordWebhook("123456789012345678", "short"));
        assertNull(DropTrackerUrls.discordWebhook("notanid", "abcdefghijklmnopqrstuvwxyz"));
        assertNull(DropTrackerUrls.discordWebhook(null, "abcdefghijklmnopqrstuvwxyz"));
        assertNull(DropTrackerUrls.discordWebhook("123456789012345678", null));
    }

    @Test
    public void buildsDiscordInviteFromCode() {
        assertEquals(HttpUrl.get("https://discord.gg/droptracker"),
            DropTrackerUrls.discordInvite("droptracker"));
        assertNull(DropTrackerUrls.discordInvite("https://discord.gg/droptracker"));
        assertNull(DropTrackerUrls.discordInvite("a/b"));
        assertNull(DropTrackerUrls.discordInvite(""));
        assertNull(DropTrackerUrls.discordInvite(null));
    }
}

package io.droptracker;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Pins {@code DropTrackerPlugin.pluginVersion} to {@code build.gradle}'s version.
 * <p>
 * The version lives in two places that nothing keeps in sync: gradle's is what
 * the Plugin Hub builds and publishes, the field's is what the client reports
 * as {@code p_v} and compares against the server's advertised latest version.
 * Bump one without the other and the update nag misfires for everybody — a
 * client on the newest build reports the old number, so the server keeps
 * telling it to fetch a release it is already running, every single login.
 */
public class PluginVersionMatchesBuildTest {

    private static final Pattern GRADLE_VERSION =
        Pattern.compile("^version\\s*=\\s*['\"]([^'\"]+)['\"]", Pattern.MULTILINE);

    @Test
    public void fieldMatchesGradle() throws IOException {
        Path gradle = findBuildGradle();
        String text = new String(Files.readAllBytes(gradle), StandardCharsets.UTF_8);
        Matcher m = GRADLE_VERSION.matcher(text);
        assertTrue("no top-level `version = '...'` in " + gradle, m.find());

        assertEquals(
            "build.gradle and DropTrackerPlugin.pluginVersion disagree — bump both",
            m.group(1),
            new DropTrackerPlugin().pluginVersion);
    }

    /** Tests may run from the project dir or a parent; walk up until it turns up. */
    private static Path findBuildGradle() {
        for (Path dir = Paths.get("").toAbsolutePath(); dir != null; dir = dir.getParent()) {
            Path candidate = dir.resolve("build.gradle");
            if (Files.isRegularFile(candidate)) {
                return candidate;
            }
        }
        throw new IllegalStateException("build.gradle not found from " + Paths.get("").toAbsolutePath());
    }
}

package io.droptracker.util;

import com.google.gson.Gson;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

public class RegionNameRegistryTest {

    // Tests are not part of the shipped plugin jar, so constructing a plain
    // Gson here does not trip the plugin-hub instantiation check.
    private static final RegionNameRegistry REGISTRY = new RegionNameRegistry(new Gson());

    /**
     * region_names.json was extracted from the 397 region-carrying constants of
     * RuneLite's DiscordGameEventType, covering 974 distinct region ids. If the
     * resource is regenerated against a newer RuneLite these counts move, and
     * that should be a deliberate change rather than a silent one.
     */
    @Test
    public void registryCoversExpectedRegionCount() {
        assertEquals(974, REGISTRY.size());
    }

    @Test
    public void namesRaidRegions() {
        // Every region of a multi-region raid resolves to the same area.
        assertEquals("Theatre of Blood", REGISTRY.nameOf(12867));
        assertEquals("Theatre of Blood", REGISTRY.nameOf(13379));
        assertEquals("Chambers of Xeric", REGISTRY.nameOf(12889));
        assertEquals("Tombs of Amascut", REGISTRY.nameOf(14160));
    }

    @Test
    public void namesBossRegions() {
        assertEquals("Vorkath", REGISTRY.nameOf(9023));
        assertEquals("Cerberus", REGISTRY.nameOf(4883));
        assertEquals("Cerberus", REGISTRY.nameOf(5395));
    }

    @Test
    public void namesTheRegionTheEmbedEditorAdvertises() {
        // The custom-embed UI documents {location} with this exact sample.
        assertEquals("Catacombs of Kourend", REGISTRY.nameOf(6557));
    }

    @Test
    public void reportsAreaType() {
        assertEquals("RAIDS", REGISTRY.typeOf(12867));
        assertEquals("BOSSES", REGISTRY.typeOf(9023));
        assertEquals("DUNGEONS", REGISTRY.typeOf(6557));
        assertEquals("CITIES", REGISTRY.typeOf(12850));
        assertEquals("MINIGAMES", REGISTRY.typeOf(9043));
        assertEquals("REGIONS", REGISTRY.typeOf(12598));
    }

    @Test
    public void lookupExposesNameAndType() {
        RegionNameRegistry.Area area = REGISTRY.lookup(12598);
        assertNotNull(area);
        assertEquals("Grand Exchange", area.getName());
        assertEquals("REGIONS", area.getType());
    }

    @Test
    public void unmappedRegionResolvesToNull() {
        // Callers fall back to reporting the bare region id, so null is the
        // contract for "no name" rather than an empty string.
        assertNull(REGISTRY.lookup(0));
        assertNull(REGISTRY.nameOf(0));
        assertNull(REGISTRY.typeOf(0));
        assertNull(REGISTRY.nameOf(-1));
    }
}

