    private static final String TEAM_SIZES = "(?<teamsize>[^)]+)";

    private static final Pattern ADVENTURE_LOG_TITLE_PATTERN = Pattern.compile("The Exploits of (.+)");
    private static final Pattern ADVENTURE_LOG_PB_PATTERN = Pattern.compile(
        "Fastest (?:kill|run|Room time|Overall time)(?: - \\(Team size: " + TEAM_SIZES + "\\))?:\\s*(?<time>[0-9:]+(?:\\.[0-9]+)?)?"
    );
    private static final Pattern ADVENTURE_LOG_PB_TIME_ONLY_PATTERN = Pattern.compile("^(?<time>[0-9:]+(?:\\.[0-9]+)?)$");

    static final int ADV_LOG_EXPLOITS_TEXT_INDEX = 1;

    private static class BossPB {
        private final String bossName;
        private final String teamSize;
        private final double time;

        public BossPB(String bossName, String teamSize, double time) {
            this.bossName = bossName;
            this.teamSize = teamSize;
            this.time = time;
        }

        public String getBossName() {
            return bossName;
        }

        public String getTeamSize() {
            return teamSize;
        }

        public double getTime() {
            return time;
        }
    }


    @SuppressWarnings("deprecation")
    public void onWidgetLoaded(WidgetLoaded widget)
    {
        switch (widget.getGroupId())
        {
            case InterfaceID.ADVENTURE_LOG:
                advLogLoaded = true;
                break;
            case InterfaceID.KILL_LOG:
                bossLogLoaded = true;
                break;
            case InterfaceID.ACHIEVEMENT_DIARY_SCROLL:
                scrollInterfaceLoaded = true;
                break;
        }
    }

    @SuppressWarnings({ "deprecation", "null" })
    @Subscribe
    public void onGameTick(GameTick event)
    {
        if (client.getLocalPlayer() == null)
        {
            return;
        }

        if (advLogLoaded)
        {
            advLogLoaded = false;

            Widget adventureLog = client.getWidget(ComponentID.ADVENTURE_LOG_CONTAINER);

            if (adventureLog != null && adventureLog.getChild(ADV_LOG_EXPLOITS_TEXT_INDEX) != null)
            {
                Matcher advLogExploitsText = ADVENTURE_LOG_TITLE_PATTERN.matcher(adventureLog.getChild(ADV_LOG_EXPLOITS_TEXT_INDEX).getText());
                if (advLogExploitsText.find())
                {
                    pohOwner = advLogExploitsText.group(1);
                }
            }
        }

        if (bossLogLoaded && (pohOwner == null || pohOwner.equals(client.getLocalPlayer().getName())))
        {
            bossLogLoaded = false;

            Widget title = client.getWidget(ComponentID.KILL_LOG_TITLE);
            Widget bossMonster = client.getWidget(ComponentID.KILL_LOG_MONSTER);
            Widget bossKills = client.getWidget(ComponentID.KILL_LOG_KILLS);

            if (title == null || bossMonster == null || bossKills == null
                || !"Boss Kill Log".equals(title.getText()))
            {
                return;
            }

        }

        // Adventure log - Counters
        if (scrollInterfaceLoaded)
        {
            scrollInterfaceLoaded = false;

            collectAndSendAdventureLogPBs();
        }
    }



    @VisibleForTesting
    static String secondsToTimeString(double seconds)
    {
        int hours = (int) (Math.floor(seconds) / 3600);
        int minutes = (int) (Math.floor(seconds / 60) % 60);
        seconds = seconds % 60;

        String timeString = hours > 0 ? String.format("%d:%02d:", hours, minutes) : String.format("%d:", minutes);

        // If the seconds is an integer, it is ambiguous if the pb is a precise
        // pb or not. So we always show it without the trailing .00.
        return timeString + (Math.floor(seconds) == seconds ? String.format("%02d", (int) seconds) : String.format("%05.2f", seconds));
    }

    // Method to collect all PBs from the adventure log
    @SuppressWarnings({ "null", "deprecation" })
    private void collectAndSendAdventureLogPBs() {
        if (client.getLocalPlayer() == null || client.getLocalPlayer().getName() == null || pohOwner == null) {
            return;
        }
        // Only process if we're in our own POH
        if (!client.getLocalPlayer().getName().equals(pohOwner)) {
            return;
        }

        List<BossPB> personalBests = new ArrayList<>();

        Widget parent = client.getWidget(ComponentID.ACHIEVEMENT_DIARY_SCROLL_TEXT);
        if (parent == null) {
            return;
        }

        // Each line is a separate static child
        Widget[] children = parent.getStaticChildren();
        String[] text = Arrays.stream(children)
            .map(Widget::getText)
            .map(Text::removeTags)
            .toArray(String[]::new);

        for (int i = 0; i < text.length; ++i) {
            String bossHeader = text[i] == null ? "" : text[i].trim();
            if (bossHeader.isEmpty()) {
                continue;
            }

            String boss = longBossName(bossHeader);
            String pendingTeamSize = null;

            for (i = i + 1; i < text.length; ++i) {
                String line = text[i] == null ? "" : text[i].trim();
                if (line.isEmpty()) {
                    break;
                }

                Matcher descriptorMatcher = ADVENTURE_LOG_PB_PATTERN.matcher(line);
                if (descriptorMatcher.find()) {
                    String normalizedTeamSize = normalizeTeamSize(descriptorMatcher.group("teamsize"));
                    String inlineTime = descriptorMatcher.group("time");

                    if (inlineTime != null && !inlineTime.isEmpty()) {
                        final double seconds = timeStringToSeconds(inlineTime);
                        personalBests.add(new BossPB(boss, normalizedTeamSize, seconds));
                        pendingTeamSize = null;
                    } else {
                        pendingTeamSize = normalizedTeamSize;
                    }
                    continue;
                }

                Matcher timeOnlyMatcher = ADVENTURE_LOG_PB_TIME_ONLY_PATTERN.matcher(line);
                if (timeOnlyMatcher.find() && pendingTeamSize != null) {
                    final double seconds = timeStringToSeconds(timeOnlyMatcher.group("time"));
                    personalBests.add(new BossPB(boss, pendingTeamSize, seconds));
                    pendingTeamSize = null;
                }
            }
        }

        if (!personalBests.isEmpty()) {
            sendPersonalBestsWebhook(pohOwner, personalBests);
        }
    }
    private void sendPersonalBestsWebhook(String playerName, List<BossPB> personalBests) {
        if (personalBests.isEmpty()) {
            return;
        }

        CustomWebhookBody customWebhookBody = new CustomWebhookBody();
        customWebhookBody.setContent(playerName + "'s Personal Best Times:");

        // Create a main embed for the PBs
        CustomWebhookBody.Embed pbEmbed = new CustomWebhookBody.Embed();
        pbEmbed.title = playerName + "'s Personal Best Times";

        // Add player info fields
        String accountHash = String.valueOf(client.getAccountHash());
        pbEmbed.addField("type", "adventure_log", true);
        pbEmbed.addField("player", playerName, true);
        pbEmbed.addField("acc_hash", accountHash, true);

        // Group PBs into batches (5 PBs per field)
        int pbsPerField = 5;
        int fieldCount = (int) Math.ceil(personalBests.size() / (double) pbsPerField);

        List<Integer> playerPets = getPetList();

        for (int i = 0; i < fieldCount; i++) {
            StringBuilder fieldContent = new StringBuilder();
            int startIdx = i * pbsPerField;
            int endIdx = Math.min(startIdx + pbsPerField, personalBests.size());

            for (int j = startIdx; j < endIdx; j++) {
                BossPB pb = personalBests.get(j);
                String formattedTime = formatTime(pb.getTime());

                // Format each PB as with "`boss name` - `team_size` : `time`" for easy parsing
                fieldContent.append("`" + pb.getBossName() + "`")
                           .append(" - ")
                           .append("`" + pb.getTeamSize() + "`")
                           .append(" : ")
                           .append("`" + formattedTime + "`");

                // Add a newline between entries (except the last one)
                if (j < endIdx - 1) {
                    fieldContent.append("\n");
                }
            }

            // Add the field with a batch number
            pbEmbed.addField("" + (i + 1), fieldContent.toString(), false);
        }
        pbEmbed.addField("Pets", playerPets.toString(), false);

        customWebhookBody.getEmbeds().add(pbEmbed);

        // Use the main plugin class' sendWebhook method
        submissionManager.sendDataToDropTracker(customWebhookBody, SubmissionType.ADVENTURE_LOG);
    }
    /**
     * Formats a time in seconds to a string in the format mm:ss or h:mm:ss
     */
    private String formatTime(double seconds)
    {
        int hours = (int) (seconds / 3600);
        int minutes = (int) ((seconds % 3600) / 60);
        double secs = seconds % 60;

        if (hours > 0)
        {
            return String.format("%d:%02d:%05.2f", hours, minutes, secs);
        }
        else
        {
            return String.format("%d:%05.2f", minutes, secs);
        }
    }

    private String longBossName(String boss)
    {
        return bossNameRegistry.canonicalName(boss, WordUtils::capitalize);
    }

    private void loadPets()
    {
        assert petsIconIdx == -1;

        // !pets requires off thread pets access, so we just store a copy
        EnumComposition petsEnum = client.getEnum(EnumID.PETS);
        pets = new int[petsEnum.size()];
        for (int i = 0; i < petsEnum.size(); ++i)
        {
            pets[i] = petsEnum.getIntValue(i);
        }

        final IndexedSprite[] modIcons = client.getModIcons();
        assert modIcons != null;

        final IndexedSprite[] newModIcons = Arrays.copyOf(modIcons, modIcons.length + pets.length);
        petsIconIdx = modIcons.length;

        client.setModIcons(newModIcons);

        for (int i = 0; i < pets.length; i++)
        {
            final int petId = pets[i];

            final AsyncBufferedImage abi = itemManager.getImage(petId);
            final int idx = petsIconIdx + i;
            abi.onLoaded(() ->
            {
                final BufferedImage image = ImageUtil.resizeImage(abi, 18, 16);
                final IndexedSprite sprite = ImageUtil.getImageIndexedSprite(image, client);
                client.getModIcons()[idx] = sprite;
            });
        }
    }

    /**
     * Looks up the list of owned pets for the local player
     */
    private List<Pet> getPetListOld()
    {
        String petListJson = configManager.getRSProfileConfiguration("chatcommands", "pets",
                String.class);

        List<Pet> petList;
        try
        {
            // CHECKSTYLE:OFF
            petList = gson.fromJson(petListJson, new TypeToken<List<Pet>>(){}.getType());
            // CHECKSTYLE:ON
        }
        catch (JsonSyntaxException ex)
        {
            return Collections.emptyList();
        }

        return petList != null ? petList : Collections.emptyList();
    }

    private List<Integer> getPetList()
    {
        List<Pet> old = getPetListOld();
        if (!old.isEmpty())
        {
            List<Integer> l = old.stream().map(Pet::getIconID).collect(Collectors.toList());
            return l;
        }

        String petListJson = configManager.getRSProfileConfiguration("chatcommands", "pets2",
                String.class);

        List<Integer> petList;
        try
        {
            // CHECKSTYLE:OFF
            petList = gson.fromJson(petListJson, new TypeToken<List<Integer>>(){}.getType());
            // CHECKSTYLE:ON
        }
        catch (JsonSyntaxException ex)
        {
            return Collections.emptyList();
        }

        return petList != null ? petList : Collections.emptyList();
    }

    @VisibleForTesting
    static double timeStringToSeconds(String timeString)
    {
        String[] s = timeString.split(":");
        if (s.length == 2) // mm:ss
        {
            return Integer.parseInt(s[0]) * 60 + Double.parseDouble(s[1]);
        }
        else if (s.length == 3) // h:mm:ss
        {
            return Integer.parseInt(s[0]) * 60 * 60 + Integer.parseInt(s[1]) * 60 + Double.parseDouble(s[2]);
        }
        return Double.parseDouble(timeString);
    }

    private static String normalizeTeamSize(String rawTeamSize)
    {
        if (rawTeamSize == null)
        {
            return "Solo";
        }

        String teamSize = rawTeamSize.toLowerCase().trim();
        if (teamSize.isEmpty())
        {
            return "Solo";
        }
        if (teamSize.contains("solo"))
        {
            return "Solo";
        }

        // Handles values like "3 player hard mode", "4 players expert mode", "6+ players".
        teamSize = teamSize
            .replace("hard mode", "")
            .replace("entry mode", "")
            .replace("expert mode", "")
            .replace("player", "")
            .replace("players", "")
            .trim();

        if ("1".equals(teamSize))
        {
            return "Solo";
        }

        return teamSize.isEmpty() ? "Solo" : teamSize;
    }
    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        switch (event.getGameState())
        {
            case LOADING:
            case HOPPING:
                pohOwner = null;
                break;
            case STARTING:
                petsIconIdx = -1;
                pets = null;
                break;
            case LOGIN_SCREEN:
                if (petsIconIdx == -1)
                {
                    loadPets();
                }
                break;
            default:
                break;
        }
    }

}

package io.droptracker.events;

import com.google.inject.Inject;
import io.droptracker.models.CustomWebhookBody;
import io.droptracker.models.submissions.Drop;
import io.droptracker.models.submissions.SubmissionType;
import io.droptracker.service.CollectionLogSlots;
import io.droptracker.service.KCService;
import io.droptracker.service.StateSyncScheduler;
import io.droptracker.service.StateSyncService;
import io.droptracker.util.ItemIDSearch;
import io.droptracker.util.Rarity;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.game.ItemStack;
import net.runelite.http.api.loottracker.LootRecordType;
import org.jetbrains.annotations.Nullable;

import java.time.Duration;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.regex.Matcher;
import java.util.regex.Pattern;


@Slf4j
public class ClogHandler extends BaseEventHandler {
    private final Rarity rarity;
    private final KCService kcService;
    private final ItemIDSearch itemIDFinder;
    /* State sync: a newly unlocked slot should reach the website promptly,
     * rather than waiting out the periodic sync interval. */
    private final StateSyncService stateSyncService;
    private final StateSyncScheduler stateSyncScheduler;
    /* Which ids the collection log actually has slots for, so the id we record
     * for an unlock is the log's, not the first item to share its name. */
    private final CollectionLogSlots collectionLogSlots;

    private final AtomicBoolean popupStarted = new AtomicBoolean(false);

    private static final Duration RECENT_DROP = Duration.ofSeconds(30L);

    @Inject
    public ClogHandler(ItemIDSearch itemIDFinder, Rarity rarity, KCService kcService,
                       StateSyncService stateSyncService, StateSyncScheduler stateSyncScheduler,
                       CollectionLogSlots collectionLogSlots) {
        this.stateSyncService = stateSyncService;
        this.stateSyncScheduler = stateSyncScheduler;
        this.collectionLogSlots = collectionLogSlots;
        this.itemIDFinder = itemIDFinder;
        this.rarity = rarity;
        this.kcService = kcService;
    }


    static final Pattern COLLECTION_LOG_REGEX = Pattern.compile("New item added to your collection log: (?<itemName>(.*))");
    private static final int POPUP_PREFIX_LENGTH = "New item:".length();



    @Override
    public boolean isEnabled() {
        return config.clogEmbeds();
    }


    public void onChatMessage(String chatMessage) {
        if (client.getVarbitValue(VarbitID.OPTION_COLLECTION_NEW_ITEM) != 1 || !this.isEnabled()) {
            // require notifier enabled without popup mode to use chat event
            return;
        }
        Matcher collectionMatcher = COLLECTION_LOG_REGEX.matcher(chatMessage);
        if (collectionMatcher.find()) {
            String itemName = collectionMatcher.group("itemName");
            clientThread.invokeLater(() -> processCollection(itemName));
        }
    }

    public void reset() {
        popupStarted.set(false);
    }

    public void onScript(int scriptId) {
        if (scriptId == ScriptID.NOTIFICATION_START) {
            popupStarted.set(true);
        } else if (scriptId == ScriptID.NOTIFICATION_DELAY) {
            String topText = client.getVarcStrValue(VarClientStr.NOTIFICATION_TOP_TEXT);
            if (popupStarted.getAndSet(false) && "Collection log".equalsIgnoreCase(topText) && this.isEnabled()) {
                String bottomText = submissionManager.sanitize(client.getVarcStrValue(VarClientStr.NOTIFICATION_BOTTOM_TEXT));
                processCollection(bottomText.substring(POPUP_PREFIX_LENGTH).trim());
            }
        }
    }




    private void processCollection(String itemName) {
        if (!this.isEnabled()) {
            log.debug("Collection log processing disabled");
            return;
        }

        if (itemName == null || itemName.trim().isEmpty()) {
            log.debug("Cannot process collection log with null/empty item name");
            return;
        }

        try {
            int completed = 0;
            int total = 0;

            if (client != null) {
                completed = client.getVarpValue(VarPlayerID.COLLECTION_COUNT);
                total = client.getVarpValue(VarPlayerID.COLLECTION_COUNT_MAX);
            }

            boolean varpValid = total > 0 && completed > 0;
            if (!varpValid) {
                // This occurs if the player doesn't have the character summary tab selected
                log.debug("Collection log progress varps were invalid ({} / {})", completed, total);
            }

            Integer itemId = null;
            if (itemIDFinder != null) {
                try {
                    itemId = itemIDFinder.findItemId(itemName);
                } catch (Exception e) {
                    log.debug("Error finding item ID for {}: {}", itemName, e.getMessage());
                }
            }

            // Feed the state snapshot too: one new slot is cheap to record and
            // means the profile page updates now instead of at the next
            // scheduled sync. Additive only - this never implies the rest of
            // the log was read.
            //
            // The id has to be the *collection log's*, which is not always the
            // one a name resolves to: ItemIDSearch answers with the earliest
            // item sharing the name, so "Coal bag" gives 764 where the log
            // holds 25627. A wrong id leaves the slot looking unfilled and puts
            // a non-slot into the account's item map, so an id the log does not
            // define is dropped rather than recorded - a full read of the log
            // reports the slot properly soon enough.
            Integer slotId = collectionLogSlots != null
                    ? collectionLogSlots.resolve(itemId, itemName)
                    : itemId;
            if (slotId != null && stateSyncService != null && stateSyncService.isEnabled()) {
                stateSyncService.storeItem(slotId, 1);
                stateSyncScheduler.scheduleRapid("clog-item");
            }

            Drop loot = itemId != null ? getLootSource(itemId) : null;
            Integer killCount = 0;
            if (loot != null && kcService != null) {
                try {
                    killCount = kcService.getKillCountWithStorage(loot.getCategory(), loot.getSource());
                } catch (Exception e) {
                    log.debug("Error getting kill count: {}", e.getMessage());
                }
            }

            OptionalDouble itemRarity = OptionalDouble.empty();
            if (loot != null && loot.getCategory() == LootRecordType.NPC && itemId != null && rarity != null) {
                try {
                    itemRarity = rarity.getRarity(loot.getSource(), itemId, 1);
                } catch (Exception e) {
                    log.debug("Error calculating rarity: {}", e.getMessage());
                }
            }

            String player = getPlayerName();
            if (player == null) {
                log.debug("Skipping collection log submission: no resolvable player name");
                return;
            }
            CustomWebhookBody collectionLogBody = createWebhookBody(player + " received a collection log:");
            CustomWebhookBody.Embed collEmbed = createEmbed(player + " received a collection log:", "collection_log");

            Map<String, Object> fieldData = new HashMap<>();
            fieldData.put("source", loot != null && loot.getSource() != null ? loot.getSource() : "unknown");
            fieldData.put("item", itemName);
            fieldData.put("kc", killCount);
            fieldData.put("rarity", itemRarity.isPresent() ? itemRarity.getAsDouble() : "unknown");
            fieldData.put("item_id", itemId);
            fieldData.put("slots", varpValid ? completed + "/" + total : "unknown");

            addFields(collEmbed, fieldData);

            if (collectionLogBody != null && collEmbed != null) {
                collectionLogBody.getEmbeds().add(collEmbed);
                sendData(collectionLogBody, SubmissionType.COLLECTION_LOG);
            } else {
                log.warn("Failed to create webhook or embed for collection log");
            }
        } catch (Exception e) {
            log.error("Error processing collection log for item {}: {}", itemName, e.getMessage(), e);
        }
    }

    @Nullable
    private Drop getLootSource(int itemId) {
        if (plugin == null) {
            return null;
        }

        Drop drop = plugin.lastDrop;
        if (drop == null || drop.getTime() == null) {
            return null;
        }

        try {
            if (Duration.between(drop.getTime(), Instant.now()).compareTo(RECENT_DROP) > 0) {
                return null;
            }

            if (drop.getItems() == null) {
                return null;
            }

            for (ItemStack item : drop.getItems()) {
                if (item != null && item.getId() == itemId) {
                    return drop;
                }
            }
        } catch (Exception e) {
            log.debug("Error checking loot source for item {}: {}", itemId, e.getMessage());
        }

        return null;
    }

}

package io.droptracker.events;

import java.util.HashMap;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import io.droptracker.models.CustomWebhookBody;
import io.droptracker.models.submissions.SubmissionType;
import lombok.extern.slf4j.Slf4j;

/**
 * Tracks achievement diary completions via the game-message announcement, e.g.
 * "Congratulations! You have completed all of the easy tasks in the Ardougne area."
 *
 * Invoked manually from DropTrackerPlugin's event subscriptions (handlers in
 * this package are not registered on the RuneLite event bus).
 */
@Slf4j
public class DiaryHandler extends BaseEventHandler {

    private static final Pattern DIARY_COMPLETION_PATTERN = Pattern.compile(
        "Congratulations! You have completed all of the (?<tier>easy|medium|hard|elite) tasks in (?:the )?(?<area>.+?) area",
        Pattern.CASE_INSENSITIVE
    );

    @Override
    public boolean isEnabled() {
        return config.diaryEmbeds();
    }

    public void onGameMessage(String message) {
        if (!isEnabled() || !plugin.isTracking || message == null) {
            return;
        }

        Matcher matcher = DIARY_COMPLETION_PATTERN.matcher(message);
        if (!matcher.find()) {
            return;
        }

        String tier = ucFirst(matcher.group("tier"));
        String area = matcher.group("area").trim();

        String playerName = getPlayerName();
        if (playerName == null) {
            log.debug("Skipping diary submission: no resolvable player name");
            return;
        }
        CustomWebhookBody webhook = createWebhookBody(playerName + " completed an achievement diary!");
        CustomWebhookBody.Embed embed = createEmbed(playerName + " completed the " + tier + " " + area + " diary!", "diary");

        Map<String, Object> fieldData = new HashMap<>();
        fieldData.put("diary_name", area);
        fieldData.put("diary_tier", tier);
        addFields(embed, fieldData);
        webhook.getEmbeds().add(embed);

        sendData(webhook, SubmissionType.DIARY);
    }

    private static String ucFirst(String text) {
        if (text == null || text.isEmpty()) {
            return text;
        }
        return Character.toUpperCase(text.charAt(0)) + text.substring(1).toLowerCase();
    }
}

package io.droptracker.events;

import com.google.inject.Inject;
import io.droptracker.DropTrackerConfig;
import io.droptracker.DropTrackerPlugin;
import io.droptracker.api.DropTrackerApi;
import io.droptracker.models.CustomWebhookBody;
import io.droptracker.models.submissions.SubmissionType;
import io.droptracker.service.SubmissionManager;
import io.droptracker.util.DebugLogger;
import io.droptracker.util.PlayerIdentity;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;

import javax.annotation.Nullable;
import java.util.concurrent.ScheduledExecutorService;
import java.util.Map;

/**
 * Base abstract class for all event handlers
 * Provides common dependencies, shared logic, and standardized methods for webhook creation and data transmission.
 */
@Slf4j
public abstract class BaseEventHandler {

    @Inject
    protected DropTrackerPlugin plugin;

    @Inject
    protected Client client;

    @Inject
    protected ConfigManager configManager;

    @Inject
    protected ClientThread clientThread;

    @Inject
    protected DropTrackerApi api;

    @Inject
    protected DropTrackerConfig config;

    @Inject
    protected SubmissionManager submissionManager;

    // Optional dependency - not all handlers use the executor
    @Inject(optional = true)
    protected ScheduledExecutorService executor;

    /**
     * Determines if this event handler is currently enabled.
     * Override this method in subclasses to implement specific enable/disable logic.
     * 
     * @return true if the handler is enabled, false otherwise
     */
    public boolean isEnabled() {
        return true;
    }

    /**
     * Resolves the RSN to submit this event under.
     *
     * <p>See {@link PlayerIdentity} for why this never falls back to a made-up
     * name, and what it does fall back to instead.
     *
     * @return the RSN, or {@code null} when it cannot be established — callers
     *         must skip the submission entirely rather than send it nameless
     */
    @Nullable
    protected String getPlayerName() {
        return PlayerIdentity.resolve(
            plugin != null ? plugin.getLocalPlayerName() : null,
            getAccountHash(),
            config != null ? config.lastAccountName() : null,
            config != null ? config.lastAccountHash() : null);
    }

    /**
     * Gets the account hash as a string.
     * 
     * @return the account hash, or "0" if client is null
     */
    protected String getAccountHash() {
        return client != null ? String.valueOf(client.getAccountHash()) : "0";
    }

    /**
     * Adds common fields that are present in all webhook embeds.
     * This includes player_name, acc_hash, p_v, and any global fields.
     * 
     * @param embed the embed to add fields to
     */
    protected void addCommonFields(CustomWebhookBody.Embed embed) {
        if (embed == null) {
            log.warn("Attempted to add common fields to null embed");
            return;
        }

        String playerName = getPlayerName();
        String accountHash = getAccountHash();
        String pluginVersion = plugin != null && plugin.pluginVersion != null ? plugin.pluginVersion : "unknown";
        String guid = api != null ? api.generateGuidForSubmission() : "unknown";

        /* Handlers are expected to bail before building an embed they have no
           identity for. If one ever forgets, an empty name is what makes the
           submission fail SubmissionManager's identity check instead of going
           out under a made-up one. */
        if (playerName == null) {
            log.debug("Building an embed with no resolvable player name; this submission will be dropped");
            playerName = "";
        }

        embed.addField("player_name", playerName, true);
        embed.addField("acc_hash", accountHash, true);
        embed.addField("p_v", pluginVersion, true);
        embed.addField("guid", guid, true);
        /* The server's "Drop processed" confirmation obeys this over the
           player's website setting, which only covers builds without it. */
        if (config != null) {
            boolean confirm = config.receiveInGameMessages() && config.dropConfirmations();
            embed.addField("drop_confirm", String.valueOf(confirm), true);
        }
    }

    /**
     * Creates a new webhook body with basic setup.
     * 
     * @param content the main content message for the webhook
     * @return a new CustomWebhookBody instance
     */
    protected CustomWebhookBody createWebhookBody(String content) {
        CustomWebhookBody webhook = new CustomWebhookBody();
        webhook.setContent(content != null ? content : "DropTracker Event");
        return webhook;
    }

    /**
     * Creates a new embed with the specified title and type, and automatically adds common fields.
     * 
     * @param title the title for the embed
     * @param type the type of the embed (e.g., "drop", "combat_achievement", "collection_log", "npc_kill")
     * @return a new CustomWebhookBody.Embed instance with common fields already added
     */
    protected CustomWebhookBody.Embed createEmbed(String title, String type) {
        CustomWebhookBody.Embed embed = new CustomWebhookBody.Embed();
        if (title != null && !title.trim().isEmpty()) {
            embed.setTitle(title);
        } else {
            embed.setTitle("DropTracker Event");
        }
        if (type != null && !type.trim().isEmpty()) {
            embed.addField("type", type, true);
        }
        addCommonFields(embed);
        return embed;
    }

    /**
     * Creates a new embed with the specified title (no type field).
     * 
     * @param title the title for the embed
     * @return a new CustomWebhookBody.Embed instance
     */
    protected CustomWebhookBody.Embed createEmbed(String title) {
        return createEmbed(title, null);
    }

    /**
     * Adds multiple fields to an embed from a map of field data.
     * 
     * @param embed the embed to add fields to
     * @param fieldData map of field names to values
     */
    protected void addFields(CustomWebhookBody.Embed embed, Map<String, Object> fieldData) {
        addFields(embed, fieldData, true);
    }

    /**
     * Adds multiple fields to an embed from a map of field data.
     * 
     * @param embed the embed to add fields to
     * @param fieldData map of field names to values
     * @param inline whether the fields should be inline
     */
    protected void addFields(CustomWebhookBody.Embed embed, Map<String, Object> fieldData, boolean inline) {
        if (embed == null) {
            log.warn("Attempted to add fields to null embed");
            return;
        }
        if (fieldData == null) {
            log.warn("Attempted to add null fieldData to embed");
            return;
        }

        for (Map.Entry<String, Object> entry : fieldData.entrySet()) {
            String fieldName = entry.getKey();
            if (fieldName == null || fieldName.trim().isEmpty()) {
                log.debug("Skipping field with null/empty name");
                continue;
            }

            String value;
            Object rawValue = entry.getValue();
            if (rawValue == null) {
                value = "N/A";
            } else if (rawValue instanceof String && ((String) rawValue).trim().isEmpty()) {
                value = "N/A";
            } else {
                value = String.valueOf(rawValue);
            }

            embed.addField(fieldName, value, inline);
        }
    }

    /**
     * Sends webhook data to the DropTracker API with a string type identifier.
     * Used for events like combat achievements, collection logs, and kills.
     * 
     * @param webhook the webhook body to send
     * @param type the event type identifier
     */
    protected void sendData(CustomWebhookBody webhook, SubmissionType type) {
        DebugLogger.log("[BaseEventHandler][send] sendData called; type=" + type
            + ", embedCount=" + (webhook != null && webhook.getEmbeds() != null ? webhook.getEmbeds().size() : 0)
            + ", payload=" + webhook);
        if (webhook == null) {
            log.warn("Attempted to send null webhook data");
            return;
        }
        if (webhook.getEmbeds() == null || webhook.getEmbeds().isEmpty()) {
            log.warn("Attempted to send webhook with no embeds");
            return;
        }
        if (type == null) {
            log.warn("Attempted to send webhook with null submission type");
            return;
        }
        if (submissionManager == null) {
            log.error("SubmissionManager is null, cannot send webhook data");
            return;
        }

        try {
            submissionManager.sendDataToDropTracker(webhook, type);
        } catch (Exception e) {
            log.error("Failed to send webhook data: {}", e.getMessage(), e);
        }
    }

    /**
     * Sends webhook data to the DropTracker API with a numeric value.
     * Used for drops where the value is the total drop value.
     * 
     * @param webhook the webhook body to send
     * @param value the total value of the event
     * @param singleValue the value of individual items (for stacked item checking)
     */
    protected void sendData(CustomWebhookBody webhook, long value, long singleValue, boolean valueModified) {
        if (webhook == null) {
            log.warn("Attempted to send null webhook data");
            return;
        }
        if (webhook.getEmbeds() == null || webhook.getEmbeds().isEmpty()) {
            log.warn("Attempted to send webhook with no embeds");
            return;
        }
        if (submissionManager == null) {
            log.error("SubmissionManager is null, cannot send webhook data");
            return;
        }

        try {
            submissionManager.sendDataToDropTracker(webhook, value, singleValue, valueModified);
        } catch (Exception e) {
            log.error("Failed to send webhook data: {}", e.getMessage(), e);
        }
    }

    /**
     * Gets the kill count for a specific boss from the configuration.
     * 
     * @param bossName the name of the boss
     * @return the kill count, or 0 if not found
     */
    protected int getKillCount(String bossName) {
        if (bossName == null) {
            return 0;
        }
        Integer killCount = configManager.getRSProfileConfiguration("killcount", bossName.toLowerCase(), int.class);
        return killCount != null ? killCount : 0;
    }


}

package io.droptracker.events;

import java.util.Collection;
import java.util.HashMap;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import javax.annotation.Nullable;
import javax.inject.Singleton;

import org.apache.commons.lang3.StringUtils;

import com.google.common.collect.ImmutableList;

import io.droptracker.models.CustomWebhookBody;
import io.droptracker.models.submissions.SubmissionType;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.VarPlayer;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

@Slf4j
@Singleton
public class QuestHandler extends BaseEventHandler {

    private static final Pattern QUEST_PATTERN_1 = Pattern.compile(".+?ve\\.*? (?<verb>been|rebuilt|.+?ed)? ?(?:the )?'?(?<quest>.+?)'?(?: [Qq]uest)?[!.]?$");
    private static final Pattern QUEST_PATTERN_2 = Pattern.compile("'?(?<quest>.+?)'?(?: [Qq]uest)? (?<verb>[a-z]\\w+?ed)?(?: f.*?)?[!.]?$");
    private static final Collection<String> RFD_TAGS = ImmutableList.of("Another Cook", "freed", "defeated", "saved");
    private static final Collection<String> WORD_QUEST_IN_NAME_TAGS = ImmutableList.of("Another Cook", "Doric", "Heroes", "Legends", "Observatory", "Olaf", "Waterfall");
    private static final Map<String, String> QUEST_REPLACEMENTS = Map.of(
        "Lumbridge Cook... again", "Another Cook's",
        "Skrach 'Bone Crusher' Uglogwee", "Skrach Uglogwee"
    );

    /* VarbitIDs for quest tracking */
    private static final int VARBIT_QUESTS_COMPLETED_COUNT = 6347;
    private static final int VARBIT_QUESTS_TOTAL_COUNT = 11877;
    private static final int VARBIT_QP_MAX = 1782;


    @Override
    public boolean isEnabled() {
        return config.questsEmbed();
    }

    public void onWidgetLoaded(WidgetLoaded event) {
        if (event.getGroupId() == InterfaceID.QUESTSCROLL && isEnabled()) {
            Widget questTitle = client.getWidget(InterfaceID.Questscroll.QUEST_TITLE); // Quest title widget
            if (questTitle != null) {
                String questText = questTitle.getText();
                // 1 tick delay to ensure relevant varbits have been processed by the client
                clientThread.invokeLater(() -> handleQuestCompletion(questText));
            }
        }
    }

    @SuppressWarnings("deprecation")
    private void handleQuestCompletion(String questText) {
        // Get quest completion stats
        int completedQuests = client.getVarbitValue(VARBIT_QUESTS_COMPLETED_COUNT);
        int totalQuests = client.getVarbitValue(VARBIT_QUESTS_TOTAL_COUNT);
        boolean validQuests = completedQuests > 0 && totalQuests > 0;

        // Get quest points
        int questPoints = client.getVarpValue(VarPlayer.QUEST_POINTS);
        int totalQuestPoints = client.getVarbitValue(VARBIT_QP_MAX);
        boolean validPoints = questPoints > 0 && totalQuestPoints > 0;

        // Parse the quest name
        String parsedQuestName = parseQuestWidget(questText);
        if (parsedQuestName == null) {
            return;
        }

        String playerName = getPlayerName();
        if (playerName == null) {
            log.debug("Skipping quest submission: no resolvable player name");
            return;
        }

        CustomWebhookBody webhook = createWebhookBody(playerName + " completed a quest!");
        CustomWebhookBody.Embed embed = createEmbed("Quest Completed!", "quest");

        Map<String, Object> fieldData = new HashMap<>();
        fieldData.put("quest_name", parsedQuestName);

        if (validQuests) {
            fieldData.put("quests_completed", completedQuests);
            fieldData.put("total_quests", totalQuests);
            fieldData.put("completion_percentage", String.format("%.1f%%", (completedQuests * 100.0) / totalQuests));
        }

        if (validPoints) {
            fieldData.put("quest_points", questPoints);
            fieldData.put("total_quest_points", totalQuestPoints);
            fieldData.put("qp_percentage", String.format("%.1f%%", (questPoints * 100.0) / totalQuestPoints));
        }

        fieldData.put("timestamp", System.currentTimeMillis() / 1000);

        addFields(embed, fieldData);
        webhook.getEmbeds().add(embed);

        sendData(webhook, SubmissionType.QUEST_COMPLETION);
    }

    /* Helper methods */

    @Nullable
    private String parseQuestWidget(final String text) {
        if (text == null || text.isEmpty()) {
            return null;
        }

        // Try to match the quest completion text
        Matcher matcher = getMatcher(text);
        if (matcher == null) {
            // If no pattern matches, try to extract quest name directly
            // Some quests might just show the name without additional text
            return cleanQuestName(text);
        }

        String quest = matcher.group("quest");
        quest = QUEST_REPLACEMENTS.getOrDefault(quest, quest);

        String verb = StringUtils.defaultString(matcher.group("verb"));

        if (verb.contains("kind of")) {
            return null;
        } else if (verb.contains("completely")) {
            quest += " II";
        }

        // Handle Recipe for Disaster subquests
        if (RFD_TAGS.stream().anyMatch((quest + verb)::contains)) {
            quest = "Recipe for Disaster - " + quest;
        }

        // Add "Quest" to certain quest names that need it
        if (WORD_QUEST_IN_NAME_TAGS.stream().anyMatch(quest::contains)) {
            quest += " Quest";
        }

        return quest;
    }

    @Nullable
    private Matcher getMatcher(String text) {
        if (text == null || text.isEmpty()) {
            return null;
        }


        // "You have completed The Corsair Curse!"
        Matcher questMatch1 = QUEST_PATTERN_1.matcher(text);
        if (questMatch1.matches()) {
            return questMatch1;
        }

        // "'One Small Favour' completed!"
        Matcher questMatch2 = QUEST_PATTERN_2.matcher(text);
        if (questMatch2.matches()) {
            return questMatch2;
        }

        return null;
    }

    private String cleanQuestName(String text) {
        // Remove common prefixes/suffixes
        String cleaned = text;
        cleaned = cleaned.replaceAll("^You have completed ", "");
        cleaned = cleaned.replaceAll("^Congratulations! You've completed ", "");
        cleaned = cleaned.replaceAll("[!.]$", "");
        cleaned = cleaned.trim();
        // If it's still empty or too short, return null
        if (cleaned.isEmpty() || cleaned.length() < 3) {
            return null;
        }

        return cleaned;
    }
}

package io.droptracker.events;

import java.util.Collections;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import com.google.common.annotations.VisibleForTesting;
import com.google.inject.Inject;

import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.game.ItemStack;

/**
 * Tracks deep sea trawling (Sailing) catches. Trawled fish never fire a
 * RuneLite loot event — they land in the ship's shared trawling net and are
 * only later collected into the inventory or cargo hold (where they turn into
 * fish crates, losing item identity). We therefore count the per-catch game
 * message ("You catch 2 raw haddock!"), which also attributes each fish to
 * the player who caught it rather than whoever empties the net.
 *
 * Ordinary fishing produces "You catch a ..." messages too, so only species
 * from the static trawling map are ever submitted — never a generic
 * name-to-id lookup. Crewmate catches ("<name> catches ..."), "Trawler's
 * trust" bonus lines and net-empty/collection messages are ignored. Prior
 * art for the message formats: github.com/CarelessEsper/deepSeaTrawling.
 *
 * Invoked manually from DropTrackerPlugin's event subscriptions (handlers in
 * this package are not registered on the RuneLite event bus).
 */
@Slf4j
public class TrawlingHandler extends BaseEventHandler {

    public static final String SOURCE_NAME = "Deep Sea Trawling";

    /* "You catch a raw halibut!" / "You catch 2 raw giant krill!" */
    private static final Pattern CATCH_PATTERN = Pattern.compile(
        "^You catch (?<qty>an?|\\d+) (?<fish>.+?)[!.]?$"
    );

    /* Trawling-only species, keyed by lowercase item name without the "raw "
     * prefix. Acts as both the id map and the allowlist that keeps ordinary
     * fishing catches out. Trophy fish are included in case their
     * announcement arrives as a catch-style message. */
    private static final Map<String, Integer> FISH_IDS;
    static {
        Map<String, Integer> ids = new HashMap<>();
        ids.put("giant krill", ItemID.RAW_GIANT_KRILL);
        ids.put("haddock", ItemID.RAW_HADDOCK);
        ids.put("yellowfin", ItemID.RAW_YELLOWFIN);
        ids.put("halibut", ItemID.RAW_HALIBUT);
        ids.put("bluefin", ItemID.RAW_BLUEFIN);
        ids.put("marlin", ItemID.RAW_MARLIN);
        ids.put("giant blue krill", ItemID.POH_TROPHYDROP_GIANT_KRILL);
        ids.put("golden haddock", ItemID.POH_TROPHYDROP_HADDOCK);
        ids.put("orangefin", ItemID.POH_TROPHYDROP_YELLOWFIN);
        ids.put("huge halibut", ItemID.POH_TROPHYDROP_HALIBUT);
        ids.put("purplefin", ItemID.POH_TROPHYDROP_BLUEFIN);
        ids.put("swift marlin", ItemID.POH_TROPHYDROP_MARLIN);
        FISH_IDS = Collections.unmodifiableMap(ids);
    }

    private final DropHandler dropHandler;

    @Inject
    public TrawlingHandler(DropHandler dropHandler) {
        this.dropHandler = dropHandler;
    }

    @Override
    public boolean isEnabled() {
        return config.trackActivities() && config.trackTrawling();
    }

    public void onGameMessage(String message) {
        if (!isEnabled() || !plugin.isTracking || message == null) {
            return;
        }

        ParsedCatch parsed = parseCatch(message);
        if (parsed == null) {
            return;
        }

        Integer itemId = resolveFishId(parsed.getFishName());
        if (itemId == null) {
            /* Ordinary fishing catch, or a species we don't know yet */
            return;
        }

        dropHandler.onActivityLoot(SOURCE_NAME,
            Collections.singletonList(new ItemStack(itemId, parsed.getQuantity())));
    }

    /** Parses a "You catch ..." message; null for everything else. */
    @VisibleForTesting
    static ParsedCatch parseCatch(String message) {
        /* The "Trawler's trust" bonus line duplicates fish that already had
         * their own catch message, so it must never be counted. */
        if (message.contains("Trawler's trust")) {
            return null;
        }
        Matcher matcher = CATCH_PATTERN.matcher(message);
        if (!matcher.matches()) {
            return null;
        }
        String qtyToken = matcher.group("qty");
        int quantity = qtyToken.startsWith("a") ? 1 : Integer.parseInt(qtyToken);
        if (quantity <= 0) {
            return null;
        }
        return new ParsedCatch(matcher.group("fish").trim(), quantity);
    }

    /** Maps a message fish name to a trawling item id, or null when unknown. */
    @VisibleForTesting
    static Integer resolveFishId(String fishName) {
        String name = fishName.toLowerCase(Locale.ROOT).trim();
        if (name.startsWith("raw ")) {
            name = name.substring(4);
        }
        Integer id = FISH_IDS.get(name);
        if (id == null && name.endsWith("s")) {
            /* Multi-catch messages may pluralize ("2 raw haddocks") */
            id = FISH_IDS.get(name.substring(0, name.length() - 1));
        }
        return id;
    }

    @Value
    @VisibleForTesting
    static class ParsedCatch {
        String fishName;
        int quantity;
    }
}

package io.droptracker.events;

import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import javax.annotation.Nullable;
import javax.inject.Singleton;

import org.jetbrains.annotations.VisibleForTesting;

import io.droptracker.models.CustomWebhookBody;
import io.droptracker.models.submissions.SubmissionType;
import io.droptracker.util.DebugLogger;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.GameState;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.DBTableID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;

/**
 * Slayer task completions, for event goals that count them ("25 tasks, no
 * Turael skipping", "10 tasks from Duradel").
 *
 * <p>A completion needs two signals, landing within {@value #WINDOW_TICKS}
 * ticks of each other:
 * <ol>
 *   <li>the game's completion line, "You have completed your task! You killed
 *       245 Cave Kraken. You gained 62,475 xp.", and</li>
 *   <li>the kills-remaining varp ({@code SLAYER_COUNT}) dropping from above
 *       zero to zero.</li>
 * </ol>
 * Neither is enough alone. Cancelling a task zeroes the count without the
 * line, and the line is only text: another plugin can print one.
 *
 * <p>What the task was (assignment, boss, master, area, starting amount) is
 * read the way RuneLite's own slayer plugin reads it, from varps and the
 * cache's slayer tables, never from chat. It is snapshotted while the task is
 * live, because finishing the task zeroes the count those reads depend on.
 *
 * <p>Every completion goes out with the raw {@code SLAYER_MASTER} value. Which
 * masters count toward a goal is the event task's own config, decided on the
 * server; the plugin never filters. The ids match the cache's
 * {@code slayer_master_task} rows (1 Turael ... 10 Mortimer).
 *
 * <p>Invoked from DropTrackerPlugin's subscriptions; handlers in this package
 * are not registered on the RuneLite event bus.
 */
@Slf4j
@Singleton
public class SlayerHandler extends BaseEventHandler {

    /** Most ticks allowed between the completion line and the count drop. */
    @VisibleForTesting
    static final int WINDOW_TICKS = 2;

    /**
     * {@code SLAYER_TARGET} for a boss task; which boss is in
     * {@code SLAYER_TARGET_BOSSID}. From [proc,helper_slayer_current_assignment].
     */
    @VisibleForTesting
    static final int BOSS_TASK_ID = 98;

    /* Masters whose streak lives in its own var (RuneLite's SlayerPlugin). */
    private static final int KRYSTILIA = 7;
    private static final int MORTIMER = 10;

    /** {@code slayer_modifiers} row 2: the kill count was changed at assignment. */
    private static final int MODIFIER_QUANTITY_CHANGE = 2;

    /** The server keeps this much of the raw lines. */
    private static final int MAX_MESSAGE_LENGTH = 255;

    @VisibleForTesting
    static final Pattern TASK_LINE = Pattern.compile(
        "You have completed your task! You killed (?<killed>[\\d,]+) (?<name>[^.]+)\\."
            + "(?:.*?You gained (?<xp>[\\d,]+) xp)?");

    /**
     * Precedes the completion line on a boss task, which itself only says
     * "You killed 11 Bosses". The cache name wins; this is the fallback.
     */
    @VisibleForTesting
    static final Pattern BOSS_LINE = Pattern.compile(
        "for completing your boss task against (?<name>.+?)\\.?$");

    /**
     * Follows the completion line. Three endings: points awarded, the points
     * cap reached, or a master that awards none (Turael/Aya, Spria).
     */
    @VisibleForTesting
    static final Pattern STREAK_LINE = Pattern.compile(
        "You've completed (?:at least )?(?<streak>[\\d,]+) (?:Wilderness |Mortimer )?tasks?"
            + "(?: and received (?<points>[\\d,]+) points?, giving you a total of (?<total>[\\d,]+)"
            + "| and reached the maximum amount of Slayer points \\((?<cap>[\\d,]+)\\)"
            + "|(?<nopoints>\\. ?You'll be eligible to earn reward points))?");

    /** The task the game has live right now; null when there is none. */
    private LiveTask liveTask;
    /** The task whose count just dropped to zero, and the tick it did. */
    private LiveTask zeroedTask;
    private int zeroedTick;
    /** The chat half of a completion, waiting on the count. */
    private PendingChat chat;
    /** A boss-task reward line, waiting on the completion line after it. */
    private String bossLineName;
    private int bossLineTick;
    /**
     * Varps arriving now are a login or world-hop sync, not changes, so a count
     * reading zero is not a task ending. RuneLite's {@code loginFlag}.
     */
    private boolean syncing;

    @Override
    public boolean isEnabled() {
        return config.slayerEmbeds();
    }

    /**
     * Enabling the plugin mid-task fires no varp change, so read the live task
     * directly. Task state is kept whatever the config says: turning the option
     * on mid-task must not lose the task it is on.
     */
    public void startUp() {
        clientThread.invokeLater(this::syncIfLoggedIn);
    }

    @VisibleForTesting
    void syncIfLoggedIn() {
        if (client.getGameState() == GameState.LOGGED_IN) {
            syncing = true;
            refreshTask();
        }
    }

    public void reset() {
        liveTask = null;
        zeroedTask = null;
        chat = null;
        bossLineName = null;
        syncing = false;
    }

    public void onGameStateChanged(GameState state) {
        switch (state) {
            case LOGIN_SCREEN:
                // The next login may be another account.
                reset();
                break;
            case HOPPING:
            case LOGGING_IN:
            case CONNECTION_LOST:
                syncing = true;
                break;
            default:
                break;
        }
    }

    public void onVarbitChanged(VarbitChanged event) {
        int varp = event.getVarpId();
        int varbit = event.getVarbitId();
        if (varp == VarPlayerID.SLAYER_COUNT
            || varp == VarPlayerID.SLAYER_TARGET
            || varp == VarPlayerID.SLAYER_AREA
            || varp == VarPlayerID.SLAYER_COUNT_ORIGINAL
            || varbit == VarbitID.SLAYER_TARGET_BOSSID
            || varbit == VarbitID.SLAYER_MASTER
            || varbit == VarbitID.SLAYER_MODIFIER_ID
            || varbit == VarbitID.SLAYER_MODIFIER_VALUE
            || varbit == VarbitID.SLAYER_MODIFIER_NEGATIVE) {
            afterVarps(this::refreshTask);
        }
    }

    /**
     * Reads once the whole batch of var updates has landed, so a new assignment
     * is never snapshotted half-written (the count from the new task, the master
     * from the old one).
     */
    @VisibleForTesting
    void afterVarps(Runnable read) {
        clientThread.invokeLater(read);
    }

    public void onGameMessage(String message) {
        // All three lines say "task"; most game messages don't.
        if (message == null || !message.contains("task")) {
            return;
        }
        int tick = client.getTickCount();

        Optional<TaskLine> taskLine = parseTaskLine(message);
        if (taskLine.isPresent()) {
            String bossName = bossLineName != null && tick - bossLineTick <= WINDOW_TICKS ? bossLineName : null;
            chat = new PendingChat(taskLine.get(), bossName, tick);
            bossLineName = null;
            return;
        }

        Optional<StreakLine> streakLine = parseStreakLine(message);
        if (streakLine.isPresent()) {
            if (chat != null && chat.streak == null && tick - chat.tick <= WINDOW_TICKS) {
                chat.streak = streakLine.get();
            }
            return;
        }

        Optional<String> bossName = parseBossLine(message);
        if (bossName.isPresent()) {
            bossLineName = bossName.get();
            bossLineTick = tick;
        }
    }

    public void onTick() {
        if (syncing) {
            refreshTask();
            syncing = false;
        }
        int now = client.getTickCount();

        if (chat != null) {
            boolean countDropped = zeroedTask != null && Math.abs(zeroedTick - chat.tick) <= WINDOW_TICKS;
            // The streak line normally lands on the completion line's tick;
            // one tick later, go without it rather than lose the completion.
            if (countDropped && (chat.streak != null || now - chat.tick >= 1)) {
                Completion completion = complete(chat, zeroedTask);
                chat = null;
                zeroedTask = null;
                if (isEnabled() && plugin.isTracking) {
                    submit(completion);
                }
                return;
            }
            if (now - chat.tick > WINDOW_TICKS) {
                DebugLogger.log("[SlayerHandler] completion line with no task count drop; not submitted: "
                    + chat.taskLine.getRaw());
                chat = null;
            }
        }
        // A count drop no line followed (a cancelled task) needs no clean-up:
        // the window check above keeps it from pairing with a later line.
    }

    @VisibleForTesting
    void refreshTask() {
        int remaining = client.getVarpValue(VarPlayerID.SLAYER_COUNT);
        if (remaining > 0) {
            liveTask = readTask();
            return;
        }
        LiveTask ended = liveTask;
        liveTask = null;
        if (ended != null && !syncing) {
            zeroedTask = ended;
            zeroedTick = client.getTickCount();
        }
    }

    private LiveTask readTask() {
        int taskId = client.getVarpValue(VarPlayerID.SLAYER_TARGET);
        int bossId = taskId == BOSS_TASK_ID ? client.getVarbitValue(VarbitID.SLAYER_TARGET_BOSSID) : 0;

        int initial = client.getVarpValue(VarPlayerID.SLAYER_COUNT_ORIGINAL);
        if (client.getVarbitValue(VarbitID.SLAYER_MODIFIER_ID) == MODIFIER_QUANTITY_CHANGE) {
            int change = client.getVarbitValue(VarbitID.SLAYER_MODIFIER_VALUE);
            initial += client.getVarbitValue(VarbitID.SLAYER_MODIFIER_NEGATIVE) == 1 ? -change : change;
        }

        return new LiveTask(
            taskId,
            bossId,
            lookUpTaskName(taskId, bossId),
            client.getVarpValue(VarPlayerID.SLAYER_AREA),
            initial,
            client.getVarbitValue(VarbitID.SLAYER_MASTER));
    }

    /**
     * The assignment's name as the cache spells it ("Cave Kraken", "The
     * Alchemical Hydra"), the same lookup RuneLite's slayer plugin makes. Null
     * when the tables have no row for it; the chat line then names the task.
     */
    @Nullable
    private String lookUpTaskName(int taskId, int bossId) {
        try {
            int taskRow;
            if (taskId == BOSS_TASK_ID) {
                List<Integer> bossRows = client.getDBRowsByValue(
                    DBTableID.SlayerTaskSublist.ID, DBTableID.SlayerTaskSublist.COL_TASK_SUBTABLE_ID, 0, bossId);
                if (bossRows == null || bossRows.isEmpty()) {
                    return null;
                }
                Object[] task = client.getDBTableField(bossRows.get(0), DBTableID.SlayerTaskSublist.COL_TASK, 0);
                if (task == null || task.length == 0 || !(task[0] instanceof Integer)) {
                    return null;
                }
                taskRow = (Integer) task[0];
            } else {
                List<Integer> taskRows = client.getDBRowsByValue(
                    DBTableID.SlayerTask.ID, DBTableID.SlayerTask.COL_ID, 0, taskId);
                if (taskRows == null || taskRows.isEmpty()) {
                    return null;
                }
                taskRow = taskRows.get(0);
            }
            Object[] name = client.getDBTableField(taskRow, DBTableID.SlayerTask.COL_NAME_UPPERCASE, 0);
            if (name == null || name.length == 0 || !(name[0] instanceof String)) {
                return null;
            }
            String text = ((String) name[0]).trim();
            return text.isEmpty() ? null : text;
        } catch (RuntimeException e) {
            log.debug("Slayer task lookup failed (task {}, boss {})", taskId, bossId, e);
            return null;
        }
    }

    private Completion complete(PendingChat chat, LiveTask task) {
        TaskLine line = chat.taskLine;
        StreakLine streak = chat.streak;

        String name = task.getTaskName();
        if (name == null && task.getTaskId() == BOSS_TASK_ID) {
            name = chat.bossName;
        }
        if (name == null) {
            name = line.getName();
        }

        Integer streakCount = streak != null ? streak.getStreak() : null;
        if (streakCount == null) {
            streakCount = readStreak(task.getMasterId());
        }
        Integer pointsTotal = streak != null ? streak.getPointsTotal() : null;
        if (pointsTotal == null) {
            pointsTotal = client.getVarbitValue(VarbitID.SLAYER_POINTS);
        }

        String message = streak != null ? line.getRaw() + " " + streak.getRaw() : line.getRaw();
        if (message.length() > MAX_MESSAGE_LENGTH) {
            message = message.substring(0, MAX_MESSAGE_LENGTH);
        }

        return new Completion(
            name,
            task.getTaskId(),
            task.getBossId(),
            task.getMasterId(),
            task.getAreaId(),
            task.getAmountInitial(),
            line.getKilled(),
            line.getXp(),
            streakCount,
            streak != null ? streak.getPointsAwarded() : null,
            pointsTotal,
            message);
    }

    private int readStreak(int masterId) {
        switch (masterId) {
            case KRYSTILIA:
                return client.getVarbitValue(VarbitID.SLAYER_WILDERNESS_TASKS_COMPLETED);
            case MORTIMER:
                return client.getVarpValue(VarPlayerID.SLAYER_MORTIMER_TASKS_COMPLETED);
            default:
                return client.getVarbitValue(VarbitID.SLAYER_TASKS_COMPLETED);
        }
    }

    @VisibleForTesting
    void submit(Completion completion) {
        String playerName = getPlayerName();
        if (playerName == null) {
            log.debug("Skipping slayer task submission: no resolvable player name");
            return;
        }
        CustomWebhookBody webhook = createWebhookBody(playerName + " completed a slayer task!");
        CustomWebhookBody.Embed embed = createEmbed(completion.getTaskName(), "slayer_task");
        addFields(embed, fields(completion, System.currentTimeMillis() / 1000));
        webhook.getEmbeds().add(embed);
        sendData(webhook, SubmissionType.SLAYER_TASK);
    }

    /**
     * The submission's fields. Unknowns are left out rather than sent as
     * {@code addFields}' "N/A", which the server would store as text.
     */
    @VisibleForTesting
    static Map<String, Object> fields(Completion completion, long timestamp) {
        Map<String, Object> fields = new LinkedHashMap<>();
        fields.put("task_name", completion.getTaskName());
        fields.put("task_id", completion.getTaskId());
        fields.put("is_boss", completion.isBoss());
        if (completion.isBoss() && completion.getBossId() > 0) {
            fields.put("boss_id", completion.getBossId());
        }
        fields.put("master_id", completion.getMasterId());
        if (completion.getAreaId() > 0) {
            fields.put("area_id", completion.getAreaId());
        }
        if (completion.getAmountInitial() > 0) {
            fields.put("amount_initial", completion.getAmountInitial());
        }
        fields.put("amount_killed", completion.getAmountKilled());
        putIfKnown(fields, "xp_gained", completion.getXpGained());
        putIfKnown(fields, "streak", completion.getStreak());
        putIfKnown(fields, "points_awarded", completion.getPointsAwarded());
        putIfKnown(fields, "points_total", completion.getPointsTotal());
        fields.put("completion_message", completion.getCompletionMessage());
        fields.put("timestamp", timestamp);
        return fields;
    }

    private static void putIfKnown(Map<String, Object> fields, String key, @Nullable Integer value) {
        if (value != null) {
            fields.put(key, value);
        }
    }

    // --- chat parsing ---------------------------------------------------

    @VisibleForTesting
    static Optional<TaskLine> parseTaskLine(String message) {
        Matcher m = TASK_LINE.matcher(message);
        if (!m.find()) {
            return Optional.empty();
        }
        Integer killed = parseNumber(m.group("killed"));
        String name = m.group("name").trim();
        if (killed == null || name.isEmpty()) {
            return Optional.empty();
        }
        return Optional.of(new TaskLine(killed, name, parseNumber(m.group("xp")), message.trim()));
    }

    @VisibleForTesting
    static Optional<StreakLine> parseStreakLine(String message) {
        Matcher m = STREAK_LINE.matcher(message);
        if (!m.find()) {
            return Optional.empty();
        }
        Integer streak = parseNumber(m.group("streak"));
        if (streak == null) {
            return Optional.empty();
        }
        Integer awarded = parseNumber(m.group("points"));
        Integer total = parseNumber(m.group("total"));
        Integer cap = parseNumber(m.group("cap"));
        if (m.group("nopoints") != null) {
            // Turael/Aya and Spria: nothing awarded. The total is untouched and
            // not in the line; the caller reads it from the varbit.
            awarded = 0;
        } else if (cap != null) {
            // Capped: the line gives the new total but not what was added.
            total = cap;
        }
        return Optional.of(new StreakLine(streak, awarded, total, message.trim()));
    }

    /**
     * The boss's name as the reward line gives it, capitalised the way the cache
     * spells boss tasks ("the Cave Kraken boss" becomes "The Cave Kraken boss").
     */
    @VisibleForTesting
    static Optional<String> parseBossLine(String message) {
        Matcher m = BOSS_LINE.matcher(message);
        if (!m.find()) {
            return Optional.empty();
        }
        String name = m.group("name").trim();
        if (name.isEmpty()) {
            return Optional.empty();
        }
        return Optional.of(Character.toUpperCase(name.charAt(0)) + name.substring(1));
    }

    @Nullable
    private static Integer parseNumber(@Nullable String digits) {
        if (digits == null) {
            return null;
        }
        try {
            return Integer.parseInt(digits.replace(",", ""));
        } catch (NumberFormatException e) {
            return null;
        }
    }

    // --- values ---------------------------------------------------------

    /** A task as the varps describe it, captured while it is live. */
    @Value
    @VisibleForTesting
    static class LiveTask {
        int taskId;
        int bossId;
        @Nullable
        String taskName;
        int areaId;
        int amountInitial;
        int masterId;
    }

    /** "You have completed your task! You killed N name. You gained X xp." */
    @Value
    @VisibleForTesting
    static class TaskLine {
        int killed;
        String name;
        @Nullable
        Integer xp;
        String raw;
    }

    /** "You've completed N tasks and received P points, giving you a total of T..." */
    @Value
    @VisibleForTesting
    static class StreakLine {
        int streak;
        @Nullable
        Integer pointsAwarded;
        @Nullable
        Integer pointsTotal;
        String raw;
    }

    private static final class PendingChat {
        private final TaskLine taskLine;
        @Nullable
        private final String bossName;
        private final int tick;
        @Nullable
        private StreakLine streak;

        private PendingChat(TaskLine taskLine, @Nullable String bossName, int tick) {
            this.taskLine = taskLine;
            this.bossName = bossName;
            this.tick = tick;
        }
    }

    /** One completed task, as it is submitted. */
    @Value
    @VisibleForTesting
    static class Completion {
        String taskName;
        int taskId;
        int bossId;
        /** Raw {@code SLAYER_MASTER}; the server names it. */
        int masterId;
        int areaId;
        int amountInitial;
        int amountKilled;
        @Nullable
        Integer xpGained;
        @Nullable
        Integer streak;
        @Nullable
        Integer pointsAwarded;
        @Nullable
        Integer pointsTotal;
        String completionMessage;

        boolean isBoss() {
            return taskId == BOSS_TASK_ID;
        }
    }
}

package io.droptracker.events;

import java.lang.ref.WeakReference;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Optional;
import java.util.function.Predicate;

import javax.annotation.Nullable;
import javax.inject.Inject;

import io.droptracker.models.CustomWebhookBody;
import io.droptracker.models.submissions.SubmissionType;
import io.droptracker.service.RecentCombatTracker;
import io.droptracker.util.DeathRegions;
import io.droptracker.util.DeathValuation;
import io.droptracker.util.NpcUtilities;
import io.droptracker.util.RegionNameRegistry;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.ParamID;
import net.runelite.api.Player;
import net.runelite.api.WorldType;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.InteractingChanged;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.NPCManager;
import org.apache.commons.lang3.ArrayUtils;
import org.apache.commons.lang3.StringUtils;
import org.jetbrains.annotations.VisibleForTesting;

/**
 * Tracks local player deaths and submits them to the DropTracker.
 *
 * Invoked manually from DropTrackerPlugin's event subscriptions (handlers in
 * this package are not registered on the RuneLite event bus).
 */
@Slf4j
public class DeathHandler extends BaseEventHandler {

    /** Suppress duplicate submissions if the client fires multiple death events. */
    private static final long DUPLICATE_WINDOW_MS = 5_000;

    private static final String ATTACK_OPTION = "Attack";

    private static final String KILLER_NPC = "npc";
    private static final String KILLER_PLAYER = "player";
    private static final String KILLER_UNKNOWN = "unknown";

    @Inject
    private NPCManager npcManager;

    @Inject
    private ItemManager itemManager;

    @Inject
    private RegionNameRegistry regionNames;

    private long lastDeathAtMs = 0;

    /**
     * The last actor the local player interacted with.
     *
     * Reading {@code localPlayer.getInteracting()} on the death tick is not
     * enough on its own: the interaction is frequently already cleared by then,
     * and it answers the wrong question anyway (who we were attacking, not who
     * was attacking us). Tracking the target as it changes gives a candidate
     * that survives the death tick.
     *
     * Weakly held so a despawning actor can still be collected; the referent
     * may be null.
     */
    private WeakReference<Actor> lastTarget = new WeakReference<>(null);

    /**
     * The engagements of the last few ticks, in both directions.
     *
     * <p>The live scan below can only ever find an actor that is still targeting
     * us on the death tick, and on a great many deaths nothing is: the game drops
     * an NPC's target as soon as that target dies, instanced bosses despawn with
     * the instance, and in a group the boss has already moved on to whoever is
     * still alive. This is the memory that lets those deaths still be attributed.
     */
    @VisibleForTesting
    final RecentCombatTracker recentCombat = new RecentCombatTracker();

    @Override
    public boolean isEnabled() {
        return config.deathEmbeds();
    }

    public void onInteractingChanged(InteractingChanged event) {
        Player localPlayer = client.getLocalPlayer();
        if (localPlayer == null) {
            return;
        }

        Actor source = event.getSource();
        Actor target = event.getTarget();
        int tick = client.getTickCount();

        if (source == localPlayer) {
            // Outbound: what we are attacking.
            if (target != null) {
                if (target.getCombatLevel() > 0) {
                    lastTarget = new WeakReference<>(target);
                }
                recentCombat.recordAttacking(target, tick);
            } else {
                recentCombat.endAttacking(null, tick);
            }
            return;
        }

        // Inbound: what is attacking us. This half of the signal used to be
        // thrown away, even though it is the one that actually answers "who
        // killed me" — the outbound target only says who we were fighting.
        if (target == localPlayer) {
            recentCombat.recordAttackedBy(source, tick);
        } else if (source != null) {
            // It turned away from us (or onto someone else). Remembering *when*
            // it disengaged is what makes a boss that dropped its target on the
            // death tick rank ahead of every older candidate.
            recentCombat.endAttackedBy(source, tick);
        }
    }

    public void onActorDeath(ActorDeath event) {
        Player localPlayer = client.getLocalPlayer();
        boolean self = localPlayer != null && event.getActor() == localPlayer;

        try {
            if (!self || !isEnabled() || !plugin.isTracking) {
                return;
            }

            long now = System.currentTimeMillis();
            if (now - lastDeathAtMs < DUPLICATE_WINDOW_MS) {
                return;
            }
            lastDeathAtMs = now;

            submitDeath(localPlayer);
        } finally {
            // Clear the tracked target once it is dead — ours or theirs — so a
            // later death cannot be attributed to a corpse.
            if (self || event.getActor() == lastTarget.get()) {
                lastTarget = new WeakReference<>(null);
            }
            if (self) {
                // Respawning starts a new fight; nothing before the death can
                // explain the next one.
                recentCombat.clear();
            } else {
                recentCombat.forget(event.getActor());
            }
        }
    }

    private void submitDeath(Player localPlayer) {
        WorldPoint location = currentLocation(localPlayer);
        Killer killer = identifyKiller(localPlayer);
        boolean pk = killer != null && killer.isPlayer();
        boolean npc = killer != null && killer.isNpc();

        // Classified before the fields are built because the valuation below
        // needs it: a safe death loses nothing regardless of what is carried.
        // An unknown location is treated as dangerous — the server filters on
        // this, and guessing "safe" would silently swallow the notification.
        boolean safeDeath = location != null && DeathRegions.isSafe(client, location.getRegionID());

        String playerName = getPlayerName();
        if (playerName == null) {
            log.debug("Skipping death submission: no resolvable player name");
            return;
        }

        // Read while the containers still hold what the player died with — they
        // are emptied within a tick or two of here, and this is still the death
        // tick. After the name check so a submission we are about to drop does
        // not price a full inventory on the client thread first.
        DeathValuation.Valuation valuation = DeathValuation.value(client, itemManager, safeDeath);
        CustomWebhookBody webhook = createWebhookBody(playerName + " has died!");
        CustomWebhookBody.Embed embed = createEmbed(playerName + " has died!", "death");

        // LinkedHashMap: field order is the order they appear in the embed, and
        // addFields turns a null or blank value into the literal "N/A", so a
        // value we do not have must be left out rather than added empty.
        Map<String, Object> fieldData = new LinkedHashMap<>();

        String killerName = killer != null
                ? NpcUtilities.canonicalizeSpecialSource(killer.getName())
                : null;
        if (killerName != null) {
            fieldData.put("source", killerName);
        }
        fieldData.put("killer_type", pk ? KILLER_PLAYER : npc ? KILLER_NPC : KILLER_UNKNOWN);
        fieldData.put("is_pvp", pk);

        if (killer != null) {
            if (npc && killer.getNpcId() != null) {
                fieldData.put("killer_npc_id", killer.getNpcId());
            }
            if (killer.getCombatLevel() > 0) {
                fieldData.put("killer_combat_level", killer.getCombatLevel());
            }
        }

        if (location != null) {
            int regionId = location.getRegionID();
            fieldData.put("region_id", regionId);

            RegionNameRegistry.Area area = regionNames.lookup(regionId);
            if (area != null) {
                fieldData.put("region_name", area.getName());
                if (area.getType() != null) {
                    fieldData.put("region_type", area.getType());
                }
                // "location" is what the notification embed renders and what
                // the custom-embed {location} token has always been documented
                // to be ("Catacombs of Kourend"). Leaving it out when the
                // region is unnamed lets the server fall back to showing the
                // bare region id rather than printing coordinates at people.
                fieldData.put("location", area.getName());
            }

            // The raw point still travels, just no longer as "location".
            fieldData.put("coordinates", location.getX() + "," + location.getY() + "," + location.getPlane());
            fieldData.put("plane", location.getPlane());
            fieldData.put("instanced", isInstance(localPlayer));
        }

        // Sent unconditionally, not inside the location block: the server's
        // safe-death filter defaults to muting safe deaths, so a death that
        // could not be located must still say which side of that line it fell
        // on rather than arriving with the field missing.
        fieldData.put("is_safe_death", safeDeath);

        if (valuation != null) {
            // What the death actually cost — the value a group filters on.
            fieldData.put("value_lost", valuation.getLostValue());
            fieldData.put("value_kept", valuation.getKeptValue());
            fieldData.put("items_lost", valuation.getLostItemCount());
        }

        addFields(embed, fieldData);
        webhook.getEmbeds().add(embed);

        sendData(webhook, SubmissionType.DEATH);
    }

    /**
     * The local player's position, corrected for instances.
     *
     * Inside an instance {@code getWorldLocation()} returns a point in template
     * space, whose region id belongs to whichever chunk the instance was built
     * from — so every raid, Gauntlet, Inferno and Nightmare death used to
     * report a region that had nothing to do with where it happened.
     */
    @Nullable
    private WorldPoint currentLocation(Player localPlayer) {
        if (localPlayer == null) {
            return null;
        }
        WorldView worldView = localPlayer.getWorldView();
        if (worldView != null && worldView.isInstance()) {
            return WorldPoint.fromLocalInstance(client, localPlayer.getLocalLocation(), worldView.getPlane());
        }
        return localPlayer.getWorldLocation();
    }

    private boolean isInstance(Player localPlayer) {
        WorldView worldView = localPlayer != null ? localPlayer.getWorldView() : null;
        return worldView != null && worldView.isInstance();
    }

    @Nullable
    private static String actorName(@Nullable Actor actor) {
        return actor != null ? RecentCombatTracker.cleanName(actor.getName()) : null;
    }

    /**
     * @return who most likely killed us, or null when the death cannot be
     *         attributed at all (poison, falling damage, an attacker we never
     *         saw engage us).
     */
    @Nullable
    @VisibleForTesting
    Killer identifyKiller(Player localPlayer) {
        boolean pvpEnabled = isPvpEnabled();

        Actor live = findLiveKiller(localPlayer, pvpEnabled);
        if (live != null) {
            return Killer.of(live);
        }

        // Nothing is targeting us any more. Fall back to who was, moments ago:
        // by the time ActorDeath fires the interaction is usually already gone,
        // which is exactly how a death ends up with no source on it at all.
        return recentCombat.mostLikelyKiller(client.getTickCount(), pvpEnabled)
                .map(Killer::of)
                .orElse(null);
    }

    /** The Dink-style scan: an actor that is still targeting us right now. */
    @Nullable
    private Actor findLiveKiller(Player localPlayer, boolean pvpEnabled) {
        Predicate<Actor> interactingWithUs = actor -> isInteractingWith(localPlayer, actor);

        // Fast path: whatever we were last engaged with, if it is still a
        // plausible killer.
        Actor recentTarget = lastTarget.get();
        if (isLikelyKiller(localPlayer, recentTarget, pvpEnabled)) {
            return recentTarget;
        }

        WorldView worldView = worldView(localPlayer);
        if (worldView == null) {
            return null;
        }

        // A player can only have killed us where PvP is possible. Prefer one
        // who is not a friend/clanmate, since those are usually bystanders.
        if (pvpEnabled) {
            Optional<? extends Player> pker = worldView.players().stream()
                    .filter(interactingWithUs)
                    .min(pkComparator(localPlayer));
            if (pker.isPresent()) {
                return pker.get();
            }
        }

        // Otherwise the best-ranked NPC currently attacking us.
        return worldView.npcs().stream()
                .filter(interactingWithUs)
                .filter(npc -> isValidKiller(npc.getTransformedComposition()))
                .min(npcComparator(localPlayer))
                .orElse(null);
    }

    /**
     * The world view to search for candidates.
     *
     * <p>The local player's own view rather than the top level one: content that
     * runs in a nested world view keeps its NPCs there, and scanning the top
     * level would find none of them.
     */
    @Nullable
    private WorldView worldView(@Nullable Player localPlayer) {
        WorldView own = localPlayer != null ? localPlayer.getWorldView() : null;
        return own != null ? own : client.getTopLevelWorldView();
    }

    private boolean isPvpEnabled() {
        if (isPvpSafeZone()) {
            // Bank/lobby areas of PvP worlds and Deadman — nobody can be
            // attacked here, so no bystander should be blamed.
            return false;
        }
        return client.getVarbitValue(VarbitID.INSIDE_WILDERNESS) > 0
                || client.getWorldType().contains(WorldType.PVP)
                || client.getWorldType().contains(WorldType.DEADMAN);
    }

    private boolean isPvpSafeZone() {
        Widget widget = client.getWidget(InterfaceID.PvpIcons.SAFEZONE);
        return widget != null && !widget.isHidden();
    }

    /** Whether the actor is alive and targeting the local player. */
    private static boolean isInteractingWith(Player localPlayer, @Nullable Actor actor) {
        return actor != null
                && actor != localPlayer
                && !actor.isDead()
                && actor.getInteracting() == localPlayer;
    }

    /** Whether an NPC is a plausible killer rather than scenery or a pet. */
    private static boolean isValidKiller(@Nullable NPCComposition composition) {
        return composition != null
                && composition.isInteractible()
                && !composition.isFollower()
                && composition.getCombatLevel() > 0;
    }

    private static boolean isLikelyKiller(Player localPlayer, @Nullable Actor actor, boolean pvpEnabled) {
        if (!isInteractingWith(localPlayer, actor)) {
            return false;
        }

        if (actor instanceof Player) {
            Player other = (Player) actor;
            return pvpEnabled && !other.isClanMember() && !other.isFriend() && !other.isFriendsChatMember();
        }

        if (actor instanceof NPC) {
            NPCComposition composition = ((NPC) actor).getTransformedComposition();
            return isValidKiller(composition) && ArrayUtils.contains(composition.getActions(), ATTACK_OPTION);
        }

        return false;
    }

    /**
     * Orders candidate NPCs by how likely each is to be the killer, best first
     * (so {@code Stream#min} picks the winner).
     */
    private Comparator<NPC> npcComparator(Player localPlayer) {
        return Comparator
                .comparing(
                        NPC::getTransformedComposition,
                        Comparator.nullsFirst(
                                Comparator
                                        // named in the hitpoints UI — i.e. something the game
                                        // itself treats as a notable opponent
                                        .comparing((NPCComposition c) -> c.getStringValue(ParamID.NPC_HP_NAME),
                                                Comparator.comparing(StringUtils::isNotEmpty))
                                        .thenComparing(c -> ArrayUtils.contains(c.getActions(), ATTACK_OPTION))
                                        .thenComparingInt(NPCComposition::getCombatLevel)
                                        .thenComparingInt(NPCComposition::getSize)
                                        .thenComparing(NPCComposition::isMinimapVisible)
                                        .thenComparing(c -> npcManager != null ? npcManager.getHealth(c.getId()) : null,
                                                Comparator.nullsFirst(Comparator.naturalOrder()))))
                .thenComparingInt(npc -> -distanceTo(localPlayer, npc))
                .reversed();
    }

    /**
     * Orders candidate players by how likely each is to be the killer, best
     * first. Friends and clanmates rank last; a similar combat level and
     * proximity rank higher.
     */
    private static Comparator<Player> pkComparator(Player localPlayer) {
        return Comparator
                .comparing(Player::isClanMember)
                .thenComparing(Player::isFriend)
                .thenComparing(Player::isFriendsChatMember)
                .thenComparingInt(p -> Math.abs(localPlayer.getCombatLevel() - p.getCombatLevel()))
                .thenComparingInt(p -> -p.getCombatLevel())
                .thenComparing(p -> p.getOverheadIcon() == null)
                .thenComparing(p -> p.getTeam() == localPlayer.getTeam())
                .thenComparingInt(p -> distanceTo(localPlayer, p));
    }

    private static int distanceTo(Player localPlayer, Actor other) {
        if (localPlayer.getLocalLocation() == null || other.getLocalLocation() == null) {
            return Integer.MAX_VALUE;
        }
        return localPlayer.getLocalLocation().distanceTo(other.getLocalLocation());
    }

    /**
     * Who killed us, as a snapshot rather than a live scene reference.
     *
     * <p>The fallback path names actors that have already despawned by the time
     * the submission is built, so the attribution cannot be an {@link Actor}.
     */
    @VisibleForTesting
    static final class Killer {

        private final String name;
        private final Integer npcId;
        private final int combatLevel;
        private final boolean player;
        private final boolean npc;

        private Killer(@Nullable String name, @Nullable Integer npcId, int combatLevel,
                boolean player, boolean npc) {
            this.name = name;
            this.npcId = npcId;
            this.combatLevel = combatLevel;
            this.player = player;
            this.npc = npc;
        }

        static Killer of(Actor actor) {
            if (actor instanceof NPC) {
                NPC killerNpc = (NPC) actor;
                String name = actorName(killerNpc);
                if (name == null) {
                    // Some instanced NPCs report no name until their composition
                    // is transformed; without this the embed would carry an NPC
                    // id and no source at all.
                    NPCComposition composition = killerNpc.getTransformedComposition();
                    name = composition != null ? RecentCombatTracker.cleanName(composition.getName()) : null;
                }
                return new Killer(name, killerNpc.getId(), killerNpc.getCombatLevel(), false, true);
            }
            return new Killer(actorName(actor), null, actor.getCombatLevel(), actor instanceof Player, false);
        }

        static Killer of(RecentCombatTracker.Engagement engagement) {
            return new Killer(engagement.getName(), engagement.getNpcId(), engagement.getCombatLevel(),
                    engagement.isPlayer(), engagement.isNpc());
        }

        @Nullable
        String getName() {
            return name;
        }

        @Nullable
        Integer getNpcId() {
            return npcId;
        }

        int getCombatLevel() {
            return combatLevel;
        }

        boolean isPlayer() {
            return player;
        }

        boolean isNpc() {
            return npc;
        }
    }
}

package io.droptracker.events;

import lombok.AccessLevel;
import lombok.Setter;
import net.runelite.api.gameval.VarbitID;
import net.runelite.http.api.loottracker.LootRecordType;
import org.apache.commons.lang3.StringUtils;
import org.jetbrains.annotations.VisibleForTesting;

import javax.inject.Inject;
import javax.inject.Singleton;

import java.util.HashMap;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import io.droptracker.service.KCService;
import io.droptracker.util.ItemIDSearch;
import io.droptracker.models.CustomWebhookBody;
import io.droptracker.models.Pet;
import io.droptracker.models.submissions.SubmissionType;
import lombok.extern.slf4j.Slf4j;

@Slf4j
@Singleton
public class PetHandler extends BaseEventHandler {

    public static final String UNTRADEABLE_WARNING = "Pet Notifier cannot reliably identify pet names unless you enable the game setting: Untradeable loot notifications";

    @VisibleForTesting
    static final Pattern PET_REGEX = Pattern.compile("You (?:have a funny feeling like you|feel something weird sneaking).*");

    @VisibleForTesting
    static final Pattern CLAN_REGEX = Pattern.compile("\\b(?<user>[\\w\\s]+) (?:has a funny feeling like .+ followed|feels something weird sneaking into .+ backpack): (?<pet>.+) at (?<milestone>.+)");

    private static final Pattern UNTRADEABLE_REGEX = Pattern.compile("Untradeable drop: (.+)");
    private static final Pattern COLLECTION_LOG_REGEX = Pattern.compile("New item added to your collection log: (.+)");

    /**
     * The maximum number ticks to wait for milestone to be populated,
     * before firing notification with only the petName.
     */
    @VisibleForTesting
    static final int MAX_TICKS_WAIT = 5;

    /**
     * Tracks the number of ticks that occur where milestone is not populated
     * while petName is populated.
     */
    private final AtomicInteger ticksWaited = new AtomicInteger();

    @Inject
    private ItemIDSearch itemSearcher;

    @Inject
    private KCService kcService;

    @Setter(AccessLevel.PRIVATE)
    private volatile String petName = null;

    private volatile String milestone = null;

    private volatile boolean duplicate = false;

    private volatile boolean backpack = false;

    private volatile boolean collection = false;

    /**
     * Stores a pet name detected from an untradeable-drop or collection-log message that
     * arrived *before* the "You have a funny feeling…" game message.  For first-time pet
     * drops the game sometimes sends the item-name notification ahead of the pet message,
     * so we cache it here and consume it when PET_REGEX eventually fires.
     */
    private volatile String pendingPetName = null;
    private volatile boolean pendingCollection = false;

    private static final String PRIMED_NAME = "";

    @Override
    public boolean isEnabled() {
        return true; // Always track pets
    }

    public void onGameMessage(String chatMessage) {
        if (!isEnabled()) return;

        if (petName == null) {
            // Pre-capture pet name from untradeable-drop or collection-log messages.
            // For first-time pet drops the game can send these item-name notifications
            // *before* "You have a funny feeling…", so we store any matching name here
            // and consume it when PET_REGEX fires below.
            parseItemFromGameMessage(chatMessage)
                    .filter(item -> item.itemName.startsWith("Pet ") || isPetName(item.itemName))
                    .ifPresent(parseResult -> {
                        this.pendingPetName = parseResult.itemName;
                        this.pendingCollection = parseResult.collectionLog;
                    });

            if (PET_REGEX.matcher(chatMessage).matches()) {
                // If we already captured the name from a preceding message, use it
                // directly; otherwise prime the notifier to wait for the next message.
                if (pendingPetName != null) {
                    this.petName = pendingPetName;
                    this.collection = pendingCollection;
                } else {
                    this.petName = PRIMED_NAME;
                }
                this.duplicate = chatMessage.contains("would have been");
                this.backpack = chatMessage.contains(" backpack");
                this.pendingPetName = null;
                this.pendingCollection = false;
            }
        } else if (PRIMED_NAME.equals(petName) || !collection) {
            parseItemFromGameMessage(chatMessage)
                    .filter(item -> item.itemName.startsWith("Pet ") || isPetName(item.itemName))
                    .ifPresent(parseResult -> {
                        this.petName = parseResult.itemName;
                        if (parseResult.collectionLog) {
                            this.collection = true;
                        }
                    });
        }
    }

    public void onClanChatNotification(String message) {
        if (petName == null) {
            // We have not received the normal message about a pet drop, so this clan message cannot be relevant to us
            return;
        }

        Matcher matcher = CLAN_REGEX.matcher(message);
        if (matcher.find()) {
            String user = matcher.group("user").trim();
            if (user.equals(getPlayerName())) {
                this.petName = matcher.group("pet");
                this.milestone = StringUtils.removeEnd(matcher.group("milestone"), ".");
            }
        }
    }

    public void onTick() {
        if (petName == null) return;

        if (milestone != null || ticksWaited.incrementAndGet() > MAX_TICKS_WAIT) {
            // ensure notifier was not disabled during wait ticks
            if (isEnabled()) {
                this.handleNotify();
            }
            this.reset();
        }
    }

    public void reset() {
        this.petName = null;
        this.milestone = null;
        this.duplicate = false;
        this.backpack = false;
        this.collection = false;
        this.ticksWaited.set(0);
        this.pendingPetName = null;
        this.pendingCollection = false;
    }

    private void handleNotify() {
        Boolean previouslyOwned;
        if (duplicate) {
            previouslyOwned = true;
        } else if (client.getVarbitValue(VarbitID.OPTION_COLLECTION_NEW_ITEM) % 2 == 1) {
            // when collection log chat notification is enabled, presence or absence of notification indicates ownership history
            previouslyOwned = !collection;
        } else {
            previouslyOwned = null;
        }

        String gameMessage;
        if (backpack) {
            gameMessage = "feels something weird sneaking into their backpack";
        } else if (previouslyOwned != null && previouslyOwned) {
            gameMessage = "has a funny feeling like they would have been followed...";
        } else {
            gameMessage = "has a funny feeling like they're being followed";
        }

        String playerName = getPlayerName();
        if (playerName == null) {
            log.debug("Skipping pet submission: no resolvable player name");
            return;
        }

        CustomWebhookBody webhook = createWebhookBody(playerName + " received a pet!");
        CustomWebhookBody.Embed embed = createEmbed("Pet Drop!", "pet");

        Map<String, Object> fieldData = new HashMap<>();
        fieldData.put("pet_name", petName != null && !petName.isEmpty() ? ucFirst(petName) : "Unknown Pet");
        fieldData.put("game_message", gameMessage);
        fieldData.put("duplicate", duplicate);

        if (milestone != null) {
            fieldData.put("milestone", milestone);
        }

        if (previouslyOwned != null) {
            fieldData.put("previously_owned", previouslyOwned);
        }

        // Try to get KC information for the pet source.
        // getKillCountWithStorage checks the in-memory cache AND falls back to data
        // stored by the RuneLite Chat Commands / Loot Tracker plugins, so it works
        // even on the very first kill of a session (when the cache is cold).
        String pet = petName != null ? ucFirst(petName) : null;
        if (pet != null && PET_TO_SOURCE.containsKey(pet)) {
            String source = PET_TO_SOURCE.get(pet);
            Integer kc = kcService.getKillCountWithStorage(LootRecordType.UNKNOWN, source);
            if (kc != null && kc > 0) {
                fieldData.put("source", source);
                fieldData.put("killcount", kc);
            }
        }

        fieldData.put("timestamp", System.currentTimeMillis() / 1000);

        addFields(embed, fieldData);

        // Try to set pet image
        if (pet != null && !pet.isEmpty()) {
            Integer itemId = itemSearcher.findItemId(pet);
            if (itemId != null) {
                embed.setImage(plugin.itemImageUrl(itemId));
            }
        }

        webhook.getEmbeds().add(embed);

        sendData(webhook, SubmissionType.PET); 
    }

    private static Optional<ParseResult> parseItemFromGameMessage(String message) {
        Matcher untradeableMatcher = UNTRADEABLE_REGEX.matcher(message);
        if (untradeableMatcher.find()) {
            return Optional.of(new ParseResult(untradeableMatcher.group(1), false));
        }

        Matcher collectionMatcher = COLLECTION_LOG_REGEX.matcher(message);
        if (collectionMatcher.find()) {
            return Optional.of(new ParseResult(collectionMatcher.group(1), true));
        }

        return Optional.empty();
    }

    private static class ParseResult {
        final String itemName;
        final boolean collectionLog;

        ParseResult(String itemName, boolean collectionLog) {
            this.itemName = itemName;
            this.collectionLog = collectionLog;
        }
    }

    /**
     * Converts text into "upper case first" form, as is used by OSRS for item names.
     *
     * @param text the string to be transformed
     * @return the text with only the first character capitalized
     */
    private static String ucFirst(String text) {
        if (text == null || text.isEmpty()) return text;
        if (text.length() < 2) return text.toUpperCase();
        return Character.toUpperCase(text.charAt(0)) + text.substring(1).toLowerCase();
    }

    // Skilling pets (Beaver, Heron, Rocky, ...) have no boss source, so PET_TO_SOURCE
    // alone isn't a complete pet list; the Pet enum carries them, PET_TO_SOURCE the newer
    // boss pets it lacks. Accept a name present in either.
    @VisibleForTesting
    static boolean isPetName(String itemName) {
        if (itemName == null) return false;
        String name = ucFirst(itemName);
        return Pet.findPet(name) != null || PET_TO_SOURCE.containsKey(name);
    }

    // Boss pet to source mapping - used for KC lookup. Skilling pets have no boss
    // source; their source (the skill) is attributed server-side to avoid a plugin
    // release per new pet and to keep skill names out of NPC resolution.
    private static final Map<String, String> PET_TO_SOURCE = Map.ofEntries(
        Map.entry("Abyssal orphan", "Abyssal Sire"),
        // "Mad Angel" (not the collection-log page's "The Mad Angel") — the npc
        // name the kc storage and npc_list are both keyed on.
        Map.entry("Aggy", "Mad Angel"),
        Map.entry("Baby mole", "Giant Mole"),
        Map.entry("Baron", "Duke Sucellus"),
        Map.entry("Butch", "Vardorvis"),
        Map.entry("Callisto cub", "Callisto"),
        Map.entry("Chompy chick", "Chompy bird"),
        Map.entry("Hellpuppy", "Cerberus"),
        Map.entry("Herbi", "Herbiboar"),
        Map.entry("Huberte", "The Hueycoatl"),
        Map.entry("Ikkle hydra", "Alchemical Hydra"),
        Map.entry("Jal-nib-rek", "TzKal-Zuk"),
        Map.entry("Kalphite princess", "Kalphite Queen"),
        Map.entry("Lil' creator", "Spoils of war"),
        Map.entry("Lil' zik", "Theatre of Blood"),
        Map.entry("Lil'viathan", "The Leviathan"),
        Map.entry("Little nightmare", "Nightmare"),
