package io.droptracker.events;

import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicLong;
import java.util.concurrent.atomic.AtomicReference;

import javax.inject.Inject;

import com.google.common.cache.Cache;
import com.google.common.cache.CacheBuilder;

import io.droptracker.models.CustomWebhookBody;
import io.droptracker.models.submissions.Drop;
import io.droptracker.service.EventNotificationService;
import io.droptracker.service.KCService;
import io.droptracker.util.ItemStacks;
import io.droptracker.util.NpcUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ItemComposition;
import net.runelite.api.NPC;
import net.runelite.client.events.NpcLootReceived;
import net.runelite.client.events.PlayerLootReceived;
import net.runelite.client.events.ServerNpcLoot;
import net.runelite.client.game.ItemStack;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.http.api.loottracker.LootRecordType;

@Slf4j
public class DropHandler extends BaseEventHandler {

    @Inject
    private KCService kcService;

    @Inject
    private ItemManager itemManager;

    @Inject
    private EventNotificationService eventNotificationService;

    /** One in-flight untradeable-list reload at a time: a busy player killing
     *  through an outage would otherwise queue a fetch per drop. */
    private final AtomicBoolean untradeableReloadInFlight = new AtomicBoolean(false);

    /**
     * Short-lived record of boss loot already submitted, keyed by
     * accountHash|canonicalSource|itemSignature. RuneLite fires more than one
     * loot event for multi-part / server-loot bosses (e.g. a granular
     * NpcLootReceived AND a generic LootReceived for Grotesque Guardians), so
     * the same kill reaches processDropEvent twice with identical items. We
     * submit the first and drop the rest within the window. The window is far
     * shorter than the minimum time to re-kill any of these bosses, and this is
     * scoped to boss sources only (isMultiPathLootSource), so ordinary NPCs that
     * are legitimately multi-killed in one tick are never de-duplicated.
     */
    private static final Cache<String, Boolean> recentBossLoot = CacheBuilder.newBuilder()
            .expireAfterWrite(5, TimeUnit.SECONDS)
            .maximumSize(256L)
            .build();

    /*
     * NOTE: These handlers are NOT registered on the RuneLite event bus — they are
     * invoked manually by DropTrackerPlugin's own @Subscribe methods, which also
     * dispatch KCService. Do not call KCService from here, or kill counts get
     * incremented twice per event.
     */
	public void onNpcLootReceived(NpcLootReceived event) {
		if (!plugin.isTracking) {
			return;
		}
		NPC npc = event.getNpc();
		Collection<ItemStack> items = event.getItems();
		processDropEvent(npc.getName(), "npc", LootRecordType.NPC, items);
	}

	public void onPlayerLootReceived(PlayerLootReceived playerLootReceived) {
		if (!plugin.isTracking) {
			return;
		}
		Collection<ItemStack> items = playerLootReceived.getItems();
		processDropEvent(playerLootReceived.getPlayer().getName(), "pvp", LootRecordType.PLAYER, items);
	}

	public void onServerNpcLoot(ServerNpcLoot event) {
		if (!plugin.isTracking) {
			return;
		}
		var comp = event.getComposition();
		log.debug("onServerNpcLoot: processing {} (npcId={})", comp.getName(), comp.getId());
		processDropEvent(comp.getName(), "npc", LootRecordType.NPC, event.getItems());
	}

	public void onLootReceived(LootReceived lootReceived) {
		if (!plugin.isTracking) {
			return;
		}
		/* A select few npc loot sources will arrive here, instead of npclootreceived events */
		String npcName = NpcUtilities.getStandardizedSource(lootReceived, plugin);
		if (lootReceived.getType() == LootRecordType.NPC && NpcUtilities.SPECIAL_NPC_NAMES.contains(npcName)) {
			// Remap sub-NPC names to the canonical encounter name. processDropEvent
			// also canonicalises, but doing it here keeps the pre-canonical name
			// out of downstream logic and mirrors the historical behaviour.
			npcName = NpcUtilities.canonicalizeSpecialSource(npcName);

			processDropEvent(npcName, "npc", LootRecordType.NPC, lootReceived.getItems());
			return;
		}
		if (lootReceived.getType() != LootRecordType.EVENT && lootReceived.getType() != LootRecordType.PICKPOCKET) {
			return;
		}
		processDropEvent(npcName, "other", lootReceived.getType(), lootReceived.getItems());
	}

	/**
	 * Entry point for activity loot that never fires a RuneLite loot event
	 * (deep sea trawling catches).
	 * The source name must exist in the server's npc_list, or the submission
	 * is rejected server-side.
	 */
	public void onActivityLoot(String sourceName, Collection<ItemStack> items) {
		if (!plugin.isTracking || items.isEmpty()) {
			return;
		}
		processDropEvent(sourceName, "other", LootRecordType.EVENT, items);
	}

    private void processDropEvent(String rawNpcName, String sourceType, LootRecordType lootRecordType, Collection<ItemStack> items) {
		final Collection<ItemStack> finalItems = new ArrayList<>(items);
		if (!plugin.isTracking) {
			return;
		}
		// Collapse every loot path to one canonical boss name (e.g. "Dusk" ->
		// "Grotesque Guardians") so the record, the KC lookup and the dedup key
		// all agree regardless of which RuneLite event delivered the kill.
		final String npcName = NpcUtilities.canonicalizeSpecialSource(rawNpcName);
		// Cross-handler de-duplication: a multi-part / server-loot boss fires
		// more than one loot event per kill, so the same items reach here twice.
		// Submit the first, drop identical repeats within the window. Scoped to
		// boss sources only, so normal per-death AoE multi-kills are unaffected.
		if (NpcUtilities.isMultiPathLootSource(npcName)) {
			String dedupKey = getAccountHash() + "|" + npcName + "|" + ItemStacks.signature(finalItems);
			if (recentBossLoot.getIfPresent(dedupKey) != null) {
				log.debug("Suppressing duplicate loot submission for {} (already submitted this kill)", npcName);
				return;
			}
			recentBossLoot.put(dedupKey, Boolean.TRUE);
		}
		if (NpcUtilities.LONG_TICK_NPC_NAMES.contains(npcName)){
			plugin.ticksSinceNpcDataUpdate -= 30;
		}
        plugin.lastDrop = new Drop(npcName, lootRecordType, finalItems);
		/* These lists are normally loaded off-thread at startup. When that
		   failed, this used to fetch them INLINE — but processDropEvent runs
		   on the game client thread (straight off @Subscribe), and the fetch is
		   a synchronous OkHttp call with a 5s connect / 10s read timeout. So
		   the one situation where the list is missing (the server was
		   unreachable at startup, and probably still is) froze the client for
		   up to 15 seconds on EVERY drop — and since a failed fetch returns
		   null, the guard never cleared and it happened again on the next one.
		   Kick a reload off-thread instead; the consumer loop below already
		   null-guards both lists, so this drop simply goes un-flagged. */
		if ((plugin.valuedItemIds == null || plugin.untradeableItemIds == null)
				&& executor != null && untradeableReloadInFlight.compareAndSet(false, true)) {
			executor.submit(() -> {
				try {
					if (plugin.valuedItemIds == null) {
						plugin.valuedItemIds = api.getValuedUntradeables();
					}
					if (plugin.untradeableItemIds == null) {
						plugin.untradeableItemIds = api.getNotableUntradeables();
					}
				} catch (Exception e) {
					log.debug("Untradeable list reload failed: {}", e.getMessage());
				} finally {
					untradeableReloadInFlight.set(false);
				}
			});
		}
		/* Items required by one of the player's active events (from the last
		/event_state snapshot) are always screenshotted for proof — this
		overrides the "Screenshot untradeables" toggle. API users only:
		webhook-only clients never poll event state, so their coverage is
		whatever the toggle + notable-untradeables list provide. */
		final Set<Integer> eventItemIds = config.useApi()
			? eventNotificationService.getEventScreenshotItemIds()
			: Collections.emptySet();
		final AtomicReference<Boolean> untradeableScreenshot = new AtomicReference<>(false);
		clientThread.invokeLater(() -> {
			// Gather all game state info needed
			List<ItemStack> stackedItems = new ArrayList<>(ItemStacks.stack(finalItems));
			String localPlayerName = getPlayerName();
			if (localPlayerName == null) {
				/* No identity, no submission: the drop cannot be attributed to
				   anyone, and this bails before the screenshot work below. */
				log.debug("Skipping drop submission for {}: no resolvable player name", npcName);
				return;
			}
			AtomicLong totalValue = new AtomicLong(0);
			List<CustomWebhookBody.Embed> embeds = new ArrayList<>();
			AtomicLong singleValue = new AtomicLong(0);

			for (ItemStack item : stackedItems) {
				int itemId = item.getId();
				/* Check if the itemId exists in the valued list we obtained */
				if (plugin.valuedItemIds != null && plugin.valuedItemIds.contains(itemId)) {
					untradeableScreenshot.set(true);
				} else if (config.screenshotUntradeables() && plugin.untradeableItemIds != null
						&& plugin.untradeableItemIds.contains(itemId)) {
					/* Notable untradeable (0gp) drop — toggle-gated screenshot */
					untradeableScreenshot.set(true);
				} else if (eventItemIds.contains(itemId)) {
					/* Event-required item — forced for proof, regardless of toggles */
					untradeableScreenshot.set(true);
				}
				int qty = item.getQuantity();
				long price = itemManager.getItemPrice(itemId);
				ItemComposition itemComposition = itemManager.getItemComposition(itemId);
				totalValue.addAndGet(qty * price);
				singleValue.addAndGet(price);
				CustomWebhookBody.Embed itemEmbed = createEmbed(localPlayerName + " received some drops:", "drop");
				itemEmbed.setImage(plugin.itemImageUrl(itemId));
				Map<String, Object> fieldData = new HashMap<>();
				fieldData.put("source_type", sourceType);
				fieldData.put("item", itemComposition.getName());
				fieldData.put("id", itemComposition.getId());
				fieldData.put("quantity", qty);
				fieldData.put("value", price);
				fieldData.put("source", npcName);

				if (npcName != null) {
					Integer killCount = kcService.getKillCountWithStorage(lootRecordType, npcName);
					fieldData.put("killcount", killCount != null ? killCount : 0);
				}

				addFields(itemEmbed, fieldData);
				embeds.add(itemEmbed);
			}

			// Now do the heavy work off the client thread
			executor.submit(() -> {
				try {
					CustomWebhookBody customWebhookBody = createWebhookBody(localPlayerName + " received some drops:");
					customWebhookBody.getEmbeds().addAll(embeds);

					if (!customWebhookBody.getEmbeds().isEmpty()) {
						long valueToSend = totalValue.get();
						Boolean valueModified = untradeableScreenshot.get();
						sendData(customWebhookBody, valueToSend, singleValue.get(), valueModified);
					}
				} catch (Exception e) {
					log.error("Error processing drop event", e);
				}
			});
		});
	}

}

package io.droptracker.events;

import com.google.inject.Inject;
import io.droptracker.models.CustomWebhookBody;
import io.droptracker.models.submissions.SubmissionType;
import io.droptracker.service.NearbyPlayerTracker;
import io.droptracker.service.LoadoutCapture;
import io.droptracker.service.PlayerModelService;
import io.droptracker.util.NpcUtilities;
import io.droptracker.util.DebugLogger;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.annotations.Varbit;
import org.apache.commons.lang3.ObjectUtils;
import org.apache.commons.lang3.tuple.Pair;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;
import org.jetbrains.annotations.VisibleForTesting;

import java.time.Duration;
import java.time.LocalTime;
import java.time.temporal.Temporal;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicReference;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import static java.time.temporal.ChronoField.*;
import static org.apache.commons.lang3.ObjectUtils.defaultIfNull;

@Slf4j
public class PbHandler extends BaseEventHandler {

    @VisibleForTesting
    static final int MAX_BAD_TICKS = 10;
    private static final long DUPLICATE_THRESHOLD = 5000;

    private static final Pattern BOSS_COUNT_PATTERN = Pattern.compile(
        "Your (?<key>[\\w\\s:'-]+) (?<type>kill|chest|completion|success) count is:? (?<value>[\\d,]+)", 
        Pattern.CASE_INSENSITIVE
    );

    private static final Pattern SECONDARY_BOSS_PATTERN = Pattern.compile(
        "Your (?<type>completed|subdued) (?<key>[\\w\\s:]+) count is:?[ \\t]*(?<value>[\\d,]+)",
        Pattern.CASE_INSENSITIVE
    );

    private static final Pattern TIME_WITH_PB_PATTERN = Pattern.compile(
        "(?<prefix>.*?)(?<duration>\\d*:?\\d+:\\d+(?:\\.\\d+)?)\\.?\\s*(?:Personal best: (?<pbtime>\\d*:?\\d+:\\d+(?:\\.\\d+)?)\\.?\\s*)?(?<pbIndicator>\\(new personal best\\))?",
        Pattern.CASE_INSENSITIVE
    );

    /**
     * The game buckets large teams rather than reporting a head count, and the
     * bucket label is the whole token: "16-23 players", "24+ players", "6+
     * players". The range and open-ended alternatives must precede the bare
     * {@code \d+}, or it matches the low end alone and a 16-23 raid is
     * submitted as a 16-player one, splitting the board away from the same
     * raid's adventure-log and clan-broadcast copies (suggestion #153).
     */
    private static final Pattern TEAM_SIZE_PATTERN = Pattern.compile(
        "Team size:\\s*(?<size>\\d+\\s*-\\s*\\d+|\\d+\\s*\\+|\\d+|Solo)\\s*(?:players?)?",
        Pattern.CASE_INSENSITIVE
    );

    /**
     * The wall-clock total is not the tracked PB metric; RuneLite excludes the
     * same line with a {@code (?<!total )completion time:} lookbehind.
     */
    private static final Pattern TOTAL_COMPLETION_PATTERN = Pattern.compile(
        "total completion time",
        Pattern.CASE_INSENSITIVE
    );

    /**
     * A raid's in-raid completion line — the metric the adventure log and clan
     * bots track. The lookbehind keeps the wall-clock "total completion time"
     * out, same as {@link #TOTAL_COMPLETION_PATTERN}.
     */
    private static final Pattern COMPLETION_TIME_PATTERN = Pattern.compile(
        "(?<!total )completion time:",
        Pattern.CASE_INSENSITIVE
    );

    @VisibleForTesting
    static Pattern bossCountPattern() {
        return BOSS_COUNT_PATTERN;
    }

    @VisibleForTesting
    static Pattern secondaryBossPattern() {
        return SECONDARY_BOSS_PATTERN;
    }

    @VisibleForTesting
    static Pattern timeWithPbPattern() {
        return TIME_WITH_PB_PATTERN;
    }

    @VisibleForTesting
    static Pattern teamSizePattern() {
        return TEAM_SIZE_PATTERN;
    }

    @Inject
    protected NearbyPlayerTracker nearbyPlayerTracker;

    /* Gear and inventory at the moment of the kill; see LoadoutCapture. */
    @Inject
    protected LoadoutCapture loadoutCapture;

    /* Which uploaded character model the kill was made in; see PlayerModelService. */
    @Inject
    protected PlayerModelService playerModelService;

    private final AtomicInteger badTicks = new AtomicInteger();
    private final AtomicReference<KillData> killData = new AtomicReference<>();
    private String lastProcessedKill = null;
    private long lastProcessedTime = 0;
    private long lastKillDataUpdate = 0L;

    private static class KillData {
        final String boss;
        final Integer count;
        final Duration time;
        final Duration bestTime;
        final boolean isPersonalBest;
        final String teamSize;
        final String gameMessage;

        KillData(String boss, Integer count, Duration time, Duration bestTime, 
                boolean isPersonalBest, String teamSize, String gameMessage) {
            this.boss = boss;
            this.count = count;
            this.time = time;
            this.bestTime = bestTime;
            this.isPersonalBest = isPersonalBest;
            this.teamSize = teamSize;
            this.gameMessage = gameMessage;
        }

        boolean isValid() {
            if (boss != null) {
                if (boss.contains("Doom")) {
                    // Doom levels do not include count; so we do not need a null check here
                    return time != null && !time.isZero();
                }
            }
            return boss != null && count != null && time != null && !time.isZero();
        }
    }

    @Override
    public boolean isEnabled() {
        return config.pbEmbeds();
    }

    public void onGameMessage(String message) {
        if (!isEnabled()) return;
        parseMessage(message).ifPresent(this::updateKillData);
    }

    public void onFriendsChatNotification(String message) {
        if (message.startsWith("Congratulations - your raid is complete!")) {
            onGameMessage(message);
        }
    }

    public void onTick() {
        KillData data = killData.get();
        if (data == null) {
            if (badTicks.incrementAndGet() > MAX_BAD_TICKS) {
                reset();
            }
            return;
        }

        if (data.isValid() && isEnabled()) {
            if (data.count == null) {
                /* Doom does not have KCs available for individual floors, so we need to handle the data anyways for this boss */
                /* Otherwise, we should handle other data with no count included consistently with before */
                if (data.boss.contains("Doom")) {
                    processKill(data);
                    reset();
                }
            } else {
                processKill(data);
                reset();
            }
        } else {
            // Allow partial data (e.g., time before count or vice versa) to coalesce for up to 10 seconds
            long now = System.currentTimeMillis();
            if (now - lastKillDataUpdate > 10_000) {
                reset();
            }
        }
    }

    private Optional<KillData> parseMessage(String message) {
        if (message.startsWith("Preparation")) {
            return Optional.empty();
        }
        // Ignore raid target-time announcements (e.g. "Your party failed to beat the overall target time of 40:00.")
        // These contain a time string but are unrelated to the player's personal best.
        if (message.contains("target time")) {
            return Optional.empty();
        }

        // Try boss count first
        Optional<Pair<String, Integer>> bossCount = parseBossCount(message);
        if (bossCount.isPresent()) {
            Pair<String, Integer> pair = bossCount.get();
            return Optional.of(new KillData(pair.getLeft(), pair.getRight(), 
                Duration.ZERO, Duration.ZERO, false, null, message));
        }

        // Try time data
        return parseTimeData(message);
    }

    private Optional<Pair<String, Integer>> parseBossCount(String message) {
        Matcher primary = BOSS_COUNT_PATTERN.matcher(message);
        if (primary.find()) {
            String boss = parsePrimaryBoss(primary.group("key"), primary.group("type"));
            if (boss != null) {
                try {
                    int count = Integer.parseInt(primary.group("value").replace(",", ""));
                    return Optional.of(Pair.of(boss, count));
                } catch (NumberFormatException e) {
                    log.debug("Failed to parse kill count: {}", primary.group("value"));
                }
            }
        }

        Matcher secondary = SECONDARY_BOSS_PATTERN.matcher(message);
        if (secondary.find()) {
            String boss = parseSecondaryBoss(secondary.group("key"));
            if (boss != null) {
                try {
                    int count = Integer.parseInt(secondary.group("value").replace(",", ""));
                    return Optional.of(Pair.of(boss, count));
                } catch (NumberFormatException e) {
                    log.debug("Failed to parse kill count: {}", secondary.group("value"));
                }
            }
        }

        return Optional.empty();
    }

    /**
     * Picks the line to read a kill time from: drops "total completion time"
     * lines, prefers a line carrying personal-best info, else the first timed
     * line. Null when the message has no usable time.
     * <p>
     * When the message states a raid completion time, that line is the ONLY
     * candidate. The same message also carries the final room's
     * {@code Duration:} — at ToB that is the Verzik split, which sits first and
     * so won any fallback that was allowed to look past the completion line.
     * Two ways that happened: a non-PB raid, where the completion line carries
     * no PB marker at all and nothing returned early; and a room that was
     * itself a personal best, whose {@code Duration:} line carries the marker
     * the completion line lacks. Both submitted a ~5 minute "raid" time.
     */
    @VisibleForTesting
    static String selectTimeLine(String message) {
        if (message == null) {
            return null;
        }
        String[] lines = message.split("\n");
        String fromCompletion = selectTimeLine(lines, true);
        return fromCompletion != null ? fromCompletion : selectTimeLine(lines, false);
    }

    /**
     * @param completionOnly restrict candidates to raid completion lines; the
     *                       caller retries without it for everything that has
     *                       no completion line (CoX, Gauntlet, ordinary bosses)
     */
    private static String selectTimeLine(String[] lines, boolean completionOnly) {
        String firstTimed = null;
        for (String line : lines) {
            if (TOTAL_COMPLETION_PATTERN.matcher(line).find()) {
                continue;
            }
            if (completionOnly && !COMPLETION_TIME_PATTERN.matcher(line).find()) {
                continue;
            }
            Matcher matcher = TIME_WITH_PB_PATTERN.matcher(line);
            if (!matcher.find()) {
                continue;
            }
            if (matcher.group("pbIndicator") != null || matcher.group("pbtime") != null) {
                return line;
            }
            if (firstTimed == null) {
                firstTimed = line;
            }
        }
        return firstTimed;
    }

    private Optional<KillData> parseTimeData(String message) {
        // Only the time is read off the selected line; boss and team size
        // still come from the whole message.
        String timeLine = selectTimeLine(message);
        if (timeLine == null) {
            return Optional.empty();
        }
        Matcher matcher = TIME_WITH_PB_PATTERN.matcher(timeLine);
        if (!matcher.find()) {
            return Optional.empty();
        }

        try {
            Duration time = parseTime(matcher.group("duration"));
            String pbTimeStr = matcher.group("pbtime");
            Duration bestTime = pbTimeStr != null ? parseTime(pbTimeStr) : Duration.ZERO;
            boolean isPersonalBest = matcher.group("pbIndicator") != null;

            String bossName = determineBossFromContext(message);
            String teamSize = extractTeamSize(message, bossName);

            // For CoX, PB lines often include Olm split but team size isn't always on KC line. If team size missing, try to extract now.
            if (teamSize == null && message.contains("Team size:")) {
                teamSize = extractTeamSize(message, bossName);
            }
            return Optional.of(new KillData(bossName, null, time, bestTime, 
                isPersonalBest, teamSize, message));

        } catch (Exception e) {
            log.error("Error parsing time data: {}", e.getMessage());
            return Optional.empty();
        }
    }

    private String determineBossFromContext(String message) {
        if (message.contains("Tombs of Amascut")) {
            return message.contains("Expert Mode") ? "Tombs of Amascut: Expert Mode" : "Tombs of Amascut";
        }
        if (message.contains("Theatre of Blood")) {
            return "Theatre of Blood";
        }
        if (message.contains("Chambers of Xeric")) {
            return "Chambers of Xeric";
        }
        // Chambers of Xeric time lines often omit the raid name but include the Olm split
        if (message.contains("Olm Duration")) {
            return "Chambers of Xeric";
        }
        if (message.contains("Corrupted challenge")) {
            return "Corrupted Hunllef";
        }
        if (message.contains("Challenge duration")) {
            return "Crystalline Hunllef";
        }
        if (message.contains("Colosseum duration")) {
            return "Sol Heredit";
        }
        if (message.contains("Delve level")) {
            return extractDelveBoss(message);
        }
        // With an unknown context, don't guess--defer to subsequent kill-count parsing
        return null;
    }

    private String extractDelveBoss(String message) {
        Pattern delvePattern = Pattern.compile("Delve level: (\\S+)");
        Matcher matcher = delvePattern.matcher(message);
        if (matcher.find()) {
            return "Doom of Mokhaiotl (Level:" + matcher.group(1).trim() + ")";
        }
        return "Doom of Mokhaiotl";
    }

    private String extractTeamSize(String message, String bossName) {
        Matcher teamMatcher = TEAM_SIZE_PATTERN.matcher(message);
        if (teamMatcher.find()) {
            String raw = teamMatcher.group("size");
            if (raw == null) {
                return "Solo";
            }
            if (raw.equalsIgnoreCase("solo")) {
                return "Solo";
            }
            // "16 - 23" and "24 +" are the same brackets as "16-23" and "24+";
            // the label is the board's identity, so spacing cannot vary.
            String size = raw.replaceAll("\\s+", "");
            return "1".equals(size) ? "Solo" : size;
        }

        boolean mentionsToa = message.contains("Tombs of Amascut") || (bossName != null && bossName.contains("Tombs of Amascut"));
        boolean mentionsTob = message.contains("Theatre of Blood") || (bossName != null && bossName.contains("Theatre of Blood"));
        boolean mentionsRoyalTitans = message.contains("Royal Titans") || (bossName != null && bossName.contains("Royal Titans"));

        if (mentionsToa) {
            return getToaTeamSize();
        }
        if (mentionsTob) {
            return getTobTeamSize();
        }
        if (mentionsRoyalTitans) {
            return getRoyalTitansTeamSize();
        }

        return "Solo";
    }

    private void updateKillData(KillData newData) {
        DebugLogger.log("[PbHandler][update] updateKillData called; newData=" + newData);
        killData.getAndUpdate(old -> {
            if (old == null) {
                lastKillDataUpdate = System.currentTimeMillis();
                return newData;
            }

            String boss = defaultIfNull(newData.boss, old.boss);
            DebugLogger.log("[PbHandler][update] boss merge; newBoss=" + newData.boss + ", oldBoss=" + old.boss);
            Integer count = defaultIfNull(newData.count, old.count);
            Duration time = newData.time != null && !newData.time.isZero() ? newData.time : old.time;
            Duration bestTime = newData.bestTime != null && !newData.bestTime.isZero() ? newData.bestTime : old.bestTime;
            boolean isPersonalBest = newData.isPersonalBest || old.isPersonalBest;
            String teamSize = defaultIfNull(newData.teamSize, old.teamSize);
            String gameMessage = defaultIfNull(newData.gameMessage, old.gameMessage);
            DebugLogger.log("[PbHandler][update] merged killData=" + new KillData(boss, count, time, bestTime, isPersonalBest, teamSize, gameMessage));
            lastKillDataUpdate = System.currentTimeMillis();
            return new KillData(boss, count, time, bestTime, isPersonalBest, teamSize, gameMessage);
        });
        DebugLogger.log("[PbHandler][update] updateKillData completed; boss=" + newData.boss + ", time=" + newData.time + ", count=" + newData.count);
    }

    // === KILL PROCESSING ===
    private void processKill(KillData data) {
        DebugLogger.log("[PbHandler][process] processKill invoked; data=" + data);
        if (data == null || !data.isValid()) {
            DebugLogger.log("[PbHandler][process] skipping invalid kill data");
            log.debug("Invalid kill data, skipping processing");
            return;
        }

        // Duplicate prevention
        String killIdentifier = data.boss + "-" + data.count;
        long currentTime = System.currentTimeMillis();

        if (killIdentifier.equals(lastProcessedKill) && 
            (currentTime - lastProcessedTime) < DUPLICATE_THRESHOLD) {
            if (!data.boss.contains("1-8")) {

                DebugLogger.log("[PbHandler][process] duplicate kill detected; killIdentifier=" + killIdentifier);
                log.debug("Duplicate kill detected, skipping: {}", killIdentifier);
                return;
            }
        }

        lastProcessedKill = killIdentifier;
        lastProcessedTime = currentTime;

        if (clientThread == null) {
            DebugLogger.log("[PbHandler][process] cannot process kill; clientThread=null");
            log.error("ClientThread is null, cannot process kill");
            return;
        }

        clientThread.invokeLater(() -> {
            try {
                sendKillNotification(data);
            } catch (Exception e) {
                DebugLogger.log("[PbHandler][process] sendKillNotification failed; reason=" + e.getMessage());
                log.error("Error processing kill notification: {}", e.getMessage(), e);
            }
        });
    }

    private void sendKillNotification(KillData data) {
        String player = getPlayerName();
        if (player == null) {
            DebugLogger.log("[PbHandler][send] skipping kill notification; no resolvable player name");
            log.debug("Skipping kill time submission: no resolvable player name");
            return;
        }
        String formattedTime = formatTime(data.time, isPreciseTiming(client));
        String formattedBestTime = formatTime(data.bestTime, isPreciseTiming(client));

        CustomWebhookBody webhook = createWebhookBody(player + " has killed a boss:");
        CustomWebhookBody.Embed embed = createEmbed(player + " has killed a boss:", "npc_kill");

        Map<String, Object> fieldData = new HashMap<>();
        fieldData.put("boss_name", data.boss);
        fieldData.put("kill_time", formattedTime != null ? formattedTime : "N/A");
        fieldData.put("best_time", formattedBestTime != null ? formattedBestTime : "N/A");
        fieldData.put("is_pb", data.isPersonalBest);
        fieldData.put("team_size", data.teamSize != null ? data.teamSize : "Solo");
        fieldData.put("killcount", data.count);

        // Loadout at the moment of the kill. Captured here because this runs on
        // the client thread immediately after the kill is recognised - by the
        // time a submission is assembled the player may have banked or died.
        if (loadoutCapture != null && loadoutCapture.isEnabled()) {
            String equipment = loadoutCapture.captureEquipment();
            String inventory = loadoutCapture.captureInventory();
            if (equipment != null) {
                fieldData.put("equipment", equipment);
            }
            if (inventory != null) {
                fieldData.put("inventory", inventory);
            }
            // The outfit fingerprint pairs this time with the character model
            // the automatic upload files under the same key, so the leaderboard
            // shows the model as worn for the kill rather than whatever the
            // player happened to upload last. Same consent as the gear itself.
            String fingerprint = playerModelService != null
                    ? playerModelService.currentFingerprint() : null;
            if (fingerprint != null) {
                fieldData.put("model_fingerprint", fingerprint);
            }
        }

        addFields(embed, fieldData);
        webhook.getEmbeds().add(embed);

        sendData(webhook, SubmissionType.KILL_TIME);
    }

    public void reset() {
        killData.set(null);
        badTicks.set(0);
    }

    @VisibleForTesting
    static Duration parseTime(String timeStr) {
        if (timeStr == null || timeStr.trim().isEmpty()) {
            return Duration.ZERO;
        }

        try {
            String timePart = timeStr.contains(".") ? timeStr.substring(0, timeStr.indexOf('.')) : timeStr;
            String[] timeParts = timePart.split(":");

            long hours = 0, minutes = 0, seconds = 0, millis = 0;

            if (timeParts.length == 3) {  // h:m:s
                hours = Long.parseLong(timeParts[0]);
                minutes = Long.parseLong(timeParts[1]);
                seconds = Long.parseLong(timeParts[2]);
            } else if (timeParts.length == 2) {  // m:s
                minutes = Long.parseLong(timeParts[0]);
                seconds = Long.parseLong(timeParts[1]);
            }

            if (timeStr.contains(".")) {
                String millisStr = timeStr.substring(timeStr.indexOf('.') + 1);
                while (millisStr.length() < 3) {
                    millisStr += "0";
                }
                millis = Long.parseLong(millisStr);
            }

            return Duration.ofHours(hours).plusMinutes(minutes).plusSeconds(seconds).plusMillis(millis);

        } catch (Exception e) {
            log.error("Error parsing time: {}", e.getMessage());
            return Duration.ZERO;
        }
    }

    @NotNull
    public String formatTime(@Nullable Duration duration, boolean precise) {
        Temporal time = ObjectUtils.defaultIfNull(duration, Duration.ZERO).addTo(LocalTime.of(0, 0));
        StringBuilder sb = new StringBuilder();

        int h = time.get(HOUR_OF_DAY);
        if (h > 0) sb.append(String.format("%02d", h)).append(':');

        sb.append(String.format("%02d", time.get(MINUTE_OF_HOUR))).append(':');
        sb.append(String.format("%02d", time.get(SECOND_OF_MINUTE)));

        if (precise) sb.append('.').append(String.format("%02d", time.get(MILLI_OF_SECOND) / 10));

        return sb.toString();
    }

    public boolean isPreciseTiming(@NotNull Client client) {
        @Varbit int ENABLE_PRECISE_TIMING = 11866;
        return client.getVarbitValue(ENABLE_PRECISE_TIMING) > 0;
    }

    // === BOSS PARSING METHODS ===
    @Nullable
    private static String parsePrimaryBoss(String boss, String type) {
        switch (type.toLowerCase()) {
            case "chest":
                if ("Barrows".equalsIgnoreCase(boss)) return boss;
                if ("Lunar".equals(boss)) return boss + " " + type;
                return null;
            case "completion":
                if (NpcUtilities.GAUNTLET_NAME.equalsIgnoreCase(boss)) return NpcUtilities.GAUNTLET_BOSS;
                if (NpcUtilities.CG_NAME.equalsIgnoreCase(boss)) return NpcUtilities.CG_BOSS;
                return null;
            case "kill":
            case "success":
                return boss;
            default:
                return null;
        }
    }

    private static String parseSecondaryBoss(String boss) {
        if (boss == null || "Wintertodt".equalsIgnoreCase(boss)) return boss;

        int modeSeparator = boss.lastIndexOf(':');
        String raid = modeSeparator > 0 ? boss.substring(0, modeSeparator) : boss;
        if (raid.equalsIgnoreCase("Theatre of Blood") || raid.equalsIgnoreCase("Tombs of Amascut") ||
            raid.equalsIgnoreCase("Chambers of Xeric") || raid.equalsIgnoreCase("Chambers of Xeric Challenge Mode")) {
            return boss;
        }
        return null;
    }

    // === TEAM SIZE METHODS ===
    @SuppressWarnings("deprecation")
    private String getTobTeamSize() {
        int varbitSize = Math.min(client.getVarbitValue(Varbits.THEATRE_OF_BLOOD_ORB1), 1) +
                Math.min(client.getVarbitValue(Varbits.THEATRE_OF_BLOOD_ORB2), 1) +
                Math.min(client.getVarbitValue(Varbits.THEATRE_OF_BLOOD_ORB3), 1) +
                Math.min(client.getVarbitValue(Varbits.THEATRE_OF_BLOOD_ORB4), 1) +
                Math.min(client.getVarbitValue(Varbits.THEATRE_OF_BLOOD_ORB5), 1);
        return formatRaidTeamSize(
            nearbyPlayerTracker != null ? nearbyPlayerTracker.raidRosterSize(NearbyPlayerTracker.RAID_TOB) : 0,
            varbitSize);
    }

    @SuppressWarnings("deprecation")
    private String getToaTeamSize() {
        int varbitSize = Math.min(client.getVarbitValue(Varbits.TOA_MEMBER_0_HEALTH), 1) +
                Math.min(client.getVarbitValue(Varbits.TOA_MEMBER_1_HEALTH), 1) +
                Math.min(client.getVarbitValue(Varbits.TOA_MEMBER_2_HEALTH), 1) +
                Math.min(client.getVarbitValue(Varbits.TOA_MEMBER_3_HEALTH), 1) +
                Math.min(client.getVarbitValue(Varbits.TOA_MEMBER_4_HEALTH), 1) +
                Math.min(client.getVarbitValue(Varbits.TOA_MEMBER_5_HEALTH), 1) +
                Math.min(client.getVarbitValue(Varbits.TOA_MEMBER_6_HEALTH), 1) +
                Math.min(client.getVarbitValue(Varbits.TOA_MEMBER_7_HEALTH), 1);
        return formatRaidTeamSize(
            nearbyPlayerTracker != null ? nearbyPlayerTracker.raidRosterSize(NearbyPlayerTracker.RAID_TOA) : 0,
            varbitSize);
    }

    /**
     * Prefers the accumulated raid roster over the health-orb varbits — the
     * orbs clear at completion, collapsing group raids to "Solo". The varbit
     * read remains the fallback when no roster was accumulated.
     */
    @VisibleForTesting
    static String formatRaidTeamSize(int rosterSize, int varbitSize) {
        int teamSize = Math.max(rosterSize, varbitSize);
        return teamSize == 1 ? "Solo" : Integer.toString(teamSize);
    }

    @SuppressWarnings("deprecation")
    private String getRoyalTitansTeamSize() {
        int size = client.getPlayers().size();
        return size == 1 ? "Solo" : String.valueOf(size);
    }

}

package io.droptracker.events;

import com.google.common.collect.ImmutableSet;
import com.google.gson.Gson;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Experience;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import net.runelite.api.WorldType;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.StatChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.util.QuantityFormatter;
import org.jetbrains.annotations.VisibleForTesting;

import io.droptracker.models.CustomWebhookBody;
import io.droptracker.models.api.GroupConfig;
import io.droptracker.models.submissions.SubmissionType;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ArrayBlockingQueue;
import java.util.concurrent.BlockingQueue;

import static net.runelite.api.Experience.MAX_REAL_LEVEL;

@Slf4j
@Singleton
public class ExperienceHandler extends BaseEventHandler {
    public static final int LEVEL_FOR_MAX_XP = Experience.MAX_VIRT_LEVEL + 1; // 127
    static final @VisibleForTesting int INIT_GAME_TICKS = 16; // ~10s
    private static final Set<WorldType> SPECIAL_WORLDS = EnumSet.of(WorldType.PVP_ARENA, WorldType.QUEST_SPEEDRUNNING, WorldType.BETA_WORLD, WorldType.NOSAVE_MODE, WorldType.TOURNAMENT_WORLD, WorldType.DEADMAN, WorldType.SEASONAL);
    private static final int SKILL_COUNT = Skill.values().length;
    private static final String COMBAT_NAME = "Combat";
    private static final Set<String> COMBAT_COMPONENTS;

    // Configuration constants
    private static final int XP_INTERVAL_MILLIONS = 1; // Track every 1M XP milestone
    private static final int LEVEL_MIN_VALUE = 1; // Minimum level to track
    private static final int LEVEL_INTERVAL = 1; // Track every level
    private static final boolean TRACK_VIRTUAL_LEVELS = true; // Track levels above 99
    private static final boolean TRACK_COMBAT_LEVEL = true; // Track combat level increases

    // How often (in game ticks) to submit a full XP snapshot while an active
    // event is tracking this player's experience (~2 minutes)
    private static final int PERIODIC_SNAPSHOT_TICKS = 200;

    private final BlockingQueue<String> levelledSkills = new ArrayBlockingQueue<>(SKILL_COUNT + 1);
    private final Set<Skill> xpReached = EnumSet.noneOf(Skill.class);
    private final Map<String, Integer> currentLevels = new HashMap<>();
    private final Map<Skill, Integer> currentXp = new EnumMap<>(Skill.class);
    private final Map<String, Integer> previousLevels = new HashMap<>(); // Track previous levels for level increase calculation
    private final Map<Skill, Integer> lastSnapshotXp = new EnumMap<>(Skill.class);

    private int ticksWaited = 0;
    private int initTicks = 0;
    private int ticksSinceSnapshot = 0;
    private boolean loginSnapshotSent = false;
    private Set<WorldType> specialWorldType = null;

    @Inject
    private ClientThread clientThread;

    @Inject
    private Gson gson;


    @Override
    public boolean isEnabled() {
        return config.trackExperience();
    }

    private void initLevels() {
        for (Skill skill : Skill.values()) {
            int xp = client.getSkillExperience(skill);
            int level = client.getRealSkillLevel(skill); // O(1)
            if (level >= MAX_REAL_LEVEL) {
                level = getLevel(xp);
            }
            currentLevels.put(skill.getName(), level);
            currentXp.put(skill, xp);
        }
        currentLevels.put(COMBAT_NAME, calculateCombatLevel());
        this.initTicks = 0;
        this.specialWorldType = getSpecialWorldTypes();
        log.debug("Initialized current skill levels: {}", currentLevels);

        if (!loginSnapshotSent) {
            loginSnapshotSent = true;
            sendXpSnapshot("login");
        }
    }

    public void reset() {
        levelledSkills.clear();
        clientThread.invoke(() -> {
            this.initTicks = 0;
            this.ticksWaited = 0;
            this.ticksSinceSnapshot = 0;
            this.loginSnapshotSent = false;
            xpReached.clear();
            currentXp.clear();
            currentLevels.clear();
            previousLevels.clear();
            lastSnapshotXp.clear();
            this.specialWorldType = null;
        });
    }

    public void onTick() {
        if (this.initTicks > INIT_GAME_TICKS) {
            initLevels();
            return;
        }

        if (currentLevels.size() < SKILL_COUNT) {
            this.initTicks++;
            return;
        }

        // Periodic full-XP snapshot while an active event tracks this player's
        // experience, so xp_target tasks progress without requiring level-ups
        if (++this.ticksSinceSnapshot >= PERIODIC_SNAPSHOT_TICKS) {
            this.ticksSinceSnapshot = 0;
            if (config.useApi()) {
                // rate-limited internally; picks up events activated mid-session
                api.refreshGroupConfigsAsync();
                if (isXpEventTrackingActive()) {
                    sendXpSnapshot("periodic");
                }
            }
        }

        // Handle level ups and XP milestones
        if (!levelledSkills.isEmpty() || !xpReached.isEmpty()) {
            // We wait a couple extra ticks so we can ensure that we process all the levels of the previous tick
            if (++this.ticksWaited > 2) {
                this.ticksWaited = 0;
                // ensure notifier was not disabled during ticks waited
                if (isEnabled()) {
                    attemptNotify();
                } else {
                    levelledSkills.clear();
                    xpReached.clear();
                }
            }
        }
    }

    public void onStatChanged(StatChanged statChange) {
        this.handleStatChange(statChange.getSkill(), statChange.getLevel(), statChange.getXp());
    }

    public void onGameStateChanged(GameStateChanged gameStateChanged) {
        if (gameStateChanged.getGameState() == GameState.LOGIN_SCREEN) {
            // flush session gains before the cached state is cleared
            sendXpSnapshot("logout");
            this.reset();
        } else if (gameStateChanged.getGameState() == GameState.HOPPING) {
            sendXpSnapshot("world_hop");
        } else if (gameStateChanged.getGameState() == GameState.LOGGED_IN && !getSpecialWorldTypes().equals(this.specialWorldType)) {
            // world switched where player may have different level profiles; re-initialize
            this.reset();
        }
    }

    private void handleStatChange(Skill skill, int level, int xp) {
        if (xp <= 0 || level <= 1 || !isEnabled()) return;

        Integer previousXp = currentXp.put(skill, xp);
        if (previousXp == null) {
            return;
        }

        String skillName = skill.getName();
        int virtualLevel = level < MAX_REAL_LEVEL ? level : getLevel(xp); // avoid log(n) query when not needed
        Integer previousLevel = currentLevels.put(skillName, virtualLevel);

        if (previousLevel == null) {
            this.initTicks = INIT_GAME_TICKS; // force init on next tick
            return;
        }

        if (virtualLevel < previousLevel || xp < previousXp) {
            // base skill level should never regress; reset notifier state
            reset();
            return;
        }

        // Check normal skill level up
        checkLevelUp(true, skillName, previousLevel, virtualLevel);

        // Check if xp milestone reached (config-gated; the backend applies each
        // group's own post99_xp_interval on top of this 1M reporting granularity)
        int xpInterval = XP_INTERVAL_MILLIONS * 1_000_000;
        if (config.xpMilestoneEmbeds() && xpInterval > 0 && level >= MAX_REAL_LEVEL && xp > previousXp) {
            int remainder = xp % xpInterval;
            if (remainder == 0 || xp - remainder > previousXp || xp >= Experience.MAX_SKILL_XP) {
                log.debug("Observed XP milestone for {} to {}", skill, xp);
                xpReached.add(skill);
                this.ticksWaited = 0;
            }
        }

        // Skip combat level checking if no level up has occurred
        if (virtualLevel <= previousLevel) {
            // only return if we don't need to initialize combat level for the first time
            if (currentLevels.containsKey(COMBAT_NAME))
                return;
        }

        // Check for combat level increase
        if (COMBAT_COMPONENTS.contains(skillName) && currentLevels.size() >= SKILL_COUNT) {
            int combatLevel = calculateCombatLevel();
            Integer previousCombatLevel = currentLevels.put(COMBAT_NAME, combatLevel);
            checkLevelUp(TRACK_COMBAT_LEVEL, COMBAT_NAME, previousCombatLevel, combatLevel);
        }
    }

    private void checkLevelUp(boolean configEnabled, String skill, Integer previousLevel, int currentLevel) {
        if (previousLevel == null || currentLevel <= previousLevel) {
            log.trace("Ignoring non-level-up for {}: {}", skill, currentLevel);
            return;
        }

        if (!configEnabled) {
            log.trace("Ignoring level up of {} to {} due to disabled config setting", skill, currentLevel);
            return;
        }

        if (!checkLevelInterval(previousLevel, currentLevel, COMBAT_NAME.equals(skill))) {
            log.trace("Ignoring level up of {} from {} to {} that does not align with config interval", skill, previousLevel, currentLevel);
            return;
        }

        if (levelledSkills.offer(skill)) {
            log.debug("Observed level up for {} to {}", skill, currentLevel);

            // Track previous level for level increase calculation
            previousLevels.put(skill, previousLevel);

            // allow more accumulation of level ups into single notification
            this.ticksWaited = 0;
        }
    }

    private void attemptNotify() {
        notifyLevels();
        notifyXp();
    }

    /**
     * True when any of the player's groups has an active event with XP-based
     * tasks, per the API-provided group configs. Requires the API integration.
     */
    private boolean isXpEventTrackingActive() {
        if (!config.useApi() || api == null || api.groupConfigs == null) {
            return false;
        }
        for (GroupConfig groupConfig : api.groupConfigs) {
            if (groupConfig != null && groupConfig.isTrackXpEvents()) {
                return true;
            }
        }
        return false;
    }

    /**
     * Submits a full snapshot of the player's current XP and levels across all
     * skills as an {@code experience_update}. The backend uses these to update
     * stored experience and advance event XP baselines/deltas; they never
     * produce Discord notifications. Sent on login, logout and world-hop, and
     * periodically while an event is tracking this player's XP. Skipped when
     * nothing changed since the last snapshot.
     */
    private void sendXpSnapshot(String reason) {
        if (!isEnabled() || currentXp.size() < SKILL_COUNT) {
            return;
        }
        if (specialWorldType != null && !specialWorldType.isEmpty()) {
            // temporary level profiles (deadman, speedrunning, ...) are not synced
            return;
        }
        if (currentXp.equals(lastSnapshotXp)) {
            return;
        }
        /* Before any state is consumed below: skipping without a name has to
           leave the snapshot pending, not swallow it. The login snapshot is the
           one most likely to land here, since it fires while the RSN may still
           be loading. */
        String playerName = getPlayerName();
        if (playerName == null) {
            log.debug("Skipping {} XP snapshot: no resolvable player name", reason);
            return;
        }

        Map<String, List<Integer>> skillsData = new LinkedHashMap<>();
        long totalXp = 0;
        int totalLevel = 0;
        for (Skill skill : Skill.values()) {
            Integer xp = currentXp.get(skill);
            Integer level = currentLevels.get(skill.getName());
            if (xp == null || level == null) {
                return; // not fully initialized yet; a later snapshot will cover it
            }
            skillsData.put(skill.getName().toLowerCase(), Arrays.asList(xp, level));
            totalXp += xp;
            totalLevel += Math.min(level, MAX_REAL_LEVEL);
        }

        Integer combatLevel = currentLevels.get(COMBAT_NAME);

        CustomWebhookBody webhook = createWebhookBody(playerName + " experience update");
        CustomWebhookBody.Embed embed = createEmbed("Experience Update", "experience_update");
        embed.addField("snapshot_reason", reason, true);
        embed.addField("total_level", String.valueOf(totalLevel), true);
        embed.addField("total_xp", String.valueOf(totalXp), true);
        embed.addField("combat_level", String.valueOf(combatLevel != null ? combatLevel : calculateCombatLevel()), true);
        embed.addField("skills_data", gson.toJson(skillsData), false);
        webhook.getEmbeds().add(embed);

        lastSnapshotXp.clear();
        lastSnapshotXp.putAll(currentXp);
        this.ticksSinceSnapshot = 0;

        log.debug("Sending XP snapshot (reason={}, totalXp={})", reason, totalXp);
        sendData(webhook, SubmissionType.EXPERIENCE_UPDATE);
    }

    /**
     * Creates a simplified field data map for level-up submissions.
     * 
     * @param skillsTrainedList list of skill names that were trained
     * @param skillsLeveledList list of skill names that leveled up
     * @param experienceData map containing experience data for relevant skills
     * @return a map containing only the essential fields
     */
    private Map<String, Object> createLevelUpFieldData(List<String> skillsTrainedList, 
                                                      List<String> skillsLeveledList,
                                                      Map<String, Object> experienceData) {
        Map<String, Object> fieldData = new HashMap<>();

        // General player stats
        fieldData.put("total_level", client.getTotalLevel());
        fieldData.put("total_xp", client.getOverallExperience());
        fieldData.put("combat_level", currentLevels.get(COMBAT_NAME));

        // Skills data - flatten to simple fields
        fieldData.put("skills_trained", String.join(",", skillsTrainedList));
        fieldData.put("skills_leveled", String.join(",", skillsLeveledList));

        // Experience data - flatten to individual fields
        for (Map.Entry<String, Object> entry : experienceData.entrySet()) {
            String key = entry.getKey();
            Object value = entry.getValue();

            if (value instanceof Map) {
                @SuppressWarnings("unchecked")
                Map<String, Object> skillData = (Map<String, Object>) value;
                for (Map.Entry<String, Object> skillEntry : skillData.entrySet()) {
                    fieldData.put(key + "_" + skillEntry.getKey(), skillEntry.getValue());
                }
            } else {
                fieldData.put(key, value);
            }
        }

        return fieldData;
    }

    private void notifyXp() {
        final int n = xpReached.size();
        if (n == 0) return;

        // Bail before xpReached is cleared, so the milestone survives to the
        // next attempt rather than being lost with the submission.
        String playerName = getPlayerName();
        if (playerName == null) {
            log.debug("Skipping XP milestone submission: no resolvable player name");
            return;
        }

        int interval = XP_INTERVAL_MILLIONS * 1_000_000;
        List<String> milestones = new ArrayList<>(n);

        StringBuilder skillMessage = new StringBuilder();
        boolean first = true;

        for (Skill skill : xpReached) {
            int xp = currentXp.getOrDefault(skill, 0);
            xp -= xp % interval;
            milestones.add(skill.getName());

            if (!first) {
                skillMessage.append(", ");
            }
            first = false;

            skillMessage.append(skill.getName())
                       .append(" to ")
                       .append(QuantityFormatter.formatNumber(xp))
                       .append(" XP");
        }

        Map<String, Object> experienceData = new HashMap<>();
        experienceData.put("xp_milestone_interval", interval);

        for (Skill skill : xpReached) {
            int xp = currentXp.getOrDefault(skill, 0);
            xp -= xp % interval; // Get the milestone XP amount
            String skillName = skill.getName().toLowerCase();
            Map<String, Object> skillData = new HashMap<>();
            skillData.put("xp_milestone", xp);
            skillData.put("xp_total", currentXp.get(skill));
            // Virtual level for nicer embeds server-side (99+ skills only).
            Integer level = currentLevels.get(skill.getName());
            if (level != null) {
                skillData.put("new_level", level);
            }
            experienceData.put(skillName, skillData);
        }

        List<String> skillsLeveled = new ArrayList<>(); // No level ups for XP milestones
        Map<String, Object> fieldData = createLevelUpFieldData(milestones, skillsLeveled, experienceData);

        CustomWebhookBody webhook = createWebhookBody(playerName + " reached an XP milestone!");
        CustomWebhookBody.Embed embed = createEmbed("XP Milestone Reached", "experience_milestone");

        addFields(embed, fieldData);
        webhook.getEmbeds().add(embed);

        xpReached.clear();

        sendData(webhook, SubmissionType.EXPERIENCE_MILESTONE);
    }

    private void notifyLevels() {
        /* For level ups specifically  */
        int n = levelledSkills.size();
        if (n == 0) return;

        // Bail before levelledSkills is drained, for the same reason as notifyXp.
        String playerName = getPlayerName();
        if (playerName == null) {
            log.debug("Skipping level up submission: no resolvable player name");
            return;
        }

        // Prepare level state
        List<String> levelled = new ArrayList<>(n);
        int count = levelledSkills.drainTo(levelled);
        if (count == 0) return;

        Map<String, Integer> lSkills = new HashMap<>(count);
        Map<String, Integer> currentLevels = new HashMap<>(this.currentLevels);

        // Build skill message and collect skills involved
        Set<Skill> skillsInvolved = EnumSet.noneOf(Skill.class);
        StringBuilder skillMessage = new StringBuilder();

        for (int index = 0; index < count; index++) {
            String skill = levelled.get(index);
            if (index > 0) {
                if (count > 2) {
                    skillMessage.append(",");
                }
                skillMessage.append(" ");
                if (index + 1 == count) {
                    skillMessage.append("and ");
                }
            }
            Integer level = currentLevels.get(skill);
            skillMessage.append(skill)
                        .append(" to ")
                        .append(level < LEVEL_FOR_MAX_XP ? level : "Max XP (200M)");
            lSkills.put(skill, level);

            // Add skill to involved skills if it's not combat
            if (!COMBAT_NAME.equals(skill)) {
                for (Skill s : Skill.values()) {
                    if (s.getName().equals(skill)) {
                        skillsInvolved.add(s);
                        break;
                    }
                }
            }
        }

        // Check for combat level increase
        Boolean combatLevelUp = lSkills.remove(COMBAT_NAME) != null;
        Integer combatLevel = currentLevels.get(COMBAT_NAME);
        if (combatLevel == null) {
            combatLevel = calculateCombatLevel();
        }

        // Create skills leveled list and experience data
        List<String> skillsLeveledList = new ArrayList<>();
        List<String> skillsTrainedList = new ArrayList<>();
        Map<String, Object> experienceData = new HashMap<>();

        for (String skill : levelled) {
            if (!COMBAT_NAME.equals(skill)) {
                skillsTrainedList.add(skill);
                skillsLeveledList.add(skill);

                Integer previousLevel = previousLevels.get(skill);
                Integer currentLevel = currentLevels.get(skill);
                if (previousLevel != null && currentLevel != null) {
                    String skillName = skill.toLowerCase();
                    Map<String, Object> skillData = new HashMap<>();
                    skillData.put("level_gained", currentLevel - previousLevel);
                    skillData.put("new_level", currentLevel);

                    // Add XP data if available
                    for (Skill s : Skill.values()) {
                        if (s.getName().equals(skill)) {
                            Integer skillXp = currentXp.get(s);
                            if (skillXp != null) {
                                skillData.put("xp_total", skillXp);
                            }
                            break;
                        }
                    }

                    experienceData.put(skillName, skillData);
                }
            }
        }

        // Handle combat level separately
        if (combatLevelUp != null && combatLevelUp) {
            skillsLeveledList.add("Combat");
            Map<String, Object> combatData = new HashMap<>();
            combatData.put("level_gained", 1); // Assume +1 for combat level increases
            combatData.put("new_level", combatLevel);
            experienceData.put("combat", combatData);
        }

        Map<String, Object> fieldData = createLevelUpFieldData(skillsTrainedList, skillsLeveledList, experienceData);

        // Update combat level if it leveled up
        if (combatLevelUp != null && combatLevelUp) {
            fieldData.put("combat_level", combatLevel);
        }

        CustomWebhookBody webhook = createWebhookBody(playerName + " leveled up!");
        CustomWebhookBody.Embed embed = createEmbed("Level Up!", "level_up");

        addFields(embed, fieldData);
        webhook.getEmbeds().add(embed);

        sendData(webhook, SubmissionType.LEVEL_UP);
    }

    private boolean checkLevelInterval(int previous, int level, boolean skipVirtualCheck) {
        if (level < LEVEL_MIN_VALUE)
            return false;

        if (!skipVirtualCheck && level > MAX_REAL_LEVEL && !TRACK_VIRTUAL_LEVELS)
            return false;

        int interval = LEVEL_INTERVAL;
        if (interval <= 1 || level == MAX_REAL_LEVEL || level == LEVEL_FOR_MAX_XP)
            return true;

        // Check levels in (previous, current] for divisibility by interval
        // Allows for firing notification if jumping over a level that would've notified
        int remainder = level % interval;
        return remainder == 0 || (level - remainder) > previous;
    }

    private int calculateCombatLevel() {
        return Experience.getCombatLevel(
            getRealLevel(Skill.ATTACK),
            getRealLevel(Skill.STRENGTH),
            getRealLevel(Skill.DEFENCE),
            getRealLevel(Skill.HITPOINTS),
            getRealLevel(Skill.MAGIC),
            getRealLevel(Skill.RANGED),
            getRealLevel(Skill.PRAYER)
        );
    }

    private int getRealLevel(Skill skill) {
        Integer cachedLevel = currentLevels.get(skill.getName());
        return cachedLevel != null
            ? Math.min(cachedLevel, MAX_REAL_LEVEL)
            : client.getRealSkillLevel(skill);
    }

    private int getLevel(int xp) {
        // treat 200M XP as level 127
        if (xp >= Experience.MAX_SKILL_XP)
            return LEVEL_FOR_MAX_XP;

        // log(n) operation to support virtual levels
        return Experience.getLevelForXp(xp);
    }

    private Set<WorldType> getSpecialWorldTypes() {
        var world = client.getWorldType().clone();
        world.retainAll(SPECIAL_WORLDS); // O(1)
        return world;
    }

    static {
        COMBAT_COMPONENTS = ImmutableSet.of(
            Skill.ATTACK.getName(),
            Skill.STRENGTH.getName(),
            Skill.DEFENCE.getName(),
            Skill.HITPOINTS.getName(),
            Skill.MAGIC.getName(),
            Skill.RANGED.getName(),
            Skill.PRAYER.getName()
        );
    }
}

/*
 * Adapted from RuneProfile (github.com/ReinhardtR/runeprofile-plugin),
 * Copyright (c) 2022, Reinhardt Rijna, BSD 2-Clause License (see LICENSE). Exports a game Model as binary glTF so the player's
 * character - equipment included, since the local player's model is composed
 * from what they are wearing - can be rendered outside the client.
 */
package io.droptracker.modelexport;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import lombok.NonNull;

import javax.annotation.Nullable;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.Map;

/**
 * Serialises a {@link MeshData} to a binary glTF (.glb) file.
 * <p>
 * The output is one mesh whose primitives all share a single vertex buffer,
 * one per group of faces that can be drawn with the same material. Materials
 * are unlit, because the game does no lighting: the colour you see is the
 * vertex colour multiplied by the texel, which is exactly what glTF's base
 * colour factor, base colour texture and COLOR_0 attribute multiply out to.
 * <p>
 * Textures are either embedded in the file, which makes a single self contained
 * model that any glTF viewer will open, or referenced by URL so they can be
 * served once from a CDN and shared across every profile.
 */
public final class GlbWriter {
    private static final int GLB_MAGIC = 0x46546C67; // "glTF"
    private static final int GLB_VERSION = 2;
    private static final int CHUNK_JSON = 0x4E4F534A;
    private static final int CHUNK_BIN = 0x004E4942;

    private static final int TARGET_ARRAY_BUFFER = 34962;
    private static final int TARGET_ELEMENT_ARRAY_BUFFER = 34963;

    private static final int COMPONENT_UNSIGNED_BYTE = 5121;
    private static final int COMPONENT_UNSIGNED_SHORT = 5123;
    private static final int COMPONENT_UNSIGNED_INT = 5125;
    private static final int COMPONENT_FLOAT = 5126;

    private static final int FILTER_NEAREST = 9728;
    private static final int FILTER_LINEAR_MIPMAP_LINEAR = 9987;
    private static final int WRAP_REPEAT = 10497;

    /**
     * Game models are around 128 units per tile. Scaling the root node rather
     * than the vertex data keeps positions as exact small integers and still
     * gives a roughly human sized character in any viewer that assumes metres.
     */
    private static final float UNITS_PER_METRE = 128f;

    /** UNSIGNED_SHORT indices stop here; 65535 is reserved as a restart value. */
    private static final int MAX_SHORT_INDEX = 65535;

    /** How the file should refer to its textures. */
    public static final class Options {
        private boolean embedTextures = true;
        private String textureUrlTemplate;
        private String modelName = "model";
        private Map<String, Object> extras;

        /** Embed texture PNGs in the file. Self contained but not shared between models. */
        public Options embedTextures() {
            this.embedTextures = true;
            this.textureUrlTemplate = null;
            return this;
        }

        /**
         * Reference textures by URL instead of embedding them. The template
         * takes the texture id, e.g. {@code https://cdn.example.com/texture/%d.png}.
         */
        public Options textureUrls(@NonNull String template) {
            this.embedTextures = false;
            this.textureUrlTemplate = template;
            return this;
        }

        public Options modelName(@NonNull String modelName) {
            this.modelName = modelName;
            return this;
        }

        /** Arbitrary metadata to attach to the glTF asset. */
        public Options extras(@Nullable Map<String, Object> extras) {
            this.extras = extras;
            return this;
        }
    }

    private GlbWriter() {
    }

    public static byte[] write(@NonNull MeshData mesh, @NonNull TextureLookup textures,
                               @NonNull Options options) throws IOException {
        if (mesh.isEmpty()) {
            throw new IOException("Refusing to write an empty model");
        }

        final BinaryChunk bin = new BinaryChunk();

        final JsonArray bufferViews = new JsonArray();
        final JsonArray accessors = new JsonArray();
        final JsonArray materials = new JsonArray();
        final JsonArray gltfTextures = new JsonArray();
        final JsonArray images = new JsonArray();
        // Several primitives can share a texture: the same cape is split by
        // translucency. Each needs its own material but they must all point at
        // one image, or the PNG is embedded once per group.
        final Map<Integer, Integer> textureIndexById = new HashMap<>();

        // Vertex attributes, shared by every primitive.
        final int positionAccessor = addAccessor(bufferViews, accessors, bin,
                floatsToBytes(mesh.getPositions()), TARGET_ARRAY_BUFFER,
                COMPONENT_FLOAT, "VEC3", mesh.getVertexCount(), mesh.getMin(), mesh.getMax(), false);

        final int colorAccessor = addAccessor(bufferViews, accessors, bin,
                mesh.getColors(), TARGET_ARRAY_BUFFER,
                COMPONENT_UNSIGNED_BYTE, "VEC4", mesh.getVertexCount(), null, null, true);

        final int uvAccessor = mesh.getUvs() == null ? -1 : addAccessor(bufferViews, accessors, bin,
                floatsToBytes(mesh.getUvs()), TARGET_ARRAY_BUFFER,
                COMPONENT_FLOAT, "VEC2", mesh.getVertexCount(), null, null, false);

        // Face render priority travels per vertex under a custom attribute name,
        // so a renderer can offset by it without the exporter having to split
        // primitives - which translucency cannot afford, since all of it has to
        // share one mesh to be sorted.
        final int priorityAccessor = mesh.getPriorities() == null ? -1
                : addAccessor(bufferViews, accessors, bin,
                        floatsToBytes(mesh.getPriorities()), TARGET_ARRAY_BUFFER,
                        COMPONENT_FLOAT, "SCALAR", mesh.getVertexCount(), null, null, false);

        // One index buffer view for the whole mesh; each primitive gets an
        // accessor pointing at its own slice of it.
        final boolean wideIndices = mesh.getVertexCount() > MAX_SHORT_INDEX;
        final int indexComponentType = wideIndices ? COMPONENT_UNSIGNED_INT : COMPONENT_UNSIGNED_SHORT;
        final int indexStride = wideIndices ? 4 : 2;
        final int indexBufferView = addBufferView(bufferViews, bin,
                indicesToBytes(mesh.getIndices(), wideIndices), TARGET_ELEMENT_ARRAY_BUFFER, 0);

        final JsonArray primitives = new JsonArray();

        for (MeshData.Primitive primitive : mesh.getPrimitives()) {
            final GameTextures.TextureData texture = primitive.isTextured()
                    ? textures.get(primitive.getTextureId())
                    : null;

            final JsonObject accessor = new JsonObject();
            accessor.addProperty("bufferView", indexBufferView);
            accessor.addProperty("byteOffset", primitive.getIndexOffset() * indexStride);
            accessor.addProperty("componentType", indexComponentType);
            accessor.addProperty("count", primitive.getIndexCount());
            accessor.addProperty("type", "SCALAR");
            accessors.add(accessor);
            final int indexAccessor = accessors.size() - 1;

            // A texture whose pixels could not be read still contributes its
            // average colour to the material, so the surface degrades to a flat
            // approximation instead of the bare grey the lightness alone gives.
            final boolean hasImage = texture != null
                    && (options.embedTextures ? texture.getPng() != null : true);

            final JsonObject attributes = new JsonObject();
            attributes.addProperty("POSITION", positionAccessor);
            attributes.addProperty("COLOR_0", colorAccessor);
            // Only textured primitives declare UVs, even though the accessor is
            // shared, so an untextured primitive costs nothing extra.
            if (hasImage && uvAccessor != -1) {
                attributes.addProperty("TEXCOORD_0", uvAccessor);
            }
            if (priorityAccessor != -1) {
                attributes.addProperty("_PRIORITY", priorityAccessor);
            }

            final JsonObject gltfPrimitive = new JsonObject();
            gltfPrimitive.add("attributes", attributes);
            gltfPrimitive.addProperty("indices", indexAccessor);
            gltfPrimitive.addProperty("material", materials.size());
            primitives.add(gltfPrimitive);

            int textureIndex = -1;
            if (hasImage) {
                Integer existing = textureIndexById.get(texture.getId());
                if (existing == null) {
                    gltfTextures.add(buildTexture(images.size()));
                    images.add(buildImage(texture, options, bufferViews, bin));
                    existing = gltfTextures.size() - 1;
                    textureIndexById.put(texture.getId(), existing);
                }
                textureIndex = existing;
            }

            materials.add(buildMaterial(primitive, texture, hasImage, textureIndex));
        }

        final JsonObject mesh0 = new JsonObject();
        mesh0.add("primitives", primitives);
        mesh0.addProperty("name", options.modelName);

        final float scale = 1f / UNITS_PER_METRE;
        final JsonObject node0 = new JsonObject();
        node0.addProperty("mesh", 0);
        node0.addProperty("name", options.modelName);
        node0.add("scale", jsonArray(scale, scale, scale));

        final JsonObject asset = new JsonObject();
        asset.addProperty("version", "2.0");
        asset.addProperty("generator", "RuneProfile");
        if (options.extras != null && !options.extras.isEmpty()) {
            asset.add("extras", extrasToJson(options.extras));
        }

        final JsonObject gltf = new JsonObject();
        gltf.add("asset", asset);
        gltf.addProperty("scene", 0);
        gltf.add("scenes", singletonArray(sceneWithNode()));
        gltf.add("nodes", singletonArray(node0));
        gltf.add("meshes", singletonArray(mesh0));
        gltf.add("materials", materials);
        if (gltfTextures.size() > 0) {
            gltf.add("textures", gltfTextures);
            gltf.add("images", images);
            gltf.add("samplers", singletonArray(buildSampler()));
        }
        gltf.add("accessors", accessors);
        gltf.add("bufferViews", bufferViews);

        final JsonObject buffer = new JsonObject();
        buffer.addProperty("byteLength", bin.size());
        gltf.add("buffers", singletonArray(buffer));

        final JsonArray extensionsUsed = new JsonArray();
        extensionsUsed.add("KHR_materials_unlit");
        gltf.add("extensionsUsed", extensionsUsed);

        return assemble(gltf.toString(), bin.toByteArray());
    }

    /**
     * Serialises the caller's extras map by hand.
     *
     * A {@code Gson} instance would do this in one call, but the plugin hub
     * rejects plugins that construct their own — you are expected to inject the
     * client's — and a static writer has nowhere to inject one. The map only
     * ever carries strings and numbers, so reflection buys nothing.
     */
    private static JsonObject extrasToJson(@NonNull Map<String, Object> extras) {
        final JsonObject json = new JsonObject();
        for (Map.Entry<String, Object> entry : extras.entrySet()) {
            final Object value = entry.getValue();
            if (value instanceof Number) {
                json.addProperty(entry.getKey(), (Number) value);
            } else if (value instanceof Boolean) {
                json.addProperty(entry.getKey(), (Boolean) value);
            } else if (value != null) {
                json.addProperty(entry.getKey(), String.valueOf(value));
            }
        }
        return json;
    }

    /** Resolves a texture id to its pixels; lets the writer stay free of client types. */
    public interface TextureLookup {
        @Nullable
        GameTextures.TextureData get(int textureId);
    }

    private static JsonObject sceneWithNode() {
        final JsonArray nodes = new JsonArray();
        nodes.add(0);
        final JsonObject scene = new JsonObject();
        scene.add("nodes", nodes);
        return scene;
    }

    private static JsonObject buildMaterial(MeshData.Primitive primitive,
                                            @Nullable GameTextures.TextureData texture,
                                            boolean hasImage,
                                            int textureIndex) {
        final JsonObject pbr = new JsonObject();
        if (hasImage) {
            pbr.add("baseColorFactor", jsonArray(1f, 1f, 1f, 1f));
            final JsonObject baseColorTexture = new JsonObject();
            baseColorTexture.addProperty("index", textureIndex);
            pbr.add("baseColorTexture", baseColorTexture);
        } else if (texture != null) {
            final int average = texture.getAverageColor();
            pbr.add("baseColorFactor", jsonArray(
                    ((average >> 16) & 0xff) / 255f,
                    ((average >> 8) & 0xff) / 255f,
                    (average & 0xff) / 255f,
                    1f));
        } else {
            pbr.add("baseColorFactor", jsonArray(1f, 1f, 1f, 1f));
        }
        pbr.addProperty("metallicFactor", 0f);
        pbr.addProperty("roughnessFactor", 1f);

        final JsonObject material = new JsonObject();
        material.addProperty("name", texture == null
                ? "untextured"
                : "texture-" + texture.getId());
        material.add("pbrMetallicRoughness", pbr);
        // The game does not light models, so an unlit material is not a
        // simplification here, it is the accurate one.
        material.add("extensions", unlitExtension());
        // Game models are routinely viewed from both sides and their winding is
        // not reliably outward, so culling would punch holes in them.
        material.addProperty("doubleSided", true);

        if (primitive.isTranslucent()) {
            material.addProperty("alphaMode", "BLEND");
        } else if (hasImage) {
            // Texture transparency is all or nothing in game: the renderer
            // discards fully transparent texels rather than blending them.
            material.addProperty("alphaMode", "MASK");
            material.addProperty("alphaCutoff", 0.5f);
        } else {
            material.addProperty("alphaMode", "OPAQUE");
        }

        // Neither scrolling UVs nor a depth bias is something glTF can express,
        // so both ride along as metadata for a renderer that knows to look.
        final JsonObject runeprofile = new JsonObject();
        if (hasImage && texture.isAnimated()) {
            runeprofile.addProperty("textureId", texture.getId());
            runeprofile.addProperty("scrollU", texture.getScrollU());
            runeprofile.addProperty("scrollV", texture.getScrollV());
        }
        if (runeprofile.size() > 0) {
            final JsonObject extras = new JsonObject();
            extras.add("runeprofile", runeprofile);
            material.add("extras", extras);
        }

        return material;
    }

    private static JsonObject unlitExtension() {
        final JsonObject extensions = new JsonObject();
        extensions.add("KHR_materials_unlit", new JsonObject());
        return extensions;
    }

    private static JsonObject buildTexture(int imageIndex) {
        final JsonObject texture = new JsonObject();
        texture.addProperty("sampler", 0);
        texture.addProperty("source", imageIndex);
        return texture;
    }

    private static JsonObject buildImage(GameTextures.TextureData texture, Options options,
                                         JsonArray bufferViews, BinaryChunk bin) throws IOException {
        final JsonObject image = new JsonObject();
        image.addProperty("name", "texture-" + texture.getId());
        if (options.embedTextures) {
            image.addProperty("bufferView", addBufferView(bufferViews, bin, texture.getPng(), -1, 0));
            image.addProperty("mimeType", "image/png");
        } else {
            image.addProperty("uri", String.format(options.textureUrlTemplate, texture.getId()));
        }
        return image;
    }

    private static JsonObject buildSampler() {
        final JsonObject sampler = new JsonObject();
        // Nearest magnification keeps the chunky look the game has; mipmapped
        // minification stops distant textures shimmering.
        sampler.addProperty("magFilter", FILTER_NEAREST);
        sampler.addProperty("minFilter", FILTER_LINEAR_MIPMAP_LINEAR);
        // Game UVs run outside 0..1 and rely on the texture repeating.
        sampler.addProperty("wrapS", WRAP_REPEAT);
        sampler.addProperty("wrapT", WRAP_REPEAT);
        return sampler;
    }

    private static int addAccessor(JsonArray bufferViews, JsonArray accessors, BinaryChunk bin,
                                   byte[] data, int target, int componentType, String type,
                                   int count, @Nullable float[] min, @Nullable float[] max,
                                   boolean normalized) throws IOException {
        final int bufferView = addBufferView(bufferViews, bin, data, target, 0);

        final JsonObject accessor = new JsonObject();
        accessor.addProperty("bufferView", bufferView);
        accessor.addProperty("componentType", componentType);
        accessor.addProperty("count", count);
        accessor.addProperty("type", type);
        if (normalized) {
            accessor.addProperty("normalized", true);
        }
        if (min != null) {
            accessor.add("min", jsonArray(min));
        }
        if (max != null) {
            accessor.add("max", jsonArray(max));
        }
        accessors.add(accessor);
        return accessors.size() - 1;
    }

    private static int addBufferView(JsonArray bufferViews, BinaryChunk bin, byte[] data,
                                     int target, int byteStride) throws IOException {
        final int offset = bin.append(data);

        final JsonObject bufferView = new JsonObject();
        bufferView.addProperty("buffer", 0);
        bufferView.addProperty("byteOffset", offset);
        bufferView.addProperty("byteLength", data.length);
        if (byteStride > 0) {
            bufferView.addProperty("byteStride", byteStride);
        }
        if (target > 0) {
            bufferView.addProperty("target", target);
        }
        bufferViews.add(bufferView);
        return bufferViews.size() - 1;
    }

    private static byte[] floatsToBytes(float[] values) {
        final ByteBuffer buffer = ByteBuffer.allocate(values.length * 4).order(ByteOrder.LITTLE_ENDIAN);
        for (float value : values) {
            buffer.putFloat(value);
        }
        return buffer.array();
    }

    private static byte[] indicesToBytes(int[] indices, boolean wide) {
        final ByteBuffer buffer = ByteBuffer
                .allocate(indices.length * (wide ? 4 : 2))
                .order(ByteOrder.LITTLE_ENDIAN);
        for (int index : indices) {
            if (wide) {
                buffer.putInt(index);
            } else {
                buffer.putShort((short) index);
            }
        }
        return buffer.array();
    }

    private static JsonArray jsonArray(float... values) {
        final JsonArray array = new JsonArray();
        for (float value : values) {
            array.add(value);
        }
        return array;
    }

    private static JsonArray singletonArray(JsonObject value) {
        final JsonArray array = new JsonArray();
        array.add(value);
        return array;
    }

    /**
     * Wraps the JSON and binary payloads in the GLB container. Both chunks are
     * padded to a four byte boundary, JSON with spaces and binary with zeroes,
     * as the format requires.
     */
    private static byte[] assemble(String json, byte[] binary) {
        final byte[] jsonBytes = json.getBytes(StandardCharsets.UTF_8);
        final int jsonPadding = padding(jsonBytes.length);
        final int binaryPadding = padding(binary.length);

        final int jsonChunkLength = jsonBytes.length + jsonPadding;
        final int binaryChunkLength = binary.length + binaryPadding;
        final int totalLength = 12 + 8 + jsonChunkLength + 8 + binaryChunkLength;

        final ByteBuffer buffer = ByteBuffer.allocate(totalLength).order(ByteOrder.LITTLE_ENDIAN);
        buffer.putInt(GLB_MAGIC);
        buffer.putInt(GLB_VERSION);
        buffer.putInt(totalLength);

        buffer.putInt(jsonChunkLength);
        buffer.putInt(CHUNK_JSON);
        buffer.put(jsonBytes);
        for (int i = 0; i < jsonPadding; i++) {
            buffer.put((byte) ' ');
        }

        buffer.putInt(binaryChunkLength);
        buffer.putInt(CHUNK_BIN);
        buffer.put(binary);
        for (int i = 0; i < binaryPadding; i++) {
            buffer.put((byte) 0);
        }

        return buffer.array();
    }

    private static int padding(int length) {
        return (4 - (length % 4)) % 4;
    }

    /**
     * The single binary buffer every buffer view points into. Appends are kept
     * four byte aligned, which every accessor component type we emit requires.
     */
    private static final class BinaryChunk {
        private final ByteArrayOutputStream out = new ByteArrayOutputStream();

        int append(byte[] data) throws IOException {
            for (int i = padding(out.size()); i > 0; i--) {
                out.write(0);
            }
            final int offset = out.size();
            out.write(data);
            return offset;
        }

        int size() {
            return out.size();
        }

        byte[] toByteArray() {
            return out.toByteArray();
        }
    }
}

/*
 * Adapted from RuneProfile (github.com/ReinhardtR/runeprofile-plugin),
 * Copyright (c) 2022, Reinhardt Rijna, BSD 2-Clause License (see LICENSE). Exports a game Model as binary glTF so the player's
 * character - equipment included, since the local player's model is composed
 * from what they are wearing - can be rendered outside the client.
 */
package io.droptracker.modelexport;

import lombok.NonNull;
import net.runelite.api.Model;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

/**
 * Turns a game {@link Model} into a {@link MeshData}, keeping the texture
 * mapping the old PLY exporter threw away.
 * <p>
 * The game gives us, per face, either a colour or a texture id plus a "texture
 * triangle": three vertices of the model itself that define the texture's
 * origin and its two axes. UV coordinates are recovered by projecting each face
 * vertex onto those axes, which is what the client's own GPU renderer does every
 * frame (see {@link #computeFaceUvs}).
 * <p>
 * Vertex colours mean different things on the two kinds of face. Untextured
 * faces carry a packed HSL colour. Textured faces carry a 7 bit lightness that
 * the renderer multiplies the sampled texel by, so those become greys and the
 * multiply happens again at draw time against the texture.
 */
public final class ModelMeshBuilder {
    /** Index by packed HSL to get RGB. Matches what the old PLY exporter used. */
    private static final int[] COLOR_PALETTE = JagexColor.createPalette(JagexColor.BRIGHTNESS_MIN);

    /** Lightness on a textured face is 7 bit; the renderer divides by this. */
    private static final float TEXTURE_LIGHT_MAX = 127f;

    /** A third face colour of -1 means flat shading rather than a colour per corner. */
    private static final int FLAT_SHADED = -1;

    /**
     * A third face colour of -2 marks a face the game never draws, distinct from
     * -1 which only means flat shading. Skipping it is not an optimisation: the
     * value is a sentinel, so reading it as a colour index lands on hue 63,
     * saturation 7, luminance 126, and the face appears as a stray near white
     * triangle across the model. Missing this is why one showed over the top of
     * an inferno cape in both this exporter and the older PLY one.
     */
    private static final int HIDDEN_FACE = -2;

    /**
     * Game model space is X east, Y down, Z north. Since X cross Y equals Z it is
     * already right handed, same as glTF, so getting Y pointing up is a rotation
     * rather than a mirror: negate Y and Z, which is a 180 degree turn about X.
     * Negating Y alone would reflect the model, putting the character back to
     * front and swapping its handedness.
     * <p>
     * Because the mapping is a proper rotation its determinant is +1, so face
     * winding carries over unchanged and corners are emitted in their original
     * order.
     */
    private static final float[] AXIS_SIGNS = {1f, -1f, -1f};

    private ModelMeshBuilder() {
    }

    public static MeshData build(@NonNull Model model) {
        final Map<FaceGroup, List<Integer>> groups = groupFaces(model);
        final boolean textured = groups.keySet().stream().anyMatch(FaceGroup::isTextured);

        final VertexBuffer vertices = new VertexBuffer(model.getFaceCount(), textured,
                model.getFaceRenderPriorities() != null);
        final List<MeshData.Primitive> primitives = new ArrayList<>(groups.size());

        for (Map.Entry<FaceGroup, List<Integer>> entry : groups.entrySet()) {
            final FaceGroup group = entry.getKey();
            final int start = vertices.indexCount();

            for (int face : entry.getValue()) {
                appendFace(model, face, group.isTextured(), vertices);
            }

            primitives.add(new MeshData.Primitive(group.textureId, start,
                    vertices.indexCount() - start, group.translucent));
        }

        return vertices.toMeshData(primitives);
    }

    /**
     * Buckets the faces the game would actually draw, one bucket per primitive.
     * <p>
     * A {@link TreeMap} keeps the buckets in {@link FaceGroup}'s order, so the
     * same model always exports byte for byte the same.
     */
    private static Map<FaceGroup, List<Integer>> groupFaces(Model model) {
        final int[] colors3 = model.getFaceColors3();
        final short[] faceTextures = model.getFaceTextures();
        final byte[] faceTransparencies = model.getFaceTransparencies();

        final Map<FaceGroup, List<Integer>> groups = new TreeMap<>();
        for (int face = 0; face < model.getFaceCount(); face++) {
            if (colors3[face] == HIDDEN_FACE) {
                continue;
            }
            final int alpha = alphaOf(faceTransparencies, face);
            if (alpha == 0) {
                // Fully transparent: the game does not draw it, so neither do we.
                continue;
            }

            final int textureId = faceTextures == null ? MeshData.NO_TEXTURE : faceTextures[face];
            groups.computeIfAbsent(new FaceGroup(textureId, alpha != 255),
                    key -> new ArrayList<>()).add(face);
        }
        return groups;
    }

    /** Appends one face's three corners, in their original winding. */
    private static void appendFace(Model model, int face, boolean textured, VertexBuffer vertices) {
        final float[] verticesX = model.getVerticesX();
        final float[] verticesY = model.getVerticesY();
        final float[] verticesZ = model.getVerticesZ();

        final int[] corners = {
                model.getFaceIndices1()[face],
                model.getFaceIndices2()[face],
                model.getFaceIndices3()[face],
        };

        // A flat shaded face has one colour for the whole triangle rather than
        // one per corner.
        final int[] colors3 = model.getFaceColors3();
        final boolean flat = colors3[face] == FLAT_SHADED;
        final int[] cornerColors = {
                model.getFaceColors1()[face],
                flat ? model.getFaceColors1()[face] : model.getFaceColors2()[face],
                flat ? model.getFaceColors1()[face] : colors3[face],
        };

        final float[] u = new float[3];
        final float[] v = new float[3];
        if (textured) {
            computeFaceUvs(model, face, u, v);
        }

        final int alpha = alphaOf(model.getFaceTransparencies(), face);
        final byte[] facePriorities = model.getFaceRenderPriorities();
        final int priority = facePriorities == null ? 0 : facePriorities[face] & 0xff;

        for (int corner = 0; corner < 3; corner++) {
            final int vertex = corners[corner];
            vertices.add(
                    verticesX[vertex] * AXIS_SIGNS[0],
                    verticesY[vertex] * AXIS_SIGNS[1],
                    verticesZ[vertex] * AXIS_SIGNS[2],
                    textured
                            ? lightnessToGrey(cornerColors[corner])
                            : COLOR_PALETTE[cornerColors[corner] & 0xffff],
                    alpha,
                    textured ? u[corner] : 0f,
                    textured ? v[corner] : 0f,
                    priority);
        }
    }

    /** Face transparency is 0 for opaque, 255 for invisible; alpha is the inverse. */
    private static int alphaOf(byte[] faceTransparencies, int face) {
        if (faceTransparencies == null) {
            return 255;
        }
        return 255 - (faceTransparencies[face] & 0xff);
    }

    /**
     * A textured face's "colour" is a 7 bit lightness the renderer multiplies the
     * texel by. Expanding it to a grey lets an ordinary vertex colour multiply
     * reproduce the same shading.
     */
    private static int lightnessToGrey(int lightness) {
        final int clamped = lightness < 0 ? 0 : Math.min(lightness, (int) TEXTURE_LIGHT_MAX);
        final int level = Math.round(clamped / TEXTURE_LIGHT_MAX * 255f);
        return (level << 16) | (level << 8) | level;
    }

    /**
     * Projects a face's three vertices onto its texture triangle to recover UV
     * coordinates, mirroring {@code ModelUploader.computeFaceUvs} in the client's
     * GPU plugin so exported models are mapped exactly as the game maps them.
     * <p>
     * The texture triangle is three model vertices: the first is the texture's
     * origin, the other two are the ends of its U and V axes. Faces without one
     * fall back to mapping the triangle straight onto the texture's corner.
     */
    static void computeFaceUvs(Model model, int face, float[] u, float[] v) {
        final byte[] textureFaces = model.getTextureFaces();
        if (textureFaces == null || textureFaces[face] == -1) {
            u[0] = 0f;
            v[0] = 0f;
            u[1] = 1f;
            v[1] = 0f;
            u[2] = 0f;
            v[2] = 1f;
            return;
        }

        final float[] vertexX = model.getVerticesX();
        final float[] vertexY = model.getVerticesY();
        final float[] vertexZ = model.getVerticesZ();

        final int triangleA = model.getFaceIndices1()[face];
        final int triangleB = model.getFaceIndices2()[face];
        final int triangleC = model.getFaceIndices3()[face];

        final int textureFace = textureFaces[face] & 0xff;
        final int texA = model.getTexIndices1()[textureFace];
        final int texB = model.getTexIndices2()[textureFace];
        final int texC = model.getTexIndices3()[textureFace];

        // Texture origin, then its two axes as vectors from that origin.
        final float originX = vertexX[texA];
        final float originY = vertexY[texA];
        final float originZ = vertexZ[texA];

        final float axisUx = vertexX[texB] - originX;
        final float axisUy = vertexY[texB] - originY;
        final float axisUz = vertexZ[texB] - originZ;

        final float axisVx = vertexX[texC] - originX;
        final float axisVy = vertexY[texC] - originY;
        final float axisVz = vertexZ[texC] - originZ;

        // The face's own corners, relative to the same origin.
        final float aX = vertexX[triangleA] - originX;
        final float aY = vertexY[triangleA] - originY;
        final float aZ = vertexZ[triangleA] - originZ;

        final float bX = vertexX[triangleB] - originX;
        final float bY = vertexY[triangleB] - originY;
        final float bZ = vertexZ[triangleB] - originZ;

        final float cX = vertexX[triangleC] - originX;
        final float cY = vertexY[triangleC] - originY;
        final float cZ = vertexZ[triangleC] - originZ;

        // normal = axisU x axisV
        final float normalX = axisUy * axisVz - axisUz * axisVy;
        final float normalY = axisUz * axisVx - axisUx * axisVz;
        final float normalZ = axisUx * axisVy - axisUy * axisVx;

        // Projecting along axisV x normal isolates the U component, and the
        // reciprocal dot with axisU normalises it so axisU's end lands on u = 1.
        float projX = axisVy * normalZ - axisVz * normalY;
        float projY = axisVz * normalX - axisVx * normalZ;
        float projZ = axisVx * normalY - axisVy * normalX;
        float scale = 1.0F / (projX * axisUx + projY * axisUy + projZ * axisUz);

        u[0] = (projX * aX + projY * aY + projZ * aZ) * scale;
        u[1] = (projX * bX + projY * bY + projZ * bZ) * scale;
        u[2] = (projX * cX + projY * cY + projZ * cZ) * scale;

        // Same again with the axes swapped, for V.
        projX = axisUy * normalZ - axisUz * normalY;
        projY = axisUz * normalX - axisUx * normalZ;
        projZ = axisUx * normalY - axisUy * normalX;
        scale = 1.0F / (projX * axisVx + projY * axisVy + projZ * axisVz);

        v[0] = (projX * aX + projY * aY + projZ * aZ) * scale;
        v[1] = (projX * bX + projY * bY + projZ * bZ) * scale;
        v[2] = (projX * cX + projY * cY + projZ * cZ) * scale;
    }

    /**
     * Identifies which primitive a face belongs to: the two things that need a
     * separate material. Ordering puts untextured before textured and opaque
     * before translucent.
     * <p>
     * Nothing else belongs here. Splitting is not free - every extra primitive
     * is another mesh, and translucent triangles can only be ordered against
     * each other while they share one - so per face data a renderer needs is
     * carried per vertex instead.
     */
    private static final class FaceGroup implements Comparable<FaceGroup> {
        private final int textureId;
        private final boolean translucent;

        FaceGroup(int textureId, boolean translucent) {
            this.textureId = textureId;
            this.translucent = translucent;
        }

        boolean isTextured() {
            return textureId != MeshData.NO_TEXTURE;
        }

        @Override
        public int compareTo(FaceGroup other) {
            if (textureId != other.textureId) {
                return Integer.compare(textureId, other.textureId);
            }
            return translucent == other.translucent ? 0 : (translucent ? 1 : -1);
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) {
                return true;
            }
            if (!(o instanceof FaceGroup)) {
                return false;
            }
            final FaceGroup other = (FaceGroup) o;
            return textureId == other.textureId && translucent == other.translucent;
        }

        @Override
        public int hashCode() {
            return textureId * 2 + (translucent ? 1 : 0);
        }
    }

    /**
     * Collects vertices as faces are appended, merging any that come out
     * identical, and tracks the bounds glTF wants on the position accessor.
     * <p>
     * Sized for the worst case of three unshared vertices per face and trimmed
     * at the end, which avoids growing four parallel buffers as it goes.
     */
    private static final class VertexBuffer {
        private final float[] positions;
        private final byte[] colors;
        private final float[] uvs;
        private final float[] priorities;
        private final int[] indices;
        private final Map<VertexKey, Integer> lookup;

        private final float[] min = {Float.MAX_VALUE, Float.MAX_VALUE, Float.MAX_VALUE};
        private final float[] max = {-Float.MAX_VALUE, -Float.MAX_VALUE, -Float.MAX_VALUE};

        private int vertexCount;
        private int indexCount;

        VertexBuffer(int faceCount, boolean textured, boolean prioritised) {
            final int capacity = faceCount * 3;
            this.positions = new float[capacity * 3];
            this.colors = new byte[capacity * 4];
            this.uvs = textured ? new float[capacity * 2] : null;
            this.priorities = prioritised ? new float[capacity] : null;
            this.indices = new int[capacity];
            this.lookup = new HashMap<>(capacity * 2);
        }

        int indexCount() {
            return indexCount;
        }

        void add(float x, float y, float z, int rgb, int alpha, float u, float v, int priority) {
            final VertexKey key = new VertexKey(x, y, z, rgb, alpha, u, v, priority);
            Integer slot = lookup.get(key);
            if (slot == null) {
                slot = vertexCount++;
                positions[slot * 3] = x;
                positions[slot * 3 + 1] = y;
                positions[slot * 3 + 2] = z;

                colors[slot * 4] = (byte) ((rgb >> 16) & 0xff);
                colors[slot * 4 + 1] = (byte) ((rgb >> 8) & 0xff);
                colors[slot * 4 + 2] = (byte) (rgb & 0xff);
                colors[slot * 4 + 3] = (byte) alpha;

                if (uvs != null) {
                    uvs[slot * 2] = u;
                    uvs[slot * 2 + 1] = v;
                }

                if (priorities != null) {
                    priorities[slot] = priority;
                }

                grow(x, 0);
                grow(y, 1);
                grow(z, 2);

                lookup.put(key, slot);
            }
            indices[indexCount++] = slot;
        }

        private void grow(float value, int axis) {
            if (value < min[axis]) {
                min[axis] = value;
            }
            if (value > max[axis]) {
                max[axis] = value;
            }
        }

        MeshData toMeshData(List<MeshData.Primitive> primitives) {
            if (vertexCount == 0) {
                final float[] origin = {0f, 0f, 0f};
                return new MeshData(new float[0], new byte[0], null, null, new int[0],
                        new ArrayList<>(), origin, origin);
            }
            return new MeshData(
                    trim(positions, vertexCount * 3),
                    trim(colors, vertexCount * 4),
                    priorities == null ? null : trim(priorities, vertexCount),
                    uvs == null ? null : trim(uvs, vertexCount * 2),
                    trim(indices, indexCount),
                    primitives,
                    min,
                    max);
        }

        private static float[] trim(float[] source, int length) {
            if (source.length == length) {
                return source;
            }
            final float[] trimmed = new float[length];
            System.arraycopy(source, 0, trimmed, 0, length);
            return trimmed;
        }

        private static byte[] trim(byte[] source, int length) {
            if (source.length == length) {
                return source;
            }
            final byte[] trimmed = new byte[length];
            System.arraycopy(source, 0, trimmed, 0, length);
            return trimmed;
        }

        private static int[] trim(int[] source, int length) {
            if (source.length == length) {
                return source;
            }
            final int[] trimmed = new int[length];
            System.arraycopy(source, 0, trimmed, 0, length);
            return trimmed;
        }
    }

    /**
     * Identity of a vertex for merging. Two face corners collapse into one vertex
     * only when position, colour and UV all agree, so flat shaded faces keep
     * their hard colour edges and textured faces keep their seams.
     */
    private static final class VertexKey {
        private final float x, y, z, u, v;
        private final int rgb, alpha, priority;
        private final int hash;

        VertexKey(float x, float y, float z, int rgb, int alpha, float u, float v, int priority) {
            this.x = x;
            this.y = y;
            this.z = z;
            this.rgb = rgb;
            this.alpha = alpha;
            this.u = u;
            this.v = v;
            this.priority = priority;

            int h = Float.floatToIntBits(x);
            h = h * 31 + Float.floatToIntBits(y);
            h = h * 31 + Float.floatToIntBits(z);
            h = h * 31 + rgb;
            h = h * 31 + alpha;
            h = h * 31 + Float.floatToIntBits(u);
            h = h * 31 + Float.floatToIntBits(v);
            h = h * 31 + priority;
            this.hash = h;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) {
                return true;
            }
            if (!(o instanceof VertexKey)) {
                return false;
            }
            final VertexKey other = (VertexKey) o;
            return hash == other.hash
                    && Float.floatToIntBits(x) == Float.floatToIntBits(other.x)
                    && Float.floatToIntBits(y) == Float.floatToIntBits(other.y)
                    && Float.floatToIntBits(z) == Float.floatToIntBits(other.z)
                    && rgb == other.rgb
                    && alpha == other.alpha
                    && Float.floatToIntBits(u) == Float.floatToIntBits(other.u)
                    && Float.floatToIntBits(v) == Float.floatToIntBits(other.v)
                    && priority == other.priority;
        }

        @Override
        public int hashCode() {
            return hash;
        }
    }
}

/*
 * Adapted from RuneProfile (github.com/ReinhardtR/runeprofile-plugin),
 * Copyright (c) 2022, Reinhardt Rijna, BSD 2-Clause License (see LICENSE). Exports a game Model as binary glTF so the player's
 * character - equipment included, since the local player's model is composed
 * from what they are wearing - can be rendered outside the client.
 */
package io.droptracker.modelexport;

import java.util.Collections;
import java.util.List;

/**
 * A triangle mesh in a form that is independent of both the game's model
 * representation and the file format it will be written to.
 * <p>
 * There is a single shared vertex buffer and a single shared index buffer.
 * Each {@link Primitive} owns a contiguous run of that index buffer and names
 * the two things that decide how it is drawn: the game texture its triangles
 * are mapped to, and whether they are translucent. A model that mixes an
 * untextured body with, say, an inferno cape becomes two primitives over one
 * set of vertices rather than two meshes.
 * <p>
 * Everything else a renderer needs travels per vertex, so it never forces a
 * split. Face render priority is the reason that matters: translucent geometry
 * has to share one mesh to be sorted, so anything carried per primitive would
 * reach opaque faces only.
 * <p>
 * Faces are deliberately kept in as few primitives as they can be. Each one is
 * a separate mesh to a renderer, and translucent triangles can only be ordered
 * correctly against each other while they share one.
 * <p>
 * Coordinates are already in glTF's space: Y up, right handed, still in game
 * units (roughly 128 per tile), with index order wound counter clockwise.
 */
public final class MeshData {
    /** Texture id used by {@link Primitive#getTextureId()} for untextured triangles. */
    public static final int NO_TEXTURE = -1;

    /**
     * One run of triangles sharing a texture. {@code indexOffset} and
     * {@code indexCount} address {@link MeshData#getIndices()}.
     */
    public static final class Primitive {
        private final int textureId;
        private final int indexOffset;
        private final int indexCount;
        private final boolean translucent;

        Primitive(int textureId, int indexOffset, int indexCount, boolean translucent) {
            this.textureId = textureId;
            this.indexOffset = indexOffset;
            this.indexCount = indexCount;
            this.translucent = translucent;
        }

        public int getTextureId() {
            return textureId;
        }

        public int getIndexOffset() {
            return indexOffset;
        }

        public int getIndexCount() {
            return indexCount;
        }

        /** True when any triangle in the run is partially transparent. */
        public boolean isTranslucent() {
            return translucent;
        }




        public boolean isTextured() {
            return textureId != NO_TEXTURE;
        }
    }

    private final float[] positions;
    private final byte[] colors;
    private final float[] priorities;
    private final float[] uvs;
    private final int[] indices;
    private final List<Primitive> primitives;
    private final float[] min;
    private final float[] max;

    MeshData(float[] positions, byte[] colors, float[] priorities, float[] uvs, int[] indices,
             List<Primitive> primitives, float[] min, float[] max) {
        this.positions = positions;
        this.colors = colors;
        this.priorities = priorities;
        this.uvs = uvs;
        this.indices = indices;
        this.primitives = Collections.unmodifiableList(primitives);
        this.min = min;
        this.max = max;
    }

    /** Three floats per vertex. */
    public float[] getPositions() {
        return positions;
    }

    /** Four unsigned bytes per vertex, RGBA. */
    public byte[] getColors() {
        return colors;
    }

    /** Two floats per vertex, or null when no primitive is textured. */
    public float[] getUvs() {
        return uvs;
    }

    /**
     * One float per vertex: the game's face render priority, or null when the
     * model has none.
     * <p>
     * Per vertex rather than per primitive because a renderer needs it on
     * translucent geometry too, and translucent faces have to share one mesh so
     * their triangles can be sorted against each other. Carrying it on the
     * material would force a split that transparency cannot afford, and would
     * silently apply to opaque geometry only - which reorders opaque against
     * translucent and puts an arm through a crystal shield.
     */
    public float[] getPriorities() {
        return priorities;
    }

    public int[] getIndices() {
        return indices;
    }

    public List<Primitive> getPrimitives() {
        return primitives;
    }

    public int getVertexCount() {
        return positions.length / 3;
    }

    /** Per axis minimum of {@link #getPositions()}; glTF requires it on the position accessor. */
    public float[] getMin() {
        return min;
    }

    public float[] getMax() {
        return max;
    }

    public boolean isEmpty() {
        return indices.length == 0;
    }
}

/*
 * Adapted from RuneProfile (github.com/ReinhardtR/runeprofile-plugin),
 * Copyright (c) 2022, Reinhardt Rijna, BSD 2-Clause License (see LICENSE). Exports a game Model as binary glTF so the player's
 * character - equipment included, since the local player's model is composed
 * from what they are wearing - can be rendered outside the client.
 */
package io.droptracker.modelexport;

import lombok.NonNull;
import net.runelite.api.Client;
import net.runelite.api.Model;

import java.io.IOException;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Exports a game {@link Model} as a binary glTF.
 */
public final class GlbExporter {
    private GlbExporter() {
    }

    /**
     * Writes a self contained GLB with every texture embedded. One file, opens
     * in any glTF viewer, no external requests.
     */
    public static byte[] toBytes(@NonNull Client client, @NonNull Model model,
                                 @NonNull String name) throws IOException {
        return toBytes(client, model, new GlbWriter.Options().embedTextures().modelName(name));
    }

    public static byte[] toBytes(@NonNull Client client, @NonNull Model model,
                                 @NonNull GlbWriter.Options options) throws IOException {
        final MeshData mesh = ModelMeshBuilder.build(model);
        final GameTextures textures = new GameTextures(client);

        final Map<String, Object> extras = new LinkedHashMap<>();
        extras.put("source", "droptracker-plugin");
        extras.put("faceCount", model.getFaceCount());
        extras.put("vertexCount", mesh.getVertexCount());
        options.extras(extras);

        return GlbWriter.write(mesh, textures::get, options);
    }
}

/*
 * Adapted from RuneProfile (github.com/ReinhardtR/runeprofile-plugin),
 * Copyright (c) 2022, Reinhardt Rijna, BSD 2-Clause License (see LICENSE). Exports a game Model as binary glTF so the player's
 * character - equipment included, since the local player's model is composed
 * from what they are wearing - can be rendered outside the client.
 */
package io.droptracker.modelexport;

import lombok.NonNull;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Texture;

import javax.annotation.Nullable;
import javax.imageio.ImageIO;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.util.HashMap;
import java.util.Map;

/**
 * Reads game textures out of the client as PNGs, along with the scroll rate
 * that makes animated ones (an inferno cape's fire, lava, water) move.
 * <p>
 * Encoded PNGs are cached for the life of the client: there are only a couple
 * of hundred textures in the game and a player uses a handful, but a profile
 * sync would otherwise re-encode the same cape every time.
 */
@Slf4j
public final class GameTextures {
    /**
     * The client advances texture animation once per client tick, and shifts
     * UVs by speed/128 each time. Client ticks are 20ms, so this converts the
     * game's per tick step into UV units per second for a renderer that works
     * in wall clock time.
     */
    private static final float TICKS_PER_SECOND = 50f;
    private static final float TEXTURE_ANIM_UNIT = 1f / 128f;

    /** One texture, ready to embed or upload. */
    public static final class TextureData {
        private final int id;
        private final byte[] png;
        private final int averageColor;
        private final float scrollU;
        private final float scrollV;

        TextureData(int id, @Nullable byte[] png, int averageColor, float scrollU, float scrollV) {
            this.id = id;
            this.png = png;
            this.averageColor = averageColor;
            this.scrollU = scrollU;
            this.scrollV = scrollV;
        }

        public int getId() {
            return id;
        }

        /** Null if the pixels could not be encoded; fall back to {@link #getAverageColor()}. */
        @Nullable
        public byte[] getPng() {
            return png;
        }

        /**
         * Packed RGB mean of the non transparent texels. Used as a flat stand in
         * when the image itself is unavailable, which is what the old PLY
         * exporter did for every textured face.
         */
        public int getAverageColor() {
            return averageColor;
        }

        /** UV units per second, 0 when the texture does not animate. */
        public float getScrollU() {
            return scrollU;
        }

        public float getScrollV() {
            return scrollV;
        }

        public boolean isAnimated() {
            return scrollU != 0f || scrollV != 0f;
        }
    }

    private final Client client;
    private final Map<Integer, TextureData> cache = new HashMap<>();

    public GameTextures(@NonNull Client client) {
        this.client = client;
    }

    /**
     * Returns the texture, or null when the client has not loaded it yet (its
     * pixels are fetched lazily, so a texture the local player has never had
     * on screen may genuinely be unavailable).
     */
    @Nullable
    public TextureData get(int textureId) {
        if (textureId < 0) {
            return null;
        }
        if (cache.containsKey(textureId)) {
            return cache.get(textureId);
        }

        TextureData data = load(textureId);
        cache.put(textureId, data);
        return data;
    }

    @Nullable
    private TextureData load(int textureId) {
        final int[] pixels;
        try {
            pixels = client.getTextureProvider().load(textureId);
        } catch (RuntimeException e) {
            log.debug("Could not load texture {}", textureId, e);
            return null;
        }

        if (pixels == null || pixels.length == 0) {
            return null;
        }

        // Textures are square; the client uses 128x128 but deriving it keeps
        // this working if that ever changes.
        final int size = (int) Math.round(Math.sqrt(pixels.length));
        if (size * size != pixels.length) {
            log.debug("Texture {} is not square ({} pixels)", textureId, pixels.length);
            return null;
        }

        byte[] png = null;
        try {
            png = encodePng(pixels, size);
        } catch (IOException | RuntimeException e) {
            // Still worth returning the average colour so the model renders as
            // a plausible flat surface rather than grey.
            log.debug("Could not encode texture {}", textureId, e);
        }

        final float[] scroll = scrollOf(textureId);
        return new TextureData(textureId, png, averageColor(pixels), scroll[0], scroll[1]);
    }

    /** Mean of every texel the game actually draws, ignoring transparent ones. */
    private static int averageColor(int[] pixels) {
        long red = 0;
        long green = 0;
        long blue = 0;
        int counted = 0;
        for (int pixel : pixels) {
            if (pixel == 0) {
                continue;
            }
            red += (pixel >> 16) & 0xff;
            green += (pixel >> 8) & 0xff;
            blue += pixel & 0xff;
            counted++;
        }
        if (counted == 0) {
            return 0xffffff;
        }
        return (int) ((red / counted) << 16 | (green / counted) << 8 | (blue / counted));
    }

    /**
     * A pixel of 0 is the game's transparent texel, which the renderer discards
     * rather than drawing black, so it becomes a fully transparent PNG pixel.
     */
    private static byte[] encodePng(int[] pixels, int size) throws IOException {
        final int[] argb = new int[pixels.length];
        for (int i = 0; i < pixels.length; i++) {
            final int rgb = pixels[i];
            argb[i] = rgb == 0 ? 0 : 0xff000000 | rgb;
        }

        final BufferedImage image = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
        image.setRGB(0, 0, size, size, argb, 0, size);

        final ByteArrayOutputStream out = new ByteArrayOutputStream();
        ImageIO.write(image, "png", out);
        return out.toByteArray();
    }

    /**
     * Direction and speed come straight off the texture definition; the mapping
     * from direction to axis matches the client's own
     * {@code TextureManager.computeTextureAnimations}.
     */
    private float[] scrollOf(int textureId) {
        final Texture[] textures = client.getTextureProvider().getTextures();
        if (textures == null || textureId >= textures.length || textures[textureId] == null) {
            return new float[]{0f, 0f};
        }

        final Texture texture = textures[textureId];
        float u = 0f;
        float v = 0f;
        switch (texture.getAnimationDirection()) {
            case 1:
                v = -1f;
                break;
            case 2:
                u = -1f;
                break;
            case 3:
                v = 1f;
                break;
            case 4:
                u = 1f;
                break;
            default:
                return new float[]{0f, 0f};
        }

        final float perSecond = texture.getAnimationSpeed() * TEXTURE_ANIM_UNIT * TICKS_PER_SECOND;
        return new float[]{u * perSecond, v * perSecond};
    }
}

