    private static JPanel updateValidSubmissionPanel(JPanel panel, List<RecentSubmission> recentSubmissions, ItemManager itemManager, Client client, boolean forGroup) {
        panel.removeAll();


        GridBagConstraints c = new GridBagConstraints();
        c.fill = GridBagConstraints.NONE;
        c.anchor = GridBagConstraints.CENTER;
        c.weightx = 0.2; // Equal weight for 5 columns
        c.weighty = 0.5; // Equal weight for 2 rows
        c.gridx = 0;
        c.gridy = 0;
        c.insets = new Insets(1, 1, 1, 1); // Padding around each icon

        int successfullyAdded = 0;
        final int ITEMS_PER_ROW = 5;
        final int MAX_ITEMS = 10;

        // Add each submission icon to the panel (limit to 10 items)
        for (int i = 0; i < Math.min(recentSubmissions.size(), MAX_ITEMS); i++) {
            RecentSubmission submission = recentSubmissions.get(i);
            boolean effects = false;
            if (submission.submissionImageUrl() != null) {
                effects = true;
            }
            try {
                JLabel iconContainer = null;
                if (submission.getSubmissionType().equalsIgnoreCase("drop")) {
                    // Handle drops
                    Integer itemId = submission.getDropItemId();
                    Integer quantity = submission.getDropQuantity();

                    if (itemId != null && quantity != null && itemManager != null) {
                        final AsyncBufferedImage originalImage = itemManager.getImage(itemId, quantity, quantity > 1);
                        final float alpha = (quantity > 0 ? 1.0f : 0.5f);

                        // Create a scaled version of the image for initial display
                        BufferedImage scaledImage = new BufferedImage(28, 28, BufferedImage.TYPE_INT_ARGB);
                        BufferedImage opaque = ImageUtil.alphaOffset(scaledImage, alpha);
                        final JLabel dropContainer = PanelElements.createStyledIconContainer(effects);
                        dropContainer.setToolTipText(buildSubmissionTooltip(submission, forGroup));
                        dropContainer.setIcon(new ImageIcon(opaque));
                        iconContainer = dropContainer;

                        // onLoaded runs on the client thread (and re-posts there when
                        // the sprite is already loaded): scale and relayout on the EDT.
                        originalImage.onLoaded(() -> SwingUtilities.invokeLater(() -> {
                            // Scale the loaded image to 28x28
                            Image scaled = originalImage.getScaledInstance(28, 28, Image.SCALE_SMOOTH);
                            BufferedImage scaledBuffered = new BufferedImage(28, 28, BufferedImage.TYPE_INT_ARGB);
                            Graphics g = scaledBuffered.getGraphics();
                            g.drawImage(scaled, 0, 0, null);
                            g.dispose(); // Clean up graphics resources

                            BufferedImage finalImage = ImageUtil.alphaOffset(scaledBuffered, alpha);
                            dropContainer.setIcon(new ImageIcon(finalImage));
                            dropContainer.setToolTipText(buildSubmissionTooltip(submission, forGroup));
                            dropContainer.revalidate();
                            dropContainer.repaint();
                        }));
                    }
                } else if (submission.getSubmissionType().equalsIgnoreCase("clog")) {
                    // Handle collection log items
                    Integer itemId = submission.getClogItemId();

                    if (itemId != null && itemManager != null) {
                        final AsyncBufferedImage originalImage = itemManager.getImage(itemId, 1, false);
                        final float alpha = 1.0f;

                        // Create a scaled version of the image for initial display
                        BufferedImage scaledImage = new BufferedImage(28, 28, BufferedImage.TYPE_INT_ARGB);
                        BufferedImage opaque = ImageUtil.alphaOffset(scaledImage, alpha);

                        final JLabel clogContainer = PanelElements.createStyledIconContainer(effects);
                        clogContainer.setToolTipText(buildSubmissionTooltip(submission, forGroup));
                        clogContainer.setIcon(new ImageIcon(opaque));
                        iconContainer = clogContainer;

                        // onLoaded runs on the client thread (and re-posts there when
                        // the sprite is already loaded): scale and relayout on the EDT.
                        originalImage.onLoaded(() -> SwingUtilities.invokeLater(() -> {
                            // Scale the loaded image to 28x28
                            Image scaled = originalImage.getScaledInstance(28, 28, Image.SCALE_SMOOTH);
                            BufferedImage scaledBuffered = new BufferedImage(28, 28, BufferedImage.TYPE_INT_ARGB);
                            Graphics g = scaledBuffered.getGraphics();
                            g.drawImage(scaled, 0, 0, null);
                            g.dispose(); // Clean up graphics resources

                            BufferedImage finalImage = ImageUtil.alphaOffset(scaledBuffered, alpha);
                            clogContainer.setIcon(new ImageIcon(finalImage));
                            clogContainer.revalidate();
                            clogContainer.repaint();
                        }));
                    }
                } else {
                    // Personal bests, and event completions credited by any
                    // other source type (manual, kc, …): the API's image_path
                    // is the only icon there is.
                    boolean isPb = submission.getSubmissionType().equalsIgnoreCase("pb");
                    HttpUrl imageUrl = submission.imageUrl();

                    if (imageUrl != null) {
                        final int size = isPb ? 16 : 28;
                        final JLabel pbContainer = PanelElements.createStyledIconContainer(effects);
                        pbContainer.setToolTipText(buildSubmissionTooltip(submission, forGroup));
                        pbContainer.setText(isPb ? "PB" : "");
                        pbContainer.setFont(FontManager.getRunescapeSmallFont());
                        pbContainer.setForeground(DropTrackerTheme.TEXT);
                        iconContainer = pbContainer;

                        // Load image asynchronously
                        CompletableFuture.supplyAsync(() -> {
                            BufferedImage image = fetchImage(imageUrl);
                            if (image != null) {
                                Image scaled = image.getScaledInstance(size, size, Image.SCALE_SMOOTH);
                                return new ImageIcon(scaled);
                            }
                            return null;
                        }).thenAccept(imageIcon -> {
                            if (imageIcon != null) {
                                SwingUtilities.invokeLater(() -> {
                                    pbContainer.setText(""); // Remove text
                                    pbContainer.setIcon(imageIcon);
                                    pbContainer.revalidate();
                                    pbContainer.repaint();
                                });
                            }
                        });
                    }
                }


                // Add the icon container if it was created successfully
                if (iconContainer != null) {
                    if (submission.submissionImageUrl() != null) {
                        // Capture submission data for the click listener
                        final String submissionTypeForListener = submission.getSubmissionType();
                        final HttpUrl submissionImageUrlForListener = submission.submissionImageUrl();
                        final String tooltipForListener = buildSubmissionTooltip(submission, forGroup);
                        // Add hover effect and click listener
                        iconContainer.addMouseListener(new MouseAdapter() {
                            @Override
                            public void mouseClicked(MouseEvent e) {
                                PanelElements.showSubmissionImage(client, submissionTypeForListener, submissionImageUrlForListener, tooltipForListener);
                            }
                        });
                    }

                    panel.add(iconContainer, c);
                    successfullyAdded++;

                    // Move to next position
                    c.gridx++;
                    if (c.gridx >= ITEMS_PER_ROW) {
                        c.gridx = 0;
                        c.gridy++;
                    }
                }
            } catch (Exception e) {
                log.warn("Failed updating submission panel", e);
            }
        }


        // If no icons were added, show a message
        if (successfullyAdded == 0) {
            JLabel debugLabel = new JLabel("No recent submissions to display");
            debugLabel.setForeground(DropTrackerTheme.TEXT_MUTED);
            debugLabel.setFont(FontManager.getRunescapeSmallFont());
            c.gridx = 0;
            c.gridy = 0;
            c.gridwidth = ITEMS_PER_ROW;
            c.gridheight = 2;
            panel.add(debugLabel, c);
        }

        panel.revalidate();
        panel.repaint();
        return panel;
    }

    public static String buildSubmissionTooltip(RecentSubmission submission, boolean forGroup) {
        try {
            String tooltip = "<html><p style='font-size:10px;'>";
            if (forGroup) {
                if (submission.getSubmissionType().equalsIgnoreCase("pb")) {
                    String pbTime = sanitizeTxt(submission.getPbTime());
                    tooltip += "<b>" + pbTime + "</b> at " + sanitizeTxt(submission.getSourceName()) + "<br>" +
                            sanitizeTxt(submission.getPlayerName()) + " - new personal best!<br><br>" +
                            "<i>" + sanitizeTxt(submission.timeSinceReceived()) + "</i>";
                } else if (submission.getSubmissionType().equalsIgnoreCase("drop")) {
                    String itemName = sanitizeTxt(submission.getDropItemName());
                    tooltip += "<b>" + itemName + "</b><br>" +
                            sanitizeTxt(submission.getPlayerName()) + "<br>" +
                            "from: <i>" + sanitizeTxt(submission.getSourceName()) + "</i><br>" +
                            "<i>" + sanitizeTxt(submission.timeSinceReceived()) + "</i>";
                } else if (submission.getSubmissionType().equalsIgnoreCase("clog")) {
                    String itemName = sanitizeTxt(submission.getClogItemName());
                    tooltip += sanitizeTxt(submission.getPlayerName()) + " - New Collection Log:<br>" +
                            "<b>" + itemName + "</b><br>" +
                            "<i>from: " + sanitizeTxt(submission.getSourceName()) + "</i><br>" +
                            "<i>" + sanitizeTxt(submission.timeSinceReceived()) + "</i>";
                } else {
                    tooltip += genericSubmissionTooltip(submission);
                }
            } else {
                if (submission.getSubmissionType().equalsIgnoreCase("pb")) {
                    String pbTime = sanitizeTxt(submission.getPbTime());
                    tooltip += "<b>" + pbTime + "</b> at " + sanitizeTxt(submission.getSourceName()) + "<br>" +
                            sanitizeTxt(submission.getPlayerName()) + " - new personal best!<br><br>" +
                            "<i>" + sanitizeTxt(submission.timeSinceReceived()) + "</i>";
                } else if (submission.getSubmissionType().equalsIgnoreCase("drop")) {
                    String itemName = sanitizeTxt(submission.getDropItemName());
                    tooltip += "<b>" + itemName + "</b><br>" +
                            sanitizeTxt(submission.getPlayerName()) + "<br>" +
                            "from: <i>" + sanitizeTxt(submission.getSourceName()) + "</i><br>" +
                            "<i>" + sanitizeTxt(submission.timeSinceReceived()) + "</i>";
                } else if (submission.getSubmissionType().equalsIgnoreCase("clog")) {
                    String itemName = sanitizeTxt(submission.getClogItemName());
                    tooltip += sanitizeTxt(submission.getPlayerName()) + " - New Collection Log:<br>" +
                            "<b>" + itemName + "</b><br>" +
                            "<i>" + sanitizeTxt(submission.timeSinceReceived()) + "</i>";
                } else {
                    tooltip += genericSubmissionTooltip(submission);
                }
            }
            tooltip += "</p></html>";
            return tooltip;

        } catch (Exception e) {
            return sanitizeTxt(submission.getPlayerName() + " - " + submission.getSubmissionType() + " - " + submission.getSourceName());
        }
    }

    /**
     * Fallback body for submission types the tabs have no bespoke wording for —
     * an event completion credited by kc, xp or a moderator's hand. The API's
     * own display name is the only thing that describes those, and an empty
     * tooltip would be worse than a plain one.
     */
    private static String genericSubmissionTooltip(RecentSubmission submission) {
        String body = "<b>" + sanitizeTxt(submission.getDisplayName()) + "</b><br>" +
                sanitizeTxt(submission.getPlayerName()) + "<br>";
        if (submission.getSourceName() != null) {
            body += "for: <i>" + sanitizeTxt(submission.getSourceName()) + "</i><br>";
        }
        if (submission.getValue() != null) {
            body += sanitizeTxt(submission.getValue()) + "<br>";
        }
        return body + "<i>" + sanitizeTxt(submission.timeSinceReceived()) + "</i>";
    }

    private static String sanitizeTxt(String tooltip) {
        return escapeHtml(tooltip);
    }

    /**
     * Escapes text that is about to be interpolated into a Swing {@code <html>}
     * string. Swing's HTML renderer resolves {@code <img src>} over the network, so
     * any server-supplied string reaching a JLabel or tooltip must come through
     * here — otherwise the API could make the client fetch an arbitrary URL without
     * a single line of request code being involved.
     */
    public static String escapeHtml(String value) {
        return value == null ? "" : value
            .replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
    }

    private static void displayImageInDialog(JDialog imageDialog, BufferedImage originalImage, JFrame parentFrame) {
        // Calculate display size based on screen dimensions
        Dimension screenSize = java.awt.Toolkit.getDefaultToolkit().getScreenSize();
        int maxWidth = (int) (screenSize.width * 0.9);
        int maxHeight = (int) (screenSize.height * 0.9);

        int originalWidth = originalImage.getWidth();
        int originalHeight = originalImage.getHeight();

        int displayWidth = originalWidth;
        int displayHeight = originalHeight;

        // Scale down if image is too large for screen
        if (originalWidth > maxWidth || originalHeight > maxHeight) {
            double scaleX = (double) maxWidth / originalWidth;
            double scaleY = (double) maxHeight / originalHeight;
            double scale = Math.min(scaleX, scaleY);

            displayWidth = (int) (originalWidth * scale);
            displayHeight = (int) (originalHeight * scale);
        }

        // Create image label
        JLabel imageLabel = new JLabel();
        imageLabel.setPreferredSize(new Dimension(displayWidth, displayHeight));
        imageLabel.setBorder(new StrokeBorder(new BasicStroke(2), DropTrackerTheme.SURFACE_3));
        imageLabel.setHorizontalAlignment(JLabel.CENTER);
        imageLabel.setVerticalAlignment(JLabel.CENTER);
        imageLabel.setBackground(DropTrackerTheme.SURFACE_1);
        imageLabel.setOpaque(true);

        // Scale image if needed
        Image displayImage;
        if (displayWidth == originalWidth && displayHeight == originalHeight) {
            displayImage = originalImage;
        } else {
            displayImage = originalImage.getScaledInstance(displayWidth, displayHeight, Image.SCALE_SMOOTH);
        }

        imageLabel.setIcon(new ImageIcon(displayImage));

        // Add listeners
        addCloseListener(imageLabel, imageDialog);
        addEscapeKeyListener(imageLabel, imageDialog);

        // Set up dialog
        imageDialog.add(imageLabel);
        imageDialog.pack();
        imageDialog.setLocationRelativeTo(parentFrame);

        // Request focus for escape key
        SwingUtilities.invokeLater(() -> imageLabel.requestFocusInWindow());

    }

    // Helper methods to reduce code duplication
    private static void addCloseListener(JLabel label, JDialog dialog) {
        label.addMouseListener(new MouseAdapter() {
            @Override
            public void mouseClicked(MouseEvent e) {
                dialog.dispose();
            }
        });
    }

    private static void addEscapeKeyListener(JLabel label, JDialog dialog) {
        label.setFocusable(true);
        label.addKeyListener(new java.awt.event.KeyAdapter() {
            @Override
            public void keyPressed(java.awt.event.KeyEvent e) {
                if (e.getKeyCode() == java.awt.event.KeyEvent.VK_ESCAPE) {
                    dialog.dispose();
                }
            }
        });
    }

}

package io.droptracker.ui.components;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.GridLayout;
import java.awt.event.FocusAdapter;
import java.awt.event.FocusEvent;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.LongSupplier;
import java.util.function.Supplier;

import javax.annotation.Nullable;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JTextArea;
import javax.swing.JTextField;
import javax.swing.border.EmptyBorder;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import javax.swing.text.BadLocationException;

import io.droptracker.api.DeathMessageApi;
import io.droptracker.api.DropTrackerUrls;
import io.droptracker.models.api.DeathMessages;
import io.droptracker.ui.DropTrackerTheme;
import io.droptracker.util.DeathMessageRules;
import net.runelite.client.ui.FontManager;
import net.runelite.client.util.LinkBrowser;

/**
 * The death message editor itself: five boxes, placeholders, a preview, and
 * where the message is posted. {@link DeathMessageDialog} puts it in a window.
 *
 * <p>What the member writes here is what their clan sees when they die — in
 * every clan whose leaders let members write their own. The same messages are
 * on the website and in Discord's {@code /settings}, so this is a view onto the
 * server's copy, never a local one: it loads on open and saves straight back.
 * Nothing here is a RuneLite config item, which would be per profile rather
 * than per account and a second copy to disagree with the server's.
 */
public class DeathMessageEditor extends JPanel {

    static final int WIDTH = 390;

    private final DeathMessageApi api;
    private final LongSupplier accountHash;
    private final Supplier<String> playerNameSupplier;
    private final Runnable onClose;
    private final Runnable onResize;

    private final List<JTextField> fields = new ArrayList<>();
    private final JLabel groupsLabel = new JLabel(" ");
    private final JLabel previewLabel = new JLabel(" ");
    private final JLabel statusLabel = new JLabel(" ");
    private final JButton saveButton = new JButton("Save");
    private final JPanel tokenPanel = new JPanel(new GridLayout(0, 2, 4, 4));

    private JTextField lastFocused;
    private long hash = -1;
    @Nullable
    private String playerName;
    private List<String> savedMessages = new ArrayList<>();
    private Map<String, String> samples = new HashMap<>();
    private boolean busy;
    private boolean closed;

    /**
     * @param onClose  what "Close" does (dispose the window)
     * @param onResize called after the content changes size (re-pack the window)
     */
    public DeathMessageEditor(DeathMessageApi api, LongSupplier accountHash, Supplier<String> playerName,
                              Runnable onClose, Runnable onResize) {
        this.api = api;
        this.accountHash = accountHash;
        this.playerNameSupplier = playerName;
        this.onClose = onClose;
        this.onResize = onResize;
        build();
    }

    /** Loads the server's copy for the logged-in account. */
    public void load() {
        hash = accountHash.getAsLong();
        playerName = playerNameSupplier.get();
        if (hash == -1) {
            showStatus("Log in first: your death message belongs to the account you're playing.",
                DropTrackerTheme.EMBER);
            return;
        }
        busy = true;
        showStatus("Loading...", DropTrackerTheme.TEXT_MUTED);
        api.fetch(playerName, hash, result -> {
            busy = false;
            if (closed) {
                return;
            }
            if (result.messages == null) {
                showStatus(result.error, DropTrackerTheme.RED);
                return;
            }
            apply(result.messages);
            setEditable(true);
            showStatus(" ", DropTrackerTheme.TEXT_MUTED);
            refresh();
        });
    }

    /** Stops late answers from touching a closed window. */
    public void markClosed() {
        closed = true;
    }

    private void build() {
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setBackground(DropTrackerTheme.SURFACE_0);
        setBorder(new EmptyBorder(10, 12, 10, 12));

        JLabel title = new JLabel("Your death message");
        title.setFont(FontManager.getRunescapeBoldFont());
        title.setForeground(DropTrackerTheme.GOLD);
        add(row(title));

        add(row(wrapped(
            "Write what your clan sees when you die. One of your messages is picked at random for each death, "
                + "in every clan whose leaders let members write their own. You can also edit these on the "
                + "DropTracker website or with /settings in Discord.")));
        add(Box.createRigidArea(new Dimension(0, 6)));

        groupsLabel.setFont(FontManager.getRunescapeSmallFont());
        groupsLabel.setForeground(DropTrackerTheme.TEXT_MUTED);
        add(row(groupsLabel));
        add(Box.createRigidArea(new Dimension(0, 6)));

        JPanel rows = new JPanel(new GridLayout(DeathMessageRules.MAX_MESSAGES, 1, 0, 4));
        rows.setBackground(DropTrackerTheme.SURFACE_0);
        for (int i = 0; i < DeathMessageRules.MAX_MESSAGES; i++) {
            JTextField field = new JTextField();
            // A fixed width: a text field's preferred width follows its text,
            // so a long message would otherwise widen the whole window.
            field.setPreferredSize(new Dimension(WIDTH - 24, field.getPreferredSize().height));
            field.setToolTipText("Message " + (i + 1) + " - leave blank if you don't need it");
            field.getDocument().addDocumentListener(new DocumentListener() {
                @Override
                public void insertUpdate(DocumentEvent e) {
                    refresh();
                }

                @Override
                public void removeUpdate(DocumentEvent e) {
                    refresh();
                }

                @Override
                public void changedUpdate(DocumentEvent e) {
                    refresh();
                }
            });
            field.addFocusListener(new FocusAdapter() {
                @Override
                public void focusGained(FocusEvent e) {
                    lastFocused = field;
                    refresh();
                }
            });
            fields.add(field);
            rows.add(field);
        }
        lastFocused = fields.get(0);
        add(row(rows));
        add(Box.createRigidArea(new Dimension(0, 6)));

        JLabel tokensTitle = new JLabel("Click a placeholder to add it:");
        tokensTitle.setFont(FontManager.getRunescapeSmallFont());
        tokensTitle.setForeground(DropTrackerTheme.TEXT_MUTED);
        add(row(tokensTitle));
        tokenPanel.setBackground(DropTrackerTheme.SURFACE_0);
        setTokens(DeathMessageRules.TOKENS);
        add(row(tokenPanel));
        add(Box.createRigidArea(new Dimension(0, 6)));

        previewLabel.setFont(FontManager.getRunescapeSmallFont());
        previewLabel.setForeground(DropTrackerTheme.TEXT);
        add(row(previewLabel));
        statusLabel.setFont(FontManager.getRunescapeSmallFont());
        add(row(statusLabel));
        add(Box.createRigidArea(new Dimension(0, 8)));

        JPanel buttons = new JPanel(new BorderLayout());
        buttons.setBackground(DropTrackerTheme.SURFACE_0);
        JPanel leftButtons = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
        leftButtons.setBackground(DropTrackerTheme.SURFACE_0);
        DropTrackerTheme.styleButton(saveButton);
        saveButton.addActionListener(e -> save());
        JButton close = new JButton("Close");
        DropTrackerTheme.styleButton(close);
        close.addActionListener(e -> onClose.run());
        leftButtons.add(saveButton);
        leftButtons.add(Box.createRigidArea(new Dimension(6, 0)));
        leftButtons.add(close);
        buttons.add(leftButtons, BorderLayout.WEST);
        JButton website = new JButton("Open website");
        DropTrackerTheme.styleButton(website);
        website.setToolTipText("Edit your death messages on the DropTracker website");
        website.addActionListener(e -> LinkBrowser.browse(DropTrackerUrls.web("settings").toString()));
        buttons.add(website, BorderLayout.EAST);
        add(row(buttons));

        setEditable(false);
    }

    private void save() {
        List<String> rows = rows();
        String issue = DeathMessageRules.listIssue(rows);
        if (issue != null) {
            showStatus(issue, DropTrackerTheme.RED);
            return;
        }
        List<String> messages = DeathMessageRules.normalize(rows);
        busy = true;
        setEditable(false);
        showStatus("Saving...", DropTrackerTheme.TEXT_MUTED);
        api.save(playerName, hash, messages, result -> {
            busy = false;
            if (closed) {
                return;
            }
            setEditable(true);
            if (result.messages == null) {
                refresh();
                showStatus(result.error, DropTrackerTheme.RED);
                return;
            }
            apply(result.messages);
            refresh();
            showStatus(messages.isEmpty() ? "Cleared. Your clans will use their own death message."
                : "Saved.", DropTrackerTheme.GREEN);
        });
    }

    /** Puts the server's copy into the boxes, the groups line and the samples. */
    private void apply(DeathMessages loaded) {
        if (loaded.getPlayerName() != null) {
            playerName = loaded.getPlayerName();
        }
        savedMessages = new ArrayList<>(DeathMessageRules.normalize(loaded.getMessages()));
        for (int i = 0; i < fields.size(); i++) {
            fields.get(i).setText(i < savedMessages.size() ? savedMessages.get(i) : "");
        }
        samples = new HashMap<>();
        List<String> tokens = new ArrayList<>();
        for (DeathMessages.Token token : loaded.getTokens()) {
            if (token.getToken() == null) {
                continue;
            }
            tokens.add(token.getToken());
            samples.put(token.getToken(), token.getSample() == null ? "" : token.getSample());
        }
        setTokens(tokens.isEmpty() ? DeathMessageRules.TOKENS : tokens);
        groupsLabel.setText(groupsText(loaded.getGroups()));
        onResize.run();
    }

    /** Re-validates after any edit: the preview, the problem line and the Save button. */
    private void refresh() {
        if (busy) {
            return;
        }
        List<String> rows = rows();
        String issue = DeathMessageRules.listIssue(rows);
        boolean changed = !DeathMessageRules.normalize(rows).equals(savedMessages);
        saveButton.setEnabled(issue == null && changed && hash != -1 && fields.get(0).isEditable());

        String source = lastFocused != null && !lastFocused.getText().trim().isEmpty()
            ? lastFocused.getText() : firstNonBlank(rows);
        if (issue == null && source != null) {
            previewLabel.setText(html("Example: " + escape(DeathMessageRules.preview(source, samples, playerName))));
        } else {
            previewLabel.setText(" ");
        }
        if (issue != null) {
            showStatus(issue, DropTrackerTheme.RED);
        } else if (changed) {
            showStatus("Unsaved changes.", DropTrackerTheme.TEXT_MUTED);
        } else if (DropTrackerTheme.RED.equals(statusLabel.getForeground())) {
            showStatus(" ", DropTrackerTheme.TEXT_MUTED);
        }
    }

    private void insertToken(String token) {
        JTextField target = lastFocused != null ? lastFocused : fields.get(0);
        if (!target.isEditable()) {
            return;
        }
        String text = target.getText();
        int caret = Math.max(0, Math.min(target.getCaretPosition(), text.length()));
        boolean needsSpace = caret > 0 && !Character.isWhitespace(text.charAt(caret - 1));
        try {
            target.getDocument().insertString(caret, (needsSpace ? " " : "") + token, null);
        } catch (BadLocationException e) {
            target.setText(text + (needsSpace ? " " : "") + token);
        }
        target.requestFocusInWindow();
    }

    private void setTokens(List<String> tokens) {
        tokenPanel.removeAll();
        boolean editable = !fields.isEmpty() && fields.get(0).isEditable();
        for (String token : tokens) {
            JButton button = new JButton(token);
            DropTrackerTheme.styleButton(button);
            button.setEnabled(editable);
            button.addActionListener(e -> insertToken(token));
            tokenPanel.add(button);
        }
        tokenPanel.revalidate();
    }

    private void setEditable(boolean editable) {
        for (JTextField field : fields) {
            field.setEditable(editable);
        }
        for (Component c : tokenPanel.getComponents()) {
            c.setEnabled(editable);
        }
        saveButton.setEnabled(false);
    }

    private List<String> rows() {
        List<String> rows = new ArrayList<>();
        for (JTextField field : fields) {
            rows.add(field.getText());
        }
        return rows;
    }

    private void showStatus(@Nullable String text, Color color) {
        statusLabel.setText(text == null || text.trim().isEmpty() ? " " : html(escape(text)));
        statusLabel.setForeground(color);
    }

    // Package-private views for the tests.

    List<JTextField> fields() {
        return fields;
    }

    JButton saveButton() {
        return saveButton;
    }

    String statusText() {
        return statusLabel.getText();
    }

    String previewText() {
        return previewLabel.getText();
    }

    String groupsLabelText() {
        return groupsLabel.getText();
    }

    void clickToken(String token) {
        insertToken(token);
    }

    void clickSave() {
        save();
    }

    /** "Posted in: Clan A, Clan B (not switched on)" — where the message goes, and where not. */
    static String groupsText(List<DeathMessages.Group> groups) {
        if (groups == null || groups.isEmpty()) {
            return html("This account isn't in any clans on the DropTracker yet.");
        }
        StringBuilder sb = new StringBuilder("Posted in: ");
        for (int i = 0; i < groups.size(); i++) {
            DeathMessages.Group group = groups.get(i);
            if (i > 0) {
                sb.append(", ");
            }
            String name = escape(group.getName() == null ? "Group " + group.getId() : group.getName());
            if (group.isBlocked()) {
                sb.append(colored(name + " (blocked by its leaders)", DropTrackerTheme.RED));
            } else if (group.isAllowed()) {
                sb.append(colored(name, DropTrackerTheme.GREEN));
            } else {
                sb.append(colored(name + " (not switched on)", DropTrackerTheme.TEXT_MUTED));
            }
        }
        return html(sb.toString());
    }

    @Nullable
    private static String firstNonBlank(List<String> rows) {
        for (String row : rows) {
            if (row != null && !row.trim().isEmpty()) {
                return row;
            }
        }
        return null;
    }

    private static String colored(String escapedText, Color color) {
        return String.format("<font color='#%06x'>%s</font>", color.getRGB() & 0xFFFFFF, escapedText);
    }

    private static String html(String body) {
        // Swing's HTML renderer scales a CSS width by 96/72, so ask for three
        // quarters of the space the text should actually take.
        return "<html><div style='width:" + ((WIDTH - 30) * 3 / 4) + "px'>" + body + "</div></html>";
    }

    /** Clan names and messages are user-written; a JLabel would render their HTML. */
    static String escape(String text) {
        return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
    }

    private static JTextArea wrapped(String text) {
        JTextArea area = new JTextArea(text);
        area.setWrapStyleWord(true);
        area.setLineWrap(true);
        area.setOpaque(false);
        area.setEditable(false);
        area.setFocusable(false);
        area.setForeground(DropTrackerTheme.TEXT_MUTED);
        area.setFont(FontManager.getRunescapeSmallFont());
        area.setBorder(BorderFactory.createEmptyBorder(4, 0, 0, 0));
        area.setSize(new Dimension(WIDTH - 24, Short.MAX_VALUE));
        return area;
    }

    private static JPanel row(Component component) {
        JPanel wrap = new JPanel(new BorderLayout());
        wrap.setBackground(DropTrackerTheme.SURFACE_0);
        wrap.add(component, BorderLayout.CENTER);
        wrap.setAlignmentX(Component.LEFT_ALIGNMENT);
        wrap.setMaximumSize(new Dimension(WIDTH, Integer.MAX_VALUE));
        if (component instanceof JTextArea) {
            wrap.setPreferredSize(new Dimension(WIDTH - 24, component.getPreferredSize().height));
        }
        return wrap;
    }
}

package io.droptracker.ui.components;

import java.awt.event.WindowAdapter;
import java.awt.event.WindowEvent;

import javax.annotation.Nullable;
import javax.swing.JDialog;
import javax.swing.JFrame;

import io.droptracker.DropTrackerConfig;
import io.droptracker.api.DeathMessageApi;
import net.runelite.api.Client;

/**
 * The window around {@link DeathMessageEditor}, opened from the Home tab.
 * One at a time: a second click brings the open one forward.
 */
public final class DeathMessageDialog {

    @Nullable
    private static JDialog openDialog;

    private DeathMessageDialog() {
    }

    /** Opens the editor (or brings the open one forward). Call on the Swing thread. */
    public static void open(Client client, DropTrackerConfig config, DeathMessageApi api) {
        if (openDialog != null && openDialog.isDisplayable()) {
            openDialog.toFront();
            return;
        }
        JFrame parent = PanelElements.getParentFrame(client);
        JDialog dialog = new JDialog(parent, "DropTracker - Your death message", false);
        dialog.setDefaultCloseOperation(JDialog.DISPOSE_ON_CLOSE);

        DeathMessageEditor editor = new DeathMessageEditor(
            api, client::getAccountHash, config::lastAccountName, dialog::dispose, dialog::pack);
        dialog.setContentPane(editor);
        dialog.addWindowListener(new WindowAdapter() {
            @Override
            public void windowClosed(WindowEvent e) {
                editor.markClosed();
                if (openDialog == dialog) {
                    openDialog = null;
                }
            }
        });
        dialog.pack();
        dialog.setLocationRelativeTo(parent);
        openDialog = dialog;
        dialog.setVisible(true);
        editor.load();
    }
}

package io.droptracker.ui.components;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Component;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;

import javax.swing.Icon;

/**
 * Small symbols painted with Graphics2D instead of drawn as text.
 * <p>
 * These used to be Unicode characters. RuneLite's bundled fonts stop at U+2122,
 * so they only ever rendered by falling back to a system font — a chain that
 * does not cover them on macOS, where they came out as missing-glyph boxes.
 * Painting the shapes removes the dependency on font coverage entirely.
 * <p>
 * Symbols that Latin-1 already covers (notably {@code ×}) are left as text;
 * only shapes with no in-font equivalent live here.
 */
public final class PanelIcons {

    private PanelIcons() {
    }

    /** Tick mark, for completed / obtained state. */
    public static Icon check(Color color, int size) {
        return new ShapeIcon(size, color, (g, s, c) -> {
            g.setColor(c);
            g.setStroke(new BasicStroke(Math.max(1.6f, s * 0.16f),
                BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
            Path2D.Float p = new Path2D.Float();
            p.moveTo(s * 0.18f, s * 0.54f);
            p.lineTo(s * 0.42f, s * 0.78f);
            p.lineTo(s * 0.84f, s * 0.22f);
            g.draw(p);
        });
    }

    /** Five-pointed star; {@code filled} distinguishes pinned from unpinned. */
    public static Icon star(Color color, int size, boolean filled) {
        return new ShapeIcon(size, color, (g, s, c) -> {
            g.setColor(c);
            Path2D.Float p = starPath(s);
            if (filled) {
                g.fill(p);
            } else {
                g.setStroke(new BasicStroke(Math.max(1f, s * 0.1f),
                    BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
                g.draw(p);
            }
        });
    }

    /** Circular arrow, for refresh / retry actions. */
    public static Icon refresh(Color color, int size) {
        return new ShapeIcon(size, color, (g, s, c) -> {
            g.setColor(c);
            float inset = s * 0.18f;
            float d = s - inset * 2f;
            g.setStroke(new BasicStroke(Math.max(1.4f, s * 0.13f),
                BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
            // Open arc, with the gap where the arrowhead sits.
            g.drawArc(Math.round(inset), Math.round(inset),
                Math.round(d), Math.round(d), 55, 285);
            // Arrowhead at the open end (top-right of the arc).
            float cx = s / 2f;
            float cy = s / 2f;
            float r = d / 2f;
            double a = Math.toRadians(55);
            float hx = cx + (float) (Math.cos(a) * r);
            float hy = cy - (float) (Math.sin(a) * r);
            float h = s * 0.24f;
            Path2D.Float head = new Path2D.Float();
            head.moveTo(hx + h * 0.5f, hy - h * 0.1f);
            head.lineTo(hx - h * 0.5f, hy - h * 0.35f);
            head.lineTo(hx + h * 0.05f, hy + h * 0.6f);
            head.closePath();
            g.fill(head);
        });
    }

    /** Filled circle, for status dots. */
    public static Icon dot(Color color, int size) {
        return new ShapeIcon(size, color, (g, s, c) -> {
            g.setColor(c);
            float inset = s * 0.2f;
            g.fill(new Ellipse2D.Float(inset, inset, s - inset * 2f, s - inset * 2f));
        });
    }

    /**
     * Paints a tick directly onto an existing surface, for callers already
     * compositing an image rather than showing an {@link Icon}.
     */
    public static void paintCheck(Graphics2D g, int x, int y, int size, Color color) {
        Graphics2D g2 = (Graphics2D) g.create(x, y, size, size);
        try {
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING,
                RenderingHints.VALUE_ANTIALIAS_ON);
            g2.setColor(color);
            g2.setStroke(new BasicStroke(Math.max(1.6f, size * 0.16f),
                BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
            Path2D.Float p = new Path2D.Float();
            p.moveTo(size * 0.18f, size * 0.54f);
            p.lineTo(size * 0.42f, size * 0.78f);
            p.lineTo(size * 0.84f, size * 0.22f);
            g2.draw(p);
        } finally {
            g2.dispose();
        }
    }

    private static Path2D.Float starPath(float s) {
        Path2D.Float p = new Path2D.Float();
        float cx = s / 2f;
        float cy = s / 2f + s * 0.03f;
        float outer = s * 0.46f;
        float inner = outer * 0.42f;
        for (int i = 0; i < 10; i++) {
            double angle = Math.toRadians(-90 + i * 36);
            float r = (i % 2 == 0) ? outer : inner;
            float px = cx + (float) (Math.cos(angle) * r);
            float py = cy + (float) (Math.sin(angle) * r);
            if (i == 0) {
                p.moveTo(px, py);
            } else {
                p.lineTo(px, py);
            }
        }
        p.closePath();
        return p;
    }

    @FunctionalInterface
    private interface ShapePainter {
        void paint(Graphics2D g, float size, Color color);
    }

    /** Square icon that antialiases and hands a clean surface to its painter. */
    private static final class ShapeIcon implements Icon {
        private final int size;
        private final Color color;
        private final ShapePainter painter;

        private ShapeIcon(int size, Color color, ShapePainter painter) {
            this.size = size;
            this.color = color;
            this.painter = painter;
        }

        @Override
        public void paintIcon(Component c, Graphics g, int x, int y) {
            Graphics2D g2 = (Graphics2D) g.create(x, y, size, size);
            try {
                g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING,
                    RenderingHints.VALUE_ANTIALIAS_ON);
                g2.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL,
                    RenderingHints.VALUE_STROKE_PURE);
                painter.paint(g2, size, color);
            } finally {
                g2.dispose();
            }
        }

        @Override
        public int getIconWidth() {
            return size;
        }

        @Override
        public int getIconHeight() {
            return size;
        }
    }
}

