import org.jetbrains.annotations.VisibleForTesting;

/**
 * Captures a single frame with the widgets the user's {@link PrivacyMode} covers
 * hidden, then puts everything back.
 *
 * <p>DMs and chat messages are plain per-frame widget hides in any layout. Hiding
 * the entire chatbox is layout-dependent: in resizable modes the chatbox is an
 * overlay on the scene, so it too is a plain hide; in fixed mode the chatbox owns
 * the bottom 142px of the client, so hiding it means expanding the viewport into
 * the freed space, patching the window-frame border strips it used to cover, and
 * reasserting all of that every frame until the capture lands (widget scripts
 * re-run constantly and would revert the mutation). That machinery lives in the
 * {@link #onBeforeRender()} state machine, driven off the plugin's event bus
 * subscription.
 *
 * <p>When an interface is open inside the chatbox (a dialog, Make-X, bank
 * search), hiding the whole box would hide something the player is interacting
 * with, so the capture degrades to hiding the transcript + DMs for that shot.
 *
 * <p>Every capture in the plugin comes through here, and only one runs at a
 * time. That is a correctness requirement, not an optimisation: hiding is a flag
 * on a shared widget, so two captures overlapping meant the first one's restore
 * unhid the chat while the second was still waiting for its frame. See
 * {@link #capture(PrivacyMode, Consumer)}.
 */
@Slf4j
@Singleton
public class ScreenshotPrivacyService {

    /** Extra rendered frames to wait after hiding before capturing, so the 3D scene finishes growing. */
    private static final int SETTLE_FRAMES = 1;

    /** Give up and restore if the frame listener never fires (GPU stall, minimised client, ...). */
    private static final int MAX_HIDDEN_FRAMES = 120;

    /** Give up if the whole cycle stalls - ticks keep coming when frames do not. */
    private static final int MAX_CYCLE_TICKS = 20;

    /** Attempts one request gets before it is answered without an image. */
    private static final int MAX_ATTEMPTS = 2;

    /**
     * How long a frame already taken can stand in for a fresh request. One kill
     * commonly produces a drop submission and a collection log submission a beat
     * apart, and they are proof of the same moment - two captures would only mean
     * two rounds of hiding the chat, with the second racing the first's restore.
     * Two game ticks is long enough to pair them up and short enough that the
     * next unrelated event still gets its own frame.
     */
    private static final long REUSE_WINDOW_MS = 1200L;

    // Border sprites we synthesise to fill the window frame edges the chatbox used to cover.
    private static final int LEFT_BORDER_SPRITE_ID = -20611;
    private static final int RIGHT_BORDER_SPRITE_ID = -20612;
    private static final int CHATBOX_PARENT_WIDTH = 519;
    private static final int LEFT_BORDER_WIDTH = 4;
    private static final int RIGHT_BORDER_WIDTH = 3;
    private static final int BORDER_HEIGHT = 142;

    /*
     * The fixed viewport is 765x503. Of that, the 3D scene container is 334px tall
     * with the chatbox visible; hiding the chatbox frees the 142px it occupied and
     * lets the scene grow to 476px.
     */
    private static final int DEFAULT_VIEW_HEIGHT = 334;
    private static final int EXPANDED_VIEW_HEIGHT = 476;
    private static final int BANK_X = 12;
    private static final int BANK_Y = 2;
    private static final int SEED_VAULT_X = 6;
    private static final int SEED_VAULT_COMPONENT_ID = 41353217;

    // The view height minus BANK_Y minus 1, since there is a 1px gap at the bottom without the plugin.
    private static final int DEFAULT_VIEW_WIDGET_HEIGHT = DEFAULT_VIEW_HEIGHT - BANK_Y - 1;
    private static final int EXPANDED_VIEW_WIDGET_HEIGHT = EXPANDED_VIEW_HEIGHT - BANK_Y - 1;

    /** The fixed viewport's main container, whose static children make up the game scene area. */
    private static final Map.Entry<Integer, Integer> FIXED_MAIN = entry(net.runelite.api.widgets.InterfaceID.FIXED_VIEWPORT, 9);

    /**
     * Interfaces that live inside the chatbox. If any of these is open the chatbox
     * must stay visible, because hiding it would hide an interface the player is
     * interacting with.
     */
    private static final Set<Map.Entry<Integer, Integer>> CHATBOX_INTERFACE_WIDGETS = ImmutableSet
        .<Map.Entry<Integer, Integer>>builder()
        // 'Rub' option (S219.0) Duel rings, Slayer Rings, Burning Amulets, etc.
        .add(entry(net.runelite.api.widgets.InterfaceID.DIALOG_OPTION, 0))
        // Player dialog (S217.0) - when your player character speaks in a dialog
        .add(entry(net.runelite.api.widgets.InterfaceID.DIALOG_PLAYER, 0))
        // Sprite dialog (S193.0) - "Are you sure you want to drop..." valuable item warnings, etc.
        .add(entry(net.runelite.api.widgets.InterfaceID.DIALOG_SPRITE, 0))
        // Message box dialog (S229.0) - NPC popups with only a "Click here to continue" option.
        .add(entry(InterfaceID.MESSAGEBOX, 0))
        // Membership benefits prompt (S284.0) - "Become a Member" chatbox popup.
        .add(entry(InterfaceID.MEMBERSHIP_BENEFITS_PROMPT, 0))
        // Skill multi-choice dialog (S270.0) - "How many would you like to..." (cutting gems, etc.)
        .add(entry(InterfaceID.SKILLMULTI, 0))
        // Bank search container
        .add(entry(net.runelite.api.widgets.InterfaceID.CHATBOX, 42))
        // Catch-all layer we recurse through: wrong PIN popup, NPC dialog, Make-X, etc.
        .add(entry(net.runelite.api.widgets.InterfaceID.CHATBOX, 566))
        .add(entry(net.runelite.api.widgets.InterfaceID.CHATBOX, 43)) // GE search
        .add(entry(InterfaceID.CHAT_LEFT, 0))
        .add(entry(InterfaceID.CHATBOX, 48)) // mes layer scrollarea
        .build();

    /** Containers that overlap the chatbox area and must be resized along with the viewport. */
    private static final Set<Map.Entry<Integer, Integer>> TO_CONTRACT_WIDGETS = ImmutableSet
        .<Map.Entry<Integer, Integer>>builder()
        .add(entry(ComponentID.BANK_CONTAINER, 0))
        .add(entry(net.runelite.api.widgets.InterfaceID.SEED_VAULT, 1))
        .build();

    private enum State {
        IDLE,
        HIDE_PENDING,
        HIDDEN,
        RESTORE_PENDING
    }

    /**
     * What a capture has to keep out of the frame, independent of how it gets
     * there. {@code transcript} implies nothing about {@code chatbox} but the
     * reverse holds, so the constructor canonicalises it: coverage comparisons
     * between two plans are then a plain componentwise implication.
     */
    @VisibleForTesting
    static final class CapturePlan {

        static final CapturePlan NOTHING = new CapturePlan(false, false, false, false);

        final boolean dms;
        final boolean transcript;
        final boolean chatbox;
        /** Fixed mode only: hide the chatbox by growing the game view into its space. */
        final boolean expandViewport;

        CapturePlan(boolean dms, boolean transcript, boolean chatbox, boolean expandViewport) {
            this.dms = dms;
            this.transcript = transcript || chatbox;
            this.chatbox = chatbox;
            this.expandViewport = expandViewport;
        }

        /** Whether a frame captured under this plan is also acceptable for {@code other}. */
        boolean covers(CapturePlan other) {
            return (dms || !other.dms)
                && (transcript || !other.transcript)
                && (chatbox || !other.chatbox);
        }
    }

    /** One caller waiting for a frame. Client-thread confined. */
    private static final class Request {

        private final PrivacyMode mode;
        private final Consumer<BufferedImage> consumer;
        private int attempts;

        private Request(PrivacyMode mode, Consumer<BufferedImage> consumer) {
            this.mode = mode;
            this.consumer = consumer;
        }
    }

    private final Client client;
    private final ClientThread clientThread;
    private final DrawManager drawManager;
    private final SpriteManager spriteManager;

    /*
     * Everything below is client-thread confined: capture() marshals onto it, and
     * onBeforeRender / onGameTick / the frame callback all run there. No locking.
     */
    private State state = State.IDLE;

    /** Bumped per capture so a late frame callback from an aborted cycle can be ignored. */
    private int cycleId;
    private int framesHidden;
    private int cycleStartTick;
    private boolean captureRequested;
    private boolean widgetsMutated;
    private boolean bordersDrawn;

    /** What the in-flight cycle hides; null while {@link State#IDLE}. */
    private CapturePlan activePlan;

    /** Everyone riding the in-flight cycle's frame. Client-thread confined. */
    private final List<Request> pending = new ArrayList<>();

    /** Requests that need more hidden than the in-flight cycle hides. */
    private final List<Request> queued = new ArrayList<>();

    /** Widgets this service hid, so a restore puts back exactly those. */
    private final List<Widget> hiddenByUs = new ArrayList<>();

    private BufferedImage lastImage;
    private CapturePlan lastImagePlan;
    private long lastImageAt;

    private boolean borderSpritesLoaded;
    private SpritePixels lastWindowFrameLeftSprite;
    private SpritePixels lastSidePanelLeftUpperSprite;

    @Inject
    public ScreenshotPrivacyService(
        Client client,
        ClientThread clientThread,
        DrawManager drawManager,
        SpriteManager spriteManager
    ) {
        this.client = client;
        this.clientThread = clientThread;
        this.drawManager = drawManager;
        this.spriteManager = spriteManager;
    }

    private static Map.Entry<Integer, Integer> entry(int group, int child) {
        return new AbstractMap.SimpleEntry<>(group, child);
    }

    /**
     * Captures a frame with the given privacy mode applied and hands it to
     * {@code consumer}. Callable from any thread; the consumer runs on the client
     * thread, so keep heavy work off it.
     *
     * <p>Captures are single-flight. One kill can produce several submissions at
     * once - a drop over the screenshot threshold, the collection log slot it
     * filled, a personal best - and each of those asks for proof. They share one
     * frame: requests arriving while a capture is being set up ride it, and a
     * request arriving just after one completes is answered from
     * {@link #REUSE_WINDOW_MS the frame just taken} rather than making the client
     * draw, hide and restore all over again. Two overlapping captures used to
     * unhide each other's widgets mid-flight, which is how a screenshot with the
     * private chat still in it got submitted.
     *
     * <p>The consumer is passed {@code null} when no frame could be captured (the
     * client stopped rendering, or the layout kept moving under the capture). It
     * is never passed a frame with the privacy mode unapplied.
     */
    public void capture(PrivacyMode mode, Consumer<BufferedImage> consumer) {
        clientThread.invoke(() -> accept(new Request(mode, consumer)));
    }

    /** Restores any in-flight mutation; called from the plugin's shutDown. */
    public void shutDown() {
        clientThread.invoke(() -> {
            cycleId++;
            state = State.IDLE;
            activePlan = null;
            captureRequested = false;
            forgetLastImage();
            restoreWidgets();
            clearBorderSprites();

            // Answer anything still waiting rather than dropping it: the plugin
            // is going away, but the submission it belongs to can still be sent
            // without proof.
            final List<Request> waiting = new ArrayList<>(pending);
            waiting.addAll(queued);
            pending.clear();
            queued.clear();
            for (final Request request : waiting) {
                deliver(request, null);
            }
        });
    }

    /**
     * Watchdog, driven off the game tick because it keeps running when rendering
     * does not. A cycle that never sees another frame would otherwise hold every
     * later capture behind it forever.
     */
    public void onGameTick() {
        if (state != State.IDLE) {
            if (client.getTickCount() - cycleStartTick > MAX_CYCLE_TICKS) {
                abort("no rendered frame within " + MAX_CYCLE_TICKS + " ticks");
            }
            return;
        }

        // Nothing is holding a full-size frame open once it is too old to reuse.
        if (lastImage != null && elapsedSinceLastImage() > REUSE_WINDOW_MS) {
            forgetLastImage();
        }
        drainQueued();
    }

    private void accept(Request request) {
        final CapturePlan plan = planFor(request.mode);

        // The frame taken moments ago is the same moment this request is asking
        // about, and it already hides at least as much: reuse it.
        if (lastImage != null && lastImagePlan != null && lastImagePlan.covers(plan)
            && elapsedSinceLastImage() <= REUSE_WINDOW_MS) {
            deliver(request, lastImage);
            return;
        }

        if (state != State.IDLE) {
            if (activePlan.covers(plan)) {
                pending.add(request);
            } else {
                // Wants more hidden than the frame being set up; wait for the next cycle.
                queued.add(request);
            }
            return;
        }

        startCycle(plan, request);
    }

    private void startCycle(CapturePlan plan, Request first) {
        cycleId++;
        activePlan = plan;
        framesHidden = 0;
        captureRequested = false;
        cycleStartTick = client.getTickCount();
        hiddenByUs.clear();
        pending.add(first);
        // Nothing is hidden yet: the hide is applied from onBeforeRender so it
        // lands in the very frame that gets captured, rather than racing a draw
        // that may already be underway.
        state = State.HIDE_PENDING;
    }

    /**
     * Turns the player's configured mode into the set of things this capture must
     * keep out of the frame, given the layout in front of us right now.
     */
    private CapturePlan planFor(PrivacyMode mode) {
        if (mode == null || !mode.hidesDms()) {
            return CapturePlan.NOTHING;
        }

        // "Hide DMs" has to mean the DMs, wherever the client draws them. With
        // split private chat off there is no PM overlay at all and private
        // messages are ordinary transcript lines, so the transcript goes too -
        // otherwise the setting silently does nothing for those players.
        final boolean hideTranscript = mode.hidesMessages() || dmsAreInTranscript();

        if (!mode.hidesChatbox()) {
            return new CapturePlan(true, hideTranscript, false, false);
        }

        // Hiding the whole chatbox. With an interface open inside it (a dialog,
        // Make-X, bank search) that would hide something the player is using, so
        // the capture degrades to the transcript + DMs.
        if (isChatboxInterfaceOpen()) {
            return new CapturePlan(true, true, false, false);
        }

        // Resizable layouts draw the chatbox as an overlay on the scene, so a
        // plain hide is enough. Fixed mode needs the viewport surgery, and only
        // while logged in - a plain hide there would leave a black hole.
        if (client.isResized()) {
            return new CapturePlan(true, true, true, false);
        }
        if (client.getGameState() != GameState.LOGGED_IN) {
            return new CapturePlan(true, true, false, false);
        }
        return new CapturePlan(true, true, true, true);
    }

    /**
     * Whether private messages are rendered as ordinary chat transcript lines.
     * The split private chat overlay is its own interface: when the option is off
     * the client never loads it, so an absent widget is the signal that DMs are
     * inline. (With split chat on, the transcript still lists DMs under its
     * Private tab - "Hide messages + DMs" is the mode that covers that.)
     */
    private boolean dmsAreInTranscript() {
        return client.getWidget(InterfaceID.PmChat.CONTAINER) == null;
    }

    private long elapsedSinceLastImage() {
        return System.currentTimeMillis() - lastImageAt;
    }

    private void forgetLastImage() {
        lastImage = null;
        lastImagePlan = null;
        lastImageAt = 0L;
    }

    // region capture cycle

    public void onBeforeRender() {
        if (state == State.IDLE) {
            drainQueued();
            return;
        }

        // The player resized or logged out mid-cycle; bail out rather than fight
        // the layout. Only the viewport surgery cares - a plain widget hide works
        // in any layout.
        if (activePlan.expandViewport
            && (client.isResized() || client.getGameState() != GameState.LOGGED_IN)) {
            abort("client left fixed mode mid-capture");
            return;
        }

        switch (state) {
            case HIDE_PENDING:
                applyPlan(true);
                state = State.HIDDEN;
                maybeRequestFrame();
                framesHidden++;
                break;

            case HIDDEN:
                // Widget scripts re-run constantly, so the mutation has to be reasserted per frame.
                applyPlan(false);
                maybeRequestFrame();
                framesHidden++;

                if (framesHidden > MAX_HIDDEN_FRAMES) {
                    abort("timed out after " + MAX_HIDDEN_FRAMES + " frames");
                }
                break;

            case RESTORE_PENDING:
                restoreWidgets();
                finishCycle();
                break;

            default:
                break;
        }
    }

    /** Hides everything the active plan covers; safe to call every frame. */
    private void applyPlan(boolean transition) {
        if (activePlan.dms) {
            hideIfVisible(InterfaceID.PmChat.CONTAINER);
        }

        if (activePlan.chatbox) {
            if (activePlan.expandViewport) {
                expandOverChatbox(transition);
            } else {
                hideIfVisible(InterfaceID.Chatbox.UNIVERSE);
            }
        } else if (activePlan.transcript) {
            hideIfVisible(InterfaceID.Chatbox.CHATDISPLAY);
        }
    }

    /**
     * Hides one widget and remembers that we were the ones who did it, so the
     * restore puts back exactly what it took away - a widget the game itself had
     * hidden (a dialog replacing the transcript, split chat off) is left alone.
     * Already hidden by us means nothing to do; hidden again by a script that
     * re-ran means it comes back visible and gets re-hidden here.
     */
    private void hideIfVisible(@Component int componentId) {
        final Widget widget = client.getWidget(componentId);
        if (widget == null || widget.isSelfHidden()) {
            return;
        }

        widget.setHidden(true);
        for (final Widget alreadyTracked : hiddenByUs) {
            if (alreadyTracked == widget) {
                return;
            }
        }
        hiddenByUs.add(widget);
    }

    private void maybeRequestFrame() {
        // Only the viewport expansion needs a settling frame: the 3D scene has to
        // finish growing into the freed space before the shot is worth taking.
        final int settleFrames = activePlan.expandViewport ? SETTLE_FRAMES : 0;
        if (captureRequested || framesHidden < settleFrames) {
            return;
        }

        captureRequested = true;
        final int requestCycle = cycleId;
        drawManager.requestNextFrameListener(image -> onFrameReady(requestCycle, image));
    }

    /** Called on the client thread once the hidden frame has finished drawing. */
    private void onFrameReady(int requestCycle, Image image) {
        if (requestCycle != cycleId || state != State.HIDDEN) {
            // Stale callback from a cycle we already gave up on.
            return;
        }

        final BufferedImage captured = toBufferedImage(image);
        lastImage = captured;
        lastImagePlan = activePlan;
        lastImageAt = System.currentTimeMillis();

        // Detach this cycle's waiters before anything below can start the next
        // one, or a queued request that wanted more hidden than this frame hides
        // would be handed this frame anyway.
        final List<Request> waiting = new ArrayList<>(pending);
        pending.clear();

        state = State.RESTORE_PENDING;
        if (!activePlan.expandViewport) {
            // A plain widget hide can go back immediately now the frame is drawn;
            // only the viewport surgery has to unwind on a render pass.
            restoreWidgets();
            finishCycle();
        }

        for (final Request request : waiting) {
            deliver(request, captured);
        }
    }

    private void finishCycle() {
        state = State.IDLE;
        activePlan = null;
        captureRequested = false;
        drainQueued();
    }

    private void deliver(Request request, BufferedImage image) {
        try {
            request.consumer.accept(image);
        } catch (Exception e) {
            log.warn("screenshot consumer failed", e);
        }
    }

    /** Starts a cycle for anything that could not ride the last one. */
    private void drainQueued() {
        if (queued.isEmpty() || state != State.IDLE) {
            return;
        }

        final List<Request> batch = new ArrayList<>(queued);
        queued.clear();
        for (final Request request : batch) {
            accept(request);
        }
    }

    private void abort(String reason) {
        log.debug("screenshot privacy capture aborted: {}", reason);
        cycleId++;
        state = State.IDLE;
        activePlan = null;
        captureRequested = false;
        restoreWidgets();

        // Give each waiting request one more go with a freshly computed plan; the
        // client may simply have left fixed mode. Anything already retried is
        // answered with no image rather than left hanging - a submission without
        // proof beats a submission that never arrives, and it is never the
        // unhidden frame.
        final List<Request> waiting = new ArrayList<>(pending);
        pending.clear();
        for (final Request request : waiting) {
            if (++request.attempts >= MAX_ATTEMPTS) {
                deliver(request, null);
            } else {
                queued.add(request);
            }
        }

        drainQueued();
    }

    // endregion

    // region fixed-mode widget mutation (derived from Fixed Mode Hide Chat)

    /**
     * Fixed mode only: grow the game view into the 142px the chatbox occupies and
     * hide the frame around it. The DM/transcript hiding this rides on top of is
     * applied by {@link #applyPlan(boolean)}.
     */
    private void expandOverChatbox(boolean transition) {
        widgetsMutated = true;

        setViewSizeTo(DEFAULT_VIEW_HEIGHT, EXPANDED_VIEW_HEIGHT);
        setWidgetsSizeTo(DEFAULT_VIEW_WIDGET_HEIGHT, EXPANDED_VIEW_WIDGET_HEIGHT);
        keepContainersOnScreen(transition);

        hideIfVisible(ComponentID.CHATBOX_FRAME);

        drawChatboxBorders();
    }

    private void restoreWidgets() {
        for (final Widget widget : hiddenByUs) {
            widget.setHidden(false);
        }
        hiddenByUs.clear();

        if (!widgetsMutated || client.isResized()) {
            widgetsMutated = false;
            return;
        }

        widgetsMutated = false;

        setViewSizeTo(EXPANDED_VIEW_HEIGHT, DEFAULT_VIEW_HEIGHT);
        setWidgetsSizeTo(EXPANDED_VIEW_WIDGET_HEIGHT, DEFAULT_VIEW_WIDGET_HEIGHT);
        keepContainersOnScreen(true);
        removeChatboxBorders();
    }

    /**
     * The bank and seed vault containers drift off screen when the viewport
     * resizes under them, so their position is pinned explicitly on every frame
     * we touch the layout.
     */
    private void keepContainersOnScreen(boolean transition) {
        final Widget bankWidget = client.getWidget(ComponentID.BANK_CONTAINER);
        if (bankWidget != null && !bankWidget.isSelfHidden()) {
            // Re-run [clientscript,bankmain_init] so the tag tabs re-extend to the
            // new height. Only on the frames where the layout actually changes -
            // running it every frame tanks performance.
            if (transition) {
                client.createScriptEventBuilder(bankWidget.getOnLoadListener())
                    .setSource(bankWidget)
                    .build()
                    .run();
            }

            pinWidget(bankWidget, BANK_X);
        }

        final Widget seedVaultWidget = client.getWidget(SEED_VAULT_COMPONENT_ID);
        if (seedVaultWidget != null && !seedVaultWidget.isSelfHidden()) {
            pinWidget(seedVaultWidget, SEED_VAULT_X);
        }
    }

    private static void pinWidget(Widget widget, int x) {
        widget.setOriginalX(x);
        widget.setOriginalY(BANK_Y);
        widget.setXPositionMode(WidgetPositionMode.ABSOLUTE_LEFT);
        widget.setYPositionMode(WidgetPositionMode.ABSOLUTE_TOP);
        widget.revalidateScroll();
    }

    private static void setWidgetHeight(Widget widget, int height) {
        widget.setOriginalHeight(height);
        widget.setHeightMode(WidgetSizeMode.ABSOLUTE);
        widget.revalidateScroll();
    }

    private static void changeWidgetHeight(int originalHeight, int newHeight, Widget widget) {
        if (widget.getHeight() != originalHeight) {
            return;
        }

        setWidgetHeight(widget, newHeight);

        final Widget[] nestedChildren = widget.getNestedChildren();
        if (nestedChildren != null) {
            for (final Widget nestedChild : nestedChildren) {
                if (nestedChild != null && nestedChild.getHeight() == originalHeight) {
                    setWidgetHeight(nestedChild, newHeight);
                }
            }
        }

        final Widget[] dynamicChildren = widget.getDynamicChildren();
        if (dynamicChildren != null) {
            for (final Widget child : dynamicChildren) {
                if (child != null && child.getHeight() == originalHeight) {
                    setWidgetHeight(child, newHeight);
                }
            }
        }
    }

    private void setWidgetsSizeTo(int originalHeight, int newHeight) {
        for (final Map.Entry<Integer, Integer> entry : TO_CONTRACT_WIDGETS) {
            final Widget widget = entry.getValue() == 0
                ? client.getWidget(entry.getKey())
                : client.getWidget(entry.getKey(), entry.getValue());

            if (widget != null && !widget.isSelfHidden()) {
                changeWidgetHeight(originalHeight, newHeight, widget);
            }
        }
    }

    private void setViewSizeTo(int originalHeight, int newHeight) {
        final Widget viewport = client.getWidget(InterfaceID.Toplevel.MAIN);
        if (viewport != null) {
            setWidgetHeight(viewport, newHeight);
        }

        final Widget fixedMain = client.getWidget(FIXED_MAIN.getKey(), FIXED_MAIN.getValue());
        if (fixedMain == null || fixedMain.getHeight() != originalHeight) {
            return;
        }

        setWidgetHeight(fixedMain, newHeight);

        final Widget[] staticChildren = fixedMain.getStaticChildren();
        if (staticChildren == null) {
            return;
        }

        for (final Widget child : staticChildren) {
            if (child != null) {
                changeWidgetHeight(originalHeight, newHeight, child);
            }
        }
    }

    // endregion

    // region chatbox interface detection

    /**
     * True when something the player is interacting with lives inside the
     * chatbox - a dialog, the bank search, Make-X, a fairy ring code entry.
     * Hiding the chatbox would hide it too.
     */
    private boolean isChatboxInterfaceOpen() {
        final Widget fairyRingSearch = client.getWidget(net.runelite.api.widgets.InterfaceID.CHATBOX, 38);
        if (fairyRingSearch != null) {
            final Widget[] children = fairyRingSearch.getDynamicChildren();
            if (children != null && children.length > 0 && children[0] != null
                && children[0].getText() != null && children[0].getText().contains("fairy")) {
                return true;
            }
        }

        for (final Map.Entry<Integer, Integer> entry : CHATBOX_INTERFACE_WIDGETS) {
            final Widget widget = client.getWidget(entry.getKey(), entry.getValue());
            if (widget == null || widget.isSelfHidden()) {
                continue;
            }

            final Widget[] staticChildren = widget.getStaticChildren();
            final Widget[] nestedChildren = widget.getNestedChildren();

            final boolean found;
            if (staticChildren != null && staticChildren.length > 0) {
                found = anyVisible(staticChildren);
            } else if (nestedChildren != null && nestedChildren.length > 0) {
                found = anyVisible(nestedChildren);
            } else {
                found = isVisible(widget);
            }

            if (found) {
                return true;
            }
        }

        return false;
    }

    private static boolean anyVisible(Widget[] widgets) {
        return Arrays.stream(widgets).anyMatch(ScreenshotPrivacyService::isVisible);
    }

    private static boolean isVisible(Widget widget) {
        return widget != null && !widget.isSelfHidden() && !widget.isHidden();
    }

    // endregion

    // region chatbox border sprites

    /**
     * The chatbox covers 4px of window frame on the left and 3px on the right.
     * Once it is hidden those strips are empty, so the equivalent slices are
     * cropped out of the client's own frame sprites (respecting resource packs)
     * and drawn as children of the chatbox parent.
     */
    private void drawChatboxBorders() {
        final Widget chatbox = client.getWidget(ComponentID.CHATBOX_PARENT);
        if (chatbox == null || !updateBorderSprites() || chatbox.getChild(1) != null) {
            return;
        }

        final Widget leftBorder = chatbox.createChild(-1, WidgetType.GRAPHIC);
        leftBorder.setSpriteId(LEFT_BORDER_SPRITE_ID);
        leftBorder.setOriginalWidth(LEFT_BORDER_WIDTH);
        leftBorder.setOriginalHeight(BORDER_HEIGHT);
        leftBorder.setOriginalX(0);
        leftBorder.setOriginalY(0);
        leftBorder.setHidden(false);
        leftBorder.revalidate();

        final Widget rightBorder = chatbox.createChild(-1, WidgetType.GRAPHIC);
        rightBorder.setSpriteId(RIGHT_BORDER_SPRITE_ID);
        rightBorder.setOriginalWidth(RIGHT_BORDER_WIDTH);
        rightBorder.setOriginalHeight(BORDER_HEIGHT);
        rightBorder.setOriginalX(CHATBOX_PARENT_WIDTH - RIGHT_BORDER_WIDTH);
        rightBorder.setOriginalY(0);
        rightBorder.setHidden(false);
        rightBorder.revalidate();

        bordersDrawn = true;
    }

    private void removeChatboxBorders() {
        if (!bordersDrawn) {
            return;
        }

        bordersDrawn = false;

        final Widget chatbox = client.getWidget(ComponentID.CHATBOX_PARENT);
        if (chatbox != null && chatbox.getChild(1) != null) {
            chatbox.deleteAllChildren();
        }
    }

    private boolean updateBorderSprites() {
        final SpritePixels windowFrameLeftSprite = client.getSpriteOverrides().get(SpriteID.BACKLEFT1);
        final SpritePixels sidePanelLeftUpperSprite = client.getSpriteOverrides().get(SpriteID.SIDE_BACKGROUND_LEFT1);

        if (borderSpritesLoaded
            && windowFrameLeftSprite == lastWindowFrameLeftSprite
            && sidePanelLeftUpperSprite == lastSidePanelLeftUpperSprite) {
            return true;
        }

        final BufferedImage windowFrameLeft = windowFrameLeftSprite != null
            ? windowFrameLeftSprite.toBufferedImage()
            : spriteManager.getSprite(SpriteID.BACKLEFT1, 0);
        final BufferedImage sidePanelLeftUpper = sidePanelLeftUpperSprite != null
            ? sidePanelLeftUpperSprite.toBufferedImage()
            : spriteManager.getSprite(SpriteID.SIDE_BACKGROUND_LEFT1, 0);

        if (windowFrameLeft == null
            || windowFrameLeft.getWidth() < LEFT_BORDER_WIDTH
            || windowFrameLeft.getHeight() <= 0
            || sidePanelLeftUpper == null
            || sidePanelLeftUpper.getWidth() < RIGHT_BORDER_WIDTH
            || sidePanelLeftUpper.getHeight() <= 0) {
            // SpriteManager loads asynchronously; try again next frame.
            return false;
        }

        final int leftSourceY = Math.max(0, windowFrameLeft.getHeight() - BORDER_HEIGHT);
        final BufferedImage leftBorder = flipVertically(cropSprite(windowFrameLeft, leftSourceY, LEFT_BORDER_WIDTH));
        final BufferedImage rightBorder = cropSprite(sidePanelLeftUpper, 0, RIGHT_BORDER_WIDTH);

        client.getSpriteOverrides().put(LEFT_BORDER_SPRITE_ID, ImageUtil.getImageSpritePixels(leftBorder, client));
        client.getSpriteOverrides().put(RIGHT_BORDER_SPRITE_ID, ImageUtil.getImageSpritePixels(rightBorder, client));

        lastWindowFrameLeftSprite = windowFrameLeftSprite;
        lastSidePanelLeftUpperSprite = sidePanelLeftUpperSprite;
        borderSpritesLoaded = true;
        client.getWidgetSpriteCache().reset();
        return true;
    }

    private void clearBorderSprites() {
        client.getSpriteOverrides().remove(LEFT_BORDER_SPRITE_ID);
        client.getSpriteOverrides().remove(RIGHT_BORDER_SPRITE_ID);
        borderSpritesLoaded = false;
        lastWindowFrameLeftSprite = null;
        lastSidePanelLeftUpperSprite = null;
        client.getWidgetSpriteCache().reset();
    }

    private static BufferedImage cropSprite(BufferedImage source, int sourceY, int width) {
        final int sourceHeight = Math.min(BORDER_HEIGHT, source.getHeight() - sourceY);
        final BufferedImage cropped = new BufferedImage(width, BORDER_HEIGHT, BufferedImage.TYPE_INT_ARGB);
        final Graphics2D graphics = cropped.createGraphics();
        graphics.drawImage(source, 0, 0, width, BORDER_HEIGHT, 0, sourceY, width, sourceY + sourceHeight, null);
        graphics.dispose();
        return cropped;
    }

    private static BufferedImage flipVertically(BufferedImage source) {
        final BufferedImage flipped = new BufferedImage(source.getWidth(), source.getHeight(), BufferedImage.TYPE_INT_ARGB);
        final Graphics2D graphics = flipped.createGraphics();
        graphics.drawImage(source, 0, source.getHeight(), source.getWidth(), -source.getHeight(), null);
        graphics.dispose();
        return flipped;
    }

    // endregion

    private static BufferedImage toBufferedImage(Image image) {
        if (image instanceof BufferedImage) {
            return (BufferedImage) image;
        }

        final BufferedImage copy = new BufferedImage(
            image.getWidth(null), image.getHeight(null), BufferedImage.TYPE_INT_ARGB);
        final Graphics2D graphics = copy.createGraphics();
        graphics.drawImage(image, 0, 0, null);
        graphics.dispose();
        return copy;
    }
}

package io.droptracker.service;

import com.google.inject.Inject;
import com.google.inject.Singleton;
import io.droptracker.DropTrackerConfig;
import io.droptracker.api.DropTrackerApi;
import io.droptracker.models.TeamIndicatorStyle;
import io.droptracker.models.api.EventRoster;
import io.droptracker.models.api.EventState;
import io.droptracker.models.api.Manifest;
import io.droptracker.util.ChatMessageUtil;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.IndexedSprite;
import net.runelite.api.MessageNode;
import net.runelite.api.events.ScriptCallbackEvent;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.ui.FontManager;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.Text;
import org.jetbrains.annotations.VisibleForTesting;

import javax.annotation.Nullable;
import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Badges clan-chat lines from players in the same live event with their team
 * (suggestion #150).
 *
 * The roster comes from the API, which is the whole difference from the plugin
 * this was modelled on: nobody types names into a panel, so teams stay right
 * when an admin moves someone, and a clanmate who has never opened the site is
 * still badged.
 *
 * <p>The badge is applied while a chat line is being <em>drawn</em>, through
 * the chat builder's {@code chatMessageBuilding} callback, and is never written
 * back to the {@link MessageNode}. The first version did write it back, and
 * that broke private messages:
 * <ul>
 * <li>{@code MessageNode.setName} changes more than the text. RuneLite also
 * rebuilds the node's sender identity from whatever follows the last '>', so a
 * name ending in {@code </col>} left the line with an empty sender. The game
 * decides "is this from a friend?" from that identity, so with Private set to
 * Friends a teammate's PMs vanished, and with Clan set to Friends so did their
 * clan lines.</li>
 * <li>The walk over {@code client.getMessages()} that badged lines already on
 * screen reached every chat type, DMs included, which is how names in the PM
 * pane got recoloured.</li>
 * </ul>
 * Now each line's type is checked before it is badged. The node keeps the name
 * the server sent, other plugins read it unchanged, and switching the feature
 * off clears every badge on the next redraw.
 *
 * <p>Whatever the badge adds must disappear under the game's
 * {@code removetags}. The chat scripts strip tags from the drawn name to find
 * the clan rank icon and to target Report, Kick, Ban, Add friend and Message.
 * {@code <img>} and {@code <col>} strip cleanly. Literal text such as "[RR]"
 * does not, so the tag is drawn into the team's sprite rather than typed into
 * the name.
 *
 * <p>Two things keep it cheap. The roster is fetched only when the
 * {@code roster_version} on the /event_state poll changes. And the mod-icon
 * slots are claimed once per client lifetime and refilled in place, because
 * growing that array repeatedly leaks slots and stomps on icons other plugins
 * appended after us.
 */
@Slf4j
@Singleton
public class EventTeamIndicatorService {

    /**
     * Sprite slots reserved for team badges, one per team. Sized to the
     * server's cap on teams per roster ({@code ROSTER_TEAMS_LIMIT}), so every
     * team it sends can have one. A team that still ends up without a slot
     * falls back to a coloured name.
     */
    static final int MAX_TEAM_ICONS = 32;

    /** Orb sprite size, matching the game's own chat icons. */
    private static final int ORB_SIZE = 12;

    /** Columns between the orb and the tag when a badge shows both. */
    private static final int PIECE_GAP = 2;

    /** The chat builders' per-line callback (ChatBuilder and ChatSplitBuilder). */
    private static final String CHAT_MESSAGE_BUILDING = "chatMessageBuilding";

    /**
     * Tag text for a team with no colour of its own. The server always sends
     * an orb colour, so this is a backstop, picked to read on both the opaque
     * and the transparent chatbox.
     */
    private static final Color FALLBACK_TAG_COLOR = new Color(0x9f9f9f);

    /** A colour tag, open or close — a coloured name replaces any already there. */
    private static final Pattern COLOR_TAG = Pattern.compile("</?col(=[0-9a-fA-F]*)?>");

    /**
     * A moderator crown leading the name. The chat builder offers "Crown Info"
     * only when the name starts with one, so a badge goes after it.
     */
    private static final Pattern LEADING_CROWN = Pattern.compile("^<img=[01]>");

    /** Runs of whitespace, folded to one — see {@link #normalize(String)}. */
    private static final Pattern WHITESPACE = Pattern.compile("\\s+");

    private final Client client;
    private final ClientThread clientThread;
    private final EventBus eventBus;
    private final DropTrackerConfig config;
    private final DropTrackerApi api;
    private final ManifestService manifestService;
    private final EventNotificationService eventNotificationService;
    private final ScheduledExecutorService executor;

    /**
     * Normalized RSN to badge, replaced wholesale, never mutated in place: the
     * chat builder reads it on the client thread while the executor builds the
     * next one.
     */
    private volatile Map<String, TeamBadge> badgesByName = Collections.emptyMap();

    /** The loaded roster's teams in roster order, kept to redraw their sprites. */
    private volatile List<TeamBadge> loadedTeams = Collections.emptyList();

    /** Roster version currently reflected in {@link #badgesByName}. */
    @Nullable
    private volatile String loadedRosterVersion;

    /** Event the loaded roster belongs to; 0 when nothing is loaded. */
    private volatile int loadedEventId;

    /**
     * Bumped by every {@link #clear()}. A roster fetched before a clear must
     * not be installed after it, or an event that just ended would put its
     * badges back.
     */
    private final AtomicInteger generation = new AtomicInteger();

    /** First slot of our reserved block, or -1 before it is claimed. Client thread. */
    private int iconOffset = -1;

    /** team id -> sprite slot, valid only while {@link #iconOffset} >= 0. */
    private volatile Map<Integer, Integer> slotByTeam = Collections.emptyMap();

    private final Runnable stateListener = this::onEventStateUpdated;

    @Inject
    public EventTeamIndicatorService(Client client,
                                     ClientThread clientThread,
                                     EventBus eventBus,
                                     DropTrackerConfig config,
                                     DropTrackerApi api,
                                     ManifestService manifestService,
                                     EventNotificationService eventNotificationService,
                                     ScheduledExecutorService executor) {
        this.client = client;
        this.clientThread = clientThread;
        this.eventBus = eventBus;
        this.config = config;
        this.api = api;
        this.manifestService = manifestService;
        this.eventNotificationService = eventNotificationService;
        this.executor = executor;
    }

    public void startUp() {
        eventBus.register(this);
        eventNotificationService.addStateUpdatedListener(stateListener);
    }

    public void shutDown() {
        eventBus.unregister(this);
        eventNotificationService.removeStateUpdatedListener(stateListener);
        clear();
        slotByTeam = Collections.emptyMap();
    }

    /**
     * The client rebuilds its mod-icon array on a restart, so the slot block is
     * claimed fresh each time. Call from GameState STARTING (reset) and
     * LOGIN_SCREEN (claim).
     */
    public void onGameStateChanged(GameState state) {
        if (state == GameState.STARTING) {
            iconOffset = -1;
            slotByTeam = Collections.emptyMap();
        } else if (state == GameState.LOGIN_SCREEN && iconOffset < 0) {
            claimIconSlots();
            // A roster held across the restart needs its sprites again.
            List<TeamBadge> teams = loadedTeams;
            if (!teams.isEmpty()) {
                assignIconSlots(teams, config.eventTeamIndicators());
            }
        }
    }

    /** True when the feature can badge anything at all right now. */
    private boolean active() {
        if (!config.useApi() || config.eventTeamIndicators() == TeamIndicatorStyle.OFF) {
            return false;
        }
        Manifest manifest = manifestService.getManifest();
        // A manifest we could not read leaves the feature on: the switch exists
        // to turn it off deliberately, not to fail closed on a fetch error.
        return manifest == null || manifest.getTeamIndicators().isEnabled();
    }

    /**
     * Fresh /event_state landed: refetch the roster if the event we are
     * badging, or its roster, changed. Runs off-EDT on the service's own
     * callback thread, so the fetch is handed to the executor.
     */
    private void onEventStateUpdated() {
        if (!active()) {
            if (!badgesByName.isEmpty()) {
                clear();
            }
            return;
        }
        EventState.Entry entry = eventNotificationService.hudEntry();
        if (entry == null || entry.getEvent() == null) {
            if (!badgesByName.isEmpty()) {
                clear();
            }
            return;
        }
        // A player can be in several live events at once, and a clanmate can be
        // on different teams in two of them. Resolve with the same pinned-event
        // order the HUD uses, so the badge and the HUD never disagree.
        int eventId = entry.getEvent().getId();
        String version = entry.getRosterVersion();
        if (version == null) {
            // Server predates the stamp: no badges rather than a roster we
            // would have no way to know had gone stale.
            clear();
            return;
        }
        if (eventId == loadedEventId && version.equals(loadedRosterVersion)) {
            return;
        }
        final int fetchGeneration = generation.get();
        executor.execute(() -> loadRoster(eventId, version, fetchGeneration));
    }

    private void loadRoster(int eventId, String version, int fetchGeneration) {
        String playerName = client.getLocalPlayer() != null
            ? client.getLocalPlayer().getName() : null;
        long accountHash = client.getAccountHash();
        if (playerName == null || accountHash == -1L) {
            return;
        }
        EventRoster roster = api.fetchEventRoster(playerName, accountHash);
        if (roster == null || roster.getEvents() == null) {
            return;
        }
        EventRoster.Entry entry = null;
        for (EventRoster.Entry candidate : roster.getEvents()) {
            if (candidate.getEventId() == eventId) {
                entry = candidate;
                break;
            }
        }
        if (entry == null || entry.getTeams() == null || entry.getMembers() == null) {
            clear();
            return;
        }

        Map<Integer, TeamBadge> badgeByTeam = new HashMap<>();
        List<TeamBadge> teams = new ArrayList<>();
        for (EventRoster.Team team : entry.getTeams()) {
            TeamBadge badge = new TeamBadge(team.getId(), team.getShortTag(),
                colorOf(team.getOrbColor()), colorOf(team.getColor()));
            badgeByTeam.put(team.getId(), badge);
            teams.add(badge);
        }
        Map<String, TeamBadge> next = new HashMap<>();
        for (Map.Entry<String, List<String>> row : entry.getMembers().entrySet()) {
            Integer teamId = parseTeamId(row.getKey());
            TeamBadge badge = teamId == null ? null : badgeByTeam.get(teamId);
            if (badge == null || row.getValue() == null) {
                continue;
            }
            for (String name : row.getValue()) {
                // Server-normalized already; normalize again so one changed
                // implementation can never split the two sides silently.
                String key = normalize(name);
                if (!key.isEmpty()) {
                    next.put(key, badge);
                }
            }
        }
        clientThread.invoke(() -> install(next, teams, eventId, version, fetchGeneration));
    }

    /**
     * Swap a freshly fetched roster in and redraw the chatbox with it. Client
     * thread, so the chat builder never sees names without their sprites.
     */
    private void install(Map<String, TeamBadge> badges, List<TeamBadge> teams,
                         int eventId, String version, int fetchGeneration) {
        if (fetchGeneration != generation.get()) {
            // Cleared while this roster was in flight. Leaving the loaded
            // version unset lets the next state poll fetch again if it should.
            return;
        }
        assignIconSlots(teams, config.eventTeamIndicators());
        loadedTeams = teams;
        badgesByName = badges;
        loadedRosterVersion = version;
        loadedEventId = eventId;
        client.refreshChat();
    }

    /** A loaded roster without the fetch or the sprite drawing. */
    @VisibleForTesting
    void useBadges(Map<String, TeamBadge> badges, Map<Integer, Integer> slots) {
        badgesByName = badges;
        slotByTeam = slots;
    }

    private void clear() {
        generation.incrementAndGet();
        boolean hadBadges = !badgesByName.isEmpty();
        badgesByName = Collections.emptyMap();
        loadedTeams = Collections.emptyList();
        loadedRosterVersion = null;
        loadedEventId = 0;
        if (hadBadges) {
            // Badges exist only while a line is drawn, so a redraw removes them.
            clientThread.invoke(client::refreshChat);
        }
    }

    /**
     * Redraw on the display settings. They only change how a line is drawn,
     * so nothing is refetched. A new style also needs new sprites.
     */
    @Subscribe
    public void onConfigChanged(ConfigChanged event) {
        if (!DropTrackerConfig.GROUP.equals(event.getGroup())) {
            return;
        }
        String key = event.getKey();
        if (!"eventTeamIndicators".equals(key)
            && !"eventTeamIndicatorColorNames".equals(key)
            && !"eventTeamIndicatorsPublicChat".equals(key)) {
            return;
        }
        clientThread.invoke(() -> {
            List<TeamBadge> teams = loadedTeams;
            if (teams.isEmpty()) {
                return;
            }
            if ("eventTeamIndicators".equals(key)) {
                assignIconSlots(teams, config.eventTeamIndicators());
            }
            client.refreshChat();
        });
    }

    /**
     * Badge one chat line as the chatbox draws it, the same way RuneLite's own
     * chat-channel rank icons are added: replace the name on the script stack
     * and leave the {@link MessageNode} alone. The stack carries the line's
     * id and split-PM flag (ints, top two) and its channel, name, message and
     * timestamp (objects, top four).
     *
     * <p>Deliberately not gated on the plugin's {@code isTracking} flag: that
     * is the webhook-exhaustion kill switch for <em>submissions</em>, and
     * hiding a display feature behind it would silently drop badges for anyone
     * whose webhook list failed to replenish.
     */
    @Subscribe
    public void onScriptCallbackEvent(ScriptCallbackEvent event) {
        if (!CHAT_MESSAGE_BUILDING.equals(event.getEventName())) {
            return;
        }
        Map<String, TeamBadge> badges = badgesByName;
        if (badges.isEmpty()) {
            return;
        }
        TeamIndicatorStyle style = config.eventTeamIndicators();
        if (style == null || style == TeamIndicatorStyle.OFF) {
            return;
        }
        int[] intStack = client.getIntStack();
        int intStackSize = client.getIntStackSize();
        Object[] objectStack = client.getObjectStack();
        int objectStackSize = client.getObjectStackSize();
        if (intStack == null || objectStack == null || intStackSize < 2 || objectStackSize < 4) {
            return;
        }
        // The split private-chat pane builds through the same callback. It
        // holds nothing but DMs, which are never ours to touch.
        if (intStack[intStackSize - 2] == 1) {
            return;
        }
        MessageNode node = client.getMessages().get(intStack[intStackSize - 1]);
        if (node == null || !isBadgedChannel(node.getType())) {
            return;
        }
        // Identify the sender by the node's own name, not the drawn one, which
        // another plugin may already have decorated.
        String sender = node.getName();
        if (sender == null || sender.isEmpty()) {
            return;
        }
        // Our own Discord->game bridge renders relayed lines as real chat
        // messages. A Discord user is not a roster member and must never be
        // badged as one.
        if (ChatMessageUtil.isDiscordBridgeSender(sender)) {
            return;
        }
        TeamBadge badge = badges.get(normalize(sender));
        if (badge == null) {
            return;
        }
        Object shown = objectStack[objectStackSize - 3];
        if (!(shown instanceof String)) {
            return;
        }
        String decorated = badge.render((String) shown, iconSlot(badge.teamId),
            config.eventTeamIndicatorColorNames());
        if (decorated != null) {
            objectStack[objectStackSize - 3] = decorated;
        }
    }

    /**
     * The chat channels a badge belongs on. Everything else, including private
     * messages, trade requests and broadcasts, is never touched.
     */
    boolean isBadgedChannel(@Nullable ChatMessageType type) {
        if (type == null) {
            return false;
        }
        switch (type) {
            case CLAN_CHAT:
            case CLAN_GUEST_CHAT:
            case CLAN_GIM_CHAT:
            case FRIENDSCHAT:
                return true;
            case PUBLICCHAT:
                return config.eventTeamIndicatorsPublicChat();
            default:
                return false;
        }
    }

    // ── sprites ──────────────────────────────────────────────────────────────

    /**
     * Reserve the whole slot block once. Growing {@code modIcons} again on
     * every roster change would leak slots and can stomp on icons a plugin
     * loaded after us appended.
     */
    private void claimIconSlots() {
        if (iconOffset >= 0) {
            return;
        }
        final IndexedSprite[] modIcons = client.getModIcons();
        if (modIcons == null) {
            return;
        }
        final IndexedSprite[] grown = Arrays.copyOf(modIcons, modIcons.length + MAX_TEAM_ICONS);
        iconOffset = modIcons.length;
        // The new slots stay null until a roster assigns them. Nothing
        // dereferences them meanwhile: a slot is only ever named in an
        // <img=> tag after assignIconSlots has filled it, which is the same
        // order RuneLite's own pet icons are loaded in.
        client.setModIcons(grown);
    }

    /** Draw each team's badge for the style into our reserved slots. Client thread. */
    private void assignIconSlots(List<TeamBadge> teams, TeamIndicatorStyle style) {
        Map<Integer, Integer> slots = new HashMap<>();
        if (iconOffset < 0) {
            claimIconSlots();
        }
        IndexedSprite[] modIcons = iconOffset < 0 ? null : client.getModIcons();
        if (modIcons != null && modIcons.length >= iconOffset + MAX_TEAM_ICONS) {
            Font font = FontManager.getRunescapeFont();
            int used = 0;
            for (TeamBadge team : teams) {
                if (used >= MAX_TEAM_ICONS) {
                    break;
                }
                BadgeArt art = drawBadge(team, style, font);
                if (art == null) {
                    continue;
                }
                IndexedSprite sprite = ImageUtil.getImageIndexedSprite(art.image, client);
                // The font sits an <img> with its bottom row on the text
                // baseline, measured by originalHeight. Rows past that hang
                // below it, as a bracket's tail does.
                sprite.setOriginalHeight(art.ascent);
                int slot = iconOffset + used;
                modIcons[slot] = sprite;
                slots.put(team.teamId, slot);
                used++;
            }
        }
        // No slot at all still works: every team falls back to a coloured name.
        slotByTeam = slots;
    }

    private int iconSlot(int teamId) {
        Integer slot = slotByTeam.get(teamId);
        return slot == null ? -1 : slot;
    }

    /** A badge's pixels, and how many of its rows sit above the text baseline. */
    static final class BadgeArt {
        final BufferedImage image;
        final int ascent;

        BadgeArt(BufferedImage image, int ascent) {
            this.image = image;
            this.ascent = ascent;
        }
    }

    /**
     * A team's badge for a style: its orb, its tag, or both side by side.
     *
     * <p>ORB degrades to the tag for a team without an orb colour, which is
     * why the default style can be ORB without every team needing one.
     *
     * @param font the chat font; with none, the tag is left out
     * @return null when the style draws nothing for this team
     */
    @Nullable
    static BadgeArt drawBadge(TeamBadge badge, TeamIndicatorStyle style, @Nullable Font font) {
        if (style == null || style == TeamIndicatorStyle.OFF) {
            return null;
        }
        List<BadgeArt> pieces = new ArrayList<>(2);
        boolean orb = style.showsOrb() && badge.orbColor != null;
        if (orb) {
            pieces.add(drawOrb(badge.orbColor));
        }
        if ((style.showsTag() || !orb) && badge.tag != null && !badge.tag.isEmpty() && font != null) {
            BadgeArt tag = drawText("[" + badge.tag + "]", badge.tagColor(), font);
            if (tag != null) {
                pieces.add(tag);
            }
        }
        if (pieces.isEmpty()) {
            return null;
        }
        return pieces.size() == 1 ? pieces.get(0) : sideBySide(pieces);
    }

    /**
     * A filled circle in the team's color, sized like the game's chat icons.
     *
     * Antialiasing is deliberately off: an IndexedSprite carries a palette and
     * a single transparent index, so soft edges would either bloat the palette
     * or come out as a fringe of near-transparent pixels. Two colors at 12px
     * is also simply what the game's own chat icons look like.
     */
    private static BadgeArt drawOrb(Color color) {
        BufferedImage image = new BufferedImage(ORB_SIZE, ORB_SIZE, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = image.createGraphics();
        try {
            g.setComposite(AlphaComposite.Src);
            g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);
            g.setColor(spriteSafe(color));
            g.fillOval(1, 1, ORB_SIZE - 2, ORB_SIZE - 2);
        } finally {
            g.dispose();
        }
        // The whole square sits above the baseline, as the game's icons do.
        return new BadgeArt(image, ORB_SIZE);
    }

    /**
     * Text drawn in the chat font, cropped to its ink.
     *
     * <p>RuneLite's RuneScape font is the game's own chat glyphs, and with
     * antialiasing off it lands on whole pixels exactly as the chatbox draws
     * it. Its metrics are the catch: the glyphs stand a few rows above the
     * baseline FontMetrics reports. So the baseline is measured instead, as
     * the row under a capital.
     */
    @Nullable
    static BadgeArt drawText(String text, Color color, Font font) {
        BufferedImage probe = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);
        Graphics2D probeGraphics = probe.createGraphics();
        FontMetrics metrics;
        try {
            metrics = probeGraphics.getFontMetrics(font);
        } finally {
            probeGraphics.dispose();
        }
        int width = metrics.stringWidth(text);
        int height = metrics.getAscent() + metrics.getDescent();
        if (width <= 0 || height <= 0) {
            return null;
        }
        BufferedImage canvas = renderLine(text, color, font, width, height, metrics.getAscent());
        BufferedImage capital = renderLine("H", color, font, width, height, metrics.getAscent());
        int top = firstInkedRow(canvas);
        int bottom = lastInkedRow(canvas);
        int baseline = lastInkedRow(capital);
        if (top < 0 || baseline < top) {
            return null;
        }
        BufferedImage cropped = new BufferedImage(width, bottom - top + 1, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = cropped.createGraphics();
        try {
            g.setComposite(AlphaComposite.Src);
            g.drawImage(canvas, 0, -top, null);
        } finally {
            g.dispose();
        }
        return new BadgeArt(cropped, baseline - top + 1);
    }

    private static BufferedImage renderLine(String text, Color color, Font font,
                                            int width, int height, int baseline) {
        BufferedImage image = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = image.createGraphics();
        try {
            g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);
            g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
            g.setRenderingHint(RenderingHints.KEY_FRACTIONALMETRICS, RenderingHints.VALUE_FRACTIONALMETRICS_OFF);
            g.setFont(font);
            g.setColor(spriteSafe(color));
            g.drawString(text, 0, baseline);
        } finally {
            g.dispose();
        }
        return image;
    }

    /** Pieces laid out left to right, standing on one shared baseline. */
    private static BadgeArt sideBySide(List<BadgeArt> pieces) {
        int ascent = 0;
        int descent = 0;
        int width = PIECE_GAP * (pieces.size() - 1);
        for (BadgeArt piece : pieces) {
            ascent = Math.max(ascent, piece.ascent);
            descent = Math.max(descent, piece.image.getHeight() - piece.ascent);
            width += piece.image.getWidth();
        }
        BufferedImage image = new BufferedImage(width, ascent + descent, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = image.createGraphics();
        try {
            g.setComposite(AlphaComposite.Src);
            int x = 0;
            for (BadgeArt piece : pieces) {
                g.drawImage(piece.image, x, ascent - piece.ascent, null);
                x += piece.image.getWidth() + PIECE_GAP;
            }
        } finally {
            g.dispose();
        }
        return new BadgeArt(image, ascent);
    }

    private static int firstInkedRow(BufferedImage image) {
        for (int y = 0; y < image.getHeight(); y++) {
            if (rowHasInk(image, y)) {
                return y;
            }
        }
        return -1;
    }

    private static int lastInkedRow(BufferedImage image) {
        for (int y = image.getHeight() - 1; y >= 0; y--) {
            if (rowHasInk(image, y)) {
                return y;
            }
        }
        return -1;
    }

    private static boolean rowHasInk(BufferedImage image, int y) {
        for (int x = 0; x < image.getWidth(); x++) {
            if ((image.getRGB(x, y) >>> 24) != 0) {
                return true;
            }
        }
        return false;
    }

    /**
     * An opaque colour the sprite can hold. The indexed-sprite conversion
     * only keeps fully opaque pixels, and it reads pure black as its
     * transparent index, so black is nudged off zero.
     */
    static Color spriteSafe(Color color) {
        int rgb = color.getRGB() & 0xFFFFFF;
        return new Color(rgb == 0 ? 0x010101 : rgb);
    }

    // ── helpers ──────────────────────────────────────────────────────────────

    /**
     * The comparison key for an RSN. {@link Text#standardize} folds the
     * non-breaking space the game uses inside names and lowercases; the
     * underscore fold matches the server's
     * {@code normalize_player_display_equivalence}, which is what the roster
     * names were built with.
     */
    static String normalize(String name) {
        if (name == null) {
            return "";
        }
        String stripped = Text.standardize(Text.removeTags(name));
        // Collapse runs of whitespace as well as folding the separators: the
        // server's normalizer does, and two implementations that disagree by
        // one space badge nobody while looking perfectly correct on both sides.
        return WHITESPACE.matcher(
            stripped.replace('_', ' ').replace('-', ' ').trim()).replaceAll(" ");
    }

    @Nullable
    private static Integer parseTeamId(String key) {
        try {
            return Integer.valueOf(key);
        } catch (NumberFormatException e) {
            return null;
        }
    }

    /** "#rrggbb" to a Color, or null for anything unusable. */
    @Nullable
    static Color colorOf(@Nullable String hex) {
        if (hex == null) {
            return null;
        }
        String value = hex.trim();
        if (value.startsWith("#")) {
            value = value.substring(1);
        }
        if (value.length() != 6) {
            return null;
        }
        try {
            return new Color(Integer.parseInt(value, 16));
        } catch (NumberFormatException e) {
            return null;
        }
    }

    /** One team's rendering inputs, resolved once per roster load. */
    static final class TeamBadge {
        private final int teamId;
        @Nullable
        private final String tag;
        @Nullable
        private final Color orbColor;
        @Nullable
        private final Color accent;

        TeamBadge(int teamId, @Nullable String tag, @Nullable Color orbColor,
                  @Nullable Color accent) {
            this.teamId = teamId;
            this.tag = tag;
            this.orbColor = orbColor;
            this.accent = accent;
        }

        /** The team's colour for text: the admin-set accent, else the orb's. */
        @Nullable
        Color nameColor() {
            return accent != null ? accent : orbColor;
        }

        Color tagColor() {
            Color color = nameColor();
            return color != null ? color : FALLBACK_TAG_COLOR;
        }

        /**
         * The sender name as the line should draw it, or null to leave it as
         * it is.
         *
         * <p>Only an {@code <img>} and a colour are ever added, both of which
         * the game's {@code removetags} strips. The tag itself lives in the
         * sprite. The badge leads the name, except that a moderator crown
         * stays first, where the chat builder looks for it.
         *
         * @param shown     the name on the script stack; another plugin may
         *                  already have given it an icon or a colour
         * @param iconSlot  this team's sprite, or -1 when it has none
         * @param colorName whether to draw the name in the team colour
         */
        @Nullable
        String render(String shown, int iconSlot, boolean colorName) {
            Color color = colorName ? nameColor() : null;
            if (iconSlot < 0 && color == null) {
                return null;
            }
            // Drop any colour the name already carries (RuneLite's chat colour
            // config, applied by a subscriber that may run before this one) so
            // the team colour is the one that shows. </col> resets to the chat
            // default rather than to an enclosing tag, so the result must be
            // one flat span, never a nested one.
            String name = color != null ? COLOR_TAG.matcher(shown).replaceAll("") : shown;
            Matcher crown = LEADING_CROWN.matcher(name);
            String lead = crown.lookingAt() ? crown.group() : "";
            String rest = name.substring(lead.length());

            StringBuilder out = new StringBuilder(lead);
            if (iconSlot >= 0) {
                out.append("<img=").append(iconSlot).append('>');
            }
            if (color != null) {
                out.append("<col=")
                    .append(String.format("%06x", color.getRGB() & 0xFFFFFF))
                    .append('>')
                    .append(rest)
                    .append("</col>");
            } else {
                out.append(rest);
            }
            return out.toString();
        }
    }
}

package io.droptracker.service;

import com.google.common.cache.Cache;
import com.google.common.cache.CacheBuilder;

import io.droptracker.util.DebugLogger;
import io.droptracker.util.ItemStacks;
import io.droptracker.util.NpcUtilities;
import net.runelite.api.Client;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.http.api.loottracker.LootRecordType;
import org.jetbrains.annotations.Nullable;
import org.jetbrains.annotations.VisibleForTesting;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.concurrent.TimeUnit;

/**
 * Suppresses the second loot event fired when a raid reward chest is opened
 * twice for the same completion. RuneLite records raid loot when the reward
 * interface OPENS, not when items are picked up — so a player who opens the
 * chest in the loot room, leaves the loot inside, and later claims it from the
 * collection chest at the bank produces two identical {@link LootReceived}
 * events minutes (or hours) apart. Without suppression the second event
 * submits a duplicate drop AND bumps {@link KCService}'s cached kill count,
 * which the backend then credits as a phantom kill.
 *
 * <p>Keyed per account + raid family, storing the signature of the last chest
 * bundle seen. A raid's next completion chat message re-arms it (see
 * {@link #onRaidCompletion}), so back-to-back raids that happen to roll
 * identical loot are never suppressed: the dedup scope is "since the last
 * completion of this raid", with a generous TTL as a memory backstop.
 *
 * <p>Must gate BOTH {@code DropHandler.onLootReceived} and
 * {@code KCService.onLoot} — suppressing only the drop submission would leave
 * the client's cached kill count permanently one ahead of reality. The single
 * call site in {@code DropTrackerPlugin.onLootReceived} sits before that
 * fan-out for exactly this reason.
 */
@Singleton
public class RaidLootDeduplicator {

    private final Client client;

    private final Cache<String, String> lastChestSignature = CacheBuilder.newBuilder()
            .expireAfterWrite(2, TimeUnit.HOURS)
            .maximumSize(32L)
            .build();

    @Inject
    public RaidLootDeduplicator(Client client) {
        this.client = client;
    }

    /**
     * Whether this loot event repeats a raid chest bundle already seen for the
     * current completion. First sight of a bundle records it and returns
     * false; an identical bundle for the same raid (until the next completion
     * message re-arms it) returns true.
     */
    public boolean isDuplicateRaidLoot(LootReceived event) {
        if (event.getType() != LootRecordType.EVENT) {
            return false;
        }
        boolean duplicate = isDuplicate(client.getAccountHash(), event.getName(),
                ItemStacks.signature(event.getItems()));
        if (duplicate) {
            DebugLogger.log("[RaidLootDeduplicator] suppressing re-looted raid chest; source="
                    + event.getName());
        }
        return duplicate;
    }

    /**
     * Re-arms the dedup for the raid named in a completion chat message
     * ("Your completed Theatre of Blood count is: ..."), so the next chest
     * open is always treated as new loot even if its bundle happens to match
     * the previous completion's.
     */
    public void onRaidCompletion(String bossName) {
        invalidate(client.getAccountHash(), bossName);
    }

    @VisibleForTesting
    boolean isDuplicate(long accountHash, String sourceName, String signature) {
        String family = raidFamily(sourceName);
        if (family == null) {
            return false;
        }
        String key = accountHash + "|" + family;
        String previous = lastChestSignature.getIfPresent(key);
        if (signature.equals(previous)) {
            return true;
        }
        lastChestSignature.put(key, signature);
        return false;
    }

    @VisibleForTesting
    void invalidate(long accountHash, String bossName) {
        String family = raidFamily(bossName);
        if (family != null) {
            lastChestSignature.invalidate(accountHash + "|" + family);
        }
    }

    /**
     * Collapses a raid source or chat-message boss name (any mode variant,
     * e.g. "Theatre of Blood: Entry Mode", "Chambers of Xeric Challenge Mode")
     * to its base raid name, or null for anything that is not a raid. The
     * loot event always carries the base name while the completion message may
     * carry a mode suffix; folding both to the family keys them identically.
     */
    @Nullable
    @VisibleForTesting
    static String raidFamily(String name) {
        if (name == null) {
            return null;
        }
        if (name.startsWith(NpcUtilities.TOB)) {
            return NpcUtilities.TOB;
        }
        if (name.startsWith(NpcUtilities.TOA)) {
            return NpcUtilities.TOA;
        }
        if (name.startsWith(NpcUtilities.COX)) {
            return NpcUtilities.COX;
        }
        return null;
    }
}

