package io.droptracker.service;

import com.google.inject.Inject;
import com.google.inject.Singleton;
import io.droptracker.DropTrackerConfig;
import io.droptracker.DropTrackerPlugin;
import io.droptracker.api.DropTrackerApi;
import io.droptracker.models.CustomWebhookBody;
import io.droptracker.models.submissions.SubmissionType;
import io.droptracker.util.ChatMessageUtil;
import io.droptracker.util.PlayerIdentity;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.clan.ClanChannel;
import net.runelite.client.util.Text;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;

/**
 * Relays clan chat to the DropTracker API for the clan features:
 * <ul>
 *   <li>{@code CLAN_MESSAGE} system broadcasts ("X received a drop: ...") as
 *       {@code clan_broadcast} submissions — server-side parsing tracks
 *       clanmates who don't run the plugin;</li>
 *   <li>{@code CLAN_CHAT} player lines as {@code clan_chat} submissions — the
 *       game→Discord half of the two-way chat bridge.</li>
 * </ul>
 *
 * The plugin stays a dumb pipe on purpose: no game-message parsing happens
 * client-side, so pattern fixes never wait on a plugin-hub review. Lines are
 * batched (2s debounce, capped batch) into one payload, and each embed
 * carries the standard relayer identity fields — the server authenticates the
 * RELAYER and dedupes across multiple relaying clanmates, so this can be
 * enabled by any number of members safely.
 *
 * API-only by contract: raw chat text must never ride the Discord-webhook
 * fallback transport. Both the queue methods here and the
 * {@link SubmissionManager} dispatch cases enforce it.
 */
@Slf4j
@Singleton
public class ClanRelayService {

    private static final int FLUSH_DELAY_SECONDS = 2;
    private static final int MAX_LINES_PER_FLUSH = 10;
    /** Backstop so a pathological chat flood can't grow the queue unbounded. */
    private static final int MAX_QUEUED_LINES = 200;
    private static final int MAX_MESSAGE_CHARS = 250;

    private final Client client;
    private final DropTrackerConfig config;
    private final DropTrackerApi api;
    private final DropTrackerPlugin plugin;
    private final SubmissionManager submissionManager;
    private final ScheduledExecutorService executor;

    private final ConcurrentLinkedQueue<PendingLine> queue = new ConcurrentLinkedQueue<>();
    private final AtomicBoolean flushScheduled = new AtomicBoolean(false);

    /**
     * The clan channel the local player currently sits in, maintained from
     * the client thread (ClanChannelChanged + relay call sites). Volatile so
     * the notification poller can attach it to presence heartbeats without
     * touching client state off-thread.
     */
    private volatile String currentClanName = null;

    @Inject
    public ClanRelayService(Client client, DropTrackerConfig config, DropTrackerApi api,
                            DropTrackerPlugin plugin, SubmissionManager submissionManager,
                            ScheduledExecutorService executor) {
        this.client = client;
        this.config = config;
        this.api = api;
        this.plugin = plugin;
        this.submissionManager = submissionManager;
        this.executor = executor;
    }

    /** Called from the client thread whenever the clan channel changes. */
    public void updateClanChannel(ClanChannel channel) {
        currentClanName = channel != null ? Text.removeTags(channel.getName()) : null;
    }

    /** The current clan's name, or null when not in a clan. Thread-safe. */
    public String getCurrentClanName() {
        return currentClanName;
    }

    /** Whether the Discord→game direction should be live (poll + display). */
    public boolean discordChatActive() {
        return config.useApi() && config.receiveDiscordChat() && currentClanName != null;
    }

    /** A CLAN_MESSAGE system broadcast (already tag-sanitized by the caller). */
    public void onClanBroadcast(String message) {
        if (!config.useApi() || !config.relayClanBroadcasts()) {
            return;
        }
        queueLine(new PendingLine(SubmissionType.CLAN_BROADCAST, null, message));
    }

    /**
     * A CLAN_CHAT player line (sender may still carry icon tags).
     *
     * <p>Discord lines the bridge renders locally arrive here too —
     * {@code client.addChatMessage} posts a real {@code ChatMessage}, so the
     * Discord→game direction feeds straight back into the game→Discord one.
     * Unguarded that echoes every Discord message back into the channel it
     * was typed in, so lines wearing {@link
     * ChatMessageUtil#DISCORD_SENDER_MARKER} stop here.</p>
     */
    public void onClanChat(String senderName, String message) {
        if (!config.useApi() || !config.relayClanChat()) {
            return;
        }
        String sender = senderName != null ? Text.removeTags(Text.toJagexName(senderName)) : null;
        if (sender == null || sender.trim().isEmpty()) {
            return;
        }
        if (ChatMessageUtil.isDiscordBridgeSender(sender)) {
            return;
        }
        queueLine(new PendingLine(SubmissionType.CLAN_CHAT, sender.trim(), message));
    }

    private void queueLine(PendingLine line) {
        refreshClanNameFromClient();
        if (currentClanName == null || line.message == null || line.message.trim().isEmpty()) {
            return;
        }
        if (queue.size() >= MAX_QUEUED_LINES) {
            return;
        }
        line.clanName = currentClanName;
        String trimmed = line.message.trim();
        line.message = trimmed.length() > MAX_MESSAGE_CHARS
            ? trimmed.substring(0, MAX_MESSAGE_CHARS) : trimmed;
        queue.add(line);
        if (flushScheduled.compareAndSet(false, true)) {
            executor.schedule(this::flush, FLUSH_DELAY_SECONDS, TimeUnit.SECONDS);
        }
    }

    /** Chat events arrive on the client thread, so this read is safe here. */
    private void refreshClanNameFromClient() {
        ClanChannel channel = client.getClanChannel();
        currentClanName = channel != null ? Text.removeTags(channel.getName()) : null;
    }

    private void flush() {
        flushScheduled.set(false);
        try {
            List<PendingLine> lines = new ArrayList<>(MAX_LINES_PER_FLUSH);
            PendingLine next;
            while (lines.size() < MAX_LINES_PER_FLUSH && (next = queue.poll()) != null) {
                lines.add(next);
            }
            if (lines.isEmpty()) {
                return;
            }
            // One webhook per submission type so SubmissionManager's per-type
            // dispatch stays uniform; a mixed 2s window is two payloads.
            sendBatch(lines, SubmissionType.CLAN_BROADCAST);
            sendBatch(lines, SubmissionType.CLAN_CHAT);
        } catch (Exception e) {
            log.debug("Clan relay flush failed: {}", e.getMessage());
        } finally {
            // Anything still queued (overflow past the batch cap, or lines
            // added mid-flush) gets its own pass.
            if (!queue.isEmpty() && flushScheduled.compareAndSet(false, true)) {
                executor.schedule(this::flush, FLUSH_DELAY_SECONDS, TimeUnit.SECONDS);
            }
        }
    }

    private void sendBatch(List<PendingLine> lines, SubmissionType type) {
        /* The relayer's own identity is what the server authenticates the batch
           against, and it rejects a batch without one. Flushing happens off the
           client thread, so an unreadable name here is routine — resolve it the
           same way submissions do, and drop the batch rather than relay it
           anonymously or under an invented name. */
        String relayerName = PlayerIdentity.resolve(
            plugin.getLocalPlayerName(),
            String.valueOf(client.getAccountHash()),
            config.lastAccountName(),
            config.lastAccountHash());
        if (relayerName == null) {
            log.debug("Skipping clan relay batch: no resolvable player name");
            return;
        }

        CustomWebhookBody webhook = null;
        for (PendingLine line : lines) {
            if (line.type != type) {
                continue;
            }
            if (webhook == null) {
                webhook = new CustomWebhookBody();
                webhook.setContent("DropTracker Clan Relay");
            }
            CustomWebhookBody.Embed embed = new CustomWebhookBody.Embed();
            embed.setTitle("Clan relay");
            embed.addField("type", type == SubmissionType.CLAN_BROADCAST ? "clan_broadcast" : "clan_chat", true);
            embed.addField("clan_name", line.clanName, true);
            embed.addField("message", line.message, false);
            if (line.sender != null) {
                embed.addField("sender", line.sender, true);
            }
            embed.addField("player_name", relayerName, true);
            embed.addField("acc_hash", String.valueOf(client.getAccountHash()), true);
            embed.addField("p_v", plugin.pluginVersion != null ? plugin.pluginVersion : "unknown", true);
            embed.addField("guid", api.generateGuidForSubmission(), true);
            webhook.getEmbeds().add(embed);
        }
        if (webhook != null) {
            submissionManager.sendDataToDropTracker(webhook, type);
        }
    }

    private static final class PendingLine {
        private final SubmissionType type;
        private final String sender;
        private String clanName;
        private String message;

        private PendingLine(SubmissionType type, String sender, String message) {
            this.type = type;
            this.sender = sender;
            this.message = message;
        }
    }
}

package io.droptracker.service;

import javax.inject.Inject;
import javax.inject.Singleton;

import io.droptracker.DropTrackerConfig;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.MenuAction;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;

/**
 * Reads the player's <em>entire</em> collection log when they open it.
 *
 * <p>The client API does not expose collection log contents; the game only sends
 * them when the interface asks. The technique here — open the log, invoke its
 * "Search" operation so the server transmits every slot, then re-run the init
 * script to put the interface back — comes from WikiSync
 * (github.com/weirdgloop/WikiSync), Copyright (c) 2021, andmcadams,
 * BSD 2-Clause License (see LICENSE), by way of RuneProfile.
 *
 * <p>Why it matters: without a full read we can only ever know about items that
 * dropped while the plugin was running, so a player's collection log page would
 * start empty on the day they installed and slowly fill in. One open of the log
 * backfills everything they have ever obtained.
 *
 * <p><b>The adventure log guard is not optional.</b> A player viewing someone
 * else's collection log through a POH adventure log receives that player's slots
 * through the very same script. Storing those would silently overwrite the
 * viewer's collection log with a stranger's, so any hint of adventure-log
 * viewing discards everything accumulated.
 */
@Slf4j
@Singleton
public class CollectionLogScraper {

	/**
	 * Fired once per <em>obtained</em> collection log slot, carrying
	 * (itemId, quantity).
	 *
	 * <p>Obtained only — the interface draws every slot on a page greyed out
	 * before the server transmits anything, and this script is what un-greys the
	 * ones the player has. So a complete read cannot tell us which slots
	 * <em>exist</em>, only which are filled; the slot list has to come from the
	 * cache instead (see {@link CollectionLogSlots}). WikiSync sets one bit per
	 * firing with no quantity check and publishes the result as a player's
	 * obtained items, which is the practical proof.
	 */
	private static final int COLLECTION_DELAYED_TRANSMIT = 4100;
	/** Fired when the collection log interface finishes building. */
	private static final int COLLECTION_LOG_SETUP = 7797;
	/** Rebuilds the interface, which closes the search we opened. */
	private static final int COLLECTION_INIT = 2240;

	/**
	 * Ticks of silence after the last slot before the read is considered done.
	 * The slots arrive over several ticks, so "no more for a couple of ticks" is
	 * the only completion signal available.
	 */
	private static final int QUIET_TICKS_UNTIL_COMPLETE = 2;

	private final EventBus eventBus;
	private final Client client;
	private final DropTrackerConfig config;
	private final StateSyncService stateSyncService;
	private final StateSyncScheduler stateSyncScheduler;

	/** Tick the last slot arrived on, or -1 when no read is in progress. */
	private int lastTransmitTick = -1;

	/** True while we are driving the interface, so our own init does not re-trigger us. */
	private boolean selfTriggered = false;

	@Inject
	public CollectionLogScraper(EventBus eventBus,
	                            Client client,
	                            DropTrackerConfig config,
	                            StateSyncService stateSyncService,
	                            StateSyncScheduler stateSyncScheduler) {
		this.eventBus = eventBus;
		this.client = client;
		this.config = config;
		this.stateSyncService = stateSyncService;
		this.stateSyncScheduler = stateSyncScheduler;
	}

	public void startUp() {
		eventBus.register(this);
	}

	public void shutDown() {
		eventBus.unregister(this);
		reset();
	}

	private void reset() {
		lastTransmitTick = -1;
		selfTriggered = false;
	}

	private boolean isEnabled() {
		return config.useApi() && config.syncAccountState() && stateSyncService.isEnabled();
	}

	/** True when the open log belongs to another player (POH adventure log). */
	private boolean isViewingSomeoneElse() {
		return client.getVarbitValue(VarbitID.COLLECTION_POH_HOST_BOOK_OPEN) == 1;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event) {
		GameState state = event.getGameState();
		if (state != GameState.LOGGED_IN && state != GameState.HOPPING) {
			reset();
		}
	}

	/**
	 * Asks the game to transmit every slot once the log has been opened.
	 *
	 * <p>The "Search" operation is what makes the server send the full contents;
	 * re-running the init script immediately afterwards restores the normal view
	 * so the player does not find their search box mysteriously open.
	 */
	@Subscribe
	public void onScriptPostFired(ScriptPostFired event) {
		if (event.getScriptId() != COLLECTION_LOG_SETUP || !isEnabled()) {
			return;
		}

		if (isViewingSomeoneElse()) {
			stateSyncService.clearItems();
			return;
		}

		// Our own init call re-fires setup; without this we would loop.
		if (selfTriggered) {
			return;
		}
		selfTriggered = true;

		client.menuAction(-1, InterfaceID.Collection.SEARCH_TOGGLE, MenuAction.CC_OP, 1, -1, "Search", null);
		client.runScript(COLLECTION_INIT);
	}

	/** Collects one slot per firing. */
	@Subscribe
	public void onScriptPreFired(ScriptPreFired event) {
		if (event.getScriptId() != COLLECTION_DELAYED_TRANSMIT || !isEnabled()) {
			return;
		}

		if (isViewingSomeoneElse()) {
			return;
		}

		Object[] args = event.getScriptEvent() == null ? null : event.getScriptEvent().getArguments();
		if (args == null || args.length < 3) {
			return;
		}

		try {
			int itemId = (int) args[1];
			int quantity = (int) args[2];
			stateSyncService.storeItem(itemId, quantity);
			lastTransmitTick = client.getTickCount();
		} catch (ClassCastException e) {
			log.debug("Unexpected collection log script arguments: {}", e.toString());
		}
	}

	/**
	 * Detects the end of a read and schedules a sync.
	 *
	 * <p>Only a read that ran to completion marks the item set as complete —
	 * that flag is what tells the server the absence of an item means "not
	 * obtained" rather than "not seen yet".
	 */
	@Subscribe
	public void onGameTick(GameTick event) {
		if (lastTransmitTick == -1) {
			return;
		}
		if (client.getTickCount() <= lastTransmitTick + QUIET_TICKS_UNTIL_COMPLETE) {
			return;
		}

		lastTransmitTick = -1;
		selfTriggered = false;

		if (isViewingSomeoneElse()) {
			stateSyncService.clearItems();
			return;
		}

		stateSyncService.markClogComplete();
		stateSyncScheduler.scheduleRapid("clog");
	}

	/**
	 * Fail-safe: if the adventure log opens at any point, drop everything.
	 *
	 * <p>The checks above cover the ordinary paths, but the cost of being wrong
	 * here is attributing another player's collection log to this account, so it
	 * is worth catching the varbit directly as well.
	 */
	@Subscribe
	public void onVarbitChanged(VarbitChanged event) {
		if (event.getVarbitId() == VarbitID.COLLECTION_POH_HOST_BOOK_OPEN && isViewingSomeoneElse()) {
			log.debug("Adventure log opened; discarding accumulated collection log items");
			stateSyncService.clearItems();
			reset();
		}
	}
}

package io.droptracker.service;

import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;

import javax.inject.Inject;
import javax.inject.Singleton;

import io.droptracker.DropTrackerConfig;
import io.droptracker.models.api.Manifest;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;

/**
 * Decides <em>when</em> a state snapshot is sent.
 *
 * <p>Three triggers, in increasing urgency:
 * <ul>
 *   <li>a periodic sync, so a player who never does anything notable still has
 *       current state;</li>
 *   <li>login, so a player who played on another client is caught up;</li>
 *   <li>a short-debounced "rapid" sync after something notable (a new collection
 *       log slot), so the website reflects it while the player still cares.</li>
 * </ul>
 *
 * <p>The interval and the debounce both come from the manifest, so sync load is
 * tunable — and switchable off — from the server without a Plugin Hub release.
 *
 * <p>On logout the remaining delay is preserved rather than restarted. Without
 * that, a player who hops worlds every few minutes would restart a 60-minute
 * timer each time and never sync at all.
 */
@Slf4j
@Singleton
public class StateSyncScheduler {

	private final EventBus eventBus;
	private final ScheduledExecutorService executor;
	private final StateSyncService stateSyncService;
	private final ManifestService manifestService;

	private ScheduledFuture<?> pendingSync;

	/** Milliseconds left on the timer when the player logged out; 0 when not paused. */
	private long remainingOnPause;

	/** Guards the future and the pause state, both touched from several threads. */
	private final Object lock = new Object();

	private static final int DEFAULT_INTERVAL_MINUTES = 60;
	private static final int DEFAULT_RAPID_SECONDS = 3;

	@Inject
	public StateSyncScheduler(EventBus eventBus,
	                          ScheduledExecutorService executor,
	                          StateSyncService stateSyncService,
	                          ManifestService manifestService) {
		this.eventBus = eventBus;
		this.executor = executor;
		this.stateSyncService = stateSyncService;
		this.manifestService = manifestService;
	}

	public void startUp() {
		eventBus.register(this);
		// Schedule immediately, not just on the next login. The plugin usually
		// starts while the player is already logged in, so waiting for a
		// GameStateChanged means the first sync never happens at all.
		if (stateSyncService.isEnabled()) {
			scheduleRapid("startup");
		}
	}

	public void shutDown() {
		eventBus.unregister(this);
		synchronized (lock) {
			cancel();
			remainingOnPause = 0;
		}
	}

	/**
	 * Reacts to the sync toggle being flipped while the client is running.
	 *
	 * <p>Without this, enabling "Sync account progress" does nothing until the
	 * player next logs in — which reads as the feature being broken, because
	 * nothing happens and there is no error to see.
	 */
	@Subscribe
	public void onConfigChanged(ConfigChanged event) {
		if (!DropTrackerConfig.GROUP.equals(event.getGroup())) {
			return;
		}
		if (stateSyncService.isEnabled()) {
			// The manifest may never have loaded (it is skipped entirely while
			// the API is disabled), and without it no combat achievement varps
			// are read at all.
			manifestService.refresh();
			scheduleRapid("config-changed");
		} else {
			synchronized (lock) {
				cancel();
				remainingOnPause = 0;
			}
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event) {
		if (!stateSyncService.isEnabled()) {
			return;
		}

		if (event.getGameState() == GameState.LOGGED_IN) {
			// A login is the one moment we know the client's view is fresh and
			// possibly stale server-side, so sync promptly rather than waiting
			// out whatever was left on the timer.
			scheduleRapid("login");
			return;
		}

		// Hopping is not really "away" — but treating it the same is harmless,
		// because the resume below restores the remaining time rather than
		// restarting it.
		synchronized (lock) {
			if (pendingSync != null) {
				remainingOnPause = Math.max(0, pendingSync.getDelay(TimeUnit.MILLISECONDS));
				cancel();
				log.debug("Paused state sync with {}ms remaining", remainingOnPause);
			}
		}
	}

	/** Schedules a sync after the short debounce, replacing anything pending. */
	public void scheduleRapid(String source) {
		if (!stateSyncService.isEnabled()) {
			return;
		}
		synchronized (lock) {
			cancel();
			pendingSync = executor.schedule(() -> run(source), rapidSeconds(), TimeUnit.SECONDS);
		}
	}

	/** Schedules the next periodic sync, resuming a paused timer if there is one. */
	public void scheduleNext() {
		if (!stateSyncService.isEnabled()) {
			return;
		}
		synchronized (lock) {
			cancel();
			long delayMs;
			if (remainingOnPause > 0) {
				delayMs = remainingOnPause;
				remainingOnPause = 0;
				log.debug("Resuming state sync in {}ms", delayMs);
			} else {
				delayMs = TimeUnit.MINUTES.toMillis(intervalMinutes());
			}
			pendingSync = executor.schedule(() -> run("interval"), delayMs, TimeUnit.MILLISECONDS);
		}
	}

	/**
	 * Runs one sync and queues the next.
	 *
	 * <p>The next sync is scheduled unconditionally, including after a failure —
	 * otherwise one network blip would end syncing for the rest of the session.
	 */
	private void run(String source) {
		try {
			stateSyncService.sync(source);
		} catch (Exception e) {
			log.debug("State sync ({}) threw: {}", source, e.toString());
		} finally {
			scheduleNext();
		}
	}

	private void cancel() {
		if (pendingSync != null) {
			pendingSync.cancel(false);
			pendingSync = null;
		}
	}

	private int intervalMinutes() {
		Manifest manifest = manifestService.getManifest();
		return manifest == null ? DEFAULT_INTERVAL_MINUTES : manifest.getSync().getIntervalMinutes();
	}

	private int rapidSeconds() {
		Manifest manifest = manifestService.getManifest();
		return manifest == null ? DEFAULT_RAPID_SECONDS : manifest.getSync().getRapidSeconds();
	}
}

package io.droptracker.service;

import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.Varbits;
import net.runelite.api.WorldView;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.party.PartyService;
import net.runelite.client.util.Text;
import io.droptracker.util.DebugLogger;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.TimeUnit;

/**
 * Service for resolving the participants attached to submissions.
 *
 * <p>For raid content (ToB / ToA / CoX) the roster is captured from the game's
 * authoritative party sources rather than inferred from proximity:
 * <ul>
 *   <li><b>ToB</b>: health-orb name varcstrings {@code TOB_CLIENT_NAME0..4}</li>
 *   <li><b>ToA</b>: health-orb name varcstrings {@code TOA_CLIENT_NAME0..7}</li>
 *   <li><b>CoX</b>: the raiding-party sidepanel list widget
 *       ({@code InterfaceID.RaidsSidepanel.LIST})</li>
 * </ul>
 * These are server-pushed and independent of render distance, so the roster is
 * exactly the raid party — not whoever happened to be standing nearby.
 *
 * <p>A solo raid yields an empty roster, which is the correct participant list
 * and is deliberately kept — it is not treated as a failed capture, and nothing
 * is guessed to fill it. Guessing only happens when the game's own team size
 * says the raid had company that the authoritative source never returned.
 *
 * <p>Non-raid submissions fall back to a plain proximity scan, and the raid
 * roster is never merged into them, so a retained ToB roster can no longer be
 * attached to an unrelated kill minutes after the raid ended.
 */
@Singleton
public class NearbyPlayerTracker
{
    private final Client client;
    private final ClientThread clientThread;
    private final PartyService partyService;

    public static final String RAID_TOB = "tob";
    public static final String RAID_TOA = "toa";
    public static final String RAID_COX = "cox";

    /**
     * Names read from the authoritative roster source of the active raid,
     * accumulated over the raid so members who disconnect or leave early are
     * still credited. Includes the local player (needed for spectator
     * detection); the local name is filtered out at emission time.
     */
    private final Set<String> authoritativeRoster = new LinkedHashSet<>();

    /**
     * Last-resort roster accumulated from proximity scans inside the raid
     * instance. Only consulted when the authoritative source yielded nothing
     * (e.g. plugin enabled mid-raid after the widgets/varcs stopped updating),
     * so drops never regress to an empty participant list (issue #43).
     */
    private final Set<String> fallbackRoster = new LinkedHashSet<>();

    /** Raid the rosters above belong to: {@code "tob"|"toa"|"cox"}, or null. */
    private String activeRaidType = null;

    /**
     * Largest team size the game itself reported during the active raid; 0
     * when it was never sampled. This is what tells a solo raid apart from a
     * failed capture — both leave the roster empty, but only the second one
     * may fall back to guessing.
     */
    private int raidTeamSizeMax = 0;

    /**
     * Whether the authoritative source ever returned a name this raid (the
     * local player counts). Proves the source is live, so an empty roster
     * after the local player is removed means "alone", not "capture broken".
     */
    private boolean authoritativeCaptureWorked = false;

    /** Last time (ms) the raid context was observed active. */
    private long rosterLastActiveMs = 0;

    /**
     * How long the roster survives after the raid context ends. Raid
     * completion resets the raid varbits before the player opens the loot
     * chest, so the roster must outlive the raid; players can idle in the
     * treasure room for several minutes before opening the chest.
     */
    private static final long RAID_ROSTER_EXPIRY_MS = TimeUnit.MINUTES.toMillis(10);

    /** Roster scans while inside a raid run every N game ticks (~0.6s each). */
    private static final int ROSTER_SCAN_TICK_INTERVAL = 5;

    /** Radius used for the fallback in-raid proximity scan; raid rooms are large. */
    private static final int ROSTER_SCAN_RADIUS_TILES = 40;

    private int ticksSinceRosterScan = 0;
    private boolean wasInRaid = false;

    @Inject
    public NearbyPlayerTracker(Client client, ClientThread clientThread, PartyService partyService)
    {
        this.client = client;
        this.clientThread = clientThread;
        this.partyService = partyService;
    }

    /**
     * Maps a submission's source name (drop {@code source} field / PB
     * {@code boss_name}) to the raid it belongs to, or null for non-raid
     * content. Contains-matching covers every mode variant ("Theatre of
     * Blood: Hard Mode", "Chambers of Xeric Challenge Mode", ...).
     */
    public static String raidTypeForSource(String sourceName)
    {
        if (sourceName == null)
        {
            return null;
        }
        String source = sourceName.toLowerCase(Locale.ROOT);
        if (source.contains("theatre of blood"))
        {
            return RAID_TOB;
        }
        if (source.contains("tombs of amascut"))
        {
            return RAID_TOA;
        }
        if (source.contains("chambers of xeric"))
        {
            return RAID_COX;
        }
        return null;
    }

    /**
     * Team size of the given raid ({@code "tob"|"toa"|"cox"}) from the
     * accumulated authoritative roster, merged with a live read. Returns 0
     * when nothing is known; callers fall back to their varbit read.
     */
    public int raidRosterSize(String raidType)
    {
        if (raidType == null)
        {
            return 0;
        }
        Set<String> live = new LinkedHashSet<>();
        if (client.isClientThread())
        {
            captureAuthoritativeRoster(raidType, live);
        }
        Set<String> history = raidType.equals(activeRaidType) ? authoritativeRoster : Collections.emptySet();
        return boundedRoster(live, history, rosterCapacity(raidType)).size();
    }

    /**
     * How many member slots the raid's authoritative source publishes, which is
     * also the largest party the game will let into it: Theatre of Blood has
     * five health orbs, Tombs of Amascut eight. 0 means "no fixed ceiling" —
     * Chambers of Xeric has no small cap, so mass raids stay legal there.
     */
    static int rosterCapacity(String raidType)
    {
        if (RAID_TOB.equals(raidType))
        {
            return 5;
        }
        if (RAID_TOA.equals(raidType))
        {
            return 8;
        }
        return 0;
    }

    /**
     * Merges a live roster read with the accumulated one, never exceeding what
     * the raid can hold.
     *
     * <p>The accumulated roster exists because the authoritative sources go
     * quiet at the end of a raid, while the completion chat and the loot chest
     * arrive after that (issue #43). But accumulating is only safe *within* one
     * raid, and the lifecycle that is supposed to guarantee that has holes —
     * ToB's state varbit covers spectating as well as raiding, so consecutive
     * runs could pile up without the roster ever being cleared. That is how the
     * PB team-size bracket, which reads this roster since plugin 6.0, started
     * submitting Theatre of Blood times as 6-, 7-, 8- and 9-player raids
     * (suggestion #140) and how split credit reached people who were in an
     * earlier run rather than this one.
     *
     * <p>So the live read wins: it is the current raid's party, straight from
     * the game. History only fills slots the live read left empty — the
     * disconnected or departed members it exists for — and never past the
     * ceiling, which self-heals a contaminated roster as soon as the next
     * raid's names appear.
     */
    static Set<String> boundedRoster(Set<String> live, Set<String> history, int capacity)
    {
        Set<String> merged = new LinkedHashSet<>(live);
        for (String name : history)
        {
            if (capacity > 0 && merged.size() >= capacity)
            {
                break;
            }
            merged.add(name);
        }
        if (capacity > 0 && merged.size() > capacity)
        {
            // The live read alone overflowed, which the slot count says cannot
            // happen — keep the first `capacity` names rather than trust it.
            Set<String> trimmed = new LinkedHashSet<>();
            for (String name : merged)
            {
                if (trimmed.size() >= capacity)
                {
                    break;
                }
                trimmed.add(name);
            }
            return trimmed;
        }
        return merged;
    }

    /**
     * Called every game tick (client thread) so the raid roster is accumulated
     * continuously while a raid is in progress, instead of only being sampled
     * when a submission happens. By loot-chest time the raid varbits have
     * already reset, so a point-in-time scan is not enough (issue #43: ToB/ToA
     * drops submitted with an empty participant list).
     */
    public void onGameTick()
    {
        String raidType = currentRaidType();
        long nowMs = System.currentTimeMillis();

        if (raidType == null)
        {
            // Retain the roster for chest-time submissions, then expire it as
            // a whole so a stale raid can't leak into a later session.
            wasInRaid = false;
            if (activeRaidType != null && nowMs - rosterLastActiveMs > RAID_ROSTER_EXPIRY_MS)
            {
                clearRoster();
            }
            return;
        }

        if (!wasInRaid || !raidType.equals(activeRaidType))
        {
            // Entering a new raid (fresh entry — even back-to-back runs of the
            // same raid — or a different raid than the retained roster): drop
            // leftovers so a previous team can't leak into this raid's
            // submissions.
            clearRoster();
            activeRaidType = raidType;
            ticksSinceRosterScan = ROSTER_SCAN_TICK_INTERVAL; // scan immediately
        }
        wasInRaid = true;
        rosterLastActiveMs = nowMs;

        if (++ticksSinceRosterScan < ROSTER_SCAN_TICK_INTERVAL)
        {
            return;
        }
        ticksSinceRosterScan = 0;

        Set<String> live = new LinkedHashSet<>();
        captureAuthoritativeRoster(raidType, live);
        Set<String> merged = boundedRoster(live, authoritativeRoster, rosterCapacity(raidType));
        authoritativeRoster.clear();
        authoritativeRoster.addAll(merged);
        authoritativeCaptureWorked |= !authoritativeRoster.isEmpty();
        // Sampled throughout the raid because the raid varbits reset before the
        // loot chest opens: by submission time there is nothing left to read.
        raidTeamSizeMax = Math.max(raidTeamSizeMax, gameReportedTeamSize(raidType));
        captureFallbackRoster();
    }

    private void clearRoster()
    {
        authoritativeRoster.clear();
        fallbackRoster.clear();
        activeRaidType = null;
        raidTeamSizeMax = 0;
        authoritativeCaptureWorked = false;
    }

    /** The game's own party size for the given raid; 0 when unreadable. */
    private int gameReportedTeamSize(String raidType)
    {
        if (raidType == null)
        {
            return 0;
        }
        switch (raidType)
        {
            case RAID_TOB:
                return getTobTeamCount();
            case RAID_TOA:
                return getToaTeamCount();
            case RAID_COX:
                return getCoxTeamCount();
            default:
                return 0;
        }
    }

    /**
     * Whether an empty roster means "nobody else was in the raid" rather than
     * "the roster capture failed". A solo raid produces an empty roster by
     * definition, so reading emptiness alone as a failure — and guessing from
     * there — is what credited people who were never in the raid.
     *
     * <p>Requires positive evidence either way: a team size the game itself
     * reported as 1, or a live authoritative source that returned the local
     * player and nobody else. Without either, the caller keeps guessing.
     */
    private boolean isSoloRaid(String submissionRaidType, boolean localPlayerInRoster)
    {
        return isSoloRaid(
            gameReportedTeamSize(submissionRaidType),
            submissionRaidType.equals(activeRaidType),
            raidTeamSizeMax,
            authoritativeCaptureWorked,
            localPlayerInRoster);
    }

    /**
     * Best-evidence raid party size (receiver included) for a raid-sourced
     * submission, as a pure function so it can be tested without a client.
     *
     * <p>Takes the max of three independently derived signals because each one
     * can be absent: the live varbit read is usually 0 by loot-chest time (the
     * raid varbits reset at completion), the accumulated max only exists if
     * the plugin was on during the raid, and the participant count is what the
     * payload is about to claim anyway — a submission naming k others asserts
     * a party of at least k+1, so the reported size can never contradict the
     * roster it travels with (the same consistency rule the server applies to
     * {@code split_size}).
     *
     * @param liveTeamSize      team size read right now; 0 when unreadable
     * @param accumulatedMax    largest team size sampled during the raid; 0
     *                          when never sampled or the roster is not this
     *                          raid's
     * @param otherParticipants names attached to the submission (local player
     *                          excluded)
     * @return party size ≥ 1
     */
    static int computeRaidPartySize(int liveTeamSize, int accumulatedMax, int otherParticipants)
    {
        return Math.max(Math.max(liveTeamSize, accumulatedMax), otherParticipants + 1);
    }

    /**
     * The decision above, as a pure function of the evidence, so it can be
     * tested without a game client.
     *
     * @param liveTeamSize      team size read right now; 0 when unreadable
     *                          (normal at loot-chest time — the raid varbits
     *                          have already reset)
     * @param rosterIsThisRaid  whether the accumulated roster state belongs to
     *                          the raid this submission came from
     * @param teamSizeMax       largest team size seen during that raid; 0 when
     *                          never sampled
     * @param captureWorked     whether the authoritative source ever returned a
     *                          name during that raid
     * @param localPlayerInRoster whether the live read just returned the local
     *                          player, which proves the source is working
     */
    static boolean isSoloRaid(
        int liveTeamSize,
        boolean rosterIsThisRaid,
        int teamSizeMax,
        boolean captureWorked,
        boolean localPlayerInRoster
    )
    {
        if (liveTeamSize > 1)
        {
            return false;
        }
        if (rosterIsThisRaid)
        {
            if (teamSizeMax > 1)
            {
                return false;
            }
            if (teamSizeMax == 1)
            {
                return true;
            }
            return captureWorked || localPlayerInRoster;
        }
        return localPlayerInRoster;
    }

    /**
     * Which raid the local player is currently inside, from the raid *state*
     * varbits rather than teammate health orbs — the orbs read zero in
     * lobbies, during transitions, and after completion, which is exactly when
     * we still need to know a raid is (or was) in progress.
     */
    private String currentRaidType()
    {
        // ToB: 0=outside, 1=in party (lobby), 2=inside raid, 3=spectating
        if (client.getVarbitValue(THEATRE_OF_BLOOD_STATE) >= 2)
        {
            return RAID_TOB;
        }
        // ToA: 0=outside, 1=in party (lobby), 2=inside raid
        if (client.getVarbitValue(VarbitID.TOA_CLIENT_PARTYSTATUS) >= 2)
        {
            return RAID_TOA;
        }
        if (client.getVarbitValue(VarbitID.RAIDS_CLIENT_INDUNGEON) == 1)
        {
            return RAID_COX;
        }
        return null;
    }

    /** Reads the authoritative roster source for the given raid into {@code into}. */
    private void captureAuthoritativeRoster(String raidType, Set<String> into)
    {
        switch (raidType)
        {
            case RAID_TOB:
                captureVarcNames(VarClientID.TOB_CLIENT_NAME0, VarClientID.TOB_CLIENT_NAME4, into);
                break;
            case RAID_TOA:
                captureVarcNames(VarClientID.TOA_CLIENT_NAME0, VarClientID.TOA_CLIENT_NAME7, into);
                break;
            case RAID_COX:
                captureCoxSidepanelNames(into);
                break;
            default:
                break;
        }
    }

    /**
     * ToB/ToA publish the party roster in varcstrings (health-orb name slots),
     * which stay populated for the whole raid — and usually beyond — regardless
     * of where teammates are standing. Empty slots read as "" or "-".
     */
    private void captureVarcNames(int firstVarcId, int lastVarcId, Set<String> into)
    {
        for (int varc = firstVarcId; varc <= lastVarcId; varc++)
        {
            String name = normalizePlayerName(client.getVarcStrValue(varc));
            if (name != null && !"-".equals(name))
            {
                into.add(name);
            }
        }
    }

    /**
     * CoX has no roster varcstrings; the authoritative source is the
     * raiding-party sidepanel list, whose child widgets carry member names.
     * The widget stays loaded while in the party/raid even when another side
     * tab is selected.
     */
    private void captureCoxSidepanelNames(Set<String> into)
    {
        Widget list = client.getWidget(InterfaceID.RaidsSidepanel.LIST);
        if (list == null)
        {
            return;
        }
        Widget[] children = list.getChildren();
        if (children == null)
        {
            return;
        }
        for (Widget child : children)
        {
            if (child == null)
            {
                continue;
            }
            String name = normalizePlayerName(child.getName());
            if (name != null && !"-".equals(name))
            {
                into.add(name);
            }
        }
    }

    /**
     * Accumulates the proximity fallback roster while inside a raid. Inside an
     * instanced raid the only nearby players are the team, so this is a
     * reasonable stand-in when the authoritative source is unavailable — but it
     * is never preferred over it.
     *
     * <p>RuneLite's PartyService used to be merged in here as well. It is not
     * evidence of raid participation: party membership survives a member
     * logging out of the game entirely and spans unrelated activities, so on a
     * solo raid it attached whoever was still in the party from an earlier
     * session. Anyone genuinely in the instance is picked up by the scan below.
     */
    private void captureFallbackRoster()
    {
        Player localPlayer = client.getLocalPlayer();

        if (localPlayer != null && localPlayer.getWorldLocation() != null)
        {
            WorldPoint center = localPlayer.getWorldLocation();
            WorldView topLevel = client.getTopLevelWorldView();
            if (topLevel != null)
            {
                ScanStats ignored = new ScanStats();
                collectNamesFromWorldView(topLevel, center, ROSTER_SCAN_RADIUS_TILES, localPlayer, fallbackRoster, ignored);
                for (WorldView subWorldView : topLevel.worldViews())
                {
                    collectNamesFromWorldView(subWorldView, center, ROSTER_SCAN_RADIUS_TILES, localPlayer, fallbackRoster, ignored);
                }
            }
        }
    }

    public List<String> getNearbyPlayerNames(int radiusTiles)
    {
        return getNearbyPlayerTrace(radiusTiles).getNearbyPlayers();
    }

    /** Participant trace with no submission source: plain proximity scan. */
    public NearbyPlayerTrace getNearbyPlayerTrace(int radiusTiles)
    {
        return getParticipantsTrace(null, radiusTiles);
    }

    /**
     * Resolves the participants to attach to a submission from
     * {@code sourceName} (drop {@code source} / PB {@code boss_name}).
     * Raid sources get the authoritative raid roster; everything else gets a
     * proximity scan with no raid-roster merge.
     */
    public NearbyPlayerTrace getParticipantsTrace(String sourceName, int radiusTiles)
    {
        if (client.isClientThread())
        {
            return collectParticipantsTrace(sourceName, radiusTiles);
        }

        CompletableFuture<NearbyPlayerTrace> future = new CompletableFuture<>();
        clientThread.invoke(() ->
        {
            try
            {
                future.complete(collectParticipantsTrace(sourceName, radiusTiles));
            }
            catch (Exception e)
            {
                future.complete(NearbyPlayerTrace.empty(Math.max(1, radiusTiles), "client-thread collection exception: " + e.getMessage()));
            }
        });

        try
        {
            return future.get(500, TimeUnit.MILLISECONDS);
        }
        catch (Exception e)
        {
            return NearbyPlayerTrace.empty(Math.max(1, radiusTiles), "future timeout/exception: " + e.getMessage());
        }
    }

    private NearbyPlayerTrace collectParticipantsTrace(String sourceName, int radiusTiles)
    {
        Player localPlayer = client.getLocalPlayer();
        if (localPlayer == null || localPlayer.getWorldLocation() == null)
        {
            return NearbyPlayerTrace.empty(Math.max(1, radiusTiles), "local player unavailable");
        }

        WorldPoint center = localPlayer.getWorldLocation();
        int effectiveRadius = Math.max(1, radiusTiles);
        String localName = normalizePlayerName(localPlayer.getName());
        String submissionRaidType = raidTypeForSource(sourceName);

        int toaTeamCount = getToaTeamCount();
        int tobTeamCount = getTobTeamCount();
        int coxTeamCount = getCoxTeamCount();
        boolean inRaidContext = (toaTeamCount > 1) || (tobTeamCount > 1) || (coxTeamCount > 1) || currentRaidType() != null;

        Set<String> names = new LinkedHashSet<>();
        String rosterSource;
        boolean localPlayerInRoster = false;
        ScanStats scanStats = new ScanStats();

        if (submissionRaidType != null)
        {
            // Raid submission: participants come from the authoritative roster
            // only. Read it live first — the ToB/ToA varcstrings and the CoX
            // sidepanel usually remain populated at loot-chest time — and let
            // the accumulated roster (which survives the varbit reset at
            // completion) fill the slots the live read left empty, bounded by
            // what the raid can hold. See boundedRoster.
            Set<String> live = new LinkedHashSet<>();
            captureAuthoritativeRoster(submissionRaidType, live);
            Set<String> history = submissionRaidType.equals(activeRaidType)
                ? authoritativeRoster
                : Collections.<String>emptySet();
            Set<String> roster = boundedRoster(live, history, rosterCapacity(submissionRaidType));
            if (submissionRaidType.equals(activeRaidType))
            {
                authoritativeRoster.clear();
                authoritativeRoster.addAll(roster);
            }

            localPlayerInRoster = localName != null && roster.contains(localName);
            if (localName != null)
            {
                roster.remove(localName);
            }

            if (!roster.isEmpty())
            {
                names.addAll(roster);
                rosterSource = "authoritative";
            }
            else if (isSoloRaid(submissionRaidType, localPlayerInRoster))
            {
                // Alone in the raid: an empty participant list is the correct
                // answer, and the only correct one. Guessing from here is what
                // credited RuneLite party members who never entered the raid,
                // and — for a submission made back in the lobby — would scan in
                // whichever strangers happened to be standing around.
                rosterSource = "solo";
            }
            else
            {
                // Capture never ran this raid (e.g. plugin enabled mid-raid):
                // fall back to the accumulated proximity roster plus a live
                // scan so the participant list isn't empty (issue #43).
                if (submissionRaidType.equals(activeRaidType))
                {
                    names.addAll(fallbackRoster);
                }
                int fallbackRadius = Math.max(effectiveRadius, ROSTER_SCAN_RADIUS_TILES);
                scanWorldViews(center, fallbackRadius, localPlayer, names, scanStats);
                rosterSource = "proximity-fallback";
            }
        }
        else
        {
            // Non-raid submission: plain proximity scan. The raid roster is
            // deliberately NOT merged here.
            scanWorldViews(center, effectiveRadius, localPlayer, names, scanStats);
            rosterSource = "proximity";
        }

        String raidType = submissionRaidType != null
            ? submissionRaidType
            : (activeRaidType != null ? activeRaidType : "none");

        // Evidence for the server: how big this raid's party actually was.
        // 0 for non-raid submissions (the field is then omitted from payloads).
        int raidPartySize = 0;
        if (submissionRaidType != null)
        {
            int accumulated = submissionRaidType.equals(activeRaidType) ? raidTeamSizeMax : 0;
            raidPartySize = computeRaidPartySize(
                gameReportedTeamSize(submissionRaidType), accumulated, names.size());
        }

        NearbyPlayerTrace trace = new NearbyPlayerTrace(
            new ArrayList<>(names),
            effectiveRadius,
            localName,
            center,
            inRaidContext,
            raidType,
            sourceName,
            rosterSource,
            localPlayerInRoster,
            raidPartySize,
            toaTeamCount,
            tobTeamCount,
            coxTeamCount,
            partyService.isInParty(),
            partyService.isInParty() ? partyService.getMembers().size() : 0,
            scanStats.worldViewsScanned,
            scanStats.playersSeen,
            scanStats.playersWithinRadius,
            scanStats.playersAdded,
            authoritativeRoster.size(),
            fallbackRoster.size(),
            System.currentTimeMillis(),
            null
        );
        DebugLogger.log("[NearbyPlayerTracker] " + trace.toDebugSummary());
        return trace;
    }

    private void scanWorldViews(WorldPoint center, int radiusTiles, Player localPlayer, Set<String> names, ScanStats scanStats)
    {
        WorldView topLevel = client.getTopLevelWorldView();
        if (topLevel == null)
        {
            return;
        }
        collectNamesFromWorldView(topLevel, center, radiusTiles, localPlayer, names, scanStats);
        for (WorldView subWorldView : topLevel.worldViews())
        {
            collectNamesFromWorldView(subWorldView, center, radiusTiles, localPlayer, names, scanStats);
        }
    }

    private void collectNamesFromWorldView(
        WorldView worldView,
        WorldPoint center,
        int radiusTiles,
        Player localPlayer,
        Set<String> names,
        ScanStats scanStats
    )
    {
        if (worldView == null)
        {
            return;
        }
        scanStats.worldViewsScanned++;

        for (Player player : worldView.players())
        {
            scanStats.playersSeen++;
            if (player == null || player == localPlayer)
            {
                continue;
            }

            String playerName = player.getName();
            WorldPoint playerLocation = player.getWorldLocation();
            if (playerName == null || playerLocation == null)
            {
                continue;
            }

            if (playerLocation.getPlane() != center.getPlane())
            {
                continue;
            }

            if (center.distanceTo2D(playerLocation) > radiusTiles)
            {
                continue;
            }
            scanStats.playersWithinRadius++;

            String normalizedName = normalizePlayerName(playerName);
            if (normalizedName != null && names.add(normalizedName))
            {
                scanStats.playersAdded++;
            }
        }
    }

    @SuppressWarnings("deprecation")
    private static final int THEATRE_OF_BLOOD_STATE = Varbits.THEATRE_OF_BLOOD;

    @SuppressWarnings("deprecation")
    private int getToaTeamCount()
    {
        return Math.min(client.getVarbitValue(Varbits.TOA_MEMBER_0_HEALTH), 1) +
            Math.min(client.getVarbitValue(Varbits.TOA_MEMBER_1_HEALTH), 1) +
            Math.min(client.getVarbitValue(Varbits.TOA_MEMBER_2_HEALTH), 1) +
            Math.min(client.getVarbitValue(Varbits.TOA_MEMBER_3_HEALTH), 1) +
            Math.min(client.getVarbitValue(Varbits.TOA_MEMBER_4_HEALTH), 1) +
            Math.min(client.getVarbitValue(Varbits.TOA_MEMBER_5_HEALTH), 1) +
            Math.min(client.getVarbitValue(Varbits.TOA_MEMBER_6_HEALTH), 1) +
            Math.min(client.getVarbitValue(Varbits.TOA_MEMBER_7_HEALTH), 1);
    }

    @SuppressWarnings("deprecation")
    private int getTobTeamCount()
    {
        return Math.min(client.getVarbitValue(Varbits.THEATRE_OF_BLOOD_ORB1), 1) +
            Math.min(client.getVarbitValue(Varbits.THEATRE_OF_BLOOD_ORB2), 1) +
            Math.min(client.getVarbitValue(Varbits.THEATRE_OF_BLOOD_ORB3), 1) +
            Math.min(client.getVarbitValue(Varbits.THEATRE_OF_BLOOD_ORB4), 1) +
            Math.min(client.getVarbitValue(Varbits.THEATRE_OF_BLOOD_ORB5), 1);
    }

    private int getCoxTeamCount()
    {
        if (client.getVarbitValue(VarbitID.RAIDS_CLIENT_INDUNGEON) == 0)
        {
            return 0;
        }
        return Math.max(client.getVarbitValue(VarbitID.RAIDS_CLIENT_PARTYSIZE), 1);
    }

    private String normalizePlayerName(String rawName)
    {
        if (rawName == null)
        {
            return null;
        }

        String normalized = Text.toJagexName(Text.removeTags(rawName)).trim();
        return normalized.isEmpty() ? null : normalized;
    }

    private static final class ScanStats
    {
        int worldViewsScanned;
        int playersSeen;
        int playersWithinRadius;
        int playersAdded;
    }

    public static final class NearbyPlayerTrace
    {
        private final List<String> nearbyPlayers;
        private final int radiusTiles;
        private final String localPlayer;
        private final WorldPoint localWorldPoint;
        private final boolean inRaidContext;
        private final String raidType;
        private final String sourceName;
        private final String rosterSource;
        private final boolean localPlayerInRoster;
        private final int raidPartySize;
        private final int toaTeamCount;
        private final int tobTeamCount;
        private final int coxTeamCount;
        private final boolean inParty;
        private final int partySize;
        private final int worldViewsScanned;
        private final int playersSeen;
        private final int playersWithinRadius;
        private final int uniquePlayersAdded;
        private final int authoritativeRosterSize;
        private final int fallbackRosterSize;
        private final long capturedAtMs;
        private final String fallbackReason;

        private NearbyPlayerTrace(
            List<String> nearbyPlayers,
            int radiusTiles,
            String localPlayer,
            WorldPoint localWorldPoint,
            boolean inRaidContext,
            String raidType,
            String sourceName,
            String rosterSource,
            boolean localPlayerInRoster,
            int raidPartySize,
            int toaTeamCount,
            int tobTeamCount,
            int coxTeamCount,
            boolean inParty,
            int partySize,
            int worldViewsScanned,
            int playersSeen,
            int playersWithinRadius,
            int uniquePlayersAdded,
            int authoritativeRosterSize,
            int fallbackRosterSize,
            long capturedAtMs,
            String fallbackReason
        )
        {
            this.nearbyPlayers = nearbyPlayers;
            this.radiusTiles = radiusTiles;
            this.localPlayer = localPlayer;
            this.localWorldPoint = localWorldPoint;
            this.inRaidContext = inRaidContext;
            this.raidType = raidType;
            this.sourceName = sourceName;
            this.rosterSource = rosterSource;
            this.localPlayerInRoster = localPlayerInRoster;
            this.raidPartySize = raidPartySize;
            this.toaTeamCount = toaTeamCount;
            this.tobTeamCount = tobTeamCount;
            this.coxTeamCount = coxTeamCount;
            this.inParty = inParty;
            this.partySize = partySize;
            this.worldViewsScanned = worldViewsScanned;
            this.playersSeen = playersSeen;
            this.playersWithinRadius = playersWithinRadius;
            this.uniquePlayersAdded = uniquePlayersAdded;
            this.authoritativeRosterSize = authoritativeRosterSize;
            this.fallbackRosterSize = fallbackRosterSize;
            this.capturedAtMs = capturedAtMs;
            this.fallbackReason = fallbackReason;
        }

        public static NearbyPlayerTrace empty(int radiusTiles, String fallbackReason)
        {
            return new NearbyPlayerTrace(
                Collections.emptyList(),
                radiusTiles,
                null,
                null,
                false,
                "none",
                null,
                "none",
                false,
                0,
                0,
                0,
                0,
                false,
                0,
                0,
                0,
                0,
                0,
                0,
                0,
                System.currentTimeMillis(),
                fallbackReason
            );
        }

        public List<String> getNearbyPlayers()
        {
            return nearbyPlayers;
        }

        /** Where the participant list came from: {@code authoritative | solo | proximity-fallback | proximity | none}. */
        public String getRosterSource()
        {
            return rosterSource;
        }

        /** Best-evidence raid party size (receiver included); 0 for non-raid submissions. */
        public int getRaidPartySize()
        {
            return raidPartySize;
        }

        public String toDebugSummary()
        {
            String localPointSummary = localWorldPoint == null
                ? "unknown"
                : localWorldPoint.getX() + "," + localWorldPoint.getY() + "," + localWorldPoint.getPlane();
            return "radius=" + radiusTiles
                + ", localPlayer=" + (localPlayer != null ? localPlayer : "unknown")
                + ", localPoint=" + localPointSummary
                + ", inRaidContext=" + inRaidContext
                + ", raidType=" + raidType
                + ", sourceName=" + (sourceName != null ? sourceName : "none")
                + ", rosterSource=" + rosterSource
                + ", localPlayerInRoster=" + localPlayerInRoster
                + ", raidPartySize=" + raidPartySize
                + ", toaTeamCount=" + toaTeamCount
                + ", tobTeamCount=" + tobTeamCount
                + ", coxTeamCount=" + coxTeamCount
                + ", inParty=" + inParty
                + ", partySize=" + partySize
                + ", worldViewsScanned=" + worldViewsScanned
                + ", playersSeen=" + playersSeen
                + ", playersWithinRadius=" + playersWithinRadius
                + ", uniquePlayersAdded=" + uniquePlayersAdded
                + ", authoritativeRosterSize=" + authoritativeRosterSize
                + ", fallbackRosterSize=" + fallbackRosterSize
                + ", nearbyPlayers=" + nearbyPlayers
                + ", capturedAtMs=" + capturedAtMs
                + (fallbackReason != null ? ", fallbackReason=" + fallbackReason : "");
        }
    }
}

package io.droptracker.service;

import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.atomic.AtomicBoolean;

import javax.inject.Inject;
import javax.inject.Singleton;

import io.droptracker.DropTrackerConfig;
import io.droptracker.DropTrackerPlugin;
import io.droptracker.api.DropTrackerApi;
import io.droptracker.models.AchievementDiaryArea;
import io.droptracker.models.StateSnapshot;
import io.droptracker.models.api.Manifest;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.Quest;
import net.runelite.api.ScriptID;
import net.runelite.api.Skill;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;

/**
 * Builds and sends {@link StateSnapshot}s — the account's current state, which
 * the event submissions cannot describe.
 *
 * <p>Also owns the collection log items accumulated by the clog subscribers,
 * because they arrive asynchronously as the player browses and must survive
 * until the next sync sends them.
 */
@Slf4j
@Singleton
public class StateSyncService {

	private final Client client;
	private final ClientThread clientThread;
	private final DropTrackerConfig config;
	private final DropTrackerApi api;
	private final ManifestService manifestService;
	private final ScheduledExecutorService executor;
	private final DropTrackerPlugin plugin;

	/**
	 * Collection log slots seen so far this session, item id -> quantity.
	 *
	 * <p>Concurrent because the clog subscribers write from the client thread
	 * while a sync may be reading on an executor thread.
	 */
	private final Map<Integer, Integer> clogItems = new ConcurrentHashMap<>();

	/** Set once a full collection log read has completed this session. */
	private final AtomicBoolean clogComplete = new AtomicBoolean(false);

	/** Prevents overlapping syncs; a slow request must not queue up behind itself. */
	private final AtomicBoolean syncing = new AtomicBoolean(false);

	@Inject
	public StateSyncService(Client client,
	                        ClientThread clientThread,
	                        DropTrackerConfig config,
	                        DropTrackerApi api,
	                        ManifestService manifestService,
	                        ScheduledExecutorService executor,
	                        DropTrackerPlugin plugin) {
		this.client = client;
		this.clientThread = clientThread;
		this.config = config;
		this.api = api;
		this.manifestService = manifestService;
		this.executor = executor;
		this.plugin = plugin;
	}

	/** True when the user has opted in and the server has not switched sync off. */
	public boolean isEnabled() {
		if (!config.useApi() || !config.syncAccountState()) {
			return false;
		}
		Manifest manifest = manifestService.getManifest();
		return manifest == null || manifest.getSync().isEnabled();
	}

	/**
	 * Records a collection log slot the player has filled.
	 *
	 * <p>The zero check is a guard, not a filter: the game transmits a slot
	 * only once it has been obtained, so nothing legitimate arrives with a
	 * quantity of zero. It stays because "absent means not obtained" is what the
	 * server reads a complete snapshot as, and a zero slipping through would say
	 * the opposite.
	 */
	public void storeItem(int itemId, int quantity) {
		if (quantity <= 0) {
			return;
		}
		clogItems.put(itemId, quantity);
	}

	/** Marks the accumulated items as a complete read of the collection log. */
	public void markClogComplete() {
		clogComplete.set(true);
	}

	/**
	 * Drops everything accumulated so far.
	 *
	 * <p>Called when we might have been reading somebody else's collection log
	 * (the POH adventure log) or when the logged-in account changes — in both
	 * cases keeping the items would attribute them to the wrong player.
	 */
	public void clearItems() {
		clogItems.clear();
		clogComplete.set(false);
	}

	public void reset() {
		clearItems();
		syncing.set(false);
	}

	/**
	 * Collects a snapshot on the client thread.
	 *
	 * <p>Everything here is a client read, so it must not run anywhere else;
	 * the returned future completes on the client thread.
	 */
	public CompletableFuture<StateSnapshot> collect(String source) {
		CompletableFuture<StateSnapshot> future = new CompletableFuture<>();
		clientThread.invokeLater(() -> {
			try {
				future.complete(buildSnapshot(source));
			} catch (Exception e) {
				future.completeExceptionally(e);
			}
		});
		return future;
	}

	/**
	 * Collects and sends a snapshot, unless one is already in flight.
	 *
	 * <p>Failures are logged at debug and otherwise ignored: state sync is a
	 * background enhancement and must never surface an error for something the
	 * player did not ask for.
	 */
	public void sync(String source) {
		if (!isEnabled() || !isPlayerReady()) {
			return;
		}
		if (!syncing.compareAndSet(false, true)) {
			log.debug("State sync already in progress; skipping {}", source);
			return;
		}
		collect(source)
				.thenAcceptAsync(snapshot -> {
					try {
						api.postStateSnapshot(snapshot);
					} finally {
						syncing.set(false);
					}
				}, executor)
				.exceptionally(e -> {
					log.debug("State sync ({}) failed: {}", source, e.toString());
					syncing.set(false);
					return null;
				});
	}

	private boolean isPlayerReady() {
		return client.getGameState() == GameState.LOGGED_IN && client.getLocalPlayer() != null;
	}

	private StateSnapshot buildSnapshot(String source) {
		StateSnapshot snapshot = new StateSnapshot();
		Manifest manifest = manifestService.getManifest();

		Player local = client.getLocalPlayer();
		snapshot.setPlayerName(local != null ? local.getName() : null);
		snapshot.setAccountHash(String.valueOf(client.getAccountHash()));
		snapshot.setSource(source);
		snapshot.setPluginVersion(plugin.pluginVersion);
		snapshot.setManifestVersion(manifest != null ? manifest.getVersion() : null);
		snapshot.setAccountType(client.getVarbitValue(VarbitID.IRONMAN));
		snapshot.setCombatLevel(local != null ? local.getCombatLevel() : null);

		collectSkills(snapshot);
		collectQuests(snapshot, manifest);
		collectCombatAchievements(snapshot, manifest);
		collectDiaries(snapshot);
		collectCollectionLog(snapshot);

		return snapshot;
	}

	private void collectSkills(StateSnapshot snapshot) {
		Map<String, Integer> skills = new HashMap<>();
		for (Skill skill : Skill.values()) {
			skills.put(skill.getName(), client.getSkillExperience(skill));
		}
		snapshot.setSkills(skills);
	}

	/**
	 * Reads the state of every quest the manifest lists.
	 *
	 * <p>Iterating the manifest rather than RuneLite's {@link Quest} enum is the
	 * point: a quest released today is trackable today, instead of after a
	 * RuneLite release and a Plugin Hub build. An empty manifest list falls back
	 * to the enum so this still works before the manifest is populated.
	 */
	private void collectQuests(StateSnapshot snapshot, Manifest manifest) {
		int[] questIds = manifest != null && !manifest.getQuestIds().isEmpty()
				? manifest.getQuestIds().stream().mapToInt(Integer::intValue).toArray()
				: Arrays.stream(Quest.values()).mapToInt(Quest::getId).toArray();

		Map<Integer, Integer> quests = new HashMap<>();
		for (int questId : questIds) {
			try {
				// What Quest#getState does internally: the script leaves the
				// status on the int stack.
				client.runScript(ScriptID.QUEST_STATUS_GET, questId);
				quests.put(questId, questStateFrom(client.getIntStack()[0]));
			} catch (Exception e) {
				log.debug("Could not read quest {}: {}", questId, e.toString());
			}
		}
		snapshot.setQuests(quests);
	}

	/** Maps a QUEST_STATUS_GET result onto 0 not started / 1 in progress / 2 finished. */
	private static int questStateFrom(int status) {
		if (status == 1) {
			return 0;
		}
		if (status == 2) {
			return 2;
		}
		return 1;
	}

	/**
	 * Reads the combat achievement completion bits listed in the manifest.
	 *
	 * <p>Deliberately does nothing without a manifest: the varps are not a
	 * contiguous range, so there is no safe range to guess at, and sending a
	 * partial set would look like the player had un-completed tasks.
	 *
	 * <p>Raw varps only, no per-task breakdown. The server holds the task
	 * registry and decodes these bits into named, tiered, per-monster tasks when
	 * a profile is read, which means a registry correction applies retroactively
	 * to everything already stored — a decode done here could only ever be
	 * staler than that, and would still miss the tasks the registry has no entry
	 * for that the varps cover anyway.
	 */
	private void collectCombatAchievements(StateSnapshot snapshot, Manifest manifest) {
		if (manifest == null) {
			return;
		}
		Map<Integer, Integer> varps = new HashMap<>();
		for (int varpId : manifest.getCombatAchievementVarps()) {
			varps.put(varpId, client.getVarpValue(varpId));
		}
		snapshot.setCombatAchievementVarps(varps);
	}

	private void collectDiaries(StateSnapshot snapshot) {
		List<StateSnapshot.DiaryTier> tiers = new java.util.ArrayList<>();
		for (AchievementDiaryArea area : AchievementDiaryArea.values()) {
			int[] completed = area.getTiersCompletedCount(client);
			for (int tier = 0; tier < completed.length; tier++) {
				tiers.add(new StateSnapshot.DiaryTier(area.getId(), tier, completed[tier]));
			}
		}
		snapshot.setDiaryTiers(tiers);
	}

	private void collectCollectionLog(StateSnapshot snapshot) {
		snapshot.setItems(new HashMap<>(clogItems));
		snapshot.setClogComplete(clogComplete.get());

		// The game's own counters are correct even when we have read no items
		// at all, so a profile can show real progress before any scrape.
		int completed = client.getVarpValue(VarPlayerID.COLLECTION_COUNT);
		int total = client.getVarpValue(VarPlayerID.COLLECTION_COUNT_MAX);
		if (total > 0 && completed >= 0) {
			snapshot.setClogSlots(completed);
			snapshot.setClogSlotsTotal(total);
		}
	}
}

package io.droptracker.service;

import java.util.Arrays;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.atomic.AtomicBoolean;

import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;

import io.droptracker.DropTrackerConfig;
import io.droptracker.api.DropTrackerApi;
import io.droptracker.modelexport.GlbExporter;
import io.droptracker.models.api.ModelStatus;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Model;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.PlayerComposition;
import net.runelite.client.callback.ClientThread;

/**
 * Exports the local player's 3D model so their character — wearing whatever
 * they are wearing — can be rendered on the website and attached to
 * notifications.
 *
 * <p>Keyed by an <b>equipment fingerprint</b> rather than exported per event. A
 * GLB is a few hundred kilobytes; sending one with every personal best would be
 * absurd, and would mostly re-send an identical model. One upload per distinct
 * outfit is enough, because the render only changes when the outfit does.
 *
 * <p><b>Ask before sending.</b> Remembering only the last outfit was not enough:
 * a player alternating between two of them re-sent one on every switch, forever,
 * and the server measured four in five uploads as a model it already had (2026-09-14:
 * ~264k uploads a day, ~20% of them new). So an outfit the server may already
 * hold costs a ~200-byte question first, and the export — which runs on the
 * client thread — happens only when the answer is no. The question doubles as
 * how the server learns what the player is wearing, so switching back into known
 * gear still moves their profile.
 *
 * <p>Exports wait for the player to be <b>idle</b>. {@code Player#getModel()}
 * returns the current animation frame, so a model captured mid-attack is
 * captured mid-swing. Nothing here is time-critical, so waiting for a neutral
 * stance costs nothing and avoids a gallery of contorted characters.
 */
@Slf4j
@Singleton
public class PlayerModelService {

	/**
	 * Ticks the player must be idle before exporting. A couple of ticks avoids
	 * catching the tail of an animation that has technically ended.
	 */
	private static final int IDLE_TICKS_REQUIRED = 3;

	private final Client client;
	private final ClientThread clientThread;
	private final DropTrackerConfig config;
	private final DropTrackerApi api;
	private final ScheduledExecutorService executor;

	/**
	 * The outfit already settled with the server this session — either uploaded,
	 * or confirmed as one it holds. Null until the first is settled.
	 *
	 * <p>One entry rather than a set on purpose: switching back to an earlier
	 * outfit should ask again, because that question is what tells the server
	 * which outfit is being worn now.
	 */
	private volatile String settledFingerprint;

	/** Guards against two exports running at once — each one allocates a mesh. */
	private final AtomicBoolean exporting = new AtomicBoolean(false);

	private int idleTicks;

	/**
	 * When the next upload attempt is allowed, as a monotonic timestamp.
	 *
	 * <p>Without this a failing upload retries every tick: the fingerprint never
	 * gets recorded, the player is still idle, so the next tick exports and
	 * uploads again. A single 401 produced 258 requests in three minutes during
	 * testing, each one re-exporting the whole model.
	 */
	// Volatile: written on the executor, read on the client thread.
	private volatile long nextAttemptAtMs;

	/** How long to wait after a failed upload before trying that outfit again. */
	private static final long FAILURE_BACKOFF_MS = 5 * 60 * 1000L;

	/**
	 * The server does not know accounts it has never had a submission from, and
	 * would refuse a model from one. Wait rather than ask on every outfit change.
	 */
	private static final long UNKNOWN_ACCOUNT_BACKOFF_MS = 30 * 60 * 1000L;

	/**
	 * Floor on the gap between two uploads. Asking first already removes the
	 * repeat sends, but a player cycling through more outfits than the server
	 * keeps would miss every time, so this bounds what that can cost: a skipped
	 * upload is not recorded as settled, and the outfit goes up the next time
	 * they stand still in it.
	 */
	private static final long MIN_UPLOAD_INTERVAL_MS = 30 * 1000L;

	/** Earliest an upload may start, as a monotonic timestamp. */
	private volatile long nextUploadAtMs;

	@Inject
	public PlayerModelService(Client client,
	                          ClientThread clientThread,
	                          DropTrackerConfig config,
	                          DropTrackerApi api,
	                          ScheduledExecutorService executor) {
		this.client = client;
		this.clientThread = clientThread;
		this.config = config;
		this.api = api;
		this.executor = executor;
	}

	public boolean isEnabled() {
		return config.useApi() && config.uploadCharacterModel();
	}

	public void reset() {
		settledFingerprint = null;
		idleTicks = 0;
		nextAttemptAtMs = 0;
		nextUploadAtMs = 0;
		exporting.set(false);
	}

	/**
	 * Called each game tick. Settles the current outfit with the server when it
	 * has changed and the player has been idle long enough.
	 *
	 * <p>Nothing expensive happens here: whether to export is decided off this
	 * thread, once the server has said whether it needs the model.
	 *
	 * <p>Must be called on the client thread.
	 */
	public void onTick() {
		if (!isEnabled() || client.getGameState() != GameState.LOGGED_IN) {
			return;
		}

		Player local = client.getLocalPlayer();
		if (local == null) {
			return;
		}

		if (isAnimating(local)) {
			idleTicks = 0;
			return;
		}
		idleTicks++;
		if (idleTicks < IDLE_TICKS_REQUIRED) {
			return;
		}

		String fingerprint = fingerprintOf(local);
		if (fingerprint == null || fingerprint.equals(settledFingerprint)) {
			return;
		}
		if (System.currentTimeMillis() < nextAttemptAtMs) {
			return;
		}
		if (!exporting.compareAndSet(false, true)) {
			return;
		}

		// Read here because it is a client read, and it decides whether a model
		// the server already holds is still missing the pet beside it.
		final boolean petOut = client.getFollower() != null;
		try {
			executor.execute(() -> settle(fingerprint, petOut));
		} catch (RuntimeException e) {
			// Never let a refused submission hold the guard — or reach the tick.
			exporting.set(false);
			log.debug("Could not schedule the outfit check: {}", e.toString());
		}
	}

	/** What to do about an outfit once the server has answered. */
	enum Action {
		/** Export and send it. */
		UPLOAD,
		/** The server has it; nothing more to do this session. */
		SETTLED,
		/** The server does not know this account yet. */
		UNKNOWN_ACCOUNT,
		/** Held back by the upload floor; try again later. */
		WAIT
	}

	/**
	 * Pure decision, so the interesting cases are testable without a client.
	 *
	 * @param status what the server answered, or null when it could not be asked
	 *               — which must lead to an upload, the behaviour that predates
	 *               the check endpoint.
	 */
	static Action decide(@Nullable ModelStatus status, boolean petOut, long now, long nextUploadAtMs) {
		if (status != null && !status.isAccepted()) {
			return Action.UNKNOWN_ACCOUNT;
		}
		// A stored outfit can predate the pet now following the player, and the
		// fingerprint cannot say so — it covers the character, not the follower.
		if (status != null && status.hasModel() && (!petOut || status.hasPet())) {
			return Action.SETTLED;
		}
		if (now < nextUploadAtMs) {
			return Action.WAIT;
		}
		return Action.UPLOAD;
	}

	/** Asks the server about an outfit, then exports only if it needs one. */
	private void settle(String fingerprint, boolean petOut) {
		boolean release = true;
		try {
			Action action = decide(api.checkPlayerModel(fingerprint), petOut,
					System.currentTimeMillis(), nextUploadAtMs);
			switch (action) {
				case SETTLED:
					// The question itself told the server what is being worn,
					// which is all the re-upload it replaces ever achieved.
					settledFingerprint = fingerprint;
					nextAttemptAtMs = 0;
					log.debug("Server already holds outfit {}", fingerprint);
					break;
				case UNKNOWN_ACCOUNT:
					nextAttemptAtMs = System.currentTimeMillis() + UNKNOWN_ACCOUNT_BACKOFF_MS;
					break;
				case WAIT:
					// Hold the whole cycle, not just the upload: without this
					// the question would be asked again on the very next tick.
					nextAttemptAtMs = nextUploadAtMs;
					break;
				case UPLOAD:
				default:
					captureAndUpload(fingerprint);
					// Only now has the guard changed hands: if the hop threw,
					// the finally below has to release it.
					release = false;
					break;
			}
		} catch (Exception e) {
			log.debug("Could not settle outfit {}: {}", fingerprint, e.toString());
		} finally {
			if (release) {
				exporting.set(false);
			}
		}
	}

	/** Exports on the client thread, then uploads off it. */
	private void captureAndUpload(String fingerprint) {
		clientThread.invoke(() -> {
			byte[] model = null;
			byte[] petModel = null;
			try {
				Player local = client.getGameState() == GameState.LOGGED_IN
						? client.getLocalPlayer() : null;
				// The outfit can change between the question and the answer, and
				// a model exported for a different one would be filed under the
				// wrong key. The next tick picks the new one up.
				if (local != null && fingerprint.equals(fingerprintOf(local))) {
					model = exportModel(local);
					petModel = exportPet();
				}
			} catch (Exception e) {
				log.debug("Could not export the player model: {}", e.toString());
			}

			if (model == null) {
				exporting.set(false);
				return;
			}

			final byte[] modelBytes = model;
			final byte[] petBytes = petModel;
			// Upload off the client thread: it is a network round-trip with a
			// payload measured in tens of kilobytes. The guard is released by
			// whoever ends up owning the work, so a refused submission (the
			// executor is shutting down) has to release it here or the uploader
			// is stuck for the rest of the session.
			try {
				executor.execute(() -> {
					try {
						if (api.uploadPlayerModel(fingerprint, modelBytes, petBytes)) {
							settledFingerprint = fingerprint;
							nextAttemptAtMs = 0;
							nextUploadAtMs = System.currentTimeMillis() + MIN_UPLOAD_INTERVAL_MS;
							log.debug("Uploaded character model for outfit {}", fingerprint);
						} else {
							// Back off rather than re-exporting on the very next tick.
							nextAttemptAtMs = System.currentTimeMillis() + FAILURE_BACKOFF_MS;
							log.debug("Model upload failed; not retrying for {} minutes",
									FAILURE_BACKOFF_MS / 60000);
						}
					} finally {
						exporting.set(false);
					}
				});
			} catch (RuntimeException e) {
				exporting.set(false);
				throw e;
			}
		});
	}

	/**
	 * Manually captures the player's current model and pins it as their
	 * profile model on the website. Triggered by the panel's "Send Player
	 * Model" button, so unlike {@link #onTick()} it does not wait for the
	 * player to be idle — the player chose this exact moment — and it does not
	 * skip already-uploaded outfits, because the point is to (re)pin this one.
	 *
	 * <p>Deliberately gated only on {@link DropTrackerConfig#useApi()}, not on
	 * the automatic-upload toggle: pressing the button is explicit consent.
	 *
	 * <p>May be called from any thread; the capture hops to the client thread
	 * and the upload to the executor. The callback receives a short
	 * user-facing result message and always runs on the Swing EDT.
	 */
	public void sendCurrentModel(java.util.function.BiConsumer<Boolean, String> callback) {
		if (!config.useApi()) {
			finish(callback, false, "Enable the DropTracker API in the plugin settings first");
			return;
		}
		if (!exporting.compareAndSet(false, true)) {
			finish(callback, false, "Already sending a model — try again in a moment");
			return;
		}
		clientThread.invoke(() -> {
			Player local = client.getGameState() == GameState.LOGGED_IN
					? client.getLocalPlayer() : null;
			if (local == null) {
				exporting.set(false);
				finish(callback, false, "Log in to send your player model");
				return;
			}

			String fingerprint = fingerprintOf(local);
			byte[] model = null;
			byte[] petModel = null;
			try {
				model = exportModel(local);
				petModel = exportPet();
			} catch (Exception e) {
				log.debug("Could not export the player model: {}", e.toString());
			}
			if (fingerprint == null || model == null) {
				exporting.set(false);
				finish(callback, false, "Could not capture your model — try again");
				return;
			}

			final String fp = fingerprint;
			final byte[] modelBytes = model;
			final byte[] petBytes = petModel;
			executor.execute(() -> {
				boolean ok = false;
				try {
					ok = api.uploadPlayerModel(fp, modelBytes, petBytes, true);
				} catch (Exception e) {
					log.debug("Manual model upload failed: {}", e.toString());
				} finally {
					exporting.set(false);
				}
				if (ok) {
					// The automatic path now knows this outfit is settled.
					settledFingerprint = fp;
					nextAttemptAtMs = 0;
				}
				finish(callback, ok, ok
						? "Model sent! Your profile now shows this outfit"
						: "Upload failed — check your connection and try again");
			});
		});
	}

	private static void finish(java.util.function.BiConsumer<Boolean, String> callback,
	                           boolean ok, String message) {
		javax.swing.SwingUtilities.invokeLater(() -> callback.accept(ok, message));
	}

	/** True while the player is doing anything other than standing still. */
	private boolean isAnimating(Player local) {
		return local.getAnimation() != -1
				|| local.getPoseAnimation() != local.getIdlePoseAnimation();
	}

	@Nullable
	private byte[] exportModel(Player local) throws Exception {
		Model model = local.getModel();
		return model == null ? null : GlbExporter.toBytes(client, model, "player");
	}

	/**
	 * The player's pet, if one is following them. Optional in every sense: a
	 * failure here must not cost us the player's own model.
	 */
	@Nullable
	private byte[] exportPet() {
		try {
			NPC follower = client.getFollower();
			Model model = follower == null ? null : follower.getModel();
			return model == null ? null : GlbExporter.toBytes(client, model, "pet");
		} catch (Exception e) {
			log.debug("Could not export the pet model: {}", e.toString());
			return null;
		}
	}

	/**
	 * Fingerprint of the local player's current outfit, or null without one.
	 *
	 * <p>What a personal best attaches so the server can pair the time with the
	 * model of the outfit it was set in: the automatic upload files that model
	 * under exactly this key, so the two meet without any further exchange.
	 * Cheap (no export, no upload) and deliberately not gated on
	 * {@link #isEnabled()} - the caller owns the consent decision.
	 *
	 * <p>Must be called on the client thread.
	 */
	@Nullable
	public String currentFingerprint() {
		return client == null ? null : fingerprintOf(client.getLocalPlayer());
	}

	/**
	 * A stable identifier for "how this character currently looks".
	 *
	 * <p>Covers worn equipment, body kits and colours, because all three change
	 * the rendered model. Two players in identical gear produce the same
	 * fingerprint, which is fine — it keys a cache, not an identity.
	 */
	@Nullable
	String fingerprintOf(Actor actor) {
		if (!(actor instanceof Player)) {
			return null;
		}
		PlayerComposition composition = ((Player) actor).getPlayerComposition();
		if (composition == null) {
			return null;
		}

		int[] equipment = composition.getEquipmentIds();
		int[] colors = composition.getColors();
		if (equipment == null) {
			return null;
		}

		// A plain hash rather than a cryptographic digest: this is a cache key,
		// and collisions cost at most a stale render.
		int hash = 17;
		hash = hash * 31 + Arrays.hashCode(equipment);
		hash = hash * 31 + (colors == null ? 0 : Arrays.hashCode(colors));
		hash = hash * 31 + composition.getGender();
		return Integer.toHexString(hash);
	}
}

package io.droptracker.service;

import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

import javax.inject.Inject;
import javax.inject.Singleton;

import lombok.extern.slf4j.Slf4j;
import org.jetbrains.annotations.VisibleForTesting;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.GameState;
import net.runelite.api.ItemComposition;
import net.runelite.api.StructComposition;
import net.runelite.client.game.ItemManager;

/**
 * Which item ids the collection log actually has slots for, read from the cache.
 *
 * <p>Needed because a collection log <em>unlock</em> reaches us as a chat
 * message carrying only the item's name, and a name does not identify an item.
 * {@link io.droptracker.util.ItemIDSearch} answers with the earliest id sharing
 * that name, which for a duplicated name is the wrong one: the collection log's
 * Coal bag is 25627, the item cache says 764. Recording the wrong id leaves the
 * slot looking unfilled on the player's profile, and puts an id that is not a
 * slot into the account's item map.
 *
 * <p>The cache states the answer outright. Walking it costs one pass over five
 * structs and their page enums:
 *
 * <pre>
 *   enum 2102         -> the five tab structs
 *   tab struct  p683  -> enum of page structs
 *   page struct p690  -> enum of item ids
 *   enum 3721         -> id replacements
 * </pre>
 *
 * <p><b>Enum 3721 is not optional.</b> A dozen slots are stored against one id
 * and drawn as another — the Coal bag's page entry is 12019, the log draws
 * 25627 — and the game remaps through 3721 before drawing, so the replaced id
 * is what the collection log reports and what the server stores.
 *
 * <p>The walk comes from WikiSync (github.com/weirdgloop/WikiSync), Copyright
 * (c) 2021, andmcadams, BSD 2-Clause License (see LICENSE), which reads the same
 * enums for the same reason.
 */
@Slf4j
@Singleton
public class CollectionLogSlots {

	/** Enum holding the collection log's top level tab structs. */
	private static final int TAB_ENUM = 2102;
	/** Tab struct param: the enum of page structs under that tab. */
	private static final int PARAM_TAB_PAGES = 683;
	/** Page struct param: the enum of item ids on that page. */
	private static final int PARAM_PAGE_ITEMS = 690;
	/** Enum mapping a page's stored item id onto the id the log draws. */
	private static final int REPLACEMENT_ENUM = 3721;

	private final Client client;
	private final ItemManager itemManager;

	/** Every slot id, or empty until the first successful read. */
	private Set<Integer> slotIds = new HashSet<>();

	/**
	 * Slot name -> id, built only when a lookup by name is actually needed.
	 *
	 * <p>Names that belong to more than one slot map to null: every Graceful
	 * piece and all the decorative armour exist several times over, and a chat
	 * message naming one cannot say which was unlocked.
	 */
	private Map<String, Integer> slotByName = null;

	@Inject
	public CollectionLogSlots(Client client, ItemManager itemManager) {
		this.client = client;
		this.itemManager = itemManager;
	}

	/** Drops the cached read, so a new session re-reads the cache. */
	public void reset() {
		slotIds = new HashSet<>();
		slotByName = null;
	}

	/**
	 * The id the collection log records for a newly unlocked item.
	 *
	 * <p>Must be called on the client thread. Returns {@code candidate} when it
	 * is already a slot, the right slot when the candidate is a same-named
	 * impostor, and null when neither is true — an unknown name, or one that
	 * several slots share. Null means "do not record this": the next full read
	 * of the log reports the slot properly, so guessing here would only write
	 * something wrong in the meantime.
	 */
	public Integer resolve(Integer candidate, String itemName) {
		if (!load()) {
			// Without the cache there is nothing to check against; the caller's
			// candidate is as good as it gets.
			return candidate;
		}
		return resolve(candidate, itemName, slotIds, byName());
	}

	/**
	 * The rule itself, separated from the cache read so it can be tested.
	 *
	 * <p>{@code slotByName} maps a lowercased slot name onto its id, with names
	 * shared by several slots mapped to null — see {@link #indexByName}.
	 */
	@VisibleForTesting
	static Integer resolve(Integer candidate, String itemName,
	                       Set<Integer> slotIds, Map<String, Integer> slotByName) {
		if (candidate != null && slotIds.contains(candidate)) {
			return candidate;
		}
		if (itemName == null || itemName.trim().isEmpty()) {
			return null;
		}
		return slotByName.get(itemName.trim().toLowerCase());
	}

	/**
	 * Lowercased slot name -> its id, with ambiguous names mapped to null.
	 *
	 * <p>Null rather than absent so the distinction survives: a name several
	 * slots share is one we must refuse to answer, not one we have never seen.
	 * Every Graceful piece and all the decorative armour land here.
	 */
	@VisibleForTesting
	static Map<String, Integer> indexByName(Map<Integer, String> namesById) {
		Map<String, Integer> byName = new HashMap<>();
		for (Map.Entry<Integer, String> entry : namesById.entrySet()) {
			String name = entry.getValue();
			if (name == null || name.isEmpty() || "null".equals(name)) {
				continue;
			}
			String key = name.toLowerCase();
			byName.put(key, byName.containsKey(key) ? null : entry.getKey());
		}
		return byName;
	}

	/** True once the slot ids have been read. Must be on the client thread. */
	public boolean load() {
		if (!slotIds.isEmpty()) {
			return true;
		}
		if (client.getGameState() != GameState.LOGGED_IN) {
			// The cache is only reliably readable once the client has loaded.
			return false;
		}

		try {
			Map<Integer, Integer> replacements = new HashMap<>();
			EnumComposition replacementEnum = client.getEnum(REPLACEMENT_ENUM);
			if (replacementEnum != null) {
				int[] keys = replacementEnum.getKeys();
				int[] values = replacementEnum.getIntVals();
				for (int i = 0; i < keys.length && i < values.length; i++) {
					replacements.put(keys[i], values[i]);
				}
			}

			Set<Integer> found = new HashSet<>();
			for (int tabStructId : client.getEnum(TAB_ENUM).getIntVals()) {
				StructComposition tabStruct = client.getStructComposition(tabStructId);
				for (int pageStructId : client.getEnum(tabStruct.getIntValue(PARAM_TAB_PAGES)).getIntVals()) {
					StructComposition pageStruct = client.getStructComposition(pageStructId);
					for (int itemId : client.getEnum(pageStruct.getIntValue(PARAM_PAGE_ITEMS)).getIntVals()) {
						found.add(replacements.getOrDefault(itemId, itemId));
					}
				}
			}

			if (found.isEmpty()) {
				log.debug("Collection log structure read produced no slots");
				return false;
			}
			slotIds = found;
			log.debug("Read {} collection log slots from the cache", found.size());
			return true;
		} catch (Exception e) {
			// A cache the client has not loaded, or an enum that moved in a game
			// update. Neither is worth failing an unlock over.
			log.debug("Could not read the collection log structure: {}", e.toString());
			return false;
		}
	}

	/** Lazily names every slot; only an unrecognised id ever needs this. */
	private Map<String, Integer> byName() {
		if (slotByName != null) {
			return slotByName;
		}
		Map<Integer, String> namesById = new HashMap<>();
		for (int itemId : slotIds) {
			try {
				ItemComposition composition = itemManager.getItemComposition(itemId);
				namesById.put(itemId, composition == null ? null : composition.getName());
			} catch (Exception e) {
				log.debug("Could not name collection log slot {}: {}", itemId, e.toString());
			}
		}
		slotByName = indexByName(namesById);
		return slotByName;
	}
}

package io.droptracker.service;

import io.droptracker.DropTrackerConfig;
import io.droptracker.api.DropTrackerApi;
import io.droptracker.models.api.EventNotification;
import io.droptracker.models.api.EventState;
import io.droptracker.util.ChatMessageUtil;
import io.droptracker.util.DebugLogger;
import io.droptracker.util.ValueFormat;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.util.Text;
import okhttp3.Call;

import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentLinkedDeque;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;

/**
 * In-game event notifications + HUD state (EVENT_PLUGIN_NOTIFICATIONS_PLAN P2).
 *
 * Long-polls GET /notifications?wait={@value #LONG_POLL_WAIT_SECONDS} while
 * the server reports a live event tracking this player (the
 * {@code active_event} flag in the group configs / notifications response):
 * the server holds an empty-inbox request open until a notification lands,
 * so delivery is near-immediate, and each completed request immediately
 * re-issues the next. Servers that predate the {@code wait} param (no
 * {@code long_poll: true} in the response) fall back to a fixed
 * {@value #POLL_INTERVAL_SECONDS}s poll. The held call runs on OkHttp's own
 * dispatcher via enqueue — the shared client executor is only ever used to
 * schedule the next cycle, never blocked through a hold. Each typed envelope
 * dispatches through a hardcoded renderer registry (unknown types are
 * dropped silently — the forward-compatibility contract), and the service
 * keeps the {@code /event_state} snapshot the HUD and Events tab render.
 *
 * Stacking rules: envelopes are processed per poll as one batch, grouped by
 * event — at most ONE pop-up per batch (coalesced across events, headlined by
 * the most important update), chat collapses beyond
 * {@value #MAX_CHAT_LINES_PER_EVENT} lines per event, a seen-id LRU guards
 * against replays, and at most one state refresh runs per batch. Pop-ups are
 * additionally deduped by (event, task, type) for
 * {@value #TOAST_DEDUPE_WINDOW_MS}ms across batches, and their lifetime and
 * styling follow the envelope's {@code priority} tier.
 */
@Slf4j
@Singleton
public class EventNotificationService {
    /** Fallback poll cadence for legacy servers that ignore the wait param. */
    static final int POLL_INTERVAL_SECONDS = 10;
    /** Requested server-side hold per long-poll (the server clamps to its cap). */
    static final int LONG_POLL_WAIT_SECONDS = 25;
    /** Pause between held polls so a busy inbox can't turn into a hot loop. */
    private static final long REISSUE_DELAY_MS = 250;
    /**
     * An allegedly-held poll that returns empty this fast wasn't actually
     * held (misbehaving proxy/server); use the legacy cadence for that cycle.
     */
    private static final long SUSPICIOUS_FAST_EMPTY_MS = 1500;
    private static final long MAX_FAILURE_BACKOFF_MS = 60_000L;
    private static final int SEEN_IDS_MAX = 200;
    /**
     * Catch-up digest gate: the session's first non-empty batch collapses
     * into a "while you were away" summary instead of a message flood, when
     * it is at least this big and provably stale (an envelope older than
     * {@link #CATCHUP_MIN_AGE_SECONDS} — inbox entries survive 24h offline).
     */
    private static final int CATCHUP_MIN_ENVELOPES = 4;
    private static final long CATCHUP_MIN_AGE_SECONDS = 600;
    private static final int MAX_CHAT_LINES_PER_EVENT = 3;
    /** Indented detail lines under the catch-up header (plus that header). */
    private static final int CATCHUP_MAX_DETAIL_LINES = 4;
    private static final int MAX_TOASTS_QUEUED = 6;
    /**
     * A pop-up about the same (event, task, type) inside this window is the
     * same update to a human — a task ticking twice in a breath (two players
     * feeding it, a re-drain) must not queue twice.
     */
    static final long TOAST_DEDUPE_WINDOW_MS = 10_000L;
    private static final int TOAST_KEYS_MAX = 32;
    /** Re-check the active_event flag this often when idle (no live event). */
    private static final int IDLE_RECHECK_SECONDS = 60;
    /** Recheck cadence for a 404 (identity not registered) — terminal-ish. */
    private static final long NOT_REGISTERED_RECHECK_MS =
        TimeUnit.MINUTES.toMillis(10);
    private static final int MAX_TEXT_LENGTH = 120;

    private final DropTrackerConfig config;
    private final DropTrackerApi api;
    private final ChatMessageUtil chatMessageUtil;
    private final Client client;
    private final ScheduledExecutorService executor;
    private final ConfigManager configManager;
    private final ClanRelayService clanRelayService;

    /** Next scheduled poll cycle; guarded by {@code this}. */
    private ScheduledFuture<?> pollTask;
    private final AtomicBoolean running = new AtomicBoolean(false);
    /** Set while a cycle (including its in-flight HTTP call) owns the chain. */
    private final AtomicBoolean cycleInFlight = new AtomicBoolean(false);
    @Nullable
    private volatile Call inFlightCall;
    /** Only mutated by the single in-flight cycle chain. */
    private volatile int consecutiveFailures = 0;
    /** Cleared when a wait-request comes back without long_poll=true. */
    private volatile boolean serverSupportsLongPoll = true;
    /**
     * Last server-reported active_event. Authoritative over the cached group
     * config for choosing the wait mode: the config cache refreshes on
     * login/XP/submission (all throttled) and NEVER for an idle player, so
     * when an event went live the plugin used to keep sending plain polls —
     * which reissued at {@link #REISSUE_DELAY_MS} — a permanent ~4 req/s hot
     * loop exactly at event start (audit P0-2).
     */
    private volatile boolean serverReportedActiveEvent = false;
    /** True until the session's first non-empty batch (catch-up candidate). */
    private volatile boolean firstBatchOfSession = true;

    /** LRU of processed envelope ids (replay guard). */
    private final Map<String, Boolean> seenIds =
        Collections.synchronizedMap(new LinkedHashMap<String, Boolean>() {
            @Override
            protected boolean removeEldestEntry(Map.Entry<String, Boolean> eldest) {
                return size() > SEEN_IDS_MAX;
            }
        });

    /** Toasts pending display; consumed by EventToastOverlay. */
    @Getter
    private final ConcurrentLinkedDeque<Toast> toasts = new ConcurrentLinkedDeque<>();

    /** Last shown-at per pop-up dedupe key; guarded by its own monitor. */
    private final Map<String, Long> recentToastKeys =
        new LinkedHashMap<String, Long>() {
            @Override
            protected boolean removeEldestEntry(Map.Entry<String, Long> eldest) {
                return size() > TOAST_KEYS_MAX;
            }
        };

    /** Latest /event_state snapshot (HUD + Events tab). */
    @Getter
    @Nullable
    private volatile EventState eventState;
    private volatile long eventStateAtMs = 0;

    /**
     * Invoked (off-EDT) whenever a fresh event state lands.
     *
     * A list rather than a single slot: the side panel and the clan-chat team
     * indicators both hang off this signal, and with one setter the second
     * registration silently replaced the first — the panel would simply stop
     * refreshing, with nothing in the log to say why.
     */
    private final List<Runnable> stateUpdatedListeners = new CopyOnWriteArrayList<>();

    /**
     * Stamped by EventHudOverlay each frame it paints. While fresh, the HUD
     * renders pop-ups as nudges anchored beneath itself and the stand-alone
     * toast overlay stays quiet — exactly one owner draws the queue, and the
     * user only ever positions the HUD.
     */
    private volatile long hudRenderedAtMs = 0;

    public void markHudRendered() {
        hudRenderedAtMs = System.currentTimeMillis();
    }

    /** True while the HUD painted within the last second. */
    public boolean hudOwnsToasts() {
        return System.currentTimeMillis() - hudRenderedAtMs < 1000;
    }

    @Inject
    public EventNotificationService(DropTrackerConfig config, DropTrackerApi api,
                                    ChatMessageUtil chatMessageUtil, Client client,
                                    ScheduledExecutorService executor,
                                    ConfigManager configManager,
                                    ClanRelayService clanRelayService) {
        this.config = config;
        this.api = api;
        this.chatMessageUtil = chatMessageUtil;
        this.client = client;
        this.executor = executor;
        this.configManager = configManager;
        this.clanRelayService = clanRelayService;
    }

    /* ===================== lifecycle ===================== */

    public void start() {
        if (!running.compareAndSet(false, true)) {
            return;
        }
        serverSupportsLongPoll = true;
        serverReportedActiveEvent = false;
        consecutiveFailures = 0;
        firstBatchOfSession = true;
        scheduleNext(POLL_INTERVAL_SECONDS * 1000L);
    }

    public void stop() {
        running.set(false);
        synchronized (this) {
            if (pollTask != null) {
                pollTask.cancel(false);
                pollTask = null;
            }
        }
        Call call = inFlightCall;
        if (call != null) {
            call.cancel();
        }
        toasts.clear();
        synchronized (recentToastKeys) {
            recentToastKeys.clear();
        }
        eventState = null;
        eventStateAtMs = 0;
    }

    private boolean enabled() {
        // The poll loop serves two consumers: event notifications and the
        // Discord→game chat bridge. Either keeps it alive.
        return config.useApi()
            && (config.eventNotifications() || clanRelayService.discordChatActive());
    }

    private void scheduleNext(long delayMs) {
        if (!running.get()) {
            return;
        }
        synchronized (this) {
            if (!running.get()) {
                return;
            }
            pollTask = executor.schedule(this::runCycleSafely, delayMs, TimeUnit.MILLISECONDS);
        }
    }

    private void runCycleSafely() {
        try {
            runCycle();
        } catch (Exception e) {
            log.debug("event notification cycle failed: {}", e.getMessage());
            cycleInFlight.set(false);
            scheduleNext(POLL_INTERVAL_SECONDS * 1000L);
        }
    }

    /**
     * One poll cycle. Runs briefly on the shared executor: it only picks the
     * wait mode and enqueues the HTTP call; the OkHttp callback processes the
     * response and schedules the next cycle. Exactly one cycle owns the chain
     * at a time ({@link #cycleInFlight}); the flag is always cleared before
     * the owner schedules its successor, so the chain cannot strand itself.
     */
    private void runCycle() {
        if (!running.get() || !cycleInFlight.compareAndSet(false, true)) {
            return;
        }
        boolean handedOff = false;
        try {
            if (!enabled()) {
                scheduleNext(IDLE_RECHECK_SECONDS * 1000L);
                return;
            }
            final String playerName = client.getLocalPlayer() != null
                ? client.getLocalPlayer().getName() : null;
            final long accountHash = client.getAccountHash();
            if (playerName == null || accountHash == -1L) {
                scheduleNext(POLL_INTERVAL_SECONDS * 1000L);
                return;
            }
            // Idle (no live event): a plain poll checks the authoritative
            // active_event flag; long-holds are reserved for live events.
            // The server's own last report ORs in so a just-started event
            // flips us to held long-polls immediately instead of waiting for
            // the (throttled, maybe-never) config cache refresh (P0-2). The
            // chat bridge holds too — Discord lines should land in seconds.
            final boolean bridgeActive = clanRelayService.discordChatActive();
            final int waitSeconds =
                ((api.hasActiveEvent() || serverReportedActiveEvent || bridgeActive)
                    && serverSupportsLongPoll)
                ? LONG_POLL_WAIT_SECONDS : 0;
            // The clan param doubles as the bridge presence heartbeat: the
            // server fans Discord lines out only to players it has seen
            // polling with this clan recently.
            final String bridgeClan = bridgeActive
                ? clanRelayService.getCurrentClanName() : null;
            Call call = api.newNotificationsCall(playerName, accountHash, waitSeconds, bridgeClan);
            if (call == null) {
                scheduleNext(POLL_INTERVAL_SECONDS * 1000L);
                return;
            }
            inFlightCall = call;
            final long startedAtMs = System.currentTimeMillis();
            try {
                call.enqueue(new okhttp3.Callback() {
                    @Override
                    public void onFailure(okhttp3.Call c, java.io.IOException e) {
                        inFlightCall = null;
                        cycleInFlight.set(false);
                        if (!running.get() || c.isCanceled()) {
                            return;
                        }
                        consecutiveFailures++;
                        log.debug("/notifications poll failed: {}", e.getMessage());
                        scheduleNext(failureBackoffMs());
                    }

                    @Override
                    public void onResponse(okhttp3.Call c, okhttp3.Response response) {
                        inFlightCall = null;
                        long nextDelayMs;
                        try {
                            final int httpCode = response.code();
                            DropTrackerApi.NotificationsResponse parsed;
                            try (okhttp3.Response r = response) {
                                parsed = api.parseNotificationsResponse(r);
                            }
                            if (parsed == null) {
                                if (httpCode == 404) {
                                    // Not a registered player: terminal for
                                    // this identity, not a server fault —
                                    // recheck rarely instead of retrying the
                                    // failure backoff forever (audit).
                                    consecutiveFailures = 0;
                                    nextDelayMs = NOT_REGISTERED_RECHECK_MS;
                                } else {
                                    consecutiveFailures++;
                                    nextDelayMs = failureBackoffMs();
                                }
                            } else {
                                consecutiveFailures = 0;
                                handleResponse(parsed, playerName, accountHash);
                                nextDelayMs = nextDelayMs(parsed, waitSeconds,
                                    System.currentTimeMillis() - startedAtMs);
                            }
                        } catch (Exception e) {
                            log.debug("/notifications processing failed: {}", e.getMessage());
                            nextDelayMs = POLL_INTERVAL_SECONDS * 1000L;
                        } finally {
                            cycleInFlight.set(false);
                        }
                        scheduleNext(nextDelayMs);
                    }
                });
                handedOff = true;
            } catch (Exception e) {
                inFlightCall = null;
                log.debug("/notifications enqueue failed: {}", e.getMessage());
                scheduleNext(POLL_INTERVAL_SECONDS * 1000L);
            }
        } finally {
            if (!handedOff) {
                cycleInFlight.set(false);
            }
        }
    }

    /** Runs on the OkHttp callback thread (off-EDT, off-client-thread). */
    private void handleResponse(DropTrackerApi.NotificationsResponse response,
                                String playerName, long accountHash) {
        List<EventNotification> fresh = new ArrayList<>();
        if (response.notifications != null) {
            for (EventNotification n : response.notifications) {
                if (n == null || n.getType() == null) {
                    continue;
                }
                if (n.getId() != null && seenIds.put(n.getId(), Boolean.TRUE) != null) {
                    continue; // replay
                }
                fresh.add(n);
            }
        }
        // Bridge lines are chat, not event state: render them immediately and
        // keep them out of the event grouping/catch-up machinery entirely.
        fresh = renderAndStripClanChat(fresh);
        if (!fresh.isEmpty()) {
            DebugLogger.log("[EventNotifications] batch size=" + fresh.size());
            boolean catchUp = firstBatchOfSession && isCatchUpBatch(fresh);
            firstBatchOfSession = false;
            renderBatch(fresh, catchUp);
        }
        if (Boolean.TRUE.equals(response.activeEvent)) {
            serverReportedActiveEvent = true;
        } else if (Boolean.FALSE.equals(response.activeEvent)) {
            serverReportedActiveEvent = false;
        }
        long sinceStateMs = System.currentTimeMillis() - eventStateAtMs;
        boolean stateStale = sinceStateMs > TimeUnit.MINUTES.toMillis(3);
        // Fresh-batch refreshes are coalesced (audit P0-14): notifications
        // fan out to whole teams, and every teammate re-fetching the heavy
        // /event_state on every batch turned one completion into N
        // compositions at once. The batch itself already carries the
        // headline info; the full snapshot follows within the cooldown.
        boolean cooledDown = sinceStateMs > TimeUnit.SECONDS.toMillis(20);
        if ((eventState == null || stateStale || (!fresh.isEmpty() && cooledDown))
                && Boolean.TRUE.equals(response.activeEvent)) {
            refreshEventState(playerName, accountHash);
        }
        if (Boolean.FALSE.equals(response.activeEvent) && eventState != null) {
            // Event(s) ended: clear the HUD snapshot.
            eventState = null;
            notifyStateUpdated();
        }
    }

    /** Age past which a bridge chat line is history, not conversation. */
    private static final long BRIDGE_LINE_MAX_AGE_SECONDS = 120;

    /** Server-side cap for Discord→game lines (clan_chat_bridge.py). */
    private static final int BRIDGE_MESSAGE_MAX_CHARS = 200;

    /**
     * Renders {@code clan_chat_message} envelopes (Discord→game bridge) as
     * clan-styled chat lines and returns the batch without them. Stale lines
     * — an offline backlog draining on login — are silently dropped: chat
     * from twenty minutes ago is noise, exactly like real clan chat you
     * weren't online for.
     */
    private List<EventNotification> renderAndStripClanChat(List<EventNotification> batch) {
        if (batch.isEmpty()) {
            return batch;
        }
        List<EventNotification> remainder = new ArrayList<>(batch.size());
        long nowSeconds = System.currentTimeMillis() / 1000L;
        for (EventNotification n : batch) {
            if (!"clan_chat_message".equals(n.getType())) {
                remainder.add(n);
                continue;
            }
            if (!config.receiveDiscordChat()) {
                continue;
            }
            EventNotification.Data data = n.getData();
            String sender = data != null ? clean(data.getSender()) : null;
            // Matches the server's DISCORD_TO_GAME_MAX_CHARS (200) — the
            // generic 120 cap would re-truncate lines the backend already
            // capped, silently eating the tail of longer Discord messages.
            String message = data != null ? clean(data.getMessage(), BRIDGE_MESSAGE_MAX_CHARS) : null;
            if (sender == null || message == null) {
                continue;
            }
            if (n.getTs() > 0 && nowSeconds - n.getTs() > BRIDGE_LINE_MAX_AGE_SECONDS) {
                continue;
            }
            chatMessageUtil.sendDiscordClanMessage(sender, message);
        }
        return remainder;
    }

    /** Delay before the next cycle, from the just-finished poll's outcome. */
    private long nextDelayMs(DropTrackerApi.NotificationsResponse response,
                             int waitRequestedSeconds, long elapsedMs) {
        boolean active = Boolean.TRUE.equals(response.activeEvent) || api.hasActiveEvent()
            || clanRelayService.discordChatActive();
        if (!active) {
            return IDLE_RECHECK_SECONDS * 1000L;
        }
        if (waitRequestedSeconds > 0) {
            if (!Boolean.TRUE.equals(response.longPoll)) {
                // Legacy server: the wait param was ignored. Stop asking and
                // poll on the fixed cadence for the rest of the session.
                serverSupportsLongPoll = false;
                DebugLogger.log("[EventNotifications] server lacks long-poll; using fixed cadence");
                return POLL_INTERVAL_SECONDS * 1000L;
            }
            boolean empty = response.notifications == null || response.notifications.isEmpty();
            if (empty && elapsedMs < SUSPICIOUS_FAST_EMPTY_MS) {
                return POLL_INTERVAL_SECONDS * 1000L;
            }
            return REISSUE_DELAY_MS;
        }
        // Plain poll while an event is live (idle flip or legacy mode). Only
        // fast-reissue when the server itself confirmed the event — the next
        // cycle then upgrades to a HELD long-poll (serverReportedActiveEvent
        // is set). Any other plain-poll outcome paces at the fixed cadence:
        // a cache-only "active" must never spin at REISSUE_DELAY_MS (P0-2).
        boolean nextCycleWillHold =
            serverSupportsLongPoll && Boolean.TRUE.equals(response.activeEvent);
        return nextCycleWillHold ? REISSUE_DELAY_MS : POLL_INTERVAL_SECONDS * 1000L;
    }

    private long failureBackoffMs() {
        int failures = Math.max(1, Math.min(consecutiveFailures, 5));
        return Math.min(MAX_FAILURE_BACKOFF_MS, 5000L * (1L << (failures - 1)));
    }

    /** Fetch the state snapshot now (panel open / manual refresh). Off-EDT. */
    public void refreshEventStateNow() {
        String playerName = client.getLocalPlayer() != null
            ? client.getLocalPlayer().getName() : null;
        long accountHash = client.getAccountHash();
        if (playerName == null || accountHash == -1L || !enabled()) {
            return;
        }
        refreshEventState(playerName, accountHash);
    }

    private void refreshEventState(String playerName, long accountHash) {
        EventState state = api.fetchEventState(playerName, accountHash);
        if (state != null) {
            eventState = state;
            eventStateAtMs = System.currentTimeMillis();
            notifyStateUpdated();
        }
    }

    /**
     * Item ids the server wants force-screenshotted for event proof, from the
     * latest /event_state snapshot. Empty when no event is live, the API is
     * disabled (the service never polls), or the server predates the field.
     */
    public Set<Integer> getEventScreenshotItemIds() {
        EventState state = eventState;
        List<Integer> ids = state != null ? state.getScreenshotItemIds() : null;
        if (ids == null || ids.isEmpty()) {
            return Collections.emptySet();
        }
        return new LinkedHashSet<>(ids);
    }

    /** Register a listener for fresh state. Safe to call more than once. */
    public void addStateUpdatedListener(Runnable listener) {
        if (listener != null) {
            stateUpdatedListeners.add(listener);
        }
    }

    public void removeStateUpdatedListener(Runnable listener) {
        if (listener != null) {
            stateUpdatedListeners.remove(listener);
        }
    }

    private void notifyStateUpdated() {
        for (Runnable callback : stateUpdatedListeners) {
            // One listener throwing must not cost the others their update.
            try {
                callback.run();
            } catch (Exception e) {
                log.debug("state-updated callback failed: {}", e.getMessage());
            }
        }
    }

    /** The state entry the HUD shows: the pinned event, else the first. */
    @Nullable
    public EventState.Entry hudEntry() {
        EventState state = eventState;
        if (state == null || state.getEvents() == null || state.getEvents().isEmpty()) {
            return null;
        }
        int pinned = config.pinnedEventId();
        if (pinned > 0) {
            for (EventState.Entry entry : state.getEvents()) {
                if (entry.getEvent() != null && entry.getEvent().getId() == pinned) {
                    return entry;
                }
            }
        }
        return state.getEvents().get(0);
    }

    /* ===================== tracked-task override ===================== */

    private String trackedTaskKey(int eventId) {
        return "trackedTask_" + eventId;
    }

    /** The user's manually tracked task for an event, or 0 = server decides. */
    public int trackedTaskId(int eventId) {
        try {
            Integer stored = configManager.getConfiguration(
                DropTrackerConfig.GROUP, trackedTaskKey(eventId), Integer.class);
            return stored != null ? stored : 0;
        } catch (Exception e) {
            return 0;
        }
    }

    /** Track a task on the HUD for this event; taskId <= 0 reverts to auto. */
    public void setTrackedTask(int eventId, int taskId) {
        if (taskId <= 0) {
            configManager.unsetConfiguration(DropTrackerConfig.GROUP, trackedTaskKey(eventId));
        } else {
            configManager.setConfiguration(DropTrackerConfig.GROUP, trackedTaskKey(eventId), taskId);
        }
    }

    /**
     * The task the HUD and the Events tab headline for an entry: the user's
     * tracked pick while it exists and is incomplete, else the server's focus
     * task ("the server decides"). Null when neither applies.
     *
     * <p>A pin always wins — it is the user saying "this one" — but a server
     * focus the user hid is skipped for the next visible incomplete task, in
     * the order the panel lists them. The server stamps a focus for hours
     * after you progress a task, so without that skip the gold TRACKING box
     * keeps headlining the very tile you just filed under "N hidden".
     */
    @Nullable
    public DisplayTask displayTask(EventState.Entry entry) {
        if (entry == null || entry.getEvent() == null) {
            return null;
        }
        int eventId = entry.getEvent().getId();
        int tracked = trackedTaskId(eventId);
        // Board games have no free task choice: the current tile is the task.
        boolean pickable = !"board_game".equals(entry.getEvent().getKind());
        List<EventState.TaskInfo> tasks = entry.getTasks();
        if (tracked > 0 && pickable && tasks != null) {
            for (EventState.TaskInfo task : tasks) {
                if (task.getId() == tracked && !task.isCompleted()) {
                    return new DisplayTask(task.getId(), task.getLabel(),
                        task.getHave(), task.getNeed(),
                        task.getIconItemId(), task.getIconPath(), true);
                }
            }
        }
        EventState.FocusTask focus = entry.getFocusTask();
        if (focus == null) {
            return null;
        }
        Set<Integer> hidden = pickable ? hiddenTaskIds(eventId) : Collections.emptySet();
        if (!hidden.contains(focus.getId())) {
            return new DisplayTask(focus.getId(), focus.getLabel(),
                focus.getHave(), focus.getNeed(),
                focus.getIconItemId(), focus.getIconPath(), false);
        }
        if (tasks != null) {
            for (EventState.TaskInfo task : tasks) {
                if (!task.isCompleted() && !hidden.contains(task.getId())) {
                    return new DisplayTask(task.getId(), task.getLabel(),
                        task.getHave(), task.getNeed(),
                        task.getIconItemId(), task.getIconPath(), false);
                }
            }
        }
        return null;
    }

    /**
     * Task ids the user hid for this event in the Events tab. Package-private
     * and overridable: this is the seam the notification tests drive, since
     * {@link ConfigManager} cannot be constructed off a live client.
     */
    Set<Integer> hiddenTaskIds(int eventId) {
        return eventId > 0
            ? EventTaskPrefs.hidden(configManager, eventId) : Collections.emptySet();
    }

    /**
     * True when an envelope is a routine update about a task the user hid.
     * Only task-scoped chatter consults this: event-level news (lead changes,
     * lines, start/end) is never about the one task whose id it happens to
     * carry, and a genuine completion is deliberately still announced.
     */
    private boolean hiddenTask(EventNotification n) {
        EventNotification.Data data = n.getData();
        Integer taskId = data != null ? data.getTaskId() : null;
        Integer eventId = n.getEvent() != null ? n.getEvent().getId() : null;
        return taskId != null && taskId > 0 && eventId != null
            && hiddenTaskIds(eventId).contains(taskId);
    }

    /** Unified view of the headlined task, from either source. */
    public static class DisplayTask {
        public final int id;
        public final String label;
        public final long have;
        public final long need;
        @Nullable
        public final Integer iconItemId;
        @Nullable
        public final String iconPath;
        /** true = the user's manual pick; false = server-chosen focus. */
        public final boolean tracked;

        DisplayTask(int id, String label, long have, long need,
                    @Nullable Integer iconItemId, @Nullable String iconPath,
                    boolean tracked) {
            this.id = id;
            this.label = label;
            this.have = have;
            this.need = need;
            this.iconItemId = iconItemId;
            this.iconPath = iconPath;
            this.tracked = tracked;
        }
    }

    /* ===================== batch rendering ===================== */

    /**
     * Renders one drained batch: the digest on the session's first stale
     * flood, else the normal per-event render. Package-private — this is the
     * seam the notification tests drive.
     */
    void renderBatch(List<EventNotification> batch, boolean catchUp) {
        if (catchUp) {
            processCatchUpBatch(batch);
        } else {
            processBatch(batch);
        }
    }

    private void processBatch(List<EventNotification> batch) {
        // Group per event id (0 = event-less, e.g. submission notices).
        Map<Integer, List<EventNotification>> byEvent = new LinkedHashMap<>();
        for (EventNotification n : batch) {
            int eventId = n.getEvent() != null && n.getEvent().getId() != null
                ? n.getEvent().getId() : 0;
            byEvent.computeIfAbsent(eventId, k -> new ArrayList<>()).add(n);
        }
        List<Toast> candidates = new ArrayList<>();
        for (Map.Entry<Integer, List<EventNotification>> group : byEvent.entrySet()) {
            candidates.addAll(renderEventGroup(group.getValue()));
        }
        queueBatchToasts(candidates);
    }

    /** Renders one event's slice of a batch to chat and returns the pop-ups it
     *  earned; the caller coalesces them across events into one card. */
    private List<Toast> renderEventGroup(List<EventNotification> group) {
        List<Rendered> chatLines = new ArrayList<>();
        List<Toast> groupToasts = new ArrayList<>();
        Set<String> dedupe = new LinkedHashSet<>();
        String eventName = groupEventName(group);
        String teamName = teamNameFor(groupEventId(group));

        for (EventNotification n : group) {
            Rendered rendered = render(n);
            if (rendered == null || !dedupe.add(rendered.text)) {
                continue; // unknown type, filtered, or identical line in batch
            }
            if (rendered.chatEligible) {
                chatLines.add(rendered);
            }
            if (rendered.toastEligible) {
                groupToasts.add(new Toast(rendered.title, rendered.text,
                    rendered.iconItemId, System.currentTimeMillis(),
                    rendered.priority, rendered.dedupeKey));
            }
        }

        // Chat: everything up to the cap, then a collapse line.
        int lines = 0;
        for (Rendered line : chatLines) {
            if (lines == MAX_CHAT_LINES_PER_EVENT && chatLines.size() > MAX_CHAT_LINES_PER_EVENT + 1) {
                sendLine(eventName, teamName, null, HEX_INFO, null,
                    "... and " + (chatLines.size() - MAX_CHAT_LINES_PER_EVENT) + " more event updates.");
                break;
            }
            sendLine(eventName, teamName, line.chatTag, line.chatHex,
                line.chatEmphasis, line.text);
            lines++;
        }
        return groupToasts;
    }

    /**
     * At most ONE pop-up per batch: the most important update headlines it and
     * the rest fold into a "+N more" tail. Several events completing tasks in
     * the same poll used to mean one tall card each — three of those at
     * TOP_CENTER is most of the screen.
     */
    private void queueBatchToasts(List<Toast> candidates) {
        if (candidates.isEmpty()) {
            return;
        }
        Toast lead = candidates.get(0);
        for (Toast candidate : candidates) {
            // Priority is declared most-important-first; ties keep the first.
            if (candidate.getPriority().ordinal() < lead.getPriority().ordinal()) {
                lead = candidate;
            }
        }
        int folded = candidates.size() - 1;
        offerToast(folded == 0 ? lead
            : new Toast(lead.getTitle(),
                lead.getBody() + " (+" + folded + " more)",
                lead.getIconItemId(), lead.getCreatedAt(),
                lead.getPriority(), lead.getDedupeKey()));
    }

    /**
     * Queues a pop-up subject to the display mode, the "important only"
     * filter, the cross-batch dedupe window and the queue cap.
     */
    private void offerToast(Toast toast) {
        if (!config.eventDisplayMode().popupsEnabled()) {
            return;
        }
        if (config.eventImportantPopupsOnly()
                && toast.getPriority() != EventNotification.Priority.HIGH) {
            return;
        }
        if (!claimToastKey(toast.getDedupeKey(), toast.getCreatedAt())) {
            return;
        }
        toasts.addLast(toast);
        while (toasts.size() > MAX_TOASTS_QUEUED) {
            toasts.pollFirst();
        }
    }

    /** False when this dedupe key already popped inside the window. */
    private boolean claimToastKey(@Nullable String key, long now) {
        if (key == null) {
            return true;
        }
        synchronized (recentToastKeys) {
            Long last = recentToastKeys.get(key);
            if (last != null && now - last < TOAST_DEDUPE_WINDOW_MS) {
                return false;
            }
            recentToastKeys.put(key, now);
            return true;
        }
    }

    /** First event name carried by the group's envelopes, cleaned; null for
     *  event-less groups (submission notices), which keep the default tag. */
    @Nullable
    private static String groupEventName(List<EventNotification> group) {
        for (EventNotification n : group) {
            if (n.getEvent() != null && n.getEvent().getName() != null) {
                return clean(n.getEvent().getName());
            }
        }
        return null;
    }

    @Nullable
    private static Integer groupEventId(List<EventNotification> group) {
        for (EventNotification n : group) {
            if (n.getEvent() != null && n.getEvent().getId() != null) {
                return n.getEvent().getId();
            }
        }
        return null;
    }

    /** The player's own team in this event, from the last state snapshot
     *  (null before the first snapshot — the prefix then omits the team). */
    @Nullable
    private String teamNameFor(@Nullable Integer eventId) {
        if (eventId == null) {
            return null;
        }
        EventState state = eventState;
        if (state == null || state.getEvents() == null) {
            return null;
        }
        for (EventState.Entry entry : state.getEvents()) {
            if (entry.getEvent() != null && entry.getEvent().getId() == eventId
                    && entry.getTeam() != null) {
                return clean(entry.getTeam().getName());
            }
        }
        return null;
    }

    /**
     * "[Event Name] (Team name): TAG line" when the event is known, else the
     * default [DropTracker] tag (submission notices, event-less groups) —
     * which has no accent scheme, so the styling is dropped there.
     */
    private void sendLine(@Nullable String eventName, @Nullable String teamName,
                          @Nullable String tag, @Nullable String accentHex,
                          @Nullable String emphasis, String line) {
        if (eventName != null) {
            chatMessageUtil.sendEventChatMessage(eventName, teamName, tag, accentHex,
                emphasis, line);
        } else {
            chatMessageUtil.sendChatMessage(line);
        }
    }

    /* ===================== login catch-up digest ===================== */

    /**
     * A first batch big and stale enough that the player was clearly away:
     * summarize instead of replaying each envelope ("and 30 more..." spam).
     */
    static boolean isCatchUpBatch(List<EventNotification> batch) {
        if (batch.size() < CATCHUP_MIN_ENVELOPES) {
            return false;
        }
        long staleBefore = System.currentTimeMillis() / 1000L - CATCHUP_MIN_AGE_SECONDS;
        for (EventNotification n : batch) {
            if (n.getTs() > 0 && n.getTs() < staleBefore) {
                return true;
            }
        }
        return false;
    }

    /** Digest the backlog per event; event-less notices render normally. */
    private void processCatchUpBatch(List<EventNotification> batch) {
        Map<Integer, List<EventNotification>> byEvent = new LinkedHashMap<>();
        for (EventNotification n : batch) {
            int eventId = n.getEvent() != null && n.getEvent().getId() != null
                ? n.getEvent().getId() : 0;
            byEvent.computeIfAbsent(eventId, k -> new ArrayList<>()).add(n);
        }
        List<Toast> candidates = new ArrayList<>();
        for (Map.Entry<Integer, List<EventNotification>> group : byEvent.entrySet()) {
            if (group.getKey() == 0) {
                candidates.addAll(renderEventGroup(group.getValue()));
            } else {
                Toast digest = summarizeEventGroup(group.getValue());
                if (digest != null) {
                    candidates.add(digest);
                }
            }
        }
        queueBatchToasts(candidates);
    }

    /**
     * One event's backlog as a short digest: a "While you were away:" header
     * followed by indented tallies ("4 tasks completed (+23 pts)"), the
     * still-true facts (event started/ended, current leader) and the one
     * actionable item (a pending dice roll). At most a header plus
     * {@value #CATCHUP_MAX_DETAIL_LINES} lines and one pop-up, regardless of
     * backlog size. Returns the pop-up (null when the digest is empty).
     */
    @Nullable
    private Toast summarizeEventGroup(List<EventNotification> group) {
        String eventName = groupEventName(group);
        String teamName = teamNameFor(groupEventId(group));

        int completions = 0;
        long completionPts = 0;
        int bingoLines = 0;
        long bonusPts = 0;
        boolean blackout = false;
        int boardTurns = 0;
        Set<String> progressedTasks = new LinkedHashSet<>();
        String leadTeam = null;
        Integer leadScore = null;
        long leadTs = Long.MIN_VALUE;
        boolean started = false;
        boolean ended = false;
        boolean rollPrompt = false;
        Integer toastIcon = null;

        for (EventNotification n : group) {
            EventNotification.Data data = n.getData() != null ? n.getData() : new EventNotification.Data();
            switch (n.getType()) {
                case "event_completion":
                    completions++;
                    if (data.getPoints() != null) {
                        completionPts += data.getPoints();
                    }
                    if (toastIcon == null) {
                        toastIcon = data.getIconItemId();
                    }
                    break;
                case "event_task_progress":
                    if (!hiddenTask(n)) {
                        progressedTasks.add(data.getTaskLabel() != null ? data.getTaskLabel() : "?");
                    }
                    break;
                case "event_line":
                    bingoLines++;
                    if (data.getBonusPoints() != null) {
                        bonusPts += data.getBonusPoints();
                    }
                    break;
                case "event_blackout":
                    blackout = true;
                    if (data.getBonusPoints() != null) {
                        bonusPts += data.getBonusPoints();
                    }
                    break;
                case "event_lead_change":
                    if (n.getTs() >= leadTs) {
                        leadTs = n.getTs();
                        leadTeam = clean(data.getTeamName());
                        leadScore = data.getTeamScore();
                    }
                    break;
                case "event_board_turn":
                    boardTurns++;
                    break;
                case "event_board_roll_prompt":
                    rollPrompt = true;
                    break;
                case "event_started":
                    started = true;
                    break;
                case "event_ended":
                    ended = true;
                    break;
                default:
                    break;
            }
        }

        // The closing line is the one that outranks every tally: what state
        // the event is in now, or the action waiting on the team.
        String closing = null;
        String closingHex = null;
        if (ended) {
            closing = "The event has ended.";
            closingHex = HEX_INFO;
        } else if (rollPrompt) {
            closing = "Your team can roll the dice!";
            closingHex = HEX_ACTION;
        }
        int budget = CATCHUP_MAX_DETAIL_LINES - (closing != null ? 1 : 0);

        List<DigestLine> details = new ArrayList<>();
        if (started) {
            details.add(new DigestLine("The event started.", HEX_ACTION));
        }
        if (completions > 0) {
            details.add(new DigestLine(plural(completions, "task") + " completed"
                + (completionPts > 0 ? " (+" + ValueFormat.abbrev(completionPts) + " pts)" : ""),
                HEX_COMPLETE));
        }
        if (bingoLines > 0) {
            details.add(new DigestLine(plural(bingoLines, "bingo line")
                + (bonusPts > 0 && !blackout ? " (+" + ValueFormat.abbrev(bonusPts) + " pts)" : ""),
                HEX_LINE));
        }
        if (blackout) {
            details.add(new DigestLine("Board blackout"
                + (bonusPts > 0 ? " (+" + ValueFormat.abbrev(bonusPts) + " pts)" : ""),
                HEX_BLACKOUT));
        }
        if (leadTeam != null) {
            details.add(new DigestLine(leadTeam + " now leads"
                + (leadScore != null ? " (" + ValueFormat.abbrev(leadScore) + " pts)" : ""),
                HEX_LEAD));
        }
        // Fillers: only worth a line while the important tallies leave room.
        if (boardTurns > 0 && details.size() < budget) {
            details.add(new DigestLine(plural(boardTurns, "dice roll"), HEX_INFO));
        }
        if (!progressedTasks.isEmpty() && config.eventTaskProgressNotifications()
                && details.size() < budget) {
            details.add(new DigestLine("Progress on " + plural(progressedTasks.size(), "task"),
                HEX_MUTED));
        }
        while (details.size() > budget) {
            details.remove(details.size() - 1);
        }
        if (details.isEmpty() && closing == null) {
            return null;
        }

        // Header + indented tallies, rather than one run-on sentence.
        sendLine(eventName, teamName, null, HEX_LEAD, null, "While you were away:");
        List<String> summary = new ArrayList<>(details.size());
        for (DigestLine detail : details) {
            sendLine(eventName, teamName, null, detail.hex, null, CATCHUP_INDENT + detail.text);
            summary.add(detail.text);
        }
        if (closing != null) {
            sendLine(eventName, teamName, null, closingHex, null, CATCHUP_INDENT + closing);
        }

        String body = summary.isEmpty() ? closing : String.join(", ", summary) + ".";
        // The digest is a once-per-session headline: HIGH so "important only"
        // never swallows the one card that explains what you missed.
        return new Toast("While you were away", body, toastIcon,
            System.currentTimeMillis(), EventNotification.Priority.HIGH, null);
    }

    /** One indented line of a catch-up digest, with its accent colour. */
    private static class DigestLine {
        final String text;
        final String hex;

        DigestLine(String text, String hex) {
            this.text = text;
            this.hex = hex;
        }
    }

    private static String plural(int count, String noun) {
        return count + " " + noun + (count == 1 ? "" : "s");
    }

    /* ===================== per-type renderers ===================== */

    /**
     * Chat accents, one per kind of news, so a completion, a lead change and
     * a KC tick never read the same. Mirrors the side panel's palette
     * (DropTrackerTheme) — chat can't reference AWT colours from here, so the
     * hexes are duplicated deliberately.
     */
    private static final String HEX_COMPLETE = "#6fbf73";
    private static final String HEX_TILE = "#7fe08a";
    private static final String HEX_LEAD = "#ffd966";
    private static final String HEX_LINE = "#ff8c42";
    private static final String HEX_BLACKOUT = "#e05c4d";
    private static final String HEX_ACTION = "#ffb83f";
    private static final String HEX_INFO = "#d8c9a3";
    private static final String HEX_MUTED = "#8f8778";
    private static final String CATCHUP_INDENT = "  - ";

    /** A rendered notification: local text composed from typed fields only. */
    private static class Rendered {
        final String title;
        /** Plain body: the pop-up card and the in-batch dedupe key. */
        final String text;
        /** Uppercase chat tag, e.g. "TILE COMPLETE"; null = no tag. */
        String chatTag;
        /** Chat accent for the tag/body; null = the legacy uncoloured line. */
        String chatHex;
        /** Substring of {@link #text} to lift out of the accent (item name). */
        String chatEmphasis;
        Integer iconItemId;
        EventNotification.Priority priority = EventNotification.Priority.NORMAL;
        boolean chatEligible = true;
        boolean toastEligible = true;
        /** (event, task, type); null opts out of the cross-batch pop-up dedupe. */
        String dedupeKey;

        Rendered(String title, String text) {
            this.title = title;
            this.text = text;
        }

        Rendered tag(String tag, String hex) {
            this.chatTag = tag;
            this.chatHex = hex;
            return this;
        }

        Rendered emphasis(@Nullable String emphasis) {
            this.chatEmphasis = emphasis;
            return this;
        }

        Rendered icon(@Nullable Integer itemId) {
            this.iconItemId = itemId;
            return this;
        }

        Rendered priority(EventNotification.Priority priority) {
            this.priority = priority;
            return this;
        }

        Rendered chatOnly() {
            this.toastEligible = false;
            return this;
        }
    }

    /**
     * Renders an envelope, then stamps the importance tier the pop-up styling
     * and lifetime key off. The server's {@code priority} wins whenever it is
     * present; when the field is absent altogether — a server older than the
     * signal — the per-type default the renderer picked stands in, so tiering
     * never collapses into one flat style. An unknown value parses as NORMAL,
     * per the envelope contract.
     */
    @Nullable
    private Rendered render(EventNotification n) {
        Rendered rendered = renderTyped(n);
        if (rendered == null) {
            return null;
        }
        if (n.getPriority() != null) {
            rendered.priority = n.priorityTier();
        }
        rendered.dedupeKey = dedupeKey(n);
        return rendered;
    }

    /** Pop-up identity across batches: the same task ticking the same way. */
    private static String dedupeKey(EventNotification n) {
        Integer eventId = n.getEvent() != null ? n.getEvent().getId() : null;
        EventNotification.Data data = n.getData();
        Object task = null;
        if (data != null) {
            task = data.getTaskId() != null ? data.getTaskId() : clean(data.getTaskLabel());
        }
        return eventId + "|" + task + "|" + n.getType();
    }

    @Nullable
    private Rendered renderTyped(EventNotification n) {
        EventNotification.Data data = n.getData();
        String eventName = n.getEvent() != null ? clean(n.getEvent().getName()) : null;
        String type = n.getType();
        if (data == null) {
            data = new EventNotification.Data();
        }
        String team = clean(data.getTeamName());
        String player = clean(data.getPlayerName());
        String task = clean(data.getTaskLabel());

        switch (type) {
            case "event_completion": {
                String who = player != null ? player : (team != null ? team : "Your team");
                String item = clean(data.getReceivedItem());
                StringBuilder text = new StringBuilder(who);
                if (item != null) {
                    // "K0eppy received Bandos hilt, completing: Bandos set"
                    text.append(" received ").append(item).append(qtySuffix(data))
                        .append(", completing: ").append(orUnknown(task));
                } else {
                    text.append(" completed: ").append(orUnknown(task));
                }
                if (data.getPoints() != null && data.getPoints() > 0) {
                    text.append(" (+").append(ValueFormat.abbrev(data.getPoints())).append(" pts)");
                }
                // A completion that actually filled a bingo cell is the big
                // moment of the whole feed — name the tile and the standing it
                // moved the team to, and lift it out of the ordinary tier.
                List<String> cells = cleanAll(data.getCellLabels());
                boolean filledTile = !cells.isEmpty()
                    || (data.getCellIdxs() != null && !data.getCellIdxs().isEmpty());
                // A cell usually inherits its task's label; naming it again
                // would read "completing: Bandos set — tile: Bandos set".
                cells.removeIf(label -> label.equalsIgnoreCase(task));
                if (!cells.isEmpty()) {
                    text.append(" — tile: ").append(cells.get(0));
                    if (cells.size() > 1) {
                        text.append(" +").append(cells.size() - 1);
                    }
                }
                if (filledTile) {
                    String standing = tileStanding(data);
                    if (standing != null) {
                        text.append(" — ").append(standing);
                    }
                }
                if ("manual".equals(data.getSourceType())) {
                    // Organizer-granted credit: say so, so nobody hunts for a
                    // drop that never happened.
                    text.append(" (manual award)");
                }
                return new Rendered(filledTile ? "Tile complete!" : "Task complete!",
                    text.toString())
                    .tag(filledTile ? "TILE COMPLETE" : "COMPLETE",
                        filledTile ? HEX_TILE : HEX_COMPLETE)
                    .emphasis(item)
                    .icon(data.getIconItemId())
                    .priority(filledTile ? EventNotification.Priority.HIGH
                        : EventNotification.Priority.NORMAL);
            }
            case "event_task_progress": {
                if (!config.eventTaskProgressNotifications()) {
                    return null; // the client-side mute switch for the chattiest type
                }
                if (hiddenTask(n)) {
                    return null; // hiding a task in the panel mutes its ticks too
                }
                String who = player != null ? player : "A teammate";
                String item = clean(data.getReceivedItem());
                String progress = data.getProgress() != null && data.getTarget() != null
                    ? " (" + ValueFormat.abbrev(data.getProgress())
                        + "/" + ValueFormat.abbrev(data.getTarget()) + ")"
                    // Metric ticks report a rounded percentage instead of the
                    // raw pair (XP/KC targets fold across many paths).
                    : data.getMilestonePct() != null
                        ? " (" + data.getMilestonePct() + "%)" : "";
                // With the driving drop named: "K0eppy received Bandos hilt,
                // progressing Bandos set (2/5)"; without (XP/GP/KC ticks),
                // the compact form.
                String text = item != null
                    ? who + " received " + item + qtySuffix(data)
                        + ", progressing " + orUnknown(task) + progress
                    : who + " progressed " + orUnknown(task) + progress;
                return new Rendered("Task progress", text)
                    .tag("PROGRESS", HEX_MUTED)
                    .icon(data.getIconItemId())
                    .priority(EventNotification.Priority.LOW);
            }
            case "event_lead_change": {
                String leader = team != null ? team : "A team";
                String score = data.getTeamScore() != null
                    ? " (" + ValueFormat.abbrev(data.getTeamScore()) + " pts)" : "";
                return new Rendered("Lead change!",
                    leader + " took the lead" + score
                        + (eventName != null ? " in " + eventName : "") + "!")
                    .tag("LEAD CHANGE", HEX_LEAD)
                    .emphasis(team)
                    .priority(EventNotification.Priority.HIGH);
            }
            case "event_started":
                return new Rendered("Event started",
                    (eventName != null ? eventName : "Your event") + " has started!")
                    .tag("EVENT STARTED", HEX_ACTION)
                    .emphasis(eventName)
                    .priority(EventNotification.Priority.HIGH);
            case "event_ended":
                return new Rendered("Event ended",
                    (eventName != null ? eventName : "Your event") + " has ended.")
                    .tag("EVENT ENDED", HEX_INFO)
                    .emphasis(eventName)
                    .priority(EventNotification.Priority.HIGH);
            case "event_line": {
                String who = team != null ? team : "Your team";
                String bonus = data.getBonusPoints() != null
                    ? " (+" + ValueFormat.abbrev(data.getBonusPoints()) + " pts)" : "";
                return new Rendered("Bingo line!", who + " completed a line" + bonus + "!")
                    .tag("BINGO LINE", HEX_LINE)
                    .emphasis(team)
                    .priority(EventNotification.Priority.HIGH);
            }
            case "event_blackout": {
                String who = team != null ? team : "Your team";
                String bonus = data.getBonusPoints() != null
                    ? " (+" + ValueFormat.abbrev(data.getBonusPoints()) + " pts)" : "";
                return new Rendered("Blackout!", who + " blacked out the board" + bonus + "!")
                    .tag("BLACKOUT", HEX_BLACKOUT)
                    .emphasis(team)
                    .priority(EventNotification.Priority.HIGH);
            }
            case "event_board_turn": {
                String who = player != null ? player : (team != null ? team : "Your team");
                StringBuilder text = new StringBuilder(who + " rolled");
                if (data.getDiceStr() != null) {
                    text.append(" ").append(clean(data.getDiceStr()));
                }
                if (data.getTileTo() != null) {
                    text.append(" to tile ").append(data.getTileTo());
                }
                if (data.getNextTaskLabel() != null) {
                    text.append(": ").append(clean(data.getNextTaskLabel()));
                }
                return new Rendered("Board roll", text.toString())
                    .tag("BOARD", HEX_INFO)
                    .priority(EventNotification.Priority.NORMAL);
            }
            case "event_board_roll_prompt":
                return new Rendered("Roll the dice!",
                    "Task complete — your team can roll the dice!"
                        + (data.getCoinsAwarded() != null && data.getCoinsAwarded() > 0
                            ? " (+" + ValueFormat.abbrev(data.getCoinsAwarded()) + " coins)" : ""))
                    .tag("YOUR TURN", HEX_ACTION)
                    .priority(EventNotification.Priority.HIGH);
            case "submission_notice": {
                // Legacy server-text channel: sanitized plain chat only, gated
                // by the pre-existing receiveInGameMessages config.
                if (!config.receiveInGameMessages() || data.getMessage() == null) {
                    return null;
                }
                return new Rendered("DropTracker", clean(data.getMessage())).chatOnly();
            }
            default:
                DebugLogger.log("[EventNotifications] dropping unknown type=" + type);
                return null;
        }
    }

    private static String orUnknown(String value) {
        return value != null ? value : "a task";
    }

    /** Sanitized copy of a server-sent string list, empties dropped. */
    private static List<String> cleanAll(@Nullable List<String> values) {
        if (values == null || values.isEmpty()) {
            return Collections.emptyList();
        }
        List<String> out = new ArrayList<>(values.size());
        for (String value : values) {
            String cleaned = clean(value);
            if (cleaned != null) {
                out.add(cleaned);
            }
        }
        return out;
    }

    /** "7 tiles, 2nd of 5" from a completion's board-standing fields; null
     *  when the server sent neither (older servers, non-bingo events). */
    @Nullable
    private static String tileStanding(EventNotification.Data data) {
        List<String> parts = new ArrayList<>(2);
        if (data.getTilesCompleted() != null && data.getTilesCompleted() > 0) {
            parts.add(plural(data.getTilesCompleted(), "tile"));
        }
        if (data.getTeamRank() != null && data.getTeamRank() > 0
                && data.getTeamCount() != null && data.getTeamCount() > 0) {
            parts.add(ordinal(data.getTeamRank()) + " of " + data.getTeamCount());
        }
        return parts.isEmpty() ? null : String.join(", ", parts);
    }

    private static String ordinal(int n) {
        if (n % 100 >= 11 && n % 100 <= 13) {
            return n + "th";
        }
        switch (n % 10) {
            case 1: return n + "st";
            case 2: return n + "nd";
            case 3: return n + "rd";
            default: return n + "th";
        }
    }

    /** " ×3" when a real item stack drove the update; never for point
     *  credits (points_based), whose quantities are not item counts. */
    private static String qtySuffix(EventNotification.Data data) {
        if (Boolean.TRUE.equals(data.getPointsBased())) {
            return "";
        }
        Integer qty = data.getReceivedQty();
        return qty != null && qty > 1 ? " ×" + qty : "";
    }

    /** Tag-strip + length-cap every server-supplied string before rendering. */
    @Nullable
    static String clean(@Nullable String value) {
        return clean(value, MAX_TEXT_LENGTH);
    }

    @Nullable
    static String clean(@Nullable String value, int maxLength) {
        if (value == null) {
            return null;
        }
        String stripped = Text.removeTags(value).replace('\u00A0', ' ').trim();
        if (stripped.isEmpty()) {
            return null;
        }
        return stripped.length() > maxLength
            ? stripped.substring(0, maxLength - 1) + "…" : stripped;
    }

    /** A transient on-screen pop-up. */
    @Getter
    public static class Toast {
        /** Per-tier lifetimes: the big moments linger, routine ticks flick by. */
        static final long LIFETIME_HIGH_MS = 9000;
        static final long LIFETIME_NORMAL_MS = 6000;
        static final long LIFETIME_LOW_MS = 3500;

        private final String title;
        private final String body;
        @Nullable
        private final Integer iconItemId;
        private final long createdAt;
        private final EventNotification.Priority priority;
        /** (event, task, type) for the cross-batch dedupe; null = always show. */
        @Nullable
        private final String dedupeKey;

        public Toast(String title, String body, @Nullable Integer iconItemId, long createdAt) {
            this(title, body, iconItemId, createdAt, EventNotification.Priority.NORMAL, null);
        }

        public Toast(String title, String body, @Nullable Integer iconItemId, long createdAt,
                     EventNotification.Priority priority, @Nullable String dedupeKey) {
            this.title = title;
            this.body = body;
            this.iconItemId = iconItemId;
            this.createdAt = createdAt;
            this.priority = priority != null ? priority : EventNotification.Priority.NORMAL;
            this.dedupeKey = dedupeKey;
        }

        public long lifetimeMs() {
            switch (priority) {
                case HIGH:
                    return LIFETIME_HIGH_MS;
                case LOW:
                    return LIFETIME_LOW_MS;
                default:
                    return LIFETIME_NORMAL_MS;
            }
        }

        /** Milliseconds of life left; <= 0 once expired. */
        public long remainingMs(long now) {
            return lifetimeMs() - (now - createdAt);
        }

        public boolean expired(long now) {
            return remainingMs(now) <= 0;
        }
    }
}

