    // ========== Public Entry Points for Event Handlers ==========

    /**
     * Entry point for non-drop events (PBs, CLogs, CAs, Pets, Quests, Levels, XP, etc.)
     */
    public void sendDataToDropTracker(CustomWebhookBody webhook, SubmissionType type) {
        if (hasUnidentifiedEmbed(webhook)) {
            debugLogEventFlow("skipped", type, "player_name missing; submission has no identity");
            return;
        }
        boolean requiredScreenshot = false;
        PrivacyMode privacyMode = config.privacyMode();
        debugLogEventFlow("received", type, "entry=non-drop, useApi=" + config.useApi() + ", privacyMode=" + privacyMode.name());

        // Check if the user has this event type enabled locally
        switch (type) {
            case DROP:
                // Drops use the value-based overload; this should not be called for drops
                debugLogEventFlow("received", type, "non-drop entrypoint invoked for DROP type; ignoring");
                break;
            case KILL_TIME:
                if (!config.pbEmbeds()) {
                    debugLogEventFlow("skipped", type, "pbEmbeds=false");
                    return;
                }
                // Raid completion times are raid data: attach the
                // authoritative raid roster. Non-raid kill times are left
                // untouched.
                if (NearbyPlayerTracker.raidTypeForSource(extractSourceName(webhook)) != null) {
                    NearbyPlayerTracker.NearbyPlayerTrace killTrace = addParticipantsField(webhook);
                    debugLogEventFlow("nearby-trace", type,
                        killTrace != null ? killTrace.toDebugSummary() : "trace unavailable");
                }
                boolean isPb = isFieldTrue(webhook, "is_pb");
                if (config.screenshots() && isPb) {
                    requiredScreenshot = true;
                }
                if (!isPb) {
                    // Non-PB kill times: just send, no ValidSubmission tracking
                    debugLogEventFlow("send", type, "non-pb kill time; direct send; screenshotRequired=" + requiredScreenshot);
                    if (requiredScreenshot) {
                        captureAndSend(webhook, null, privacyMode);
                    } else {
                        sendWebhookDirect(webhook, null, null);
                    }
                    return;
                }
                break;
            case COLLECTION_LOG:
                if (!config.clogEmbeds()) {
                    debugLogEventFlow("skipped", type, "clogEmbeds=false");
                    return;
                }
                if (config.screenshots()) requiredScreenshot = true;
                break;
            case COMBAT_ACHIEVEMENT:
                if (!config.caEmbeds()) {
                    debugLogEventFlow("skipped", type, "caEmbeds=false");
                    return;
                }
                if (config.screenshots()) requiredScreenshot = true;
                break;
            case LEVEL_UP:
                if (!config.levelEmbed()) {
                    debugLogEventFlow("skipped", type, "levelEmbed=false");
                    return;
                }
                // Honor the "Minimum Level to Screenshot" option: only capture
                // when at least one skill reached that level (default 1 = always).
                if (config.screenshots()
                        && maxNewLevelIn(webhook) >= config.minLevelToScreenshot()) {
                    requiredScreenshot = true;
                }
                break;
            case QUEST_COMPLETION:
                if (!config.questsEmbed()) {
                    debugLogEventFlow("skipped", type, "questsEmbed=false");
                    return;
                }
                if (config.screenshots()) requiredScreenshot = true;
                break;
            case PET:
                if (!config.petEmbeds()) {
                    debugLogEventFlow("skipped", type, "petEmbeds=false");
                    return;
                }
                if (config.screenshots()) requiredScreenshot = true;
                break;
            case DEATH:
                if (!config.deathEmbeds()) {
                    debugLogEventFlow("skipped", type, "deathEmbeds=false");
                    return;
                }
                if (config.screenshots()) requiredScreenshot = true;
                break;
            case DIARY:
                if (!config.diaryEmbeds()) {
                    debugLogEventFlow("skipped", type, "diaryEmbeds=false");
                    return;
                }
                if (config.screenshots()) requiredScreenshot = true;
                break;
            case SLAYER_TASK:
                if (!config.slayerEmbeds()) {
                    debugLogEventFlow("skipped", type, "slayerEmbeds=false");
                    return;
                }
                if (config.screenshots()) requiredScreenshot = true;
                break;
            case EXPERIENCE:
                // No screenshots for experience events
                break;
            case EXPERIENCE_MILESTONE:
                if (!config.xpMilestoneEmbeds()) {
                    debugLogEventFlow("skipped", type, "xpMilestoneEmbeds=false");
                    return;
                }
                if (config.screenshots()) requiredScreenshot = true;
                break;
            case EXPERIENCE_UPDATE:
                // Background XP snapshot for event tracking: no screenshot,
                // no group qualification and no UI submission tracking
                debugLogEventFlow("send", type, "experience snapshot; direct send");
                sendWebhookDirect(webhook, null, null);
                return;
            case CLAN_BROADCAST:
            case CLAN_CHAT:
                // Clan relay payloads are raw chat text: API-only by contract.
                // They must NEVER ride the Discord-webhook fallback transport,
                // so hard-stop here even though ClanRelayService already gates
                // on useApi. No screenshot, no group qualification, no UI
                // submission tracking — the server owns everything downstream.
                if (!config.useApi()) {
                    debugLogEventFlow("skipped", type, "useApi=false; clan relay is API-only");
                    return;
                }
                debugLogEventFlow("send", type, "clan relay; direct send");
                sendWebhookDirect(webhook, null, null);
                return;
            case ADVENTURE_LOG:
                // No extra processing needed
                break;
        }

        // Create ValidSubmission if the event qualifies for any group
        ValidSubmission submission = createSubmissionIfQualified(webhook, type, requiredScreenshot, 0, 0);
        debugLogEventFlow("qualification", type, "screenshotRequired=" + requiredScreenshot + ", " + summarizeSubmission(submission));

        if (requiredScreenshot) {
            debugLogEventFlow("capture", type, "captureAndSend path selected");
            captureAndSend(webhook, submission, privacyMode);
        } else {
            debugLogEventFlow("send", type, "sendWebhookDirect path selected");
            sendWebhookDirect(webhook, null, submission);
        }
    }

    /**
     * Highest {@code *_new_level} field value across the webhook's embeds.
     * Level-up embeds carry one such field per levelled skill; used to honor
     * the "Minimum Level to Screenshot" config option. Returns 0 when no
     * level fields are present.
     */
    private int maxNewLevelIn(CustomWebhookBody webhook) {
        int max = 0;
        if (webhook == null || webhook.getEmbeds() == null) {
            return max;
        }
        for (CustomWebhookBody.Embed embed : webhook.getEmbeds()) {
            for (CustomWebhookBody.Field field : embed.getFields()) {
                if (field.getName() != null && field.getName().endsWith("_new_level")) {
                    try {
                        max = Math.max(max, Integer.parseInt(field.getValue().trim()));
                    } catch (NumberFormatException ignored) {
                        // non-numeric level field; skip
                    }
                }
            }
        }
        return max;
    }

    /**
     * Entry point for drop events (value-based qualification)
     */
    public void sendDataToDropTracker(CustomWebhookBody customWebhookBody, long totalValue, long singleValue, boolean valueModified) {
        if (hasUnidentifiedEmbed(customWebhookBody)) {
            debugLogEventFlow("skipped", SubmissionType.DROP, "player_name missing; submission has no identity");
            return;
        }
        if (!config.lootEmbeds()) {
            debugLogEventFlow("skipped", SubmissionType.DROP, "lootEmbeds=false");
            return;
        }

        NearbyPlayerTracker.NearbyPlayerTrace nearbyTrace = addParticipantsField(customWebhookBody);
        debugLogEventFlow("nearby-trace", SubmissionType.DROP,
            nearbyTrace != null ? nearbyTrace.toDebugSummary() : "trace unavailable");

        boolean requiredScreenshot = (config.screenshots() && totalValue > config.screenshotValue()) || valueModified;
        debugLogEventFlow("received", SubmissionType.DROP, "totalValue=" + totalValue + ", singleValue=" + singleValue
                + ", valueModified=" + valueModified + ", screenshotRequired=" + requiredScreenshot
                + ", screenshotThreshold=" + config.screenshotValue());

        // Create ValidSubmission if the drop qualifies for any group
        ValidSubmission submission = createSubmissionIfQualified(customWebhookBody, SubmissionType.DROP, requiredScreenshot, totalValue, singleValue);
        debugLogEventFlow("qualification", SubmissionType.DROP, summarizeSubmission(submission));

        // Update session value statistics
        this.sessionTotalValue += totalValue;
        if (submission != null) {
            submission.setTotalValue(totalValue);
        }

        if (requiredScreenshot) {
            PrivacyMode privacyMode = config.privacyMode();
            debugLogEventFlow("capture", SubmissionType.DROP, "captureAndSend path selected; privacyMode=" + privacyMode.name());
            captureAndSend(customWebhookBody, submission, privacyMode);
        } else {
            debugLogEventFlow("send", SubmissionType.DROP, "sendWebhookDirect path selected");
            sendWebhookDirect(customWebhookBody, null, submission);
        }
    }

    /**
     * The submission's source name from its embed fields: {@code source} on
     * drop embeds, {@code boss_name} on kill-time embeds. Null when absent.
     */
    private String extractSourceName(CustomWebhookBody webhook) {
        if (webhook == null || webhook.getEmbeds() == null) {
            return null;
        }
        for (CustomWebhookBody.Embed embed : webhook.getEmbeds()) {
            if (embed == null) {
                continue;
            }
            for (CustomWebhookBody.Field field : embed.getFields()) {
                if (field == null || field.getName() == null) {
                    continue;
                }
                if ("source".equalsIgnoreCase(field.getName()) || "boss_name".equalsIgnoreCase(field.getName())) {
                    return field.getValue();
                }
            }
        }
        return null;
    }

    /**
     * Last line of defence for the identity fix: a submission whose
     * {@code player_name} is present but blank cannot be attributed to anyone,
     * and the backend rejects it anyway. Handlers already skip these at the
     * source; this stops a future path from reintroducing a nameless — or
     * worse, invented — submission by accident. Embeds that carry no
     * {@code player_name} at all (the adventure log names its field
     * {@code player}) are left alone.
     */
    @VisibleForTesting
    static boolean hasUnidentifiedEmbed(CustomWebhookBody webhook) {
        if (webhook == null || webhook.getEmbeds() == null) {
            return false;
        }
        for (CustomWebhookBody.Embed embed : webhook.getEmbeds()) {
            if (embed == null || embed.getFields() == null) {
                continue;
            }
            for (CustomWebhookBody.Field field : embed.getFields()) {
                if (field == null || !"player_name".equalsIgnoreCase(field.getName())) {
                    continue;
                }
                if (PlayerIdentity.isMissingName(field.getValue())) {
                    return true;
                }
            }
        }
        return false;
    }

    private NearbyPlayerTracker.NearbyPlayerTrace addParticipantsField(CustomWebhookBody webhook) {
        if (webhook == null || webhook.getEmbeds() == null) {
            return NearbyPlayerTracker.NearbyPlayerTrace.empty(20, "webhook/embeds missing");
        }

        // Raid-sourced submissions get the authoritative raid roster; anything
        // else gets a plain proximity scan (see NearbyPlayerTracker).
        String sourceName = extractSourceName(webhook);
        boolean raidSourced = NearbyPlayerTracker.raidTypeForSource(sourceName) != null;
        NearbyPlayerTracker.NearbyPlayerTrace trace = nearbyPlayerTracker.getParticipantsTrace(sourceName, 20);
        List<String> members = trace.getNearbyPlayers();
        String membersValue = String.join(",", members);
        int embedsTouched = 0;
        int embedsWithExistingMembersField = 0;
        int membersFieldsAdded = 0;

        for (CustomWebhookBody.Embed embed : webhook.getEmbeds()) {
            if (embed == null) {
                continue;
            }
            embedsTouched++;

            boolean hasMembersField = false;
            boolean hasPartySizeField = false;
            for (CustomWebhookBody.Field field : embed.getFields()) {
                if (field == null || field.getName() == null) {
                    continue;
                }
                if ("nearby_players".equalsIgnoreCase(field.getName())
                        || "members".equalsIgnoreCase(field.getName())) {
                    hasMembersField = true;
                }
                if ("raid_party_size".equalsIgnoreCase(field.getName())) {
                    hasPartySizeField = true;
                }
            }

            // Discord rejects embed fields with empty values, so omit the field
            // entirely when no players are nearby rather than sending a sentinel.
            if (!hasMembersField && !membersValue.isEmpty()) {
                embed.addField("nearby_players", membersValue, false);
                membersFieldsAdded++;
            } else if (hasMembersField) {
                embedsWithExistingMembersField++;
            }

            // Raid submissions carry the evidence behind the participant list,
            // not just the list: the party size the game itself reported and
            // which source produced the roster. The server cross-checks the
            // list against these, so a roster bug (or a stale client) can no
            // longer credit people who were never in the raid — a proven solo
            // (raid_party_size=1, roster_source=solo) is never split.
            if (raidSourced && !hasPartySizeField) {
                if (trace.getRaidPartySize() > 0) {
                    embed.addField("raid_party_size", String.valueOf(trace.getRaidPartySize()), false);
                }
                if (trace.getRosterSource() != null && !trace.getRosterSource().isEmpty()) {
                    embed.addField("roster_source", trace.getRosterSource(), false);
                }
            }
        }

        debugLogEventFlow("nearby-trace", SubmissionType.DROP,
            "nearby_players field enrichment: embedsTouched=" + embedsTouched
                + ", existingMembersField=" + embedsWithExistingMembersField
                + ", membersFieldsAdded=" + membersFieldsAdded
                + ", membersValueLength=" + membersValue.length()
                + ", raidSourced=" + raidSourced
                + ", raidPartySize=" + trace.getRaidPartySize()
                + ", rosterSource=" + trace.getRosterSource());
        return trace;
    }

    // ========== Unified Qualification Logic ==========

    /**
     * Checks all group configurations to determine if this event qualifies for tracked notifications.
     * Creates a single ValidSubmission covering all qualifying groups, or returns null if none qualify.
     */
    private ValidSubmission createSubmissionIfQualified(
            CustomWebhookBody webhook, SubmissionType type,
            boolean hasScreenshot, long totalValue, long singleValue) {

        if (!config.useApi()) {
            debugLogEventFlow("qualification", type, "useApi=false; skipping group qualification");
            return null;
        }

        // Keep configs warm; the refresh is rate-limited and fully async (previously this
        // happened as a hidden side effect of getGroupConfigs()).
        api.refreshGroupConfigsAsync();
        List<GroupConfig> groupConfigs = api.getGroupConfigs();

        // If group configs haven't loaded yet, queue the event for later evaluation
        if (groupConfigs == null || groupConfigs.isEmpty()) {
            if (!groupConfigsLoaded) {
                pendingEvents.add(new PendingEvent(webhook, type, hasScreenshot, totalValue, singleValue));
                debugLogEventFlow("qualification", type, "group configs unavailable; queued for later evaluation");
            }
            debugLogEventFlow("qualification", type, "groupConfigs unavailable; queued=" + (!groupConfigsLoaded));
            return null;
        }

        ValidSubmission submission = null;

        for (GroupConfig groupConfig : groupConfigs) {
            String failReason = getQualificationFailureReason(type, groupConfig, hasScreenshot, totalValue, singleValue);
            if (failReason != null) {
                debugLogEventFlow("qualification-skip", type, "group=" + groupConfig.getGroupId() + ", reason=" + failReason);
                continue;
            }

            if (submission == null) {
                submission = new ValidSubmission(webhook, groupConfig.getGroupId(), type);
                addSubmissionToMemory(submission);
            } else {
                submission.addGroupId(groupConfig.getGroupId());
            }
            debugLogEventFlow("qualification-pass", type, "group=" + groupConfig.getGroupId());
        }

        if (submission == null) {
            debugLogEventFlow("qualification", type, "no groups qualified");
        } else {
            debugLogEventFlow("qualification", type, summarizeSubmission(submission));
        }
        return submission;
    }

    /**
     * Returns null when the event qualifies, otherwise a concise reason it was excluded.
     */
    private String getQualificationFailureReason(SubmissionType type, GroupConfig groupConfig,
                                                 boolean hasScreenshot, long totalValue, long singleValue) {
        // If the group requires screenshots and we don't have one, skip
        if (groupConfig.isOnlyScreenshots() && !hasScreenshot) {
            return "group requires screenshot";
        }

        switch (type) {
            case DROP:
                if (!groupConfig.isSendDrops()) return "group sendDrops=false";
                if (totalValue < groupConfig.getMinimumDropValue()) {
                    return "totalValue(" + totalValue + ") < groupMin(" + groupConfig.getMinimumDropValue() + ")";
                }
                // Check stacked items: if group doesn't allow stacked and total > single, skip
                if (!groupConfig.isSendStackedItems() && totalValue > singleValue && singleValue > 0) {
                    return "stacked item and group sendStackedItems=false";
                }
                return null;

            case KILL_TIME:
                return groupConfig.isSendPbs() ? null : "group sendPbs=false";

            case COLLECTION_LOG:
                return groupConfig.isSendClogs() ? null : "group sendClogs=false";

            case COMBAT_ACHIEVEMENT:
                return groupConfig.isSendCAs() ? null : "group sendCAs=false";

            case LEVEL_UP:
                return groupConfig.isSendXP() ? null : "group sendXP=false";

            case QUEST_COMPLETION:
                return groupConfig.isSendQuests() ? null : "group sendQuests=false";

            case PET:
                return groupConfig.isSendPets() ? null : "group sendPets=false";

            case DEATH:
                return groupConfig.isSendDeaths() ? null : "group sendDeaths=false";

            case DIARY:
                return groupConfig.isSendDiaries() ? null : "group sendDiaries=false";

            case SLAYER_TASK:
                // Sent regardless; groups have no slayer notifications yet, so
                // the only group a completion means anything to is one whose
                // live event may count it.
                return groupConfig.isActiveEvent() ? null : "no active event in group";

            case EXPERIENCE:
            case EXPERIENCE_MILESTONE:
                // XP events typically don't create group notifications,
                // but respect the group config if present
                return groupConfig.isSendXP() ? null : "group sendXP=false";

            case EXPERIENCE_UPDATE:
                // Snapshot syncs are sent directly and never tracked per-group
                return "experience snapshots are not tracked per-group";

            case ADVENTURE_LOG:
                // Adventure log currently has no group-level toggle
                return "adventure log unsupported for group notifications";

            default:
                return "unsupported submission type";
        }
    }

    // ========== Send Logic ==========

    /**
     * Sends a webhook directly (with optional screenshot and ValidSubmission tracking).
     * This is the single send method -- the ValidSubmission is passed through, not looked up.
     *
     * @param webhook The webhook body to send
     * @param screenshot Optional JPEG screenshot bytes
     * @param submission Optional ValidSubmission for status tracking
     */
    private void sendWebhookDirect(CustomWebhookBody webhook, byte[] screenshot, ValidSubmission submission) {
        String worldTypeName = getWorldTypeName();

        debugLogEventFlow("send", submission != null ? submission.getType() : null,
                "attempting direct send; world_type=" + worldTypeName + ", hasScreenshot=" + (screenshot != null)
                        + ", " + summarizeSubmission(submission));

        if (submission != null) {
            submission.markAsSending();
            if (screenshot != null) {
                submission.setScreenshotData(screenshot);
            }
            notifyUpdateCallback();
            schedulePersistence();
        }

        // Inject world_type into every embed so the server can distinguish main-game vs. temporary world submissions
        for (CustomWebhookBody.Embed embed : webhook.getEmbeds()) {
            embed.addField("world_type", worldTypeName, true);
        }

        sendWebhookWithRetry(webhook, screenshot, 0, submission);
    }

    private void sendWebhookWithRetry(CustomWebhookBody webhook, byte[] screenshot, int attempt, ValidSubmission submission) {

        MultipartBody.Builder requestBodyBuilder = new MultipartBody.Builder()
                .setType(MultipartBody.FORM)
                .addFormDataPart("payload_json", gson.toJson(webhook));

        if (screenshot != null) {
            String mimeType = detectImageMimeType(screenshot);
            String filename = mimeType.equals("image/png") ? "image.png" : "image.jpeg";
            requestBodyBuilder.addFormDataPart("file", filename,
                    RequestBody.create(MediaType.parse(mimeType), screenshot));
        }

        MultipartBody requestBody = requestBodyBuilder.build();

        HttpUrl url;
        if (!config.useApi()) {
            try {
                url = UrlManager.getRandomEndpoint();
                debugLogEventFlow("dispatch", submission != null ? submission.getType() : null,
                        "using random webhook endpoint (API disabled); attempt=" + attempt);
            } catch (Exception e) {
                debugLogEventFlow("failed", submission != null ? submission.getType() : null,
                        "failed to resolve webhook endpoint: " + e.getMessage());
                return;
            }
        } else {
            url = HttpUrl.parse(api.getApiUrl() + "/webhook");
            debugLogEventFlow("dispatch", submission != null ? submission.getType() : null,
                    "using API webhook endpoint; attempt=" + attempt + ", url=" + url);
        }
        // Both branches build on a hardcoded base, so this is defence in depth rather
        // than a real gate. Log only the host: a webhook URL's path is a credential.
        if (url == null || !urlManager.isValidDiscordWebhookUrl(url)) {
            String host = url == null ? "(unparseable)" : url.host();
            log.debug("Invalid or malformed webhook URL for host: {}", host);
            debugLogEventFlow("failed", submission != null ? submission.getType() : null,
                    "invalid webhook host: " + host);
            return;
        }

        Request request = new Request.Builder()
                .url(url)
                .post(requestBody)
                .build();

        okHttpClient.newCall(request).enqueue(new Callback() {
            @Override
            public void onFailure(@NotNull Call call, @NotNull IOException e) {
                debugLogEventFlow("retry", submission != null ? submission.getType() : null,
                        "network failure on attempt=" + attempt + ": " + e.getMessage());
                scheduleRetryOrFail(webhook, screenshot, submission, attempt, e);
            }

            @Override
            public void onResponse(@NotNull Call call, @NotNull Response response) throws IOException {
                try (ResponseBody body = response.body()) {
                    if (config.useApi()) {
                        api.lastCommunicationTime = (int) (System.currentTimeMillis() / 1000);
                        if (body != null) {
                            try {
                                String bodyString = body.string();
                                if (!bodyString.isEmpty()) {
                                    ApiResponse apiResponse = gson.fromJson(bodyString, ApiResponse.class);
                                    if (apiResponse != null) {
                                        String noticeMessage = apiResponse.getNotice();
                                        if (noticeMessage != null && !noticeMessage.isEmpty() && config.receiveInGameMessages()) {
                                            chatMessageUtil.sendChatMessage(noticeMessage);
                                        }
                                        String updateMessage = apiResponse.getRankUpdate();
                                        if (updateMessage != null && !updateMessage.isEmpty() && config.receiveInGameMessages()) {
                                            chatMessageUtil.sendChatMessage(updateMessage);
                                        }
                                    }
                                }
                            } catch (Exception e) {
                                log.debug("Failed to parse API response: {}", e.getMessage());
                            }
                        }
                    }

                    if (!response.isSuccessful()) {
                        int code = response.code();
                        debugLogEventFlow("response", submission != null ? submission.getType() : null,
                                "unsuccessful HTTP response code=" + code + ", message=" + response.message() + ", attempt=" + attempt);

                        if (code == 400 || code == 401 || code == 403) {
                            if (submission != null) {
                                submission.markAsFailed("HTTP " + code);
                                notifyUpdateCallback();
                                schedulePersistence();
                            }
                            debugLogEventFlow("failed", submission != null ? submission.getType() : null,
                                    "terminal HTTP failure code=" + code + "; no retry");
                            return;
                        }

                        if (code == 404) {
                            executor.submit(() -> {
                                try {
                                    urlManager.fetchNewList();
                                } catch (Exception ex) {
                                    log.debug("Failed to fetch new webhook list: {}", ex.getMessage());
                                }
                            });
                        }

                        scheduleRetryOrFail(webhook, screenshot, submission, attempt, new IOException("HTTP " + code + ": " + response.message()));
                        return;
                    }

                    // Success
                    if (submission != null) {
                        submission.markAsSuccess();
                        notifyUpdateCallback();
                        schedulePersistence();
                    }
                    debugLogEventFlow("response", submission != null ? submission.getType() : null,
                            "success HTTP response; attempt=" + attempt + ", " + summarizeSubmission(submission));

                    // Check if the API has already processed this submission
                    if (config.useApi() && submission != null && submission.getUuid() != null && !submission.getUuid().isEmpty()) {
                        executor.submit(() -> {
                            try {
                                boolean processed = api.checkSubmissionProcessed(submission.getUuid());
                                if (processed) {
                                    submission.markAsProcessed();
                                    notifyUpdateCallback();
                                    schedulePersistence();
                                    debugLogEventFlow("processed", submission.getType(),
                                            "API check confirmed processed; uuid=" + submission.getUuid());
                                }
                            } catch (IOException ignored) {
                                debugLogEventFlow("processed", submission.getType(),
                                        "API check failed for uuid=" + submission.getUuid() + ": " + ignored.getMessage());
                            }
                        });
                    }
                }
            }
        });
    }

    private void scheduleRetryOrFail(CustomWebhookBody webhook, byte[] screenshot, ValidSubmission submission, int attempt, Throwable e) {
        int maxAttempts = 10;
        if (attempt < maxAttempts) {
            long delay = BASE_RETRY_DELAY_MS * (1L << Math.min(attempt, 16));
            if (submission != null) {
                submission.markAsRetrying();
                notifyUpdateCallback();
                schedulePersistence();
            }
            executor.schedule(() -> sendWebhookWithRetry(webhook, screenshot, attempt + 1, submission), delay, TimeUnit.MILLISECONDS);
            log.debug("Scheduled webhook retry in {} ms (attempt {}/{})", delay, attempt + 1, maxAttempts);
            debugLogEventFlow("retry", submission != null ? submission.getType() : null,
                    "scheduled retry in " + delay + "ms (nextAttempt=" + (attempt + 1) + "/" + maxAttempts + ")"
                            + (e != null && e.getMessage() != null ? ", reason=" + e.getMessage() : ""));
        } else {
            if (submission != null) {
                String reason = e != null && e.getMessage() != null ? e.getMessage() : "Retry limit reached";
                submission.markAsFailed(reason);
                notifyUpdateCallback();
                schedulePersistence();
            }
            log.warn("Exhausted retry attempts when sending webhook");
            debugLogEventFlow("failed", submission != null ? submission.getType() : null,
                    "retry limit exhausted after " + maxAttempts + " attempts"
                            + (e != null && e.getMessage() != null ? ", lastError=" + e.getMessage() : ""));
        }
    }

    // ========== Capture (Screenshot) ==========

    /**
     * Runs any screenshot captures held back a game tick. Called from the
     * plugin's {@code onGameTick} ahead of its tracking check: a capture is
     * only ever queued for a submission that already qualified, so draining
     * unconditionally keeps a mid-flight tracking toggle from stranding it
     * here and firing a stale frame whenever tracking resumes.
     */
    public void onGameTick() {
        Runnable capture;
        while ((capture = deferredCaptures.poll()) != null) {
            try {
                capture.run();
            } catch (Exception e) {
                log.debug("Deferred screenshot capture failed", e);
            }
        }
    }

    private void captureAndSend(CustomWebhookBody webhook, ValidSubmission submission, PrivacyMode privacyMode) {
        // Sources that announce loot a tick late would otherwise be
        // photographed before their own drop message (issue #48).
        String source = extractSourceName(webhook);
        if (NpcUtilities.needsDeferredScreenshot(source)) {
            debugLogEventFlow("capture", submission != null ? submission.getType() : null,
                    "deferring screenshot one game tick; source=" + source);
            deferredCaptures.add(() -> captureNow(webhook, submission, privacyMode));
            return;
        }
        captureNow(webhook, submission, privacyMode);
    }

    /**
     * Captures a single screenshot and sends the webhook with it.
     *
     * @param webhook The webhook body to send after capture
     * @param submission Optional ValidSubmission for tracking
     * @param privacyMode What to hide from the frame before it is captured
     */
    private void captureNow(CustomWebhookBody webhook, ValidSubmission submission, PrivacyMode privacyMode) {
        debugLogEventFlow("capture", submission != null ? submission.getType() : null,
                "capturing screenshot; privacyMode=" + privacyMode.name());

        screenshotPrivacy.capture(privacyMode, bufferedImage -> {
            // PNG/JPEG encoding can take hundreds of ms for large frames; keep it
            // off the frame-listener thread so the client doesn't stall.
            executor.submit(() -> {
                if (bufferedImage == null) {
                    // No frame could be captured with the player's privacy mode
                    // applied. Send the submission without proof rather than lose
                    // it — an unhidden frame is never the fallback.
                    debugLogEventFlow("capture", submission != null ? submission.getType() : null,
                            "screenshot unavailable; sending without an image");
                    sendWebhookDirect(webhook, null, submission);
                    return;
                }

                byte[] imageBytes = null;
                try {
                    imageBytes = encodeForUpload(bufferedImage);
                } catch (IOException e) {
                    log.error("Error converting image to byte array", e);
                    debugLogEventFlow("capture", submission != null ? submission.getType() : null,
                            "screenshot conversion failed: " + e.getMessage());
                }

                debugLogEventFlow("capture", submission != null ? submission.getType() : null,
                        "screenshot captured; bytes=" + (imageBytes != null ? imageBytes.length : 0));
                sendWebhookDirect(webhook, imageBytes, submission);
            });
        });
    }

    /**
     * Encodes a captured frame for upload, remembering the last one.
     *
     * <p>ScreenshotPrivacyService hands the same frame to every submission that a
     * single moment produced — a drop and the collection log slot it filled share
     * one capture — so without this the identical image is compressed once per
     * submission. Encoding is the expensive half of a screenshot, so the second
     * caller waits on the lock and leaves with the bytes the first one produced.
     */
    private byte[] encodeForUpload(BufferedImage bufferedImage) throws IOException {
        synchronized (encodeLock) {
            if (bufferedImage == lastEncodedImage && lastEncodedBytes != null) {
                return lastEncodedBytes;
            }

            // Compression off = always lossless, whatever the size.
            int thresholdBytes = config.compressImages()
                ? config.imageCompressionThresholdKb() * 1024
                : Integer.MAX_VALUE;
            byte[] pngBytes = convertImageToPngBytes(bufferedImage);
            byte[] imageBytes = thresholdBytes > 0 && pngBytes.length <= thresholdBytes
                // PNG is within the threshold — send lossless
                ? pngBytes
                // PNG exceeds threshold (or threshold is 0) — compress to JPEG
                : convertImageToJpegBytes(bufferedImage);

            lastEncodedImage = bufferedImage;
            lastEncodedBytes = imageBytes;
            return imageBytes;
        }
    }

    private static byte[] convertImageToJpegBytes(BufferedImage bufferedImage) throws IOException {
        ByteArrayOutputStream byteArrayOutputStream = new ByteArrayOutputStream();
        ImageIO.write(bufferedImage, "jpeg", byteArrayOutputStream);
        return byteArrayOutputStream.toByteArray();
    }

    private static byte[] convertImageToPngBytes(BufferedImage bufferedImage) throws IOException {
        ByteArrayOutputStream byteArrayOutputStream = new ByteArrayOutputStream();
        ImageIO.write(bufferedImage, "png", byteArrayOutputStream);
        return byteArrayOutputStream.toByteArray();
    }

    /**
     * Detects image MIME type from magic bytes.
     * PNG files begin with 0x89 P N G; all others are treated as JPEG.
     */
    private static String detectImageMimeType(byte[] bytes) {
        if (bytes != null && bytes.length >= 4
                && bytes[0] == (byte) 0x89 && bytes[1] == 0x50
                && bytes[2] == 0x4E && bytes[3] == 0x47) {
            return "image/png";
        }
        return "image/jpeg";
    }

    // ========== Submission Management ==========

    public void addSubmissionToMemory(ValidSubmission validSubmission) {
        // Prune oldest processed submissions to stay within limits
        while (validSubmissions.size() >= MAX_PERSISTED_SUBMISSIONS) {
            // Prefer removing oldest processed submission first
            ValidSubmission toRemove = null;
            for (ValidSubmission s : validSubmissions) {
                if (s.getStatus() == SubmissionStatus.PROCESSED) {
                    toRemove = s;
                    break;
                }
            }
            if (toRemove != null) {
                validSubmissions.remove(toRemove);
            } else {
                // Remove the oldest submission regardless
                validSubmissions.remove(0);
            }
        }
        validSubmissions.add(validSubmission);
        notifyUpdateCallback();
        schedulePersistence();
    }

    /**
     * Retry a failed submission using the stored webhook data
     */
    public void retrySubmission(ValidSubmission validSubmission) {
        if (validSubmission == null || validSubmission.getOriginalWebhook() == null) {
            log.warn("Cannot retry submission: missing webhook data");
            return;
        }
        validSubmission.markAsRetrying();
        notifyUpdateCallback();
        schedulePersistence();
        // Use stored screenshot data if available
        byte[] screenshot = validSubmission.getScreenshotData();
        sendWebhookWithRetry(validSubmission.getOriginalWebhook(), screenshot, 0, validSubmission);
    }

    /**
     * Remove a submission from the list (e.g., when user dismisses it)
     */
    public void removeSubmission(ValidSubmission validSubmission) {
        validSubmissions.remove(validSubmission);
        notifyUpdateCallback();
        schedulePersistence();
    }

    // ========== Statistics (derived from list) ==========

    /**
     * Count of all submissions that qualified for group notifications this session
     */
    public int getTotalSubmissions() {
        return validSubmissions.size();
    }

    /**
     * Count of submissions that were successfully sent or processed
     */
    public int getNotificationsSent() {
        int count = 0;
        for (ValidSubmission s : validSubmissions) {
            if (s.getStatus() == SubmissionStatus.SENT || s.getStatus() == SubmissionStatus.PROCESSED) {
                count++;
            }
        }
        return count;
    }

    /**
     * Count of submissions that failed
     */
    public int getFailedSubmissions() {
        int count = 0;
        for (ValidSubmission s : validSubmissions) {
            if (s.getStatus() == SubmissionStatus.FAILED) {
                count++;
            }
        }
        return count;
    }

    /**
     * Total GP value of drops submitted (session-only, not derived from list because
     * non-qualifying drops also contribute to GP value)
     */
    public long getTotalValue() {
        return sessionTotalValue;
    }

    // ========== Pending Status Polling ==========

    /**
     * Poll the API to update statuses of pending submissions. All pending uuids are
     * checked with a single batch POST /check per tick; if the batch form is
     * unavailable (older custom API endpoints), it falls back to per-uuid checks for
     * that tick. A "pending" result is a normal long-lived state - submissions stay
     * pending until the API processes them or the retry logic marks them failed.
     */
    public void checkPendingStatuses() {
        if (!config.useApi()) {
            return;
        }
        executor.submit(() -> {
            try {
                List<ValidSubmission> pending = new ArrayList<>();
                List<String> uuids = new ArrayList<>();
                for (ValidSubmission submission : validSubmissions) {
                    SubmissionStatus status = submission.getStatus();
                    if (status == null || status.isTerminal()) {
                        continue;
                    }
                    String uuid = submission.getUuid();
                    if (uuid == null || uuid.isEmpty()) {
                        continue;
                    }
                    pending.add(submission);
                    uuids.add(uuid);
                }
                if (pending.isEmpty()) {
                    return;
                }

                boolean changed = false;
                java.util.Map<String, Boolean> results = null;
                try {
                    results = api.checkSubmissionsProcessed(uuids);
                } catch (IOException e) {
                    log.debug("Batch /check failed ({}); falling back to per-uuid checks", e.getMessage());
                }

                if (results != null) {
                    for (ValidSubmission submission : pending) {
                        if (Boolean.TRUE.equals(results.get(submission.getUuid()))) {
                            submission.markAsProcessed();
                            changed = true;
                        }
                    }
                } else {
                    // Legacy fallback: one request per pending submission.
                    for (ValidSubmission submission : pending) {
                        try {
                            if (api.checkSubmissionProcessed(submission.getUuid())) {
                                submission.markAsProcessed();
                                changed = true;
                            }
                        } catch (IOException e) {
                            log.debug("/check failed for uuid {}: {}", submission.getUuid(), e.getMessage());
                        }
                    }
                }

                if (changed) {
                    notifyUpdateCallback();
                    schedulePersistence();
                }
            } catch (Exception e) {
                log.debug("Error while checking pending statuses: {}", e.getMessage());
            }
        });
    }

    /**
     * Check if there are any submissions in active (non-terminal) states
     */
    public boolean hasActiveSubmissions() {
        for (ValidSubmission submission : validSubmissions) {
            SubmissionStatus status = submission.getStatus();
            if (status != null && status.isActive()) {
                return true;
            }
        }
        return false;
    }

    // ========== Group Config Loading Notification ==========

    /**
     * Called when group configs have been loaded. Re-evaluates any events that were
     * queued while configs were unavailable.
     */
    public void onGroupConfigsLoaded() {
        this.groupConfigsLoaded = true;
        if (pendingEvents.isEmpty()) {
            return;
        }

        debugLogEventFlow("qualification", null, "group configs loaded; replaying pendingEvents=" + pendingEvents.size());
        List<PendingEvent> toProcess = new ArrayList<>(pendingEvents);
        pendingEvents.clear();

        for (PendingEvent event : toProcess) {
            // Re-run qualification now that configs are available
            createSubmissionIfQualified(event.webhook, event.type, event.hasScreenshot, event.totalValue, event.singleValue);
        }

        if (!validSubmissions.isEmpty()) {
            notifyUpdateCallback();
            schedulePersistence();
        }
    }

    // ========== Persistence ==========

    /**
     * Load persisted submissions from disk for the given account hash.
     */
    public void loadSubmissions(String accountHash) {
        if (accountHash == null || accountHash.isEmpty() || "-1".equals(accountHash)) {
            return;
        }

        Path filePath = getSubmissionFilePath(accountHash);
        if (!Files.exists(filePath)) {
            return;
        }

        executor.submit(() -> {
            try {
                String json = new String(Files.readAllBytes(filePath), StandardCharsets.UTF_8);
                Type listType = new TypeToken<List<ValidSubmission>>() {}.getType();
                List<ValidSubmission> loaded = gson.fromJson(json, listType);
                if (loaded != null && !loaded.isEmpty()) {
                    // Only load submissions that are still actionable (not yet processed, or recently processed)
                    for (ValidSubmission s : loaded) {
                        // Fix null status from old persistence format
                        if (s.getStatus() == null) {
                            s.markAsFailed("Unknown state after restart");
                        }
                        // Don't re-add if we already have it in memory (by UUID)
                        if (s.getUuid() != null && findByUuid(s.getUuid()) != null) {
                            continue;
                        }
                        validSubmissions.add(s);
                    }
                    debugLogEventFlow("persistence", null, "loaded submissions count=" + loaded.size() + ", accountHash=" + accountHash);
                    notifyUpdateCallback();
                }
            } catch (Exception e) {
                log.debug("Failed to load persisted submissions: {}", e.getMessage());
            }
        });
    }

    /**
     * Save current submissions to disk. This is debounced to avoid excessive I/O.
     */
    private void schedulePersistence() {
        if (executor == null) {
            return;
        }
        if (saveScheduled.compareAndSet(false, true)) {
            pendingSave = executor.schedule(() -> {
                saveScheduled.set(false);
                persistSubmissions();
            }, 2, TimeUnit.SECONDS);
        }
    }

    private void persistSubmissions() {
        String accountHash = client != null ? String.valueOf(client.getAccountHash()) : null;
        if (accountHash == null || "-1".equals(accountHash)) {
            return;
        }

        try {
            Path filePath = getSubmissionFilePath(accountHash);
            Files.createDirectories(filePath.getParent());

            // Only persist submissions that have webhook data (can be retried) or are recent
            List<ValidSubmission> toSave = new ArrayList<>();
            for (ValidSubmission s : validSubmissions) {
                toSave.add(s);
                if (toSave.size() >= MAX_PERSISTED_SUBMISSIONS) {
                    break;
                }
            }

            String json = gson.newBuilder().setPrettyPrinting().create().toJson(toSave);
            Files.write(filePath, json.getBytes(StandardCharsets.UTF_8));
            debugLogEventFlow("persistence", null, "persisted submissions count=" + toSave.size() + ", accountHash=" + accountHash);
        } catch (Exception e) {
            log.debug("Failed to persist submissions: {}", e.getMessage());
        }
    }

    private Path getSubmissionFilePath(String accountHash) {
        return RuneLite.RUNELITE_DIR.toPath().resolve(PERSISTENCE_DIR).resolve(PERSISTENCE_FILE_PREFIX + accountHash + ".json");
    }

    private ValidSubmission findByUuid(String uuid) {
        if (uuid == null) return null;
        for (ValidSubmission s : validSubmissions) {
            if (uuid.equals(s.getUuid())) {
                return s;
            }
        }
        return null;
    }

    // ========== Utilities ==========

    /**
     * Returns a string identifying the current world type for submission tagging.
     * Returns "MAIN" for regular game worlds, or the specific WorldType name for
     * temporary/special worlds (e.g. "BETA_WORLD", "DEADMAN", "SEASONAL").
     * LAST_MAN_STANDING worlds are intentionally treated as MAIN because LMS is
     * played on rotating main-game worlds.
     * Submissions from all world types are sent to the server; this field lets the
     * server separate main-game data from temporary-world data.
     */
    private String getWorldTypeName() {
        var worldType = client.getWorldType();
        if (worldType.contains(WorldType.BETA_WORLD))         return "BETA_WORLD";
        if (worldType.contains(WorldType.DEADMAN))            return "DEADMAN";
        if (worldType.contains(WorldType.FRESH_START_WORLD))  return "FRESH_START_WORLD";
        if (worldType.contains(WorldType.NOSAVE_MODE))        return "NOSAVE_MODE";
        if (worldType.contains(WorldType.PVP_ARENA))          return "PVP_ARENA";
        if (worldType.contains(WorldType.QUEST_SPEEDRUNNING)) return "QUEST_SPEEDRUNNING";
        if (worldType.contains(WorldType.SEASONAL))           return "SEASONAL";
        if (worldType.contains(WorldType.TOURNAMENT_WORLD))   return "TOURNAMENT_WORLD";
        return "MAIN";
    }

    public String sanitize(String str) {
        if (str == null || str.isEmpty())
            return "";
        return Text.removeTags(str.replace("<br>", "\n")).replace('\u00A0', ' ').trim();
    }

    /**
     * Check if a specific embed field has value "true"
     */
    private boolean isFieldTrue(CustomWebhookBody webhook, String fieldName) {
        if (webhook == null || webhook.getEmbeds() == null) return false;
        for (CustomWebhookBody.Embed embed : webhook.getEmbeds()) {
            for (CustomWebhookBody.Field field : embed.getFields()) {
                if (field.getName().equalsIgnoreCase(fieldName)
                        && field.getValue().equalsIgnoreCase("true")) {
                    return true;
                }
            }
        }
        return false;
    }

    private void notifyUpdateCallback() {
        if (updatesEnabled && updateCallback != null) {
            updateCallback.onSubmissionsUpdated();
        }
    }

    private void debugLogEventFlow(String stage, SubmissionType type, String message) {
        DebugLogger.log("[SubmissionManager][" + stage + "][" + (type != null ? type : "UNKNOWN") + "] " + message);
    }

    private String summarizeSubmission(ValidSubmission submission) {
        if (submission == null) {
            return "submission=null";
        }
        return "submissionUuid=" + submission.getUuid()
                + ", status=" + submission.getStatus()
                + ", groups=" + Arrays.toString(submission.getGroupIds());
    }

    // ========== Inner Classes ==========

    public interface SubmissionUpdateCallback {
        void onSubmissionsUpdated();
    }

    @Getter
    private static class ApiResponse {
        @SerializedName("notice")
        private String notice;

        @SerializedName("rank_update")
        private String rankUpdate;

        @SerializedName("status")
        private String status;

        @SerializedName("processed")
        private Boolean processed;

        @SerializedName("submission_id")
        private String submissionId;
    }

    /**
     * Represents an event that arrived before group configs were loaded.
     * Stored temporarily until configs arrive, then re-evaluated.
     */
    private static class PendingEvent {
        final CustomWebhookBody webhook;
        final SubmissionType type;
        final boolean hasScreenshot;
        final long totalValue;
        final long singleValue;

        PendingEvent(CustomWebhookBody webhook, SubmissionType type, boolean hasScreenshot, long totalValue, long singleValue) {
            this.webhook = webhook;
            this.type = type;
            this.hasScreenshot = hasScreenshot;
            this.totalValue = totalValue;
            this.singleValue = singleValue;
        }
    }
}

package io.droptracker.service;

import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.atomic.AtomicBoolean;

import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;

import io.droptracker.api.DropTrackerApi;
import io.droptracker.models.api.Manifest;
import lombok.extern.slf4j.Slf4j;

/**
 * Holds the {@link Manifest} for the life of the client session.
 *
 * <p>Fetched once, off the client thread, and never re-fetched: a manifest that
 * changed underneath a running session would mean the varps we are reading stop
 * matching the varps we started with, and callers have no way to reconcile a
 * half-old snapshot. New settings therefore reach a client on its next start,
 * which is the same propagation model as the rest of the plugin's config.
 *
 * <p>Every consumer must tolerate {@link #getManifest()} returning null — that
 * is the state before the first fetch completes, and after a failed one.
 */
@Slf4j
@Singleton
public class ManifestService {

	private final DropTrackerApi api;
	private final ScheduledExecutorService executor;

	/** Guards against a second fetch while the first is still in flight. */
	private final AtomicBoolean fetching = new AtomicBoolean(false);

	private volatile Manifest manifest;

	@Inject
	public ManifestService(DropTrackerApi api, ScheduledExecutorService executor) {
		this.api = api;
		this.executor = executor;
	}

	/**
	 * The manifest, or null if it has not arrived (or could not be fetched).
	 *
	 * <p>Null is a normal state, not an error: callers fall back to their
	 * built-in behaviour, which is what the plugin did before the manifest
	 * existed.
	 */
	@Nullable
	public Manifest getManifest() {
		return manifest;
	}

	/** Kicks off the one fetch for this session. Safe to call more than once. */
	public void startUp() {
		refresh();
	}

	public void shutDown() {
		manifest = null;
		fetching.set(false);
	}

	/**
	 * Fetches the manifest in the background.
	 *
	 * <p>Failure is deliberately quiet: the manifest is an enhancement, and a
	 * user whose network blocked one request should not see an error for a
	 * feature they did not ask about.
	 */
	public void refresh() {
		if (manifest != null || !fetching.compareAndSet(false, true)) {
			return;
		}
		// A failed fetch leaves manifest null, so a later caller may retry. That
		// matters because the API can be disabled (or the endpoint wrong) when
		// the plugin starts, and without a manifest no combat achievement varps
		// are read at all — the sync silently omits them.
		executor.execute(() -> {
			try {
				Manifest fetched = api.getManifest();
				if (fetched != null) {
					manifest = fetched;
					log.debug("Loaded plugin manifest version {}", fetched.getVersion());
				}
			} catch (Exception e) {
				log.debug("Could not load plugin manifest; using built-in defaults", e);
			} finally {
				fetching.set(false);
			}
		});
	}
}

package io.droptracker.service;

import io.droptracker.DropTrackerConfig;
import io.droptracker.models.api.EventState;
import net.runelite.client.config.ConfigManager;

import javax.annotation.Nullable;
import java.util.Collection;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

/**
 * Per-event task pins and hides for the Events tab, persisted through
 * {@link ConfigManager} with the same per-event keying as the tracked task:
 * {@code pinnedTasks_<eventId>} and {@code hiddenTasks_<eventId>}, each a
 * comma-separated list of task ids in the order the user picked them.
 *
 * <p>The single tracked task is the degenerate one-pin case. The first
 * <i>incomplete</i> pinned task is mirrored into {@code trackedTask_<eventId>}
 * by {@link #syncFocus} — that key stays the canonical "focus" that
 * {@link EventNotificationService#trackedTaskId(int)} reads, so the HUD,
 * {@link EventNotificationService#displayTask(EventState.Entry)} and anything
 * else built on it keep working without knowing pins exist. Config written by
 * an older build (a tracked task, no pin list) is read back as a single pin.
 *
 * <p>The hide set is readable without a panel instance
 * ({@link #hidden(ConfigManager, int)}) because hiding has to reach past the
 * list it was clicked in: {@link EventNotificationService#hiddenTaskIds(int)}
 * reads it to keep a hidden task out of the HUD and to mute its progress
 * chat/pop-ups. Completions are still announced — see that class.
 */
public class EventTaskPrefs {
    private static final String PINNED_PREFIX = "pinnedTasks_";
    private static final String HIDDEN_PREFIX = "hiddenTasks_";
    /** Stored for an empty list: 0 is not a task id, so it parses away. */
    private static final String NO_IDS = "0";

    private final ConfigManager configManager;
    private final EventNotificationService service;

    public EventTaskPrefs(ConfigManager configManager, EventNotificationService service) {
        this.configManager = configManager;
        this.service = service;
    }

    /** Task ids the user pinned for this event, in pin order. */
    public Set<Integer> pinned(int eventId) {
        String raw = get(PINNED_PREFIX + eventId);
        if (raw == null) {
            // Pre-pin-set config: the tracked task is the one and only pin.
            Set<Integer> migrated = new LinkedHashSet<>();
            int tracked = service.trackedTaskId(eventId);
            if (tracked > 0) {
                migrated.add(tracked);
            }
            return migrated;
        }
        return parse(raw);
    }

    /** Task ids the user hid for this event. */
    public Set<Integer> hidden(int eventId) {
        return hidden(configManager, eventId);
    }

    /** {@link #hidden(int)} without a panel — for callers that only have the
     *  ConfigManager (the HUD and notification filtering). */
    public static Set<Integer> hidden(ConfigManager configManager, int eventId) {
        return parse(get(configManager, HIDDEN_PREFIX + eventId));
    }

    /** Pin or unpin a task, then re-point the HUD focus at the top pin. */
    public void togglePin(EventState.Entry entry, int taskId) {
        int eventId = eventId(entry);
        if (eventId <= 0) {
            return;
        }
        Set<Integer> ids = pinned(eventId);
        if (!ids.remove(taskId)) {
            ids.add(taskId);
            // A task cannot be both focused and out of sight.
            unhide(eventId, taskId);
        }
        put(PINNED_PREFIX + eventId, ids);
        syncFocus(entry);
    }

    /** Drop one pin (the tracked-task box's "unpin"), promoting the next. */
    public void unpin(EventState.Entry entry, int taskId) {
        int eventId = eventId(entry);
        if (eventId <= 0) {
            return;
        }
        Set<Integer> ids = pinned(eventId);
        if (ids.remove(taskId)) {
            put(PINNED_PREFIX + eventId, ids);
        }
        syncFocus(entry);
    }

    /** Hide or unhide a task; hiding it also gives up its pin. */
    public void toggleHidden(EventState.Entry entry, int taskId) {
        int eventId = eventId(entry);
        if (eventId <= 0) {
            return;
        }
        Set<Integer> ids = hidden(eventId);
        if (ids.remove(taskId)) {
            put(HIDDEN_PREFIX + eventId, ids);
        } else {
            ids.add(taskId);
            put(HIDDEN_PREFIX + eventId, ids);
            unpin(entry, taskId);
        }
    }

    /** Bring every hidden task of this event back into the list. */
    public void unhideAll(int eventId) {
        put(HIDDEN_PREFIX + eventId, new LinkedHashSet<>());
    }

    /**
     * Mirror the first incomplete pin into the canonical tracked-task key, so
     * the HUD headlines it. No pins (or every pin completed) means "let the
     * server decide", exactly as an unset tracked task always has.
     *
     * <p>Skipped for board games — their current tile is forced, never picked —
     * and while the server sends no task list, where completion is unknowable
     * and clearing the key would silently drop the user's pick.
     */
    public void syncFocus(@Nullable EventState.Entry entry) {
        int eventId = eventId(entry);
        if (eventId <= 0 || "board_game".equals(entry.getEvent().getKind())) {
            return;
        }
        List<EventState.TaskInfo> tasks = entry.getTasks();
        if (tasks == null) {
            return;
        }
        Set<Integer> pins = pinned(eventId);
        if (!pins.isEmpty() && get(PINNED_PREFIX + eventId) == null) {
            // Migrated from a tracked task: write the pin list out once so the
            // pin survives the task completing (which clears the tracked key).
            put(PINNED_PREFIX + eventId, pins);
        }
        int focus = 0;
        for (Integer id : pins) {
            EventState.TaskInfo task = task(tasks, id);
            if (task != null && !task.isCompleted()) {
                focus = id;
                break;
            }
        }
        if (focus != service.trackedTaskId(eventId)) {
            service.setTrackedTask(eventId, focus);
        }
    }

    private void unhide(int eventId, int taskId) {
        Set<Integer> ids = hidden(eventId);
        if (ids.remove(taskId)) {
            put(HIDDEN_PREFIX + eventId, ids);
        }
    }

    @Nullable
    private static EventState.TaskInfo task(List<EventState.TaskInfo> tasks, int id) {
        for (EventState.TaskInfo task : tasks) {
            if (task.getId() == id) {
                return task;
            }
        }
        return null;
    }

    private static int eventId(@Nullable EventState.Entry entry) {
        return entry != null && entry.getEvent() != null ? entry.getEvent().getId() : 0;
    }

    @Nullable
    private String get(String key) {
        return get(configManager, key);
    }

    @Nullable
    private static String get(ConfigManager configManager, String key) {
        try {
            return configManager.getConfiguration(DropTrackerConfig.GROUP, key);
        } catch (Exception e) {
            return null;
        }
    }

    /**
     * An empty set is stored as {@link #NO_IDS}, never unset and never blank:
     * "the user cleared their pins" must not read back as "never used pins",
     * which would resurrect the tracked task the pins were migrated from.
     */
    private void put(String key, Collection<Integer> ids) {
        StringBuilder csv = new StringBuilder();
        for (Integer id : ids) {
            if (csv.length() > 0) {
                csv.append(',');
            }
            csv.append(id);
        }
        if (csv.length() == 0) {
            csv.append(NO_IDS);
        }
        try {
            configManager.setConfiguration(DropTrackerConfig.GROUP, key, csv.toString());
        } catch (Exception ignored) {
            // A failed write costs the user a pin, never the panel.
        }
    }

    private static Set<Integer> parse(@Nullable String raw) {
        Set<Integer> ids = new LinkedHashSet<>();
        if (raw == null || raw.isEmpty()) {
            return ids;
        }
        for (String part : raw.split(",")) {
            try {
                int id = Integer.parseInt(part.trim());
                if (id > 0) {
                    ids.add(id);
                }
            } catch (NumberFormatException ignored) {
                // Hand-edited config: skip the junk, keep the rest.
            }
        }
        return ids;
    }
}

package io.droptracker.service;

import java.lang.ref.WeakReference;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Optional;

import javax.annotation.Nullable;

import net.runelite.api.Actor;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.Player;
import org.apache.commons.lang3.ArrayUtils;

/**
 * A short rolling memory of who the local player was fighting.
 *
 * <p>Killer attribution that only looks at the death tick answers the question
 * "who is attacking me <em>right now</em>", and on the tick a player dies the
 * answer is very often "nobody": the game drops an NPC's target the moment that
 * target dies, bosses despawn with the instance, and in group content the NPC
 * has already switched to whoever is still standing. Every candidate is then
 * filtered away and the death is submitted with no source at all.
 *
 * <p>This tracker records each engagement as it is announced by
 * {@code InteractingChanged} — both directions, ours and theirs — as a
 * <em>snapshot</em> (name, NPC id, combat level) rather than a live reference,
 * so an actor that has since despawned or been garbage collected can still be
 * named. A death that no live candidate explains is then attributed to the most
 * plausible engagement from the last few ticks.
 *
 * <p>Not thread safe; every caller is on the client thread.
 */
public final class RecentCombatTracker {

    /** How stale a <em>finished</em> engagement may be and still be blamed (~7s). */
    public static final int RECENT_WINDOW_TICKS = 12;

    /**
     * How stale an engagement we never saw end may be and still be blamed (~30s).
     *
     * <p>An engagement stays "open" until the client tells us it ended, and that
     * message never arrives if the actor simply vanished (instance torn down,
     * region change, world hop). This ceiling is what stops such a leftover from
     * being blamed for an unrelated death minutes later.
     */
    public static final int OPEN_WINDOW_TICKS = 50;

    /** An engagement this fresh is treated as having been live at the death. */
    private static final int AT_DEATH_TICKS = 3;

    private static final int MAX_TRACKED = 24;

    private static final String ATTACK_OPTION = "Attack";

    /** Access-ordered so eviction drops the least recently touched engagement. */
    private final Map<String, Engagement> engagements = new LinkedHashMap<>(16, 0.75f, true);

    /** Records that {@code actor} started attacking (or otherwise targeting) us. */
    public void recordAttackedBy(@Nullable Actor actor, int tick) {
        Engagement engagement = upsert(actor, tick);
        if (engagement != null) {
            engagement.attackedUs = true;
            engagement.inboundOpen = true;
        }
    }

    /** Records that {@code actor} stopped targeting us. */
    public void endAttackedBy(@Nullable Actor actor, int tick) {
        Engagement engagement = actor != null ? engagements.get(key(actor)) : null;
        if (engagement != null && engagement.inboundOpen) {
            engagement.inboundOpen = false;
            engagement.lastTick = tick;
        }
    }

    /**
     * Records that the local player started interacting with {@code actor}.
     *
     * <p>Our own outbound target is implicitly exclusive, so any other open
     * outbound engagement is closed at the same tick.
     */
    public void recordAttacking(@Nullable Actor actor, int tick) {
        Engagement engagement = upsert(actor, tick);
        if (engagement != null) {
            engagement.weAttacked = true;
            engagement.outboundOpen = true;
        }
        endAttacking(actor, tick);
    }

    /**
     * Closes every open outbound engagement except {@code except} (pass null when
     * the local player stopped interacting with anything at all).
     */
    public void endAttacking(@Nullable Actor except, int tick) {
        String keep = except != null ? key(except) : null;
        for (Map.Entry<String, Engagement> entry : engagements.entrySet()) {
            if (entry.getKey().equals(keep)) {
                continue;
            }
            Engagement engagement = entry.getValue();
            if (engagement.outboundOpen) {
                engagement.outboundOpen = false;
                engagement.lastTick = tick;
            }
        }
    }

    /** Drops an actor from consideration — used when it dies. */
    public void forget(@Nullable Actor actor) {
        if (actor != null) {
            engagements.remove(key(actor));
        }
    }

    public void clear() {
        engagements.clear();
    }

    /**
     * @param tick       the current client tick
     * @param pvpEnabled whether another player could plausibly have killed us
     * @return the engagement most likely to explain a death on this tick
     */
    public Optional<Engagement> mostLikelyKiller(int tick, boolean pvpEnabled) {
        Engagement best = null;
        for (Engagement candidate : engagements.values()) {
            if (!eligible(candidate, tick, pvpEnabled)) {
                continue;
            }
            if (best == null || compare(candidate, best, tick) < 0) {
                best = candidate;
            }
        }
        return Optional.ofNullable(best);
    }

    /** Visible for tests: how many engagements are currently remembered. */
    public int size() {
        return engagements.size();
    }

    @Nullable
    private Engagement upsert(@Nullable Actor actor, int tick) {
        if (actor == null) {
            return null;
        }
        String key = key(actor);
        Engagement existing = engagements.get(key);
        if (existing != null) {
            existing.lastTick = tick;
            existing.actor = new WeakReference<>(actor);
            return existing;
        }

        Engagement created = snapshot(actor, tick);
        if (created == null) {
            return null;
        }
        engagements.put(key, created);
        prune(tick);
        return created;
    }

    private void prune(int tick) {
        Iterator<Engagement> values = engagements.values().iterator();
        while (values.hasNext()) {
            Engagement engagement = values.next();
            int age = tick - engagement.lastTick;
            if (age < 0 || age > OPEN_WINDOW_TICKS) {
                values.remove();
            }
        }
        // Access-ordered: the head is the least recently touched engagement.
        Iterator<String> keys = engagements.keySet().iterator();
        while (engagements.size() > MAX_TRACKED && keys.hasNext()) {
            keys.next();
            keys.remove();
        }
    }

    private static boolean eligible(Engagement engagement, int tick, boolean pvpEnabled) {
        if (engagement.player && (!pvpEnabled || engagement.friendly)) {
            // A friend or clanmate we traded with is not a killer, and outside
            // PvP no player is.
            return false;
        }
        Actor live = engagement.actor.get();
        if (live != null && live.isDead()) {
            // We killed it (or it died first); it cannot have killed us.
            return false;
        }
        int age = tick - engagement.lastTick;
        if (age < 0) {
            // Tick counter went backwards — a hop or relog; the record predates
            // this session's world and means nothing.
            return false;
        }
        return age <= (engagement.isOpen() ? OPEN_WINDOW_TICKS : RECENT_WINDOW_TICKS);
    }

    /**
     * Orders candidates best-first (negative means {@code a} is the better
     * explanation for the death).
     */
    private static int compare(Engagement a, Engagement b, int tick) {
        int result = Boolean.compare(b.wasLiveAt(tick), a.wasLiveAt(tick));
        if (result != 0) {
            return result;
        }
        // Something we were trading blows with beats something that only
        // attacked us, which beats something we merely clicked on.
        result = Integer.compare(b.directionRank(), a.directionRank());
        if (result != 0) {
            return result;
        }
        result = Boolean.compare(b.attackable, a.attackable);
        if (result != 0) {
            return result;
        }
        result = Integer.compare(b.combatLevel, a.combatLevel);
        if (result != 0) {
            return result;
        }
        return Integer.compare(b.lastTick, a.lastTick);
    }

    /**
     * Keyed on scene index for NPCs and name for players rather than on the
     * {@link Actor} itself, so nothing here keeps a despawned actor alive.
     */
    private static String key(Actor actor) {
        if (actor instanceof NPC) {
            return "n" + ((NPC) actor).getIndex();
        }
        String name = cleanName(actor.getName());
        return "p" + (name != null ? name : String.valueOf(System.identityHashCode(actor)));
    }

    /**
     * @return a snapshot of the actor, or null when it could not plausibly kill
     *         anyone (a pet, a shopkeeper, an unnamed player)
     */
    @Nullable
    private static Engagement snapshot(Actor actor, int tick) {
        if (actor instanceof NPC) {
            NPC npc = (NPC) actor;
            NPCComposition composition = npc.getTransformedComposition();
            if (composition == null) {
                composition = npc.getComposition();
            }
            if (composition == null || composition.isFollower()) {
                return null;
            }
            boolean attackable = ArrayUtils.contains(composition.getActions(), ATTACK_OPTION);
            int combatLevel = composition.getCombatLevel();
            if (!attackable && combatLevel <= 0) {
                // Dialogue partners, pets and scenery face the player too.
                return null;
            }
            String name = cleanName(npc.getName());
            if (name == null) {
                name = cleanName(composition.getName());
            }
            // isInteractible() is deliberately not required here (it is in the
            // live scan): a few instanced attackers cannot be clicked, and this
            // snapshot is only ever consulted after the live scan came up empty.
            return new Engagement(actor, name, npc.getId(), combatLevel, false, attackable, false, tick);
        }

        if (actor instanceof Player) {
            Player player = (Player) actor;
            String name = cleanName(player.getName());
            if (name == null) {
                return null;
            }
            boolean friendly = player.isFriend() || player.isClanMember() || player.isFriendsChatMember();
            return new Engagement(actor, name, null, player.getCombatLevel(), true, true, friendly, tick);
        }

        return null;
    }

    /**
     * Actor names arrive with colour tags and non-breaking spaces; a name that is
     * nothing but markup is no name at all and must not become a blank source.
     */
    @Nullable
    public static String cleanName(@Nullable String raw) {
        if (raw == null) {
            return null;
        }
        String cleaned = raw.replace('\u00A0', ' ').replaceAll("<[^>]*>", "").trim();
        return cleaned.isEmpty() ? null : cleaned;
    }

    /** An actor the local player was recently in combat with. */
    public static final class Engagement {

        private WeakReference<Actor> actor;
        private final String name;
        private final Integer npcId;
        private final int combatLevel;
        private final boolean player;
        private final boolean attackable;
        private final boolean friendly;

        private boolean attackedUs;
        private boolean weAttacked;
        private boolean inboundOpen;
        private boolean outboundOpen;
        private int lastTick;

        Engagement(Actor actor, @Nullable String name, @Nullable Integer npcId, int combatLevel,
                boolean player, boolean attackable, boolean friendly, int tick) {
            this.actor = new WeakReference<>(actor);
            this.name = name;
            this.npcId = npcId;
            this.combatLevel = combatLevel;
            this.player = player;
            this.attackable = attackable;
            this.friendly = friendly;
            this.lastTick = tick;
        }

        @Nullable
        public String getName() {
            return name;
        }

        @Nullable
        public Integer getNpcId() {
            return npcId;
        }

        public int getCombatLevel() {
            return combatLevel;
        }

        public boolean isPlayer() {
            return player;
        }

        public boolean isNpc() {
            return !player;
        }

        boolean isOpen() {
            return inboundOpen || outboundOpen;
        }

        /** Whether the engagement was, as far as we know, still running at {@code tick}. */
        boolean wasLiveAt(int tick) {
            return isOpen() || tick - lastTick <= AT_DEATH_TICKS;
        }

        int directionRank() {
            if (attackedUs && weAttacked) {
                return 2;
            }
            return attackedUs ? 1 : 0;
        }

        @Override
        public String toString() {
            return "Engagement(" + name + ", npcId=" + npcId + ", lvl=" + combatLevel
                    + ", player=" + player + ", rank=" + directionRank() + ", open=" + isOpen()
                    + ", lastTick=" + lastTick + ")";
        }
    }
}

package io.droptracker.service;
/* Author: https://github.com/pajlads/DinkPlugin */

import com.google.common.cache.Cache;
import com.google.common.cache.CacheBuilder;
import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;

import io.droptracker.DropTrackerPlugin;
import io.droptracker.models.SerializedDrop;
import io.droptracker.models.submissions.Drop;
import io.droptracker.util.NpcUtilities;
import io.droptracker.util.Rarity;
import lombok.extern.slf4j.Slf4j;
import org.jetbrains.annotations.VisibleForTesting;
import net.runelite.api.NPC;
import net.runelite.api.NpcID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.config.RuneLiteConfig;
import net.runelite.client.events.NpcLootReceived;
import net.runelite.client.events.PlayerLootReceived;
import net.runelite.client.events.ServerNpcLoot;
import net.runelite.client.game.ItemStack;
import net.runelite.client.plugins.chatcommands.ChatCommandsPlugin;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.client.plugins.loottracker.LootTrackerConfig;
import net.runelite.client.plugins.loottracker.LootTrackerPlugin;
import net.runelite.http.api.loottracker.LootRecordType;
import org.apache.commons.lang3.StringUtils;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.*;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

@Slf4j
@Singleton
public class KCService {


    private static final String RL_CHAT_CMD_PLUGIN_NAME = ChatCommandsPlugin.class.getSimpleName().toLowerCase();
    private static final String RL_LOOT_PLUGIN_NAME = LootTrackerPlugin.class.getSimpleName().toLowerCase();
    private static final Pattern CLUE_SCROLL_REGEX = Pattern.compile("You have completed (?<scrollCount>\\d+) (?<scrollType>\\w+) Treasure Trails\\.");

    private ConfigManager configManager;


    private Gson gson;

    @Inject
    private ScheduledExecutorService executor;

    private Rarity rarityService;

    @Inject
    private DropTrackerPlugin plugin;

    /* Field-injected (nullable in tests): re-armed on completion messages so
     * the raid chest re-loot dedup never spans two completions. */
    @Inject
    private RaidLootDeduplicator raidLootDeduplicator;

    private List<Integer> whispererIds = Arrays.asList(12204, 12205, 12206, 12207);


    private static final Cache<String, Integer> killCounts = CacheBuilder.newBuilder()
            .expireAfterAccess(10, TimeUnit.MINUTES)
            .maximumSize(64L)
            .build();


    @Inject
    public KCService(ConfigManager configManager, Gson gson,
                     ScheduledExecutorService executor,
                     Rarity rarityService, DropTrackerPlugin plugin) {
        this.configManager = configManager;
        this.gson = gson;
        this.rarityService = rarityService;
        this.executor = executor;
        this.plugin = plugin;
    }

    public void reset() {
        plugin.lastDrop = null;
        KCService.killCounts.invalidateAll();
    }

    @SuppressWarnings("deprecation")
    public void onNpcKill(NpcLootReceived event) {
        NPC npc = event.getNpc();
        int id = npc.getId();
        if (whispererIds.contains(id)) {
            return;
        }

        String name = npc.getName();
        if (NpcUtilities.GAUNTLET_BOSS.equals(name) || NpcUtilities.CG_BOSS.equals(name)) {
            // already handled by onGameMessage
            return;
        }
        if (name != null) {
            this.incrementKills(LootRecordType.NPC, name, event.getItems());
        }
    }

    public void onPlayerKill(PlayerLootReceived event) {
        String name = event.getPlayer().getName();
        if (name != null) {
            this.incrementKills(LootRecordType.PLAYER, name, event.getItems());
        }
    }

    public void onLoot(LootReceived event) {
        boolean increment;
        switch (event.getType()) {
            case NPC:
                // Special case: upstream fires LootReceived for the whisperer, but not NpcLootReceived
                increment = "The Whisperer".equalsIgnoreCase(event.getName());
                break;
            case PLAYER:
                increment = false; // handled by PlayerLootReceived
                break;
            default:
                increment = true;
                break;
        }

        if (increment) {
            this.incrementKills(event.getType(), NpcUtilities.getStandardizedSource(event, plugin), event.getItems());
        }
    }
    public void onServerNpcLoot(ServerNpcLoot event) {
        /* Currently only called for Yama events */
        this.incrementKills(LootRecordType.NPC, event.getComposition().getName(), event.getItems());
    }

    public void onGameMessage(String message) {
        // update cached clue casket count
        Map.Entry<String, Integer> clue = parseClue(message);
        if (clue != null) {
            String tier = ucFirst(clue.getKey());
            int count = clue.getValue() - 1; // decremented since onLoot will increment
            killCounts.put("Clue Scroll (" + tier + ")", count);
            return;
        }

        NpcUtilities.parseBoss(message, plugin).ifPresent(pair -> {
            String boss = pair.getKey();
            Integer kc = pair.getValue();

            // A raid completion message means the next reward chest opened is
            // NEW loot — re-arm the chest re-loot dedup for that raid.
            if (raidLootDeduplicator != null) {
                raidLootDeduplicator.onRaidCompletion(boss);
            }

            // Update cache. We store kc - 1 since onNpcLootReceived will increment; kc - 1 + 1 == kc
            String cacheKey = getCacheKey(LootRecordType.UNKNOWN, boss);
            killCounts.asMap().merge(cacheKey, kc - 1, Math::max);

            if (boss.equals(NpcUtilities.GAUNTLET_BOSS) || boss.equals(NpcUtilities.CG_BOSS) || boss.startsWith(NpcUtilities.TOA) || boss.startsWith(NpcUtilities.TOB) || boss.startsWith(NpcUtilities.COX)) {
                // populate lastDrop to workaround loot tracker quirks
                // (RuneLite fires LootReceived with "The Gauntlet" for both regular and corrupted)
                plugin.lastDrop = new Drop(boss, LootRecordType.EVENT, Collections.emptyList());

                if (!isPluginDisabled(RL_LOOT_PLUGIN_NAME)) {   
                    // onLoot will already increment kc, no need to schedule task below.
                    // this early return also simplifies our test code
                    return;
                }
            }

            // However: we don't know if boss message appeared before/after the loot event.
            // If after, we should store kc. If before, we should store kc - 1.
            // Given this uncertainty, we wait so that the loot event has passed, and then we can store latest kc.


            /* -- We are using the executor here -- */
            executor.schedule(() -> {
                killCounts.asMap().merge(cacheKey, kc, Math::max);
            }, 15, TimeUnit.SECONDS);
        });
    }

    @Nullable
    public Integer getKillCount(LootRecordType type, String sourceName) {
        if (sourceName == null) return null;
        // This static method is deprecated - use instance method instead
        return killCounts.getIfPresent(getCacheKey(type, sourceName));
    }

    @Nullable
    public Integer getKillCountWithStorage(LootRecordType type, String sourceName) {
        if (sourceName == null) return null;
        Integer stored = getStoredKillCount(type, sourceName);
        if (stored != null) {
            return killCounts.asMap().merge(getCacheKey(type, sourceName), stored, Math::max);
        }
        return killCounts.getIfPresent(getCacheKey(type, sourceName));
    }

    private void incrementKills(@NotNull LootRecordType type, @NotNull String sourceName, @NotNull Collection<ItemStack> items) {
        String cacheKey = getCacheKey(type, sourceName);
        killCounts.asMap().compute(cacheKey, (key, cachedKc) -> {
            if (cachedKc != null) {
                // increment kill count
                return cachedKc + 1;
            } else {
                // pull kc from loot tracker or chat commands plugin
                Integer kc = getStoredKillCount(type, sourceName);
                // increment if found
                return kc != null ? kc + 1 : null;
            }
        });
    }

    /**
     * @param type       {@link LootReceived#getType()}
     * @param sourceName {@link NPC#getName()} or {@link LootReceived#getName()}
     * @return the kill count stored by base runelite plugins
     */
    @Nullable
    private Integer getStoredKillCount(@NotNull LootRecordType type, @NotNull String sourceName) {
        // get kc from base runelite chat commands plugin (if enabled)
        if (!isPluginDisabled(RL_CHAT_CMD_PLUGIN_NAME)) {
            Integer kc = configManager.getRSProfileConfiguration("killcount", cleanBossName(sourceName), int.class);
            if (kc != null) {
                return kc - 1; // decremented since chat event typically occurs before loot event
            }
        }

        if (isPluginDisabled(RL_LOOT_PLUGIN_NAME)) {
            // assume stored kc is useless if loot tracker plugin is disabled
            return null;
        }
        String json = configManager.getConfiguration(LootTrackerConfig.GROUP,
                configManager.getRSProfileKey(),
                "drops_" + type + "_" + sourceName
        );
        if (json == null) {
            // no kc stored implies first kill
            return 0;
        }
        try {
            int kc = gson.fromJson(json, SerializedDrop.class).getKills();

            // loot tracker doesn't count kill if no loot - https://github.com/runelite/runelite/issues/5077
            OptionalDouble nothingProbability = rarityService.getRarity(sourceName, -1, 0);
            if (nothingProbability.isPresent() && nothingProbability.getAsDouble() < 1.0) {
                // estimate the actual kc (including kills with no loot)
                kc = (int) Math.round(kc / (1 - nothingProbability.getAsDouble()));
            }

            return kc;
        } catch (JsonSyntaxException e) {
            // should not occur unless loot tracker changes stored loot POJO structure
            log.warn("Failed to read kills from loot tracker config", e);
            return null;
        }
    }

    /**
     * @param boss {@link LootReceived#getName()}
     * @return lowercase boss name that {@link ChatCommandsPlugin} uses during serialization
     */
    @VisibleForTesting
    static String cleanBossName(String boss) {
        if ("The Gauntlet".equalsIgnoreCase(boss)) return "gauntlet";
        if ("The Leviathan".equalsIgnoreCase(boss)) return "leviathan";
        if ("The Whisperer".equalsIgnoreCase(boss)) return "whisperer";
        if (boss.startsWith("Barrows")) return "barrows chests";
        if (boss.endsWith("Hallowed Sepulchre)")) return "hallowed sepulchre";
        if (boss.endsWith("Tempoross)")) return "tempoross";
        if (boss.endsWith("Wintertodt)")) return "wintertodt";
        return StringUtils.remove(boss.toLowerCase(), ':');
    }

    @VisibleForTesting
    static String getCacheKey(@NotNull LootRecordType type, @NotNull String sourceName) {
        switch (type) {
            case PICKPOCKET:
                return "pickpocket_" + sourceName;
            case PLAYER:
                return "player_" + sourceName;
            default:
                if ("The Gauntlet".equals(sourceName)) return NpcUtilities.GAUNTLET_BOSS;
                if (NpcUtilities.CG_NAME.equals(sourceName)) return NpcUtilities.CG_BOSS;
                return sourceName;
        }
    }
    @Nullable
    public static Map.Entry<String, Integer> parseClue(String gameMessage) {
        Matcher clueMatcher = CLUE_SCROLL_REGEX.matcher(gameMessage);
        if (!clueMatcher.find()) return null;
        String tier = clueMatcher.group("scrollType");
        String count = clueMatcher.group("scrollCount");
        return Map.entry(tier, Integer.parseInt(count));
    }

    public String ucFirst(@NotNull String text) {
        if (text.length() < 2) return text.toUpperCase();
        return Character.toUpperCase(text.charAt(0)) + text.substring(1).toLowerCase();
    }

    protected boolean isPluginDisabled(String simpleLowerClassName) {
        return "false".equals(configManager.getConfiguration(RuneLiteConfig.GROUP_NAME, simpleLowerClassName));
    }
}

package io.droptracker.service;

import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;

import io.droptracker.DropTrackerConfig;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;

/**
 * Reads what the player is wearing and carrying, for attaching to a personal
 * best.
 *
 * <p>"What did you bring?" is the first thing anyone asks about a good time, and
 * it is information the kill message alone cannot carry. This is item ids only —
 * no geometry, no model, no screenshot — so it costs a few hundred bytes and can
 * be rendered as the familiar inventory and equipment tabs.
 *
 * <p>Timing matters more than it looks. The capture has to happen while the
 * loadout still reflects the kill: a snapshot taken when the submission is
 * assembled can show a player who has already banked, eaten, died or teleported.
 * Callers therefore capture on the client thread as soon as the kill is
 * recognised, within a tick or two of the kill itself.
 *
 * <p>Encoded as a compact string rather than JSON because it travels in a
 * webhook embed field, and those are limited to 1024 characters — a full
 * 28-slot inventory plus worn equipment fits comfortably in this form and would
 * not as JSON.
 */
@Slf4j
@Singleton
public class LoadoutCapture {

	/** Slot-index/item-id/quantity triples, e.g. {@code "0-11802-1,3-995-1000"}. */
	private static final char ENTRY_SEPARATOR = ',';
	private static final char FIELD_SEPARATOR = '-';

	/**
	 * Hard ceiling on the encoded length. Embed field values are capped at 1024
	 * characters; a real loadout is far shorter, so hitting this means something
	 * unexpected and the value is dropped rather than truncated into nonsense.
	 */
	private static final int MAX_ENCODED_LENGTH = 1000;

	private final Client client;
	private final DropTrackerConfig config;

	@Inject
	public LoadoutCapture(Client client, DropTrackerConfig config) {
		this.client = client;
		this.config = config;
	}

	public boolean isEnabled() {
		return config.uploadCharacterModel() && config.sendLoadoutWithPbs();
	}

	/**
	 * Worn equipment, or null when unavailable or disabled.
	 *
	 * <p>Must be called on the client thread.
	 */
	@Nullable
	public String captureEquipment() {
		return isEnabled() ? encode(client.getItemContainer(InventoryID.WORN)) : null;
	}

	/**
	 * Carried inventory, or null when unavailable or disabled.
	 *
	 * <p>Must be called on the client thread.
	 */
	@Nullable
	public String captureInventory() {
		return isEnabled() ? encode(client.getItemContainer(InventoryID.INV)) : null;
	}

	/**
	 * Encodes the occupied slots of a container.
	 *
	 * <p>Empty slots are omitted rather than written as zeros: the slot index is
	 * carried explicitly, so the layout survives without paying for the gaps.
	 * Returns null for an absent or empty container, which callers treat as "no
	 * loadout" — an empty string would be indistinguishable from a real capture
	 * of a player carrying nothing.
	 */
	@Nullable
	private String encode(@Nullable ItemContainer container) {
		if (container == null) {
			return null;
		}

		Item[] items = container.getItems();
		if (items == null || items.length == 0) {
			return null;
		}

		StringBuilder encoded = new StringBuilder();
		for (int slot = 0; slot < items.length; slot++) {
			Item item = items[slot];
			if (item == null || item.getId() <= 0 || item.getQuantity() <= 0) {
				continue;
			}
			if (encoded.length() > 0) {
				encoded.append(ENTRY_SEPARATOR);
			}
			encoded.append(slot)
					.append(FIELD_SEPARATOR)
					.append(item.getId())
					.append(FIELD_SEPARATOR)
					.append(item.getQuantity());
		}

		if (encoded.length() == 0) {
			return null;
		}
		if (encoded.length() > MAX_ENCODED_LENGTH) {
			log.debug("Loadout encoding was {} chars; dropping rather than truncating",
					encoded.length());
			return null;
		}
		return encoded.toString();
	}
}

package io.droptracker.api;

import javax.crypto.Cipher;
import javax.crypto.Mac;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.Base64;

import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

@Slf4j
@Singleton
public class FernetDecrypt {
    public static String ENCRYPTION_KEY = "";

    @Inject
    public FernetDecrypt() {
    }

    public static String decryptWebhook(String webhookHash) throws Exception {
        try {
            // First decode - get the Fernet token
            String fernetToken = new String(Base64.getUrlDecoder().decode(webhookHash), StandardCharsets.UTF_8);

            // Second decode - get the encrypted data
            byte[] token = Base64.getUrlDecoder().decode(fernetToken);

            // Decode the key
            byte[] keyBytes = Base64.getUrlDecoder().decode(ENCRYPTION_KEY);
            byte[] signingKey = Arrays.copyOfRange(keyBytes, 0, 16);
            byte[] encryptionKey = Arrays.copyOfRange(keyBytes, 16, 32);

            // Extract components according to Fernet spec:
            // Version (1 byte) + Timestamp (8 bytes) + IV (16 bytes) + Ciphertext + HMAC (32 bytes)
            if (token.length < 57) { // Minimum size: 1+8+16+0+32
                throw new IllegalArgumentException("Token too short: " + token.length);
            }

            byte version = token[0];

            // Skip timestamp (bytes 1-8) - not needed for decryption

            // Extract IV (bytes 9-24)  
            byte[] iv = Arrays.copyOfRange(token, 9, 25);

            // Get the HMAC (last 32 bytes)
            byte[] hmac = Arrays.copyOfRange(token, token.length - 32, token.length);
            byte[] message = Arrays.copyOfRange(token, 0, token.length - 32);

            // Verify HMAC
            Mac mac = Mac.getInstance("HmacSHA256");
            mac.init(new SecretKeySpec(signingKey, "HmacSHA256"));
            byte[] calculatedHmac = mac.doFinal(message);

            if (!Arrays.equals(hmac, calculatedHmac)) {
                throw new SecurityException("Invalid HMAC");
            }

            // Get ciphertext (everything between IV and HMAC)
            // Start at byte 25 (after version + timestamp + IV)
            byte[] ciphertext = Arrays.copyOfRange(token, 25, token.length - 32);
            // Decrypt
            Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
            cipher.init(Cipher.DECRYPT_MODE, 
                       new SecretKeySpec(encryptionKey, "AES"),
                       new IvParameterSpec(iv));

            byte[] decryptedBytes = cipher.doFinal(ciphertext);
            String result = new String(decryptedBytes, StandardCharsets.UTF_8);

            // Post-process the result to fix common issues
            result = postProcessDecrypted(result);

            return result;
        } catch (Exception e) {
            log.error("Decryption failed for webhook hash: {}", webhookHash.substring(0, Math.min(20, webhookHash.length())) + "...", e);
            throw e;
        }
    }

    /**
     * Strips the leading non-printable bytes that occasionally survive decryption.
     *
     * <p>This used to also synthesise {@code "https://discord.com" + path} when the
     * plaintext looked like a webhook. It no longer does: the plaintext is a
     * credential, not an address, and the host is decided by
     * {@link DropTrackerUrls#DISCORD_WEBHOOK}. See
     * {@link UrlManager#parseEndpoint(String)}.
     */
    private static String postProcessDecrypted(String decrypted) {
        if (decrypted == null || decrypted.isEmpty()) {
            return decrypted;
        }
        return decrypted.replaceAll("^[\\p{Cntrl}\\p{So}\\p{Cn}]+", "");
    }
}

