                        if (!looksLikeHtml(body)) {
                            result = body;
                        }
                    }

                    // Run callback on EDT to update UI safely
                    final String finalResult = result;
                    javax.swing.SwingUtilities.invokeLater(() -> callback.accept(finalResult));
                }
            }
        });
    }

