    /** Response of GET /notifications. */
    public static class NotificationsResponse {
        @SerializedName("notifications")
        public List<io.droptracker.models.api.EventNotification> notifications;
        @SerializedName("active_event")
        public Boolean activeEvent;
        /**
         * Present (true) only when the server understood a {@code wait}
         * request; its absence marks a legacy server that ignored the param,
         * so the caller must fall back to fixed-interval polling.
         */
        @SerializedName("long_poll")
        public Boolean longPoll;
    }

    /**
     * Builds the GET /notifications call that drains the player's
     * event-notification inbox. {@code waitSeconds > 0} long-polls: the
     * server holds an empty-inbox request open up to that many seconds (it
     * clamps to its own cap) and flags the response with long_poll=true.
     * Returns null when the API is disabled or the identity/URL is unusable.
     * Long-poll calls must go through {@link Call#enqueue} — never block a
     * shared executor thread waiting out the hold.
     */
    @Nullable
    public Call newNotificationsCall(String playerName, long accountHash, int waitSeconds) {
        return newNotificationsCall(playerName, accountHash, waitSeconds, null);
    }

    /**
     * ``clanName`` (optional) is the chat-bridge presence heartbeat: polling
     * with it tells the server this plugin is online in that clan, which is
     * what Discord→game fan-out delivers against.
     */
    public Call newNotificationsCall(String playerName, long accountHash, int waitSeconds, String clanName) {
        if (!config.useApi() || playerName == null || playerName.isEmpty() || accountHash == -1L) {
            return null;
        }
        HttpUrl base = HttpUrl.parse(getApiUrl() + "/notifications");
        if (base == null) {
            return null;
        }
        HttpUrl.Builder url = base.newBuilder()
            .addQueryParameter("player_name", playerName)
            .addQueryParameter("acc_hash", String.valueOf(accountHash));
        if (waitSeconds > 0) {
            url.addQueryParameter("wait", String.valueOf(waitSeconds));
        }
        if (clanName != null && !clanName.isEmpty()) {
            url.addQueryParameter("clan", clanName);
        }
        Request request = new Request.Builder().url(url.build()).build();
        OkHttpClient callClient = waitSeconds > 0 ? longPollHttpClient : panelHttpClient;
        return callClient.newCall(request);
    }

    /**
     * Parses a successful /notifications response body. Returns null on an
     * empty or malformed body. Closing the response stays with the caller.
     */
    @Nullable
    public NotificationsResponse parseNotificationsResponse(Response response) {
        lastCommunicationTime = (int) (System.currentTimeMillis() / 1000);
        try {
            ResponseBody body = response.body();
            if (!response.isSuccessful() || body == null) {
                return null;
            }
            return gson.fromJson(body.string(), NotificationsResponse.class);
        } catch (IOException | JsonSyntaxException e) {
            log.debug("/notifications parse failed: {}", e.getMessage());
            return null;
        }
    }

    /**
     * Drains the player's event-notification inbox with a plain (non-held)
     * request. Returns null on any failure (network, non-200, malformed
     * body). Blocking — never call on the EDT or the client thread.
     */
    @Nullable
    public NotificationsResponse fetchNotifications(String playerName, long accountHash) {
        Call call = newNotificationsCall(playerName, accountHash, 0);
        if (call == null) {
            return null;
        }
        try (Response response = call.execute()) {
            return parseNotificationsResponse(response);
        } catch (IOException e) {
            log.debug("/notifications fetch failed: {}", e.getMessage());
            return null;
        }
    }

    /**
     * Fetches the HUD / Events-tab state for every active event the player
     * is in. Returns null on any failure. Blocking — off-EDT only.
     */
    @Nullable
    public io.droptracker.models.api.EventState fetchEventState(String playerName, long accountHash) {
        if (!config.useApi() || playerName == null || playerName.isEmpty() || accountHash == -1L) {
            return null;
        }
        HttpUrl base = HttpUrl.parse(getApiUrl() + "/event_state");
        if (base == null) {
            return null;
        }
        HttpUrl url = base.newBuilder()
            .addQueryParameter("player_name", playerName)
            .addQueryParameter("acc_hash", String.valueOf(accountHash))
            // This build badges chat lines as they are drawn and never renames
            // a MessageNode. Builds before it (6.0.3-6.0.8) renamed nodes, which
            // hid friends' PMs, so the server can withhold roster_version, and
            // with it every badge, from any client that does not send this.
            .addQueryParameter("badges", String.valueOf(TEAM_BADGE_RENDERER))
            .build();
        Request request = new Request.Builder().url(url).build();
        try (Response response = panelHttpClient.newCall(request).execute()) {
            lastCommunicationTime = (int) (System.currentTimeMillis() / 1000);
            if (!response.isSuccessful() || response.body() == null) {
                return null;
            }
            return gson.fromJson(response.body().string(), io.droptracker.models.api.EventState.class);
        } catch (IOException | JsonSyntaxException e) {
            log.debug("/event_state fetch failed: {}", e.getMessage());
            return null;
        }
    }

    /**
     * Team membership for the clan-chat badges. Roster-gated server-side: only
     * events this account is on a team of come back, so there is nothing to
     * filter here.
     *
     * Called only when /event_state's roster_version changes, never on a timer
     * — this carries a whole event's membership, unlike the state poll.
     */
    public io.droptracker.models.api.EventRoster fetchEventRoster(String playerName, long accountHash) {
        if (!config.useApi() || playerName == null || playerName.isEmpty() || accountHash == -1L) {
            return null;
        }
        HttpUrl base = HttpUrl.parse(getApiUrl() + "/event_roster");
        if (base == null) {
            return null;
        }
        HttpUrl url = base.newBuilder()
            .addQueryParameter("player_name", playerName)
            .addQueryParameter("acc_hash", String.valueOf(accountHash))
            .build();
        Request request = new Request.Builder().url(url).build();
        try (Response response = panelHttpClient.newCall(request).execute()) {
            lastCommunicationTime = (int) (System.currentTimeMillis() / 1000);
            if (!response.isSuccessful() || response.body() == null) {
                return null;
            }
            return gson.fromJson(response.body().string(), io.droptracker.models.api.EventRoster.class);
        } catch (IOException | JsonSyntaxException e) {
            log.debug("/event_roster fetch failed: {}", e.getMessage());
            return null;
        }
    }

    /**
     * URL of the server-rendered board image for an event (optionally one
     * team's view). The identity params ride along because the endpoint is
     * roster-gated (private events stay hidden without them).
     */
    public HttpUrl eventBoardImageUrl(int eventId, Integer teamId, String playerName, long accountHash) {
        HttpUrl base = HttpUrl.parse(getApiUrl() + "/events/" + eventId + "/board.png");
        if (base == null) {
            return null;
        }
        HttpUrl.Builder builder = base.newBuilder()
            .addQueryParameter("player_name", playerName)
            .addQueryParameter("acc_hash", String.valueOf(accountHash));
        if (teamId != null) {
            builder.addQueryParameter("team_id", String.valueOf(teamId));
        }
        return builder.build();
    }

    /** True when any loaded group config reports a live event tracking this player. */
    public boolean hasActiveEvent() {
        List<GroupConfig> configs = groupConfigs;
        if (configs == null) {
            return false;
        }
        for (GroupConfig groupConfig : configs) {
            if (groupConfig != null && groupConfig.isActiveEvent()) {
                return true;
            }
        }
        return false;
    }
}

package io.droptracker.api;

import java.util.regex.Pattern;

import javax.annotation.Nullable;

import okhttp3.HttpUrl;

/**
 * Every host this plugin is capable of connecting to, as compile-time constants.
 *
 * <p>The Plugin Hub requires that all URLs a plugin talks to are either hardcoded
 * in the plugin or typed by the user, so that the set of domains can be reviewed
 * exhaustively. The API therefore hands us <em>paths</em> (for example
 * {@code "itemdb/4151.png"}), never URLs, and this class anchors them onto one of
 * the bases below. A server response can influence which file we ask for; it can
 * never influence which host we ask.
 *
 * <p>The only address not listed here is the API base itself, which is resolved by
 * {@link DropTrackerApi#getApiUrl()} — either the {@link #DEFAULT_API} constant or
 * the endpoint the user typed into the hidden {@code customApiEndpoint} setting.
 */
public final class DropTrackerUrls {

	/** Website root: panel links, and the parent of {@link #IMAGES}. */
	public static final HttpUrl WEB = HttpUrl.get("https://www.droptracker.io/");

	/** Everything the plugin renders: item/npc icons, lootboards, submission screenshots. */
	public static final HttpUrl IMAGES = HttpUrl.get("https://www.droptracker.io/img/");

	/** Static published content: the webhook list, its key, and the item-id lists. */
	public static final HttpUrl CONTENT = HttpUrl.get("https://droptracker-io.github.io/content/");

	/** RuneLite's item cache, used to resolve item names to ids. */
	public static final HttpUrl ITEM_CACHE = HttpUrl.get("https://static.runelite.net/cache/item/");

	/** Discord webhook delivery. Submissions are POSTed to {@code base + id + token}. */
	public static final HttpUrl DISCORD_WEBHOOK = HttpUrl.get("https://discord.com/api/webhooks/");

	/** Discord invite links opened in the user's browser from the group panel. */
	public static final HttpUrl DISCORD_INVITE = HttpUrl.get("https://discord.gg/");

	/** API base used unless the user has typed their own endpoint. */
	public static final String DEFAULT_API = "https://api.droptracker.io";

	/**
	 * Characters no server-supplied path may contain: {@code :} (so nothing
	 * resembling a scheme survives), {@code %} (so nothing arrives pre-encoded and
	 * gets decoded twice), {@code ?} and {@code #} (so nothing can append a query or
	 * fragment), {@code \} and control characters.
	 *
	 * <p>Everything else is allowed and percent-encoded on the way out. Real
	 * screenshot paths contain apostrophes and parentheses ({@code Kree'arra},
	 * {@code Dagannoth_Rex_(hard)}), and it is {@code addPathSegment} — which
	 * encodes {@code /} too — that makes the host unreachable from a path, not the
	 * character set.
	 */
	private static final Pattern FORBIDDEN = Pattern.compile("[\\\\%?#:\\p{Cntrl}]");

	private static final int MAX_PATH_LENGTH = 512;
	private static final int MAX_SEGMENT_LENGTH = 128;

	private static final Pattern WEBHOOK_ID = Pattern.compile("[0-9]{5,32}");
	private static final Pattern WEBHOOK_TOKEN = Pattern.compile("[A-Za-z0-9._-]{16,200}");
	private static final Pattern INVITE_CODE = Pattern.compile("[A-Za-z0-9-]{1,64}");

	private DropTrackerUrls() {
	}

	/**
	 * Anchors a server-supplied relative path onto a compile-time base, or returns
	 * null if the path is anything other than a plain relative path.
	 *
	 * <p>Rejects absolute URLs, absolute paths, {@code .} / {@code ..} traversal,
	 * empty segments, and any {@link #FORBIDDEN} character. Callers treat null the
	 * same as "no image", so a rejected path simply renders nothing.
	 */
	@Nullable
	public static HttpUrl underBase(HttpUrl base, @Nullable String relativePath) {
		if (relativePath == null) {
			return null;
		}
		String path = relativePath.trim();
		if (path.isEmpty() || path.length() > MAX_PATH_LENGTH
				|| path.startsWith("/")
				|| FORBIDDEN.matcher(path).find()) {
			return null;
		}
		HttpUrl.Builder builder = base.newBuilder();
		for (String segment : path.split("/")) {
			if (segment.isEmpty() || segment.length() > MAX_SEGMENT_LENGTH
					|| ".".equals(segment) || "..".equals(segment)) {
				return null;
			}
			builder.addPathSegment(segment);
		}
		return builder.build();
	}

	/** {@code https://www.droptracker.io/img/<relativePath>} — item icons, lootboards, screenshots. */
	@Nullable
	public static HttpUrl image(@Nullable String relativePath) {
		return underBase(IMAGES, relativePath);
	}

	/**
	 * A page on the website, for opening in the user's browser.
	 *
	 * <p>Unlike {@link #underBase} this encodes rather than rejects, because some
	 * segments are legitimately free-form (a player name may contain spaces).
	 * {@code addPathSegment} percent-encodes {@code /} as well, so no segment can
	 * add depth or escape the host.
	 */
	public static HttpUrl web(String... segments) {
		HttpUrl.Builder builder = WEB.newBuilder();
		for (String segment : segments) {
			builder.addPathSegment(segment);
		}
		return builder.build();
	}

	/** {@code https://droptracker-io.github.io/content/<fileName>}. */
	@Nullable
	public static HttpUrl content(@Nullable String fileName) {
		return underBase(CONTENT, fileName);
	}

	/** {@code https://static.runelite.net/cache/item/<fileName>}. */
	@Nullable
	public static HttpUrl itemCache(@Nullable String fileName) {
		return underBase(ITEM_CACHE, fileName);
	}

	/**
	 * {@code https://discord.com/api/webhooks/<id>/<token>}. The id and token are
	 * opaque credentials published by the backend; the host is ours to decide.
	 */
	@Nullable
	public static HttpUrl discordWebhook(@Nullable String id, @Nullable String token) {
		if (id == null || token == null
				|| !WEBHOOK_ID.matcher(id).matches()
				|| !WEBHOOK_TOKEN.matcher(token).matches()) {
			return null;
		}
		return DISCORD_WEBHOOK.newBuilder()
			.addPathSegment(id)
			.addPathSegment(token)
			.build();
	}

	/** {@code https://discord.gg/<code>} for a group's public invite. */
	@Nullable
	public static HttpUrl discordInvite(@Nullable String code) {
		if (code == null || !INVITE_CODE.matcher(code.trim()).matches()) {
			return null;
		}
		return DISCORD_INVITE.newBuilder().addPathSegment(code.trim()).build();
	}
}

package io.droptracker.api;

import java.io.IOException;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import java.util.function.Consumer;

import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.google.gson.JsonSyntaxException;

import io.droptracker.DropTrackerConfig;
import io.droptracker.models.api.DeathMessages;
import lombok.extern.slf4j.Slf4j;
import okhttp3.CacheControl;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * Reads and saves the logged-in account's own death messages
 * ({@code GET/POST /player/death_messages}).
 *
 * <p>The same messages the website and Discord's {@code /settings} edit, keyed
 * by account: the server resolves the account hash, which is also all the
 * plugin's other endpoints go on. Every call runs on the injected executor and
 * answers on the Swing thread, because its only caller is the editor dialog.
 */
@Slf4j
@Singleton
public class DeathMessageApi {

    private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");

    private final DropTrackerConfig config;
    private final DropTrackerApi api;
    private final Gson gson;
    private final OkHttpClient httpClient;
    private final ScheduledExecutorService executor;

    @Inject
    public DeathMessageApi(DropTrackerConfig config, DropTrackerApi api, Gson gson,
                           OkHttpClient httpClient, ScheduledExecutorService executor) {
        this.config = config;
        this.api = api;
        this.gson = gson;
        this.httpClient = httpClient;
        this.executor = executor;
    }

    /** What a call came back with: the messages, or a sentence for the player. */
    public static final class Result {
        @Nullable
        public final DeathMessages messages;
        @Nullable
        public final String error;

        private Result(@Nullable DeathMessages messages, @Nullable String error) {
            this.messages = messages;
            this.error = error;
        }

        public static Result ok(DeathMessages messages) {
            return new Result(messages, null);
        }

        public static Result failed(String error) {
            return new Result(null, error);
        }
    }

    /** Loads the account's messages; {@code callback} runs on the Swing thread. */
    public void fetch(@Nullable String playerName, long accountHash, Consumer<Result> callback) {
        executor.execute(() -> {
            Result result = fetchNow(playerName, accountHash);
            SwingUtilities.invokeLater(() -> callback.accept(result));
        });
    }

    /** Replaces the account's messages; {@code callback} runs on the Swing thread. */
    public void save(@Nullable String playerName, long accountHash, List<String> messages,
                     Consumer<Result> callback) {
        executor.execute(() -> {
            Result result = saveNow(playerName, accountHash, messages);
            SwingUtilities.invokeLater(() -> callback.accept(result));
        });
    }

    private Result fetchNow(@Nullable String playerName, long accountHash) {
        HttpUrl base = endpoint();
        if (base == null) {
            return Result.failed(API_OFF);
        }
        HttpUrl url = base.newBuilder()
            .addQueryParameter("player_name", playerName == null ? "" : playerName)
            .addQueryParameter("acc_hash", String.valueOf(accountHash))
            .build();
        // FORCE_NETWORK: the injected client has a disk cache shared with the
        // whole of RuneLite, and a stale copy here would undo a save.
        Request request = new Request.Builder().url(url).cacheControl(CacheControl.FORCE_NETWORK).build();
        return execute(request);
    }

    private Result saveNow(@Nullable String playerName, long accountHash, List<String> messages) {
        HttpUrl url = endpoint();
        if (url == null) {
            return Result.failed(API_OFF);
        }
        Map<String, Object> body = new HashMap<>();
        body.put("player_name", playerName == null ? "" : playerName);
        body.put("acc_hash", String.valueOf(accountHash));
        body.put("messages", messages);
        Request request = new Request.Builder()
            .url(url)
            .post(RequestBody.create(JSON, gson.toJson(body)))
            .build();
        return execute(request);
    }

    private Result execute(Request request) {
        try (Response response = httpClient.newCall(request).execute()) {
            ResponseBody body = response.body();
            return interpret(gson, response.code(), body == null ? "" : body.string());
        } catch (IOException e) {
            log.debug("Death message request failed: {}", e.toString());
            return Result.failed(UNREACHABLE);
        }
    }

    @Nullable
    private HttpUrl endpoint() {
        if (!config.useApi()) {
            return null;
        }
        return HttpUrl.parse(api.getApiUrl() + "/player/death_messages");
    }

    static final String API_OFF = "Turn on \"Use API Connections\" in the plugin settings to edit your death message here.";
    static final String UNREACHABLE = "Couldn't reach the DropTracker. Try again in a moment.";
    static final String NOT_REGISTERED = "This account isn't registered with the DropTracker yet. Submit something first, then try again.";
    static final String TOO_MANY = "That's a lot of saves - wait a minute and try again.";

    /** Turns a response into a {@link Result}. Package-private for the tests. */
    static Result interpret(Gson gson, int code, String body) {
        if (code == 200) {
            try {
                DeathMessages parsed = gson.fromJson(body, DeathMessages.class);
                return parsed != null ? Result.ok(parsed) : Result.failed(UNREACHABLE);
            } catch (JsonSyntaxException e) {
                return Result.failed(UNREACHABLE);
            }
        }
        if (code == 404) {
            return Result.failed(NOT_REGISTERED);
        }
        if (code == 429) {
            return Result.failed(TOO_MANY);
        }
        if (code == 422 || code == 400) {
            // The server's refusal is written for the player; show it as is.
            try {
                JsonObject error = gson.fromJson(body, JsonObject.class);
                if (error != null && error.has("error") && error.get("error").isJsonPrimitive()) {
                    return Result.failed(error.get("error").getAsString());
                }
            } catch (JsonSyntaxException | IllegalStateException e) {
                // fall through to the generic message
            }
        }
        return Result.failed(UNREACHABLE);
    }
}

