	/** Add support for Yama's special drop mechanics */
	@Subscribe(priority = 1)
    public void onServerNpcLoot(ServerNpcLoot event) {
		NPCComposition eventComp = event.getComposition();
        if (!NpcUtilities.isServerLootNpc(eventComp.getId())) {
            return;
        }
        if (eventComp.getName().equalsIgnoreCase("Yama")) {
			kcService.onServerNpcLoot(event);
		}

        dropHandler.onServerNpcLoot(event);
    }

	@Subscribe(priority=1)
	public void onNpcLootReceived(NpcLootReceived npcLootReceived) {
		int npcId = npcLootReceived.getNpc().getId();
		if (npcId == NpcID.YAMA) {
			/* Yama's drop AND kill count are handled entirely by onServerNpcLoot. */
            return;
        }
		// Server-loot NPCs (Maggot King, Hespori, Sailing, ...) are submitted
		// authoritatively by onServerNpcLoot; the client-side NpcLootReceived for
		// them is a redundant duplicate, so skip its drop submission here. Kill
		// count bookkeeping stays on this path unchanged.
		if (!NpcUtilities.isServerLootNpc(npcId)) {
			dropHandler.onNpcLootReceived(npcLootReceived);
		}
		kcService.onNpcKill(npcLootReceived);
	}

	@Subscribe(priority=1)
	public void onPlayerLootReceived(PlayerLootReceived playerLootReceived) {
		dropHandler.onPlayerLootReceived(playerLootReceived);
		kcService.onPlayerKill(playerLootReceived);
	}

	@Subscribe(priority=1)
	public void onLootReceived(LootReceived lootReceived) {
		// A raid reward chest fires LootReceived once when opened in the loot
		// room and again if the unclaimed loot is taken from the collection
		// chest at the bank. Suppress the repeat BEFORE the fan-out: it must
		// reach neither DropHandler (duplicate drop submission) nor KCService
		// (phantom kill count increment).
		if (raidLootDeduplicator.isDuplicateRaidLoot(lootReceived)) {
			return;
		}
		dropHandler.onLootReceived(lootReceived);
		kcService.onLoot(lootReceived);
	}

	@Subscribe(priority = 1)
	public void onChatMessage(ChatMessage message) {
		if (!isTracking) {
			return;
		}
		String chatMessage = submissionManager.sanitize(message.getMessage());
		switch (message.getType()) {
			case WELCOME:
				if (!statsLoaded) {
					updatePanelOnLogin(chatMessage);
				}
				/* Welcome should only be called a single time on each login, 
					so we can call this regardless of whether statsLoaded is true,
					to load/refresh configurations respective to the current player logged in
				*/
				if (config.useApi()) {
					try {
						api.loadGroupConfigs(getLocalPlayerName());
						// Refresh the API panel to show updated group configs
						// Since loading is async, we need to delay the refresh
						if (panel != null) {
							// Initial refresh to show loading state
							SwingUtilities.invokeLater(() -> {
								panel.updateSentSubmissions();
							});

							// Schedule a panel submission update on the executor instead of directly waiting on the thread

							executor.schedule(() -> { panel.updateSentSubmissions(); }, 2, TimeUnit.SECONDS); // Wait 2 seconds for async load

						}
					} catch (IOException e) {
						log.debug("Couldn't refresh api Panel");
					}
				}
				break;
			case GAMEMESSAGE:
				if(pbHandler.isEnabled()){
					pbHandler.onGameMessage(chatMessage);
				}
				if(caHandler.isEnabled()){
					caHandler.onGameMessage(chatMessage);
				}
				if(clogHandler.isEnabled()) {
					clogHandler.onChatMessage(chatMessage);
				}
				if(petHandler.isEnabled()) {
					petHandler.onGameMessage(chatMessage);
				}
				if(diaryHandler.isEnabled()) {
					diaryHandler.onGameMessage(chatMessage);
				}
				if(trawlingHandler.isEnabled()) {
					trawlingHandler.onGameMessage(chatMessage);
				}
				if(slayerHandler.isEnabled()) {
					slayerHandler.onGameMessage(chatMessage);
				}
				break;
			case SPAM:
				// Trawling catch messages arrive as SPAM when game filtering is on
				if(trawlingHandler.isEnabled()) {
					trawlingHandler.onGameMessage(chatMessage);
				}
				// Slayer completion lines are GAMEMESSAGE; a filtered copy must
				// not be the one that goes missing.
				if(slayerHandler.isEnabled()) {
					slayerHandler.onGameMessage(chatMessage);
				}
				break;
			case FRIENDSCHATNOTIFICATION:
				pbHandler.onFriendsChatNotification(chatMessage);
				break;
			case CLAN_MESSAGE:
			case CLAN_GIM_MESSAGE:
                petHandler.onClanChatNotification(chatMessage);
                // Clan-broadcast relay (group feature): CLAN_MESSAGE only —
                // GIM broadcasts are a different channel and stay local.
                if (message.getType() == ChatMessageType.CLAN_MESSAGE) {
                    clanRelayService.onClanBroadcast(chatMessage);
                }
                break;
			case CLAN_CHAT:
				// Player lines feed only the Discord chat bridge (opt-in);
				// nothing else in the plugin reads clanmates' chatter.
				clanRelayService.onClanChat(message.getName(), chatMessage);
				break;
			default:
				break;
		}
		kcService.onGameMessage(chatMessage);
	}

