	@Subscribe
	public void onGameStateChanged(GameStateChanged gameStateChanged) {
		GameState newState = gameStateChanged.getGameState();

		// Ahead of the LOADING short-circuit and the same-state guard: the
		// team-badge sprite block has to be claimed at LOGIN_SCREEN and
		// released at STARTING, because the client rebuilds its mod-icon
		// array on a restart.
		eventTeamIndicatorService.onGameStateChanged(newState);

		if (newState == GameState.LOADING) {
			return;
		}

		GameState previousState = gameState.getAndSet(newState);
		if (previousState == newState) {
			return;
		}

		// A login or hop re-sends the slayer varps, so a count reading zero
		// then is not a finished task.
		slayerHandler.onGameStateChanged(newState);

		// Clear per-session handler state so a partially-coalesced PB, pet or
		// collection-log popup from before a logout/hop can't fire stale
		// notifications after the player comes back.
		if (newState == GameState.LOGIN_SCREEN || newState == GameState.HOPPING) {
			pbHandler.reset();
			petHandler.reset();
			clogHandler.reset();
		}

		justLoggedIn.set(newState == GameState.LOGGED_IN);

		if (previousState == GameState.HOPPING) {
			return;
		}

		if (justLoggedIn.get()) {
			return;
		}

		if (!isTracking || !config.trackExperience()) {
			return;
		}
		experienceHandler.onGameStateChanged(gameStateChanged);
	}

	public String getLocalPlayerName() {
		if (client.getLocalPlayer() != null) {
			return client.getLocalPlayer().getName();
		} else {
			return "";
		}
	}

	/**
	 * Best-effort update check against GET /plugin_version (runs on the executor).
	 * Below the server's minimum version: warn every login. Behind the latest
	 * version: prompt once per new version (tracked via lastVersionNotified).
	 */
	private void checkForPluginUpdates() {
		DropTrackerApi.VersionInfo info = api.fetchVersionInfo();
		if (info == null) {
			return;
		}

		if (info.minimumVersion != null && VersionUtil.isOlderThan(pluginVersion, info.minimumVersion)) {
			chatMessageUtil.sendChatMessage("Your DropTracker plugin (v" + pluginVersion
				+ ") is older than the minimum supported version (v" + info.minimumVersion
				+ ") — submissions may be rejected. Please update via the Plugin Hub.");
			if (info.message != null && !info.message.isEmpty()) {
				chatMessageUtil.sendChatMessage(info.message);
			}
			return;
		}

		if (info.latestVersion != null && VersionUtil.isOlderThan(pluginVersion, info.latestVersion)
				&& !info.latestVersion.equals(config.lastVersionNotified())) {
			config.setLastVersionNotified(info.latestVersion);
			chatMessageUtil.sendChatMessage("A new DropTracker version is available (v" + info.latestVersion
				+ ", you have v" + pluginVersion + "). Update via the Plugin Hub for the latest features and fixes.");
			if (info.message != null && !info.message.isEmpty()) {
				chatMessageUtil.sendChatMessage(info.message);
			}
		}
	}

}

package io.droptracker.util;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import javax.annotation.Nullable;

/**
 * What a member's own death message may contain, checked as they type.
 *
 * <p>The server is the authority (disc {@code db/member_messages.py}) and
 * refuses anything that breaks these rules with the same wording; this mirror
 * only exists so the editor can say what is wrong before a save round-trip.
 * The website carries the same mirror, and all three pin the same cases in
 * their tests — change a rule in all three places or the editors will
 * disagree with the server about what can be saved.
 */
public final class DeathMessageRules {

    public static final int MAX_MESSAGES = 5;
    public static final int MAX_LENGTH = 150;

    /** Placeholders a member may use, in display order. */
    public static final List<String> TOKENS = Collections.unmodifiableList(Arrays.asList(
        "{player_name}", "{killer}", "{location}", "{value_lost}", "{value_kept}", "{killer_combat_level}"));

    /** Also accepted, so a line copied from a group's own death messages works. */
    private static final Map<String, String> ALIASES = Map.of(
        "{source}", "{killer}",
        "{region_name}", "{location}");

    private static final Set<String> ALLOWED;

    static {
        Set<String> allowed = new LinkedHashSet<>(TOKENS);
        allowed.addAll(ALIASES.keySet());
        ALLOWED = Collections.unmodifiableSet(allowed);
    }

    private static final Pattern TOKEN = Pattern.compile("\\{[a-z0-9_]+\\}", Pattern.CASE_INSENSITIVE);
    private static final Pattern DISCORD_ENTITY = Pattern.compile(
        "@everyone|@here|<@[&!]?\\d+>|<#\\d+>|<a?:\\w+:\\d+>|</[^<>:\\n]+:\\d+>|<t:-?\\d+(?::[a-z])?>",
        Pattern.CASE_INSENSITIVE);
    private static final Pattern LINK = Pattern.compile(
        "https?://\\S*|www\\.\\S*|\\bdiscord(?:app)?\\.(?:gg|com/invite)\\S*"
            + "|\\b[a-z0-9][a-z0-9-]*\\.(?:com|net|org|gg|io|co|me|xyz|tv|ly|link|site|app|dev|info|ru|uk|us)\\b\\S*",
        Pattern.CASE_INSENSITIVE);
    private static final Pattern BLOCK_MARKDOWN = Pattern.compile("^\\s*(?:#{1,3}\\s|-#\\s|>>>|>\\s)");
    /** Control characters plus the Unicode line and paragraph separators. */
    private static final Pattern CONTROL = Pattern.compile("[\\x00-\\x1f\\x7f\\u2028\\u2029]");
    private static final Pattern SPACES = Pattern.compile("\\s{2,}");

    private DeathMessageRules() {
    }

    /** Why one trimmed message cannot be saved, or null. Same wording as the server. */
    @Nullable
    public static String issue(String text) {
        if (text.codePointCount(0, text.length()) > MAX_LENGTH) {
            return "Each message can be at most " + MAX_LENGTH + " characters.";
        }
        if (CONTROL.matcher(text).find()) {
            return "Each message has to be a single line of text.";
        }
        if (DISCORD_ENTITY.matcher(text).find()) {
            return "Messages can't mention people, roles or channels, or use custom emoji.";
        }
        if (LINK.matcher(text).find()) {
            return "Messages can't contain links.";
        }
        if (BLOCK_MARKDOWN.matcher(text).find()) {
            return "Messages can't start with a heading or a quote.";
        }
        Set<String> unknown = new TreeSet<>();
        Matcher m = TOKEN.matcher(text);
        while (m.find()) {
            if (!ALLOWED.contains(m.group().toLowerCase(Locale.ROOT))) {
                unknown.add(m.group());
            }
        }
        if (!unknown.isEmpty()) {
            return "Unknown placeholder" + (unknown.size() > 1 ? "s " : " ") + String.join(", ", unknown)
                + ". You can use " + String.join(", ", TOKENS) + ".";
        }
        return null;
    }

    /**
     * What the server will store: each row trimmed, blank rows and exact
     * duplicates dropped, placeholder names lowercased.
     */
    public static List<String> normalize(List<String> rows) {
        List<String> out = new ArrayList<>();
        for (String raw : rows) {
            if (raw == null) {
                continue;
            }
            String text = lowercaseTokens(raw.trim());
            if (!text.isEmpty() && !out.contains(text)) {
                out.add(text);
            }
        }
        return out;
    }

    /** The first problem with the whole list, or null when it can be saved. */
    @Nullable
    public static String listIssue(List<String> rows) {
        List<String> cleaned = normalize(rows);
        for (String message : cleaned) {
            String issue = issue(message);
            if (issue != null) {
                return issue;
            }
        }
        if (cleaned.size() > MAX_MESSAGES) {
            return "You can save at most " + MAX_MESSAGES + " messages.";
        }
        return null;
    }

    /**
     * A template filled with sample values the way the bot fills a real death:
     * {@code {player_name}} becomes the account's name, aliases read their
     * canonical placeholder's sample, and anything else is left out.
     */
    public static String preview(String template, Map<String, String> samples, String playerName) {
        Matcher m = TOKEN.matcher(template);
        StringBuilder out = new StringBuilder();
        while (m.find()) {
            String token = m.group().toLowerCase(Locale.ROOT);
            String canonical = ALIASES.getOrDefault(token, token);
            String value;
            if ("{player_name}".equals(canonical)) {
                value = playerName == null ? "" : playerName;
            } else {
                value = samples.getOrDefault(canonical, "");
            }
            m.appendReplacement(out, Matcher.quoteReplacement(value));
        }
        m.appendTail(out);
        return SPACES.matcher(out.toString()).replaceAll(" ").trim();
    }

    private static String lowercaseTokens(String text) {
        Matcher m = TOKEN.matcher(text);
        StringBuilder out = new StringBuilder();
        while (m.find()) {
            m.appendReplacement(out, Matcher.quoteReplacement(m.group().toLowerCase(Locale.ROOT)));
        }
        m.appendTail(out);
        return out.toString();
    }
}

package io.droptracker.util;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import lombok.extern.slf4j.Slf4j;

import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.BufferedReader;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;

/**
 * Resolves an OSRS map region id to a human-readable area name
 * ("Theatre of Blood", "Catacombs of Kourend") and a coarse area type.
 *
 * The data in {@code /io/droptracker/region_names.json} was extracted verbatim
 * from RuneLite's {@code DiscordGameEventType} enum (BSD 2-Clause, same licence
 * as this plugin), which maintains this mapping for Discord rich presence. That
 * enum is package-private so it cannot be imported; regenerate the resource by
 * re-parsing the enum constants that carry a {@code DiscordAreaType} and one or
 * more region ids.
 *
 * Region ids are only meaningful when they come from an instance-corrected
 * {@link net.runelite.api.coords.WorldPoint} — inside an instance the raw
 * {@code getWorldLocation()} returns template coordinates that resolve to the
 * wrong area (or none at all). See {@code DeathHandler#currentLocation}.
 */
@Slf4j
@Singleton
public final class RegionNameRegistry {

    private static final String RESOURCE_PATH = "/io/droptracker/region_names.json";

    /** A named area and the coarse bucket RuneLite files it under. */
    public static final class Area {
        private final String name;
        private final String type;

        Area(String name, String type) {
            this.name = name;
            this.type = type;
        }

        /** Human-readable area name, e.g. {@code "Theatre of Blood"}. */
        public String getName() {
            return name;
        }

        /**
         * One of {@code BOSSES}, {@code RAIDS}, {@code DUNGEONS}, {@code CITIES},
         * {@code MINIGAMES}, {@code REGIONS}.
         */
        public String getType() {
            return type;
        }

        @Override
        public String toString() {
            return name;
        }
    }

    /** Deserialization shape of the JSON resource. */
    private static final class AreaEntry {
        String name;
        String type;
        int[] regions;
    }

    private static final class AreaFile {
        List<AreaEntry> areas;
    }

    private final Map<Integer, Area> byRegion;

    @Inject
    public RegionNameRegistry(Gson gson) {
        this.byRegion = load(gson);
    }

    private static Map<Integer, Area> load(Gson gson) {
        try (InputStream is = RegionNameRegistry.class.getResourceAsStream(RESOURCE_PATH);
             Reader reader = new BufferedReader(new InputStreamReader(Objects.requireNonNull(is), StandardCharsets.UTF_8))) {
            AreaFile file = gson.fromJson(reader, new TypeToken<AreaFile>() {}.getType());
            Objects.requireNonNull(file);
            Objects.requireNonNull(file.areas);

            Map<Integer, Area> map = new HashMap<>();
            for (AreaEntry entry : file.areas) {
                if (entry == null || entry.name == null || entry.regions == null) {
                    continue;
                }
                Area area = new Area(entry.name, entry.type);
                for (int region : entry.regions) {
                    map.put(region, area);
                }
            }
            return Collections.unmodifiableMap(map);
        } catch (Exception e) {
            // A missing/corrupt resource must not break death tracking — callers
            // degrade to reporting the bare region id.
            log.error("Failed to load region names from {}", RESOURCE_PATH, e);
            return Collections.emptyMap();
        }
    }

    /**
     * @param regionId an instance-corrected map region id
     * @return the area covering that region, or null when unmapped
     */
    @Nullable
    public Area lookup(int regionId) {
        return byRegion.get(regionId);
    }

    /**
     * @param regionId an instance-corrected map region id
     * @return the human-readable area name, or null when unmapped
     */
    @Nullable
    public String nameOf(int regionId) {
        Area area = byRegion.get(regionId);
        return area != null ? area.getName() : null;
    }

    /**
     * @param regionId an instance-corrected map region id
     * @return the coarse area type, or null when unmapped
     */
    @Nullable
    public String typeOf(int regionId) {
        Area area = byRegion.get(regionId);
        return area != null ? area.getType() : null;
    }

    /** Number of distinct region ids the registry can name. */
    public int size() {
        return byRegion.size();
    }
}

package io.droptracker.util;

import java.util.Collection;
import java.util.Collections;
import java.util.HashSet;
import java.util.Optional;
import java.util.Set;
import java.util.function.Predicate;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import javax.annotation.Nullable;

import net.runelite.api.gameval.NpcID;
import org.apache.commons.lang3.tuple.Pair;
import org.jetbrains.annotations.VisibleForTesting;

import io.droptracker.DropTrackerPlugin;

import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.http.api.loottracker.LootRecordType;

public class NpcUtilities {

    public static final String GAUNTLET_NAME = "Gauntlet", GAUNTLET_BOSS = "Crystalline Hunllef";
    public static final String CG_NAME = "Corrupted Gauntlet", CG_BOSS = "Corrupted Hunllef";

    public static final String TOA = "Tombs of Amascut";
    public static final String TOB = "Theatre of Blood";
    public static final String COX = "Chambers of Xeric";

    public static final Set<String> SPECIAL_NPC_NAMES = Set.of("The Whisperer", "Araxxor", "Branda the Fire Queen",
            "Eldric the Ice King", "Dusk", "Corrupted Hunllef", "Crystalline Hunllef","Maggot King");
    public static final Set<String> LONG_TICK_NPC_NAMES = Set.of("Grotesque Guardians", "Yama");

    /**
     * Sources that announce their loot in chat a tick after the loot event
     * fires. Capturing the next frame there photographs the moment before the
     * drop message exists, so the screenshot cannot corroborate the drop
     * (issue #48). Captures for these sources wait one game tick.
     */
    public static final Set<String> DEFERRED_SCREENSHOT_NPC_NAMES = Set.of(
            "The Nightmare", "Phosani's Nightmare");

    /** Whether a submission from {@code source} must delay its screenshot a tick. */
    public static boolean needsDeferredScreenshot(@Nullable String source) {
        return source != null && DEFERRED_SCREENSHOT_NPC_NAMES.contains(source);
    }

    /* Mad Angel npc ids (Wyrmscraig, released 2026-07-29) — raw literals because
     * RuneLite 1.12.33 (latest release) has no NpcID constant for this NPC yet.
     * Two in-game variants exist, each with two ids: the version fought during
     * Fallen From Grace and the repeatable post-quest encounter. */
    public static final int MAD_ANGEL_QUEST_A = 16309;
    public static final int MAD_ANGEL_QUEST_B = 16315;
    public static final int MAD_ANGEL_POST_QUEST_A = 16305;
    public static final int MAD_ANGEL_POST_QUEST_B = 16314;

    /* Use a list for all special npc names, since Sailing added a number of them */
    public static final Set<Integer> SERVER_LOOT_NPC_IDS = Set.of(
                NpcID.YAMA,
                NpcID.HESPORI,
                NpcID.SAILING_BULL_SHARK_DEAD,
                NpcID.SAILING_HAMMERHEAD_SHARK_DEAD,
                NpcID.SAILING_TIGER_SHARK_DEAD,
                NpcID.SAILING_GREAT_WHITE_SHARK_DEAD,
                NpcID.SAILING_NARWHAL_DEAD,
                NpcID.SAILING_ORCA_DEAD,
                NpcID.SAILING_PYGMY_KRAKEN_DEAD,
                NpcID.SAILING_SPINED_KRAKEN_DEAD,
                NpcID.SAILING_ARMOURED_KRAKEN_DEAD,
                NpcID.SAILING_VAMPYRE_KRAKEN_DEAD,
                NpcID.SAILING_EAGLE_RAY_DEAD,
                NpcID.SAILING_BUTTERFLY_RAY_DEAD,
                NpcID.SAILING_STINGRAY_DEAD,
                NpcID.SAILING_MANTA_RAY_DEAD,
                NpcID.SAILING_OSPREY_DEAD,
                NpcID.SAILING_ALBATROSS_DEAD,
                NpcID.SAILING_FRIGATEBIRD_DEAD,
                NpcID.SAILING_TERN_DEAD,
                NpcID.SAILING_SEA_MOGRE_DEAD,
                NpcID.SAILING_DOLPHIN_DEAD,
                NpcID.SAILING_VEILED_KRAKEN_DEAD,
                NpcID.MAGGOT_KING,
                NpcID.MAGGOT_KING_CORPSE,
                // Mad Angel awards loot server-side, so nothing spawns on the
                // death tile for LootManager to scrape and NpcLootReceived
                // never fires — kills were tracked (166 PBs landed on release
                // day) while every drop was silently discarded by the
                // onServerNpcLoot gate below.
                MAD_ANGEL_QUEST_A,
                MAD_ANGEL_QUEST_B,
                MAD_ANGEL_POST_QUEST_A,
                MAD_ANGEL_POST_QUEST_B
        );

    /**
     * Server-loot npc ids published by the backend at
     * {@code content/server_loot_npc_ids.txt}, layered over the compiled-in
     * {@link #SERVER_LOOT_NPC_IDS} above. This is what stops a newly released
     * boss (Mad Angel, 2026-07-29) needing a plugin release before its drops
     * track at all.
     * <p>
     * Volatile immutable snapshot: written by the executor thread that fetches
     * the list, read by the loot handlers on the client thread.
     */
    private static volatile Set<Integer> remoteServerLootNpcIds = Collections.emptySet();

    /**
     * Install the published server-loot id list. A null/empty argument (fetch
     * failed, file unreachable, garbage body) is ignored rather than applied,
     * so a bad publish or an offline client degrades to the compiled-in list
     * instead of losing loot tracking for every server-loot boss.
     */
    public static void setRemoteServerLootNpcIds(Collection<Integer> ids) {
        if (ids == null || ids.isEmpty()) {
            return;
        }
        remoteServerLootNpcIds = Collections.unmodifiableSet(new HashSet<>(ids));
    }

    /**
     * Whether this npc's loot is awarded server-side, i.e. arrives via
     * {@code ServerNpcLoot} and must not also be submitted from the
     * client-side {@code NpcLootReceived} path. The union of the compiled-in
     * list and the published one — never fewer ids than the build shipped with.
     */
    public static boolean isServerLootNpc(int npcId) {
        return SERVER_LOOT_NPC_IDS.contains(npcId) || remoteServerLootNpcIds.contains(npcId);
    }

    /* Canonical encounter names that a multi-part boss's sub-NPCs are remapped
     * to (see canonicalizeSpecialSource). Loot for these can arrive via more
     * than one RuneLite loot event, so they need cross-handler de-duplication. */
    public static final Set<String> REMAP_TARGET_NAMES = Set.of(
            "Royal Titans", "Grotesque Guardians", "The Corrupted Gauntlet", "The Gauntlet");

    /**
     * Collapse the raw sub-NPC name of a multi-part boss to its canonical
     * encounter name (e.g. "Dusk" -> "Grotesque Guardians"). Names without a
     * remapping are returned unchanged. Centralises the remapping that used to
     * live inline in {@code DropHandler.onLootReceived} so every loot path
     * (NpcLootReceived / ServerNpcLoot / LootReceived) agrees on one name — a
     * prerequisite for reliably de-duplicating the same kill across handlers.
     */
    public static String canonicalizeSpecialSource(String name) {
        if (name == null) {
            return null;
        }
        switch (name) {
            case "Branda the Fire Queen":
            case "Eldric the Ice King":
                return "Royal Titans";
            case "Dusk":
                return "Grotesque Guardians";
            case "Corrupted Hunllef":
                return "The Corrupted Gauntlet";
            case "Crystalline Hunllef":
                return "The Gauntlet";
            default:
                return name;
        }
    }

    /**
     * Whether loot from this (already canonicalised) source can be delivered by
     * more than one RuneLite loot event for a single kill — the bosses in
     * {@link #SPECIAL_NPC_NAMES} (Whisperer/Araxxor/Maggot King and the raw
     * sub-NPC names) plus the {@link #REMAP_TARGET_NAMES} they collapse to.
     * These are the only sources that need duplicate submissions suppressed;
     * ordinary NPCs (which can legitimately be multi-killed in one tick with
     * identical loot) are intentionally excluded.
     */
    public static boolean isMultiPathLootSource(String canonicalName) {
        return canonicalName != null
                && (SPECIAL_NPC_NAMES.contains(canonicalName) || REMAP_TARGET_NAMES.contains(canonicalName));
    }

    public static final Pattern PRIMARY_REGEX = Pattern.compile(
            "Your (?<key>[\\w\\s:'-]+) (?<type>kill|chest|completion|success) count is:? (?<value>[\\d,]+)");
    public static final Pattern SECONDARY_REGEX = Pattern
            .compile("Your (?<type>kill|chest|completed) (?<key>[\\w\\s:]+) count is:? (?<value>[\\d,]+)");

    @SuppressWarnings("null")
    public static String getStandardizedSource(LootReceived event, DropTrackerPlugin plugin) {
        if (isCorruptedGauntlet(event, plugin)) {
            return CG_NAME;
        }
        if (plugin.lastDrop == null) {
            return event.getName();
        } else if (shouldUseChatName(event, plugin) && plugin.lastDrop.getSource() != null) {
            return plugin.lastDrop.getSource(); // distinguish entry/expert/challenge modes
        }
        return event.getName();
    }

    @SuppressWarnings("null")
    private static boolean isCorruptedGauntlet(LootReceived event, DropTrackerPlugin plugin) {
        return event.getType() == LootRecordType.EVENT && plugin.lastDrop != null
                && "The Gauntlet".equals(event.getName())
                && (CG_NAME.equals(plugin.lastDrop.getSource()) || CG_BOSS.equals(plugin.lastDrop.getSource()));
    }

    private static boolean shouldUseChatName(LootReceived event, DropTrackerPlugin plugin) {
        assert plugin.lastDrop != null;
        String lastSource = plugin.lastDrop.getSource();
        Predicate<String> coincides = source -> source.equals(event.getName()) && lastSource.startsWith(source);
        return coincides.test(TOA) || coincides.test(TOB) || coincides.test(COX);
    }

    public static Optional<Pair<String, Integer>> parseBoss(String message, DropTrackerPlugin plugin) {
        Matcher primary = PRIMARY_REGEX.matcher(message);
        Matcher secondary = SECONDARY_REGEX.matcher(message);
        Pair<String, Integer> mostRecentNpcData = null;

        if (primary.find()) {
            String boss = parsePrimaryBoss(primary.group("key"), primary.group("type"));
            String count = primary.group("value");
            if (boss != null) {
                try {
                    int killCount = Integer.parseInt(count.replace(",", ""));
                    mostRecentNpcData = Pair.of(boss, killCount);
                    plugin.ticksSinceNpcDataUpdate = 0;
                    return Optional.of(mostRecentNpcData);
                } catch (NumberFormatException ignored) {
                }
            }
        } else if (secondary.find()) {
            String key = parseSecondary(secondary.group("key"));
            String value = secondary.group("value");
            if (key != null) {
                try {
                    int killCount = Integer.parseInt(value.replace(",", ""));
                    mostRecentNpcData = Pair.of(key, killCount);
                    plugin.ticksSinceNpcDataUpdate = 0;
                    return Optional.of(mostRecentNpcData);
                } catch (NumberFormatException ignored) {
                }
            }
        }
        return Optional.empty();
    }

    @Nullable
    @VisibleForTesting
    static String parsePrimaryBoss(String boss, String type) {
        switch (type.toLowerCase()) {
            case "chest":
                if ("Barrows".equalsIgnoreCase(boss))
                    return boss;
                if ("Lunar".equals(boss))
                    return boss + " " + type;
                return null;

            case "completion":
                if (GAUNTLET_NAME.equalsIgnoreCase(boss))
                    return GAUNTLET_BOSS;
                if (CG_NAME.equalsIgnoreCase(boss))
                    return CG_BOSS;
                return null;

            case "kill":
                return boss;

            case "success":
                return boss;

            default:
                return null;
        }
    }

    @VisibleForTesting
    static String parseSecondary(String boss) {
        if (boss == null || "Wintertodt".equalsIgnoreCase(boss))
            return boss;

        int modeSeparator = boss.lastIndexOf(':');
        String raid = modeSeparator > 0 ? boss.substring(0, modeSeparator) : boss;
        if (raid.equalsIgnoreCase("Theatre of Blood")
                || raid.equalsIgnoreCase("Tombs of Amascut")
                || raid.equalsIgnoreCase("Chambers of Xeric")
                || raid.equalsIgnoreCase("Chambers of Xeric Challenge Mode"))
            return boss;

        return null;
    }

}

package io.droptracker.util;

import javax.annotation.Nullable;

/**
 * Decides which RSN a submission is sent under.
 *
 * <p>Every submission the plugin builds carries a {@code player_name}, and the
 * backend resolves that name against a real account. An unreadable RSN used to
 * be replaced with the literal string {@code "Unknown"} — which is not an inert
 * placeholder. It is a name like any other, it matches a real (but empty) Wise
 * Old Man record, and adopting that record renamed whichever live account the
 * submission resolved to, breaking its identity and silently discarding
 * everything it submitted afterwards. The server no longer trusts that record,
 * but the plugin has no business inventing a name in the first place.
 *
 * <p>So: resolve honestly or not at all. A caller that gets {@code null} skips
 * the submission — an event with no identity has nothing to attach itself to.
 */
public final class PlayerIdentity {

    private PlayerIdentity() {
    }

    /**
     * Resolves the RSN to submit under.
     *
     * <p>The live name is unreadable whenever the local player is gone: at
     * logout and during a world hop (which is where most of these come from —
     * the XP handler snapshots on both), and in the short window after login
     * before the name arrives. The account hash outlives the local player in
     * all three, so the cached name covers them — and it is trusted only when
     * it was stored against the hash logged in right now, so it can never
     * attribute an event to whichever account the player was on previously.
     *
     * @param liveName          name read from the client
     * @param accountHash       account hash of the session being submitted for
     * @param cachedName        last name stored by the plugin at login
     * @param cachedAccountHash account hash {@code cachedName} was stored for
     * @return the RSN, or {@code null} when it cannot be established
     */
    @Nullable
    public static String resolve(@Nullable String liveName, @Nullable String accountHash,
                                 @Nullable String cachedName, @Nullable String cachedAccountHash) {
        if (liveName != null && !liveName.trim().isEmpty()) {
            return liveName;
        }
        if (cachedName == null || cachedName.trim().isEmpty()) {
            return null;
        }
        // The account hash is the only thing that proves the cached name
        // belongs to this session rather than the last one.
        if (!isUsableAccountHash(accountHash) || cachedAccountHash == null
                || !accountHash.trim().equals(cachedAccountHash.trim())) {
            return null;
        }
        return cachedName;
    }

    /**
     * True when an account hash identifies a logged-in account. The client
     * reports -1 when logged out, and the plugin substitutes 0 when there is no
     * client at all; both are strings the backend would otherwise try to match
     * a player row against.
     */
    public static boolean isUsableAccountHash(@Nullable String accountHash) {
        if (accountHash == null) {
            return false;
        }
        String trimmed = accountHash.trim();
        return !trimmed.isEmpty() && !"0".equals(trimmed) && !"-1".equals(trimmed);
    }

    /**
     * True when a submission's {@code player_name} field is unusable. Used as
     * the last line of defence before a payload leaves the client.
     */
    public static boolean isMissingName(@Nullable String playerName) {
        return playerName == null || playerName.trim().isEmpty();
    }
}

package io.droptracker.util;

import java.io.File;
import java.io.FileWriter;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.StandardCopyOption;
import java.text.SimpleDateFormat;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.Date;

import io.droptracker.DropTrackerConfig;
import javax.inject.Inject;

import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;
@Slf4j
public class DebugLogger {

    private static final String PLUGIN_DIR_NAME = "droptracker";
    private static final String LOGS_DIR_NAME = "logs";
    private static final String BASE_LOG_FILENAME = "droptracker.log";

    private static volatile DebugLogger activeInstance;

    private final DropTrackerConfig config;
    private final File logsDir;
    private final File currentLogFile;
    private final Object writeLock = new Object();
    private volatile boolean sessionHeaderWritten = false;
    private FileWriter writer;

    @Inject
    public DebugLogger(DropTrackerConfig config) {
        this.config = config;

        File pluginDir = new File(RuneLite.RUNELITE_DIR, PLUGIN_DIR_NAME);
        this.logsDir = new File(pluginDir, LOGS_DIR_NAME);
        if (!logsDir.exists()) {
            logsDir.mkdirs();
        }

        this.currentLogFile = new File(logsDir, BASE_LOG_FILENAME);
        rotateIfExists(currentLogFile);

        try {
            this.writer = new FileWriter(currentLogFile, true);
        } catch (IOException e) {
            // If we cannot open the writer, logging will become a no-op
            this.writer = null;
        }

        activeInstance = this;
    }

    public boolean isEnabled() {
        return config.debugLogging();
    }

    public static void log(String message) {
        DebugLogger instance = activeInstance;
        if (instance == null) {
            return;
        }
        if (!instance.isEnabled()) {
            /* Still forwarding these messages to the default Sl4fj logger;
                since we use the DebugLogger throughout as an alternative in our plugin
            */
            log.debug(message);
            return;
        }
        log.debug("DebugLogger message: " + message);
        instance.ensureSessionHeader();
        instance.writeLine(message);
    }

    private void ensureSessionHeader() {
        if (sessionHeaderWritten) {
            return;
        }
        synchronized (writeLock) {
            if (sessionHeaderWritten) {
                return;
            }
            writeLine("---- Debug logging enabled for this session ----");
            sessionHeaderWritten = true;
        }
    }

    private void writeLine(String message) {
        synchronized (writeLock) {
            if (writer == null) {
                return;
            }
            try {
                String timestamp = DateTimeFormatter.ISO_LOCAL_DATE_TIME.format(LocalDateTime.now());
                writer.write("[" + timestamp + "] " + message + System.lineSeparator());
                writer.flush();
            } catch (IOException e) {
                // Swallow to avoid impacting game thread; debugging only
            }
        }
    }

    private void rotateIfExists(File file) {
        if (!file.exists()) {
            return;
        }

        long lastModified = file.lastModified();
        String ts = new SimpleDateFormat("yyyy-MM-dd_HHmmss").format(new Date(lastModified));
        File target = new File(logsDir, "droptracker-" + ts + ".log");

        if (target.exists()) {
            int idx = 1;
            File candidate;
            do {
                candidate = new File(logsDir, "droptracker-" + ts + "-" + idx + ".log");
                idx++;
            } while (candidate.exists());
            target = candidate;
        }

        try {
            Files.move(file.toPath(), target.toPath(), StandardCopyOption.ATOMIC_MOVE);
        } catch (IOException moveEx) {
            // Fallback to simple numeric roll if atomic move fails
            int idx = 1;
            File candidate;
            do {
                candidate = new File(logsDir, "droptracker-" + idx + ".log");
                idx++;
            } while (candidate.exists());
            // Best-effort rename; ignore result
            //noinspection ResultOfMethodCallIgnored
            file.renameTo(candidate);
        }
    }

    public void close() {
        synchronized (writeLock) {
            if (writer != null) {
                try {
                    writer.flush();
                    writer.close();
                } catch (IOException e) {
                    // Ignore on close
                } finally {
                    writer = null;
                }
            }
            if (activeInstance == this) {
                activeInstance = null;
            }
        }
    }
}

package io.droptracker.util;

import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.AsyncBufferedImage;

import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import java.awt.image.BufferedImage;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Consumer;
import java.util.function.IntFunction;

/**
 * Item sprites for the side panel, without leaning on the game thread.
 *
 * <p>Two things about {@link ItemManager#getImage} make it a poor fit for a
 * panel that rebuilds on every event update. Its cache holds only 128
 * images, so a big bingo board evicts its own icons and every rebuild renders
 * them all again. And {@link AsyncBufferedImage#onLoaded} on an image that has
 * already loaded does not run the callback: it posts it to the client thread.
 * A rebuild used to queue one such callback per icon, image scaling and Swing
 * layout included, and the game thread ran the lot in a single frame. That is
 * the hitch players felt when an event pop-up landed mid-fight.
 *
 * <p>Here, loaded sprites stay in our own larger cache, new sprites are
 * rendered at most {@value #LOADS_PER_FRAME} per frame, and callbacks always
 * run on the EDT. The game thread only ever does the sprite render itself.
 */
@Singleton
public class ItemImageCache {
    private static final int MAX_ENTRIES = 512;
    static final int LOADS_PER_FRAME = 4;

    private final IntFunction<AsyncBufferedImage> loader;
    private final ClientThread clientThread;

    /** Access-ordered LRU. Guarded by {@code this}. */
    private final Map<Integer, BufferedImage> loaded =
        new LinkedHashMap<Integer, BufferedImage>(64, 0.75f, true) {
            @Override
            protected boolean removeEldestEntry(Map.Entry<Integer, BufferedImage> eldest) {
                return size() > MAX_ENTRIES;
            }
        };
    /** Callbacks per item still loading; a key here means it is queued or rendering. Guarded by {@code this}. */
    private final Map<Integer, List<Consumer<BufferedImage>>> waiting = new HashMap<>();
    /** Item ids not yet handed to the ItemManager. Guarded by {@code this}. */
    private final ArrayDeque<Integer> queue = new ArrayDeque<>();
    /** True while a drain is scheduled on the client thread. Guarded by {@code this}. */
    private boolean draining;

    @Inject
    public ItemImageCache(ItemManager itemManager, ClientThread clientThread) {
        this(itemManager::getImage, clientThread);
    }

    /** Test seam: ItemManager cannot be constructed outside the client. */
    ItemImageCache(IntFunction<AsyncBufferedImage> loader, ClientThread clientThread) {
        this.loader = loader;
        this.clientThread = clientThread;
    }

    /**
     * The sprite for {@code itemId} if it is already here, else null. On a
     * miss the sprite is queued, and {@code onReady} runs on the EDT once it
     * has been rendered. Callable from any thread.
     */
    @Nullable
    public BufferedImage get(int itemId, @Nullable Consumer<BufferedImage> onReady) {
        boolean schedule;
        synchronized (this) {
            BufferedImage image = loaded.get(itemId);
            if (image != null) {
                return image;
            }
            List<Consumer<BufferedImage>> callbacks = waiting.get(itemId);
            if (callbacks == null) {
                callbacks = new ArrayList<>(1);
                waiting.put(itemId, callbacks);
                queue.addLast(itemId);
            }
            if (onReady != null) {
                callbacks.add(onReady);
            }
            schedule = !draining;
            draining = true;
        }
        if (schedule) {
            clientThread.invokeLater(this::drain);
        }
        return null;
    }

    /**
     * Client thread: render up to {@value #LOADS_PER_FRAME} queued sprites.
     * Returning false asks the ClientThread to run this again next frame.
     */
    boolean drain() {
        for (int i = 0; i < LOADS_PER_FRAME; i++) {
            Integer itemId;
            synchronized (this) {
                itemId = queue.pollFirst();
                if (itemId == null) {
                    draining = false;
                    return true;
                }
            }
            // On the client thread this renders the sprite inline, unless it
            // was still in the ItemManager's own cache.
            AsyncBufferedImage image = loader.apply(itemId);
            final int id = itemId;
            image.onLoaded(() -> store(id, image));
        }
        synchronized (this) {
            if (queue.isEmpty()) {
                draining = false;
                return true;
            }
            return false;
        }
    }

    private void store(int itemId, BufferedImage image) {
        List<Consumer<BufferedImage>> callbacks;
        synchronized (this) {
            loaded.put(itemId, image);
            callbacks = waiting.remove(itemId);
        }
        if (callbacks == null || callbacks.isEmpty()) {
            return;
        }
        SwingUtilities.invokeLater(() -> {
            for (Consumer<BufferedImage> callback : callbacks) {
                callback.accept(image);
            }
        });
    }
}

package io.droptracker.util;


import io.droptracker.api.DropTrackerUrls;
import com.google.gson.Gson;
import lombok.extern.slf4j.Slf4j;
import okhttp3.HttpUrl;
import okhttp3.*;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;
import org.jetbrains.annotations.VisibleForTesting;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.IOException;
import java.io.Reader;
import java.util.*;
import java.util.concurrent.CompletableFuture;
import java.util.function.Function;

/**
 * This thread-safe singleton holds a mapping of item names to their item id, using the RuneLite API.
 * <p>
 * Unlike {@link net.runelite.client.game.ItemManager#search(String)}, this mapping supports untradable items.
 *
 * Author: iProdigy ( https://github.com/pajlads/DinkPlugin )
 */

@Slf4j
@Singleton
public class ItemIDSearch {
    private final Map<String, Integer> itemIdByName = Collections.synchronizedMap(new HashMap<>(16384));
    private @Inject OkHttpClient httpClient;
    private @Inject Gson gson;

    /**
     * @param name the exact in-game name of an item
     * @return the id associated with the item name, or null if not found
     */
    @Nullable
    public Integer findItemId(@NotNull String name) {
        return itemIdByName.get(name);
    }

    /**
     * Begins the initialization process for {@link #itemIdByName}
     * by querying item names and noted item ids from the RuneLite API,
     * before passing them to {@link #populate(Map, Set)}
     *
     * @implNote This operation does not block the current thread,
     * by utilizing OkHttp's thread pool and Java's Fork-Join common pool.
     */
    @Inject
    void init() {
        queryNamesById()
                .thenAcceptBothAsync(
                        queryNotedItemIds().exceptionally(e -> {
                            log.error("Failed to read noted items", e);
                            return Collections.emptySet();
                        }),
                        this::populate
                )
                .exceptionally(e -> {
                    log.error("Failed to read item names", e);
                    return null;
                });
    }

    /**
     * Populates {@link #itemIdByName} with the inverted mappings of {@code namesById},
     * while skipping noted items specified in {@code notedIds}.
     *
     * @param namesById a mapping of item id's to the corresponding in-game name
     * @param notedIds  the id's of noted items
     * @implNote When multiple non-noted item id's have the same in-game name, only the earliest id is saved
     */
    @VisibleForTesting
    void populate(@NotNull Map<Integer, String> namesById, @NotNull Set<Integer> notedIds) {
        namesById.forEach((id, name) -> {
            if (!notedIds.contains(id))
                itemIdByName.putIfAbsent(name, id);
        });

        log.debug("Completed initialization of item cache with {} entries", itemIdByName.size());
    }

    /**
     * @return a mapping of item ids to their in-game names, provided by the RuneLite API
     */
    private CompletableFuture<Map<Integer, String>> queryNamesById() {
        // Read JSON as Map<String, String> first
        return queryCache("names.json", Map.class)
                .thenApply(stringMap -> {
                    Map<Integer, String> result = new HashMap<>();
                    for (Object keyObj : stringMap.keySet()) {
                        String keyStr = (String) keyObj;
                        Object valObj = stringMap.get(keyStr);
                        // Defensive: valObj might be String or something else
                        String valueStr = valObj != null ? valObj.toString() : null;
                        result.put(Integer.parseInt(keyStr), valueStr);
                    }
                    return result;
                });

    }

    /**
     * @return a set of id's of noted items, provided by the RuneLite API
     */
    private CompletableFuture<Set<Integer>> queryNotedItemIds() {
        return queryCache("notes.json", Map.class)
                .thenApply(stringMap -> {
                    Set<Integer> keys = new HashSet<>();
                    for (Object keyObj : stringMap.keySet()) {
                        keys.add(Integer.parseInt((String) keyObj));
                    }
                    return keys;
                });

    }

    /**
     * @param fileName the name of the file to query from RuneLite's cache
     * @param type     a type token that indicates how the json response should be parsed
     * @return the transformed cache response, wrapped in a future
     */
    private <T> CompletableFuture<T> queryCache(@NotNull String fileName, @NotNull Class<T> clazz) {
        return readJson(httpClient, gson, DropTrackerUrls.itemCache(fileName), clazz);
    }

    public <T> CompletableFuture<T> readJson(@NotNull OkHttpClient httpClient, @NotNull Gson gson, @NotNull HttpUrl url, @NotNull Class<T> clazz) {
        return readUrl(httpClient, url, reader -> gson.fromJson(reader, clazz));
    }

    public <T> CompletableFuture<T> readUrl(@NotNull OkHttpClient httpClient, @NotNull HttpUrl url, @NotNull Function<Reader, T> transformer) {
        CompletableFuture<T> future = new CompletableFuture<>();
        Request request = new Request.Builder().url(url).build();
        httpClient.newCall(request).enqueue(new Callback() {
            @Override
            public void onFailure(@NotNull Call call, @NotNull IOException e) {
                future.completeExceptionally(e);
            }

            @Override
            public void onResponse(@NotNull Call call, @NotNull Response response) {
                try (Response autoClose = response) {
                    ResponseBody body = response.body();
                    if (body == null) {
                        future.completeExceptionally(new IOException("Empty response body from " + url));
                        return;
                    }
                    try (Reader reader = body.charStream()) {
                        future.complete(transformer.apply(reader));
                    }
                } catch (Exception e) {
                    future.completeExceptionally(e);
                }
            }
        });
        return future;
    }
    public class IntStringEntry {
        public int key;
        public String value;
    }
    public class IntIntEntry {
        public int key;
        public int value;
    }


}

package io.droptracker.util;

import java.text.NumberFormat;
import java.util.Locale;

/**
 * Quantity formatting for event progress values: large targets like
 * 10,000,000 XP must never render as raw digit runs. Panel rows use comma
 * grouping ({@link #commas}); tight spots (HUD progress bar) use GP-style
 * abbreviations ({@link #abbrev}).
 */
public final class ValueFormat {

    private static final NumberFormat COMMAS = NumberFormat.getIntegerInstance(Locale.US);

    private ValueFormat() {
    }

    /** 10000000 → "10,000,000". */
    public static String commas(long value) {
        synchronized (COMMAS) {
            return COMMAS.format(value);
        }
    }

    /** 10000000 → "10M", 1250000 → "1.25M", 813636 → "813.6K", 500 → "500". */
    public static String abbrev(long value) {
        long abs = Math.abs(value);
        if (abs >= 1_000_000_000L) {
            return trim(value / 1_000_000_000.0, 2) + "B";
        }
        if (abs >= 1_000_000L) {
            return trim(value / 1_000_000.0, 2) + "M";
        }
        if (abs >= 10_000L) {
            return trim(value / 1_000.0, 1) + "K";
        }
        return commas(value);
    }

    /**
     * "have / need" for progress displays: abbreviated once values get long
     * enough that comma strings stop fitting, comma-grouped below that.
     */
    public static String progress(long have, long need) {
        if (need >= 100_000L || have >= 100_000L) {
            return abbrev(have) + " / " + abbrev(need);
        }
        return commas(have) + " / " + commas(need);
    }

    private static String trim(double value, int maxDecimals) {
        String out = String.format(Locale.US, "%." + maxDecimals + "f", value);
        while (out.contains(".") && (out.endsWith("0") || out.endsWith("."))) {
            out = out.substring(0, out.length() - 1);
        }
        return out;
    }
}

package io.droptracker.util;

import io.droptracker.api.DropTrackerUrls;
import lombok.extern.slf4j.Slf4j;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

import javax.annotation.Nullable;
import javax.imageio.ImageIO;
import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.image.BufferedImage;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ScheduledExecutorService;

/**
 * Tiny async cache for server-hosted icons (team pieces, NPC/skill task icons).
 *
 * <p>Keys are <em>relative paths</em> under {@code /img/}, e.g.
 * {@code "npcdb/2215.png"}, not URLs: the API is not permitted to tell the plugin
 * which host to contact. {@link DropTrackerUrls#image} anchors the path onto a
 * hardcoded base and rejects anything that tries to escape it, redirects are
 * disabled, and bytes go through ImageIO so a non-image body decodes to null and
 * renders nothing.
 */
@Slf4j
@Singleton
public class RemoteImageCache {
    private static final int MAX_ENTRIES = 256;
    private static final int MAX_DIMENSION = 512;

    private final Map<String, BufferedImage> cache =
        // Access-ordered, so an event board bigger than the cache evicts what it
        // is not showing, not the icons the panel is about to ask for again.
        Collections.synchronizedMap(new LinkedHashMap<String, BufferedImage>(64, 0.75f, true) {
            @Override
            protected boolean removeEldestEntry(Map.Entry<String, BufferedImage> eldest) {
                return size() > MAX_ENTRIES;
            }
        });
    private final Map<String, Boolean> inFlight = new ConcurrentHashMap<>();

    private final OkHttpClient httpClient;
    private final ScheduledExecutorService executor;

    @Inject
    public RemoteImageCache(OkHttpClient httpClient, ScheduledExecutorService executor) {
        // Redirects off: the base is hardcoded, and following one would hand the
        // choice of host back to the server.
        this.httpClient = httpClient.newBuilder()
            .followRedirects(false)
            .followSslRedirects(false)
            .build();
        this.executor = executor;
    }

    /**
     * Cached image for the given {@code /img/}-relative path, or null while it
     * loads (or when the path is absent, malformed, or not an image). Kicks off at
     * most one background fetch per path; {@code onLoaded} runs off-EDT after a
     * successful load so callers can repaint.
     */
    @Nullable
    public BufferedImage get(@Nullable String imagePath, @Nullable Runnable onLoaded) {
        HttpUrl url = DropTrackerUrls.image(imagePath);
        if (url == null) {
            return null;
        }
        final String key = imagePath;
        BufferedImage cached = cache.get(key);
        if (cached != null) {
            return cached;
        }
        if (inFlight.putIfAbsent(key, Boolean.TRUE) == null) {
            CompletableFuture.runAsync(() -> {
                try {
                    BufferedImage image = fetch(url);
                    if (image != null
                            && image.getWidth() <= MAX_DIMENSION
                            && image.getHeight() <= MAX_DIMENSION) {
                        cache.put(key, image);
                        if (onLoaded != null) {
                            onLoaded.run();
                        }
                    }
                } catch (Exception e) {
                    log.debug("icon fetch failed for {}: {}", key, e.getMessage());
                } finally {
                    inFlight.remove(key);
                }
            }, executor);
        }
        return null;
    }

    @Nullable
    private BufferedImage fetch(HttpUrl url) throws Exception {
        Request request = new Request.Builder().url(url).build();
        try (Response response = httpClient.newCall(request).execute()) {
            ResponseBody body = response.body();
            if (!response.isSuccessful() || body == null) {
                return null;
            }
            // A non-image body (HTML error page, redirect target) decodes to null and renders nothing.
            return ImageIO.read(body.byteStream());
        }
    }
}

package io.droptracker.util;

import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Prayer;
import net.runelite.api.SkullIcon;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.game.ItemManager;
import org.jetbrains.annotations.VisibleForTesting;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

/**
 * Values what a death actually cost: the GE value of the items the player
 * failed to protect.
 *
 * <p>This exists so a group can filter on it server-side — "don't announce
 * deaths under 1M" is the single most requested death filter, and it is the one
 * thing the server could not previously answer because the plugin never sent a
 * value. The algorithm mirrors Dink's {@code DeathNotifier#splitItemsByKept},
 * which is the most complete public treatment of items-kept-on-death.
 *
 * <h2>What is counted</h2>
 * Inventory and worn equipment only, exactly as Dink counts them. Containers
 * carried inside the inventory (rune pouch, looting bag, seed box) are not
 * opened; their contents are lost on death but the game does not expose them
 * as carried items, and guessing would be worse than the documented omission.
 *
 * <h2>What is approximated</h2>
 * The real items-kept-on-death rules have per-item exceptions ("never kept"
 * items, quest items, deposited items) that Dink models with a hand-maintained
 * id list. That list is not ported here: almost every entry on it has no GE
 * price, and since keep slots are handed out most-expensive-first, a zero-value
 * item sorts last and never takes a slot from something that matters. The one
 * exception that does move the number is the bond, which is special-cased
 * below. Treat the result as a good estimate, not an audit.
 */
public final class DeathValuation {

    /** Items kept on an unskulled, non-UIM death. */
    private static final int UNSKULLED_KEEP_COUNT = 3;

    /** Account-type varbit value for an Ultimate Ironman, who keeps nothing. */
    private static final int ACCOUNT_TYPE_ULTIMATE_IRONMAN = 2;

    private DeathValuation() {
    }

    /** What a death cost, in GP. */
    public static final class Valuation {

        private final long lostValue;
        private final long keptValue;
        private final int lostItemCount;

        @VisibleForTesting
        Valuation(long lostValue, long keptValue, int lostItemCount) {
            this.lostValue = lostValue;
            this.keptValue = keptValue;
            this.lostItemCount = lostItemCount;
        }

        /** Total GE value of everything that dropped. Zero on a safe death. */
        public long getLostValue() {
            return lostValue;
        }

        /** Total GE value of everything that came back with the player. */
        public long getKeptValue() {
            return keptValue;
        }

        /** Number of item stacks lost, for the "and 12 other items" case. */
        public int getLostItemCount() {
            return lostItemCount;
        }
    }

    /** A carried stack reduced to the three things the split cares about. */
    @VisibleForTesting
    static final class PricedItem {

        private final int id;
        private final int quantity;
        private final long unitPrice;

        @VisibleForTesting
        PricedItem(int id, int quantity, long unitPrice) {
            this.id = id;
            this.quantity = quantity;
            this.unitPrice = unitPrice;
        }
    }

    /**
     * Values the local player's death.
     *
     * <p>Must be called on the client thread, and while the inventory still
     * reflects the death — the containers are emptied shortly afterwards, so a
     * deferred call values an empty inventory at zero.
     *
     * @param safeDeath whether this location costs no items (see
     *                  {@link DeathRegions}); a safe death loses nothing, so
     *                  the whole split is skipped
     * @return the valuation, or {@code null} when it cannot be established
     *         (no client, no item manager) — callers must omit the field
     *         rather than send a zero that reads as "died with nothing"
     */
    public static Valuation value(Client client, ItemManager itemManager, boolean safeDeath) {
        if (client == null || itemManager == null) {
            return null;
        }

        List<PricedItem> carried = pricedItems(client, itemManager);

        // Nothing is at risk in a safe area, so everything carried is kept.
        // Short-circuited rather than run through the split because the keep
        // count is meaningless here: a skulled player in Castle Wars still
        // walks out with their whole inventory.
        if (safeDeath) {
            long kept = 0;
            for (PricedItem item : carried) {
                kept += item.unitPrice * item.quantity;
            }
            return new Valuation(0L, kept, 0);
        }

        return split(carried, keepCount(client));
    }

    /**
     * Every item the player is carrying or wearing, priced and sorted most
     * valuable first — the order the game hands out protect slots in.
     */
    private static List<PricedItem> pricedItems(Client client, ItemManager itemManager) {
        List<PricedItem> items = new ArrayList<>();
        for (int containerId : new int[] { InventoryID.INV, InventoryID.WORN }) {
            ItemContainer container = client.getItemContainer(containerId);
            if (container == null) {
                continue;
            }
            Item[] contents = container.getItems();
            if (contents == null) {
                continue;
            }
            for (Item item : contents) {
                // id -1 is an empty slot, not an item worth 0gp.
                if (item == null || item.getId() < 0 || item.getQuantity() <= 0) {
                    continue;
                }
                items.add(new PricedItem(item.getId(), item.getQuantity(),
                        unitPrice(itemManager, item.getId())));
            }
        }
        items.sort(Comparator.comparingLong((PricedItem item) -> item.unitPrice).reversed());
        return items;
    }

    /**
     * One item's value.
     *
     * <p>{@code getItemPrice} already resolves noted and worn variants back to
     * the tradeable id, so nothing needs canonicalizing first. Untradeables
     * come back as 0 and fall through to the store price, which is what the
     * game itself ranks them by when deciding what to protect.
     */
    private static long unitPrice(ItemManager itemManager, int itemId) {
        try {
            long price = itemManager.getItemPrice(itemId);
            if (price > 0) {
                return price;
            }
            return Math.max(0, itemManager.getItemComposition(itemId).getPrice());
        } catch (RuntimeException e) {
            // An unknown id must not cost us the whole submission.
            return 0L;
        }
    }

    /**
     * How many items this player would keep on an unsafe death.
     *
     * <p>Must be called on the client thread.
     */
    @VisibleForTesting
    static int keepCount(Client client) {
        if (client.getVarbitValue(VarbitID.IRONMAN) == ACCOUNT_TYPE_ULTIMATE_IRONMAN) {
            return 0;
        }

        boolean skulled = client.getLocalPlayer() != null
                && client.getLocalPlayer().getSkullIcon() != SkullIcon.NONE;
        int keepCount = skulled ? 0 : UNSKULLED_KEEP_COUNT;

        // Ruinous Powers is a separate prayer book with its own varbit, so the
        // standard Protect Item alone does not answer the question.
        if (client.isPrayerActive(Prayer.PROTECT_ITEM) || client.isPrayerActive(Prayer.RP_PROTECT_ITEM)) {
            keepCount++;
        }
        return keepCount;
    }

    /**
     * Splits priced items into kept and lost, handing the {@code keepCount}
     * protect slots to the most valuable items first.
     *
     * <p>Slots are per *item*, not per stack: a player carrying 100 sharks with
     * one slot left keeps one shark and drops 99. Kept separate from the client
     * reads so the arithmetic can be tested without a running game.
     *
     * @param itemsByPrice carried items, most valuable unit price first
     */
    @VisibleForTesting
    static Valuation split(List<PricedItem> itemsByPrice, int keepCount) {
        long lost = 0;
        long kept = 0;
        int lostStacks = 0;
        int slotsUsed = 0;

        for (PricedItem item : itemsByPrice) {
            // A bond always comes back and never occupies a protect slot. This
            // is the one never-kept-style exception worth modelling: it is
            // valuable enough to otherwise soak up a slot that belongs to real
            // gear, which would overstate the loss by millions.
            if (isBond(item.id)) {
                kept += item.unitPrice * item.quantity;
                continue;
            }

            int protectedUnits = Math.min(item.quantity, Math.max(0, keepCount - slotsUsed));
            slotsUsed += protectedUnits;
            kept += item.unitPrice * protectedUnits;

            int droppedUnits = item.quantity - protectedUnits;
            if (droppedUnits > 0) {
                lost += item.unitPrice * droppedUnits;
                lostStacks++;
            }
        }

        return new Valuation(lost, kept, lostStacks);
    }

    private static boolean isBond(int itemId) {
        return itemId == ItemID.OSRS_BOND
                || itemId == ItemID.BOUGHT_OSRS_BOND
                || itemId == ItemID.OSRS_BOND_UNTRADEABLE;
    }

    /**
     * Test seam: priced items in the most-valuable-first order {@link #split}
     * expects, from {@code {id, quantity, unitPrice}} rows.
     */
    @VisibleForTesting
    static List<PricedItem> priced(int[]... idQuantityPrice) {
        List<PricedItem> items = new ArrayList<>();
        for (int[] row : idQuantityPrice) {
            items.add(new PricedItem(row[0], row[1], row[2]));
        }
        items.sort(Comparator.comparingLong((PricedItem item) -> item.unitPrice).reversed());
        return items;
    }
}

package io.droptracker.util;

import io.droptracker.api.DropTrackerUrls;
import com.google.inject.Inject;

import io.droptracker.DropTrackerConfig;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.events.CommandExecuted;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.ColorUtil;
import net.runelite.client.util.LinkBrowser;

import java.awt.*;


public class ChatMessageUtil {

    @Inject
    private DropTrackerConfig config;

    @Inject
    private ChatMessageManager chatMessageManager;

    @Inject
    private Client client;
    @Inject
    private ClientThread clientThread;

    @Subscribe
    public void onCommandExecuted(CommandExecuted event)
    {
        if (event.getCommand().equals("droptracker"))
        {
            LinkBrowser.browse(DropTrackerUrls.web("wiki", "why-api").toString());
        }
        if (event.getCommand().equals("debugurl"))
        {
            String apiUrlToUse = event.getArguments()[0];
            config.setCustomApiEndpoint(apiUrlToUse);
            sendChatMessage("All outgoing requests will now be sent to " + apiUrlToUse);
        }
    }
    public void warnApiSetting() {
        queueWarning("It is strongly recommended that you enable our API connections in the DropTracker plugin configuration. To learn more, type ::droptracker");
    }
    public void warnClogSetting() {
        queueWarning("Your collection log slots will not be tracked unless you enabled the game setting: Collection log - New addition notification");
    }

    private void queueWarning(String message) {
        Color color = ColorUtil.fromHex("#ff0000");
        String formatted = String.format("[%s] %s: %s",
                ColorUtil.wrapWithColorTag("DropTracker.io", color),
                "Warning",
                ColorUtil.wrapWithColorTag(message, color));
        chatMessageManager.queue(
                QueuedMessage.builder()
                        .type(ChatMessageType.CONSOLE)
                        .runeLiteFormattedMessage(formatted)
                        .build()
        );
    }

    public void sendChatMessage(String messageContent) {
        ChatMessageBuilder messageBuilder = new ChatMessageBuilder();
        messageBuilder.append(ChatColorType.HIGHLIGHT)
                .append("[")
                .append(ChatColorType.NORMAL)
                .append("DropTracker")
                .append(ChatColorType.HIGHLIGHT)
                .append("] ")
                .append(ChatColorType.NORMAL);
        messageBuilder.append(messageContent);
        final String finalMessage = messageBuilder.build();
        chatMessageManager.queue(
                QueuedMessage.builder()
                        .type(ChatMessageType.CONSOLE)
                        .runeLiteFormattedMessage(finalMessage)
                        .build()
        );
    }

    /**
     * Stamped onto a Discord author's name when their line is rendered in the
     * game's clan chat. Two jobs: a Discord user can never be mistaken for an
     * in-game clanmate, AND it is what stops the bridge from looping — the
     * render goes through {@code client.addChatMessage}, which posts a real
     * {@link net.runelite.api.events.ChatMessage}, so our own injected line
     * comes straight back through the plugin's chat subscriber. An in-game
     * display name cannot contain parentheses, so no real clanmate wears it.
     */
    public static final String DISCORD_SENDER_MARKER = "(Discord)";

    /**
     * Whether a CLAN_CHAT sender name is one of our own rendered Discord
     * lines. Substring rather than suffix: the marker is appended at the end
     * today, but the test has to keep holding if the rendered name is ever
     * decorated further, and no real name can contain it either way.
     */
    public static boolean isDiscordBridgeSender(String name) {
        return name != null && name.contains(DISCORD_SENDER_MARKER);
    }

    /**
     * Discord→game bridge line, rendered to look like clan chat (visible only
     * to this client — nothing is sent to the game server). Approach adapted
     * from the TrackScape Connector, Copyright (c) 2023, Bailey Townsend,
     * BSD 2-Clause License (see LICENSE). The sender carries
     * {@link #DISCORD_SENDER_MARKER}; both strings must already be
     * sanitized/capped by the caller.
     */
    public void sendDiscordClanMessage(String sender, String messageContent) {
        // Callers arrive on the OkHttp callback thread (the notification
        // poller), and client.getClanChannel() is only safe on the client
        // thread — hop over for the read; queue() itself is thread-safe.
        clientThread.invokeLater(() -> {
            String clanName = client.getClanChannel() != null
                    ? net.runelite.client.util.Text.removeTags(client.getClanChannel().getName())
                    : "Discord";
            chatMessageManager.queue(
                    QueuedMessage.builder()
                            .type(ChatMessageType.CLAN_CHAT)
                            .name(sender + " " + DISCORD_SENDER_MARKER)
                            .sender(clanName)
                            .value(messageContent)
                            .build()
            );
        });
    }

    /**
     * Event-notification line: prefixed "[Event Name] (Team name):" instead
     * of the generic [DropTracker] tag so lines read as the event talking.
     * Both names must already be sanitized/capped by the caller; teamName is
     * optional (omitted before the first /event_state snapshot lands).
     */
    public void sendEventChatMessage(String eventName, String teamName, String messageContent) {
        sendEventChatMessage(eventName, teamName, null, null, null, messageContent);
    }

    /**
     * Accented event line: an uppercase type tag ("COMPLETE", "LEAD CHANGE",
     * "PROGRESS"...) in a brightened accent, the body in the accent itself,
     * and — when {@code emphasis} occurs in the body — that one substring
     * (usually the item name) lifted back to the bright shade. A null accent
     * reproduces the old uncoloured line exactly.
     *
     * <p>Colours must go through {@link ChatMessageBuilder#append(Color,
     * String)}: the plain {@code append(String)} runs {@code escapeJagex},
     * which would print the tags literally. All strings must already be
     * sanitized/capped by the caller.</p>
     */
    public void sendEventChatMessage(String eventName, String teamName,
                                     String tag, String accentHex,
                                     String emphasis, String messageContent) {
        ChatMessageBuilder messageBuilder = new ChatMessageBuilder();
        messageBuilder.append(ChatColorType.HIGHLIGHT)
                .append("[")
                .append(ChatColorType.NORMAL)
                .append(eventName)
                .append(ChatColorType.HIGHLIGHT)
                .append("] ");
        if (teamName != null && !teamName.isEmpty()) {
            messageBuilder.append("(")
                    .append(ChatColorType.NORMAL)
                    .append(teamName)
                    .append(ChatColorType.HIGHLIGHT)
                    .append("): ");
        }
        Color accent = accentHex != null ? ColorUtil.fromHex(accentHex) : null;
        if (accent == null) {
            if (tag != null && !tag.isEmpty()) {
                messageBuilder.append(ChatColorType.HIGHLIGHT).append(tag).append(" ");
            }
            messageBuilder.append(ChatColorType.NORMAL).append(messageContent);
        } else {
            Color bright = ColorUtil.colorLerp(accent, Color.WHITE, 0.45);
            if (tag != null && !tag.isEmpty()) {
                messageBuilder.append(bright, tag).append(" ");
            }
            appendEmphasized(messageBuilder, messageContent, emphasis, accent, bright);
        }
        chatMessageManager.queue(
                QueuedMessage.builder()
                        .type(ChatMessageType.CONSOLE)
                        .runeLiteFormattedMessage(messageBuilder.build())
                        .build()
        );
    }

    /** Body in {@code accent}, with the first occurrence of {@code emphasis}
     *  (if any) in {@code bright}. Segments are appended side by side, never
     *  nested: RuneScape's {@code </col>} resets to the chat default rather
     *  than to an enclosing tag. */
    private static void appendEmphasized(ChatMessageBuilder builder, String body,
                                         String emphasis, Color accent, Color bright) {
        int at = emphasis != null && !emphasis.isEmpty() ? body.indexOf(emphasis) : -1;
        if (at < 0) {
            builder.append(accent, body);
            return;
        }
        if (at > 0) {
            builder.append(accent, body.substring(0, at));
        }
        builder.append(bright, emphasis);
        String rest = body.substring(at + emphasis.length());
        if (!rest.isEmpty()) {
            builder.append(accent, rest);
        }
    }
}

package io.droptracker.util;

import net.runelite.client.game.ItemStack;

import java.util.ArrayList;
import java.util.Collection;
import java.util.List;
import java.util.stream.Collectors;

/**
 * Helpers for working with loot bundles ({@link ItemStack} collections).
 * Shared by {@link io.droptracker.events.DropHandler} (embed building and
 * cross-handler dedup) and {@link io.droptracker.service.RaidLootDeduplicator}
 * (raid chest re-loot suppression), so every consumer derives the same
 * signature for the same bundle.
 */
public final class ItemStacks {

    private ItemStacks() {
    }

    @SuppressWarnings("deprecation")
    public static Collection<ItemStack> stack(Collection<ItemStack> items) {
        final List<ItemStack> list = new ArrayList<>();

        for (final ItemStack item : items) {
            int quantity = 0;
            for (final ItemStack i : list) {
                if (i.getId() == item.getId()) {
                    quantity = i.getQuantity();
                    list.remove(i);
                    break;
                }
            }
            if (quantity > 0) {
                list.add(new ItemStack(item.getId(), item.getQuantity() + quantity, item.getLocation()));
            } else {
                list.add(item);
            }
        }

        return list;
    }

    /**
     * Order-independent signature of a loot bundle (consolidated id:qty pairs),
     * used to recognise the same loot arriving via two different loot events.
     */
    public static String signature(Collection<ItemStack> items) {
        return stack(items).stream()
                .map(i -> i.getId() + ":" + i.getQuantity())
                .sorted()
                .collect(Collectors.joining(","));
    }
}

package io.droptracker.util;

import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import org.jetbrains.annotations.VisibleForTesting;

import java.util.Collections;
import java.util.HashSet;
import java.util.Set;

/**
 * Classifies a death location as safe (no items lost) or dangerous.
 *
 * This is policy, deliberately kept out of {@link RegionNameRegistry} so the
 * name data there stays a verbatim, regenerable extract. The region sets and
 * the ordering of the checks mirror Dink's {@code WorldUtils#getDangerLevel},
 * which is the most complete public treatment of this question.
 *
 * Not modelled here (both grant a one-off daily resurrection that makes an
 * otherwise-safe death dangerous, and both need extra varbit reads): the
 * Karamja elite diary in the Fight Caves and the Western Provinces elite diary
 * at Zulrah. Deaths there are reported as safe.
 */
public final class DeathRegions {

    public enum Danger {
        SAFE,
        DANGEROUS
    }

    private DeathRegions() {
    }

    private static final Set<Integer> BARBARIAN_ASSAULT = regions(7508, 7509, 10322);
    private static final Set<Integer> CASTLE_WARS = regions(9520, 9620);
    private static final Set<Integer> CHAMBERS_OF_XERIC = regions(12889, 13136, 13137, 13138, 13139, 13140,
            13141, 13145, 13393, 13394, 13395, 13396, 13397, 13401);
    private static final Set<Integer> CLAN_WARS = regions(12621, 12622, 12623, 13130, 13131, 13133, 13134,
            13135, 13386, 13387, 13390, 13641, 13642, 13643, 13644, 13645, 13646, 13647, 13899, 13900,
            14155, 14156);
    private static final Set<Integer> GAUNTLET = regions(7512, 7768, 12127);
    private static final Set<Integer> LAST_MAN_STANDING = regions(13658, 13659, 13660, 13914, 13915, 13916,
            13918, 13919, 13920, 14174, 14175, 14176, 14430, 14431, 14432);
    private static final Set<Integer> PLAYER_OWNED_HOUSE = regions(7257, 7534, 7535, 7790, 7791, 8046, 8047,
            8302, 8303);
    private static final Set<Integer> SOUL_WARS = regions(8493, 8748, 8749, 9005);
    private static final Set<Integer> TOMBS_OF_AMASCUT = regions(14160, 14162, 14164, 14674, 14676, 15184,
            15186, 15188, 15696, 15698, 15700);
    private static final Set<Integer> THEATRE_OF_BLOOD = regions(12611, 12612, 12613, 12867, 12869, 13122,
            13123, 13125, 13379);

    private static final int CLAN_HALL = 6997;
    private static final int CREATURE_GRAVEYARD = 13462;
    private static final int NIGHTMARE_ZONE = 9033;
    private static final int PEST_CONTROL_LANDER = 10536;
    private static final int TZHAAR_FIGHT_PIT = 9552;

    /* Deliberately absent from the safe sets: the Inferno (9043) and the
     * TzHaar Fight Caves (9551). Both are technically safe, but losing a run
     * there is the whole point of announcing it. */

    private static final int ACCOUNT_TYPE_HARDCORE_IRONMAN = 3;
    private static final int ACCOUNT_TYPE_HARDCORE_GROUP_IRONMAN = 5;

    private static Set<Integer> regions(int... ids) {
        Set<Integer> set = new HashSet<>(ids.length);
        for (int id : ids) {
            set.add(id);
        }
        return Collections.unmodifiableSet(set);
    }

    /**
     * @param client   the game client
     * @param regionId an instance-corrected map region id
     * @return whether items are at risk in this location
     */
    public static Danger classify(Client client, int regionId) {
        // Every PvM death is dangerous on a hardcore account — the status is
        // what is actually lost, so nothing below can downgrade it to safe.
        if (isHardcore(client)) {
            return Danger.DANGEROUS;
        }

        if (isSafeRegion(regionId) || isPestControl(client, regionId)) {
            return Danger.SAFE;
        }

        return Danger.DANGEROUS;
    }

    /**
     * The account-independent half of {@link #classify}: whether this region is
     * somewhere a non-hardcore death costs no items.
     *
     * Split out so the region policy can be tested directly — the rest of the
     * classification needs a live client for the account type and the Pest
     * Control status overlay.
     */
    public static boolean isSafeRegion(int regionId) {
        // Items cannot be carried in or out of these, so a death costs the run
        // rather than the inventory. ToA/ToB/CoX deaths inside a still-running
        // raid are likewise recoverable by the rest of the team.
        if (GAUNTLET.contains(regionId)
                || TOMBS_OF_AMASCUT.contains(regionId)
                || THEATRE_OF_BLOOD.contains(regionId)
                || CHAMBERS_OF_XERIC.contains(regionId)) {
            return true;
        }

        return BARBARIAN_ASSAULT.contains(regionId)
                || CASTLE_WARS.contains(regionId)
                || CLAN_WARS.contains(regionId)
                || LAST_MAN_STANDING.contains(regionId)
                || PLAYER_OWNED_HOUSE.contains(regionId)
                || SOUL_WARS.contains(regionId)
                || regionId == CLAN_HALL
                || regionId == CREATURE_GRAVEYARD
                || regionId == NIGHTMARE_ZONE
                || regionId == PEST_CONTROL_LANDER
                || regionId == TZHAAR_FIGHT_PIT;
    }

    public static boolean isSafe(Client client, int regionId) {
        return classify(client, regionId) == Danger.SAFE;
    }

    private static boolean isHardcore(Client client) {
        // VarbitID.IRONMAN is the account-type varbit: 0 normal, 1 ironman,
        // 2 ultimate, 3 hardcore, 4 group, 5 hardcore group, 6 unranked group.
        int accountType = client.getVarbitValue(VarbitID.IRONMAN);
        return accountType == ACCOUNT_TYPE_HARDCORE_IRONMAN
                || accountType == ACCOUNT_TYPE_HARDCORE_GROUP_IRONMAN;
    }

    /**
     * The Pest Control islands are ordinary-looking regions, so the lander
     * region alone does not cover a death during a game. The status overlay is
     * only built while a game is running, which is exactly the window that
     * matters.
     */
    private static boolean isPestControl(Client client, int regionId) {
        if (regionId == PEST_CONTROL_LANDER) {
            return true;
        }
        Widget widget = client.getWidget(InterfaceID.PestStatusOverlay.PEST_STATUS_PORT2);
        return widget != null && !widget.isHidden();
    }

    /* Region ids referenced by the tests, so a renumbering shows up there
     * rather than silently reclassifying deaths. */
    @VisibleForTesting
    static final int INFERNO = 9043;
    @VisibleForTesting
    static final int TZHAAR_FIGHT_CAVE = 9551;
}

package io.droptracker.util;

/**
 * Minimal dotted-version comparison for plugin update checks.
 */
public final class VersionUtil {

    private VersionUtil() {
    }

    /**
     * Compares two dotted version strings numerically (e.g. "5.4.0" vs "5.10.2").
     * Missing segments are treated as zero; non-numeric segments compare as zero.
     *
     * @return negative if a &lt; b, 0 if equal, positive if a &gt; b
     */
    public static int compare(String a, String b) {
        String[] as = sanitize(a).split("\\.");
        String[] bs = sanitize(b).split("\\.");
        int length = Math.max(as.length, bs.length);
        for (int i = 0; i < length; i++) {
            int ai = segment(as, i);
            int bi = segment(bs, i);
            if (ai != bi) {
                return Integer.compare(ai, bi);
            }
        }
        return 0;
    }

    public static boolean isOlderThan(String current, String other) {
        return compare(current, other) < 0;
    }

    private static String sanitize(String version) {
        if (version == null) {
            return "0";
        }
        String trimmed = version.trim();
        if (trimmed.startsWith("v") || trimmed.startsWith("V")) {
            trimmed = trimmed.substring(1);
        }
        return trimmed.isEmpty() ? "0" : trimmed;
    }

    private static int segment(String[] parts, int index) {
        if (index >= parts.length) {
            return 0;
        }
        try {
            return Integer.parseInt(parts[index].trim());
        } catch (NumberFormatException e) {
            return 0;
        }
    }
}

package io.droptracker.util;


import com.google.gson.Gson;
import com.google.gson.annotations.SerializedName;
import com.google.gson.reflect.TypeToken;
import lombok.AccessLevel;
import lombok.Data;
import lombok.Setter;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ItemComposition;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemVariationMapping;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.BufferedReader;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.OptionalDouble;
import java.util.stream.Collectors;

@Slf4j
@Singleton
public class Rarity {
    private final Map<String, Collection<Drop>> dropsByNpcName = new HashMap<>(1024);
    private @Inject Gson gson;
    private @Inject ItemManager itemManager;
    public static final double EPSILON = 0.00001;
    private static final int[] FACTORIALS;

    @Inject
    void init() {
        Map<String, List<RawDrop>> raw;
        try (InputStream is = getClass().getResourceAsStream("/npc_drops.json");
             Reader reader = new BufferedReader(new InputStreamReader(Objects.requireNonNull(is)))) {
            raw = gson.fromJson(reader,
                    new TypeToken<Map<String, List<RawDrop>>>() {}.getType());
        } catch (Exception e) {
            log.error("Failed to read monster drop rates", e);
            return;
        }

        raw.forEach((npcName, rawDrops) -> {
            List<Drop> drops = rawDrops.stream()
                    .map(RawDrop::transform)
                    .flatMap(Collection::stream)
                    .collect(Collectors.toList());
            dropsByNpcName.put(npcName, drops);
        });
    }

    public OptionalDouble getRarity(String npcName, int itemId, int quantity) {
        ItemComposition composition = itemId >= 0 ? itemManager.getItemComposition(itemId) : null;
        int canonical = composition != null && composition.getNote() != -1 ? composition.getLinkedNoteId() : itemId;
        String itemName = composition != null ? composition.getMembersName() : "";
        Collection<Integer> variants = new HashSet<>(
                ItemVariationMapping.getVariations(ItemVariationMapping.map(canonical))
        );
        return dropsByNpcName.getOrDefault(npcName, Collections.emptyList())
                .stream()
                .filter(drop -> drop.getMinQuantity() <= quantity && quantity <= drop.getMaxQuantity())
                .filter(drop -> {
                    int id = drop.getItemId();
                    if (id == itemId) return true;
                    return variants.contains(id) && itemName.equals(itemManager.getItemComposition(id).getMembersName());
                })
                .mapToDouble(Drop::getProbability)
                .reduce(Double::sum);
    }

    @Value
    private static class Drop {
        int itemId;
        int minQuantity;
        int maxQuantity;
        double probability;
    }

    @Data
    @Setter(AccessLevel.PRIVATE)
    private static class RawDrop {
        private @SerializedName("i") int itemId;
        private @SerializedName("r") Integer rolls;
        private @SerializedName("d") double denominator;
        private @SerializedName("q") Integer quantity;
        private @SerializedName("m") Integer quantMin;
        private @SerializedName("n") Integer quantMax;

        Collection<Drop> transform() {
            int rounds = rolls != null ? rolls : 1;
            int min = quantMin != null ? quantMin : quantity;
            int max = quantMax != null ? quantMax : quantity;
            double prob = 1 / denominator;

            if (rounds == 1) {
                return List.of(new Drop(itemId, min, max, prob));
            }
            List<Drop> drops = new ArrayList<>(rounds);
            for (int successCount = 1; successCount <= rounds; successCount++) {
                double density = binomialProbability(prob, rounds, successCount);
                drops.add(new Drop(itemId, min * successCount, max * successCount, density));
            }
            return drops;
        }
        public double binomialProbability(double p, int nTrials, int kSuccess) {
            // https://en.wikipedia.org/wiki/Binomial_distribution#Probability_mass_function
            return binomialCoefficient(nTrials, kSuccess) * Math.pow(p, kSuccess) * Math.pow(1 - p, nTrials - kSuccess);
        }
        private int binomialCoefficient(int n, int k) {
            assert n < FACTORIALS.length && k <= n && k >= 0;
            return FACTORIALS[n] / (FACTORIALS[k] * FACTORIALS[n - k]); // https://en.wikipedia.org/wiki/nCk
        }
    }

    static {
        // precompute factorials from 0 to 9 for n-choose-k formula
        int n = 10; // max rolls in npc_drops.json is 9 (for Bloodthirsty Leagues IV tier 5 relic)
        int[] facts = new int[n];
        facts[0] = 1; // 0! = 1
        for (int i = 1; i < n; i++) {
            facts[i] = i * facts[i - 1];
        }
        FACTORIALS = facts;
    }
}

package io.droptracker.util;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import lombok.extern.slf4j.Slf4j;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.BufferedReader;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.Map;
import java.util.Objects;
import java.util.function.UnaryOperator;

/**
 * Data-driven registry mapping adventure-log / chat short boss names to their
 * canonical long names. The mappings live in
 * {@code /io/droptracker/boss_names.json} and were extracted verbatim from the
 * former switch statement in {@code WidgetEventHandler.longBossName}.
 *
 * Dynamic behavior (the {@code " (echo)"} suffix recursion and the
 * unmapped-name fallback) intentionally remains in code rather than data.
 */
@Slf4j
@Singleton
public final class BossNameRegistry {

    private static final String RESOURCE_PATH = "/io/droptracker/boss_names.json";
    private static final String ECHO_SUFFIX = " (echo)";

    private final Map<String, String> mappings;

    @Inject
    public BossNameRegistry(Gson gson) {
        this.mappings = loadMappings(gson);
    }

    private static Map<String, String> loadMappings(Gson gson) {
        try (InputStream is = BossNameRegistry.class.getResourceAsStream(RESOURCE_PATH);
             Reader reader = new BufferedReader(new InputStreamReader(Objects.requireNonNull(is), StandardCharsets.UTF_8))) {
            Map<String, String> mappings = gson.fromJson(reader,
                    new TypeToken<Map<String, String>>() {}.getType());
            return Collections.unmodifiableMap(Objects.requireNonNull(mappings));
        } catch (Exception e) {
            log.error("Failed to load boss name mappings from {}", RESOURCE_PATH, e);
            return Collections.emptyMap();
        }
    }

    /**
     * Resolves a short boss name to its canonical long name.
     * Names ending in {@code " (echo)"} (case-insensitive) are resolved by
     * recursing on the base name and re-appending {@code " (Echo)"}.
     *
     * @param shortName the short name to resolve
     * @return the canonical name, or the input unchanged when unmapped
     */
    public String canonicalName(String shortName) {
        return canonicalName(shortName, UnaryOperator.identity());
    }

    /**
     * Resolves a short boss name to its canonical long name, applying
     * {@code unmappedFallback} to the (possibly echo-stripped, lowercased)
     * name when no mapping exists. This mirrors the exact recursion order of
     * the original {@code longBossName} implementation.
     *
     * @param shortName        the short name to resolve
     * @param unmappedFallback transformation applied to unmapped names
     * @return the canonical name, or the fallback-transformed input when unmapped
     */
    public String canonicalName(String shortName, UnaryOperator<String> unmappedFallback) {
        String lowerBoss = shortName.toLowerCase();
        if (lowerBoss.endsWith(ECHO_SUFFIX)) {
            String actualBoss = lowerBoss.substring(0, lowerBoss.length() - ECHO_SUFFIX.length());
            return canonicalName(actualBoss, unmappedFallback) + " (Echo)";
        }

        String mapped = mappings.get(lowerBoss);
        return mapped != null ? mapped : unmappedFallback.apply(shortName);
    }

    /**
     * @return the number of short-name mappings loaded from the data file
     */
    public int size() {
        return mappings.size();
    }
}

package io.droptracker.util;

import com.google.gson.TypeAdapter;
import com.google.gson.stream.JsonReader;
import com.google.gson.stream.JsonWriter;

import java.io.IOException;
import java.time.Duration;
import java.time.format.DateTimeParseException;

/**
 * Serializes and deserializes {@link Duration} instances
 * from their equivalent ISO-8601 string representation.
 * <p>
 * This adapter exists because GSON does not ship with
 * a module for the Java 8 time API.
 *
 * @see <a href="https://github.com/google/gson/issues/1059">GSON Issue</a>
 */
public class DurationAdapter extends TypeAdapter<Duration> {
    @Override
    public void write(JsonWriter out, Duration duration) throws IOException {
        out.value(duration != null ? duration.toString() : null);
    }

    @Override
    public Duration read(JsonReader in) throws IOException {
        if (in.hasNext()) {
            try {
                return Duration.parse(in.nextString());
            } catch (DateTimeParseException ignored) {
            }
        }
        return null;
    }

    public static String formatDuration(Duration duration) {
        if (duration.toDays() > 0) {
			return duration.toDays() + " day ago";
		} else if (duration.toHours() > 0) {
			return duration.toHours() + " hr ago"; 
		} else if (duration.toMinutes() > 0) {
			return duration.toMinutes() + " min ago";
		} else {    
			return "just now";
		}
    }
}
